INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p996956-math101', 'stk-abo_ali', 'MATH 101', 'info', '{"desc": "بسم الله\nكتاب كالكولاس الطبعه السادسه\n\nجودة المقرر بشكل عام\nجيده جدا\n\nالمواضيع التي يغطيها المقرر\nيغطي الليميت(الحدود) + الديريفاتيف (الاشتقاق) + وفي الاخير يتكلم عن الانتيقرال (التكامل) بشكل مبسط\n\nالكتاب المستخدم للمقرر\nالكتاب ممتاز وكذلك اخراجه + امثله بسيطه وتمارين معقده + سليوشن مانيول امور\n\nالأسئلة والأمثلة المستخدمة في المقرر\nتبدا من الامثله المتوسطه الى التمارين الناريه ض1\n\nمدى فائدته في الناحية التطبيقية\nيالحين ما لقيت اي فايده من دراسه الماث اصلا 🤣\n\nنصيحه مني للجميع\n\nالكتاب كبييييييير جدا(لانه حق 3 كورسات ) فما ينفع انك تداوم فيه\nرح المكتبه واطبع الجزء اللي تريده , وبكذا ترتاح مره\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/2", "user": "Abo_Ali", "ts": 1330546630000, "tid": 120611, "pn": 2}}', 1330546630000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1029574-math101', 'stk-user7238', 'MATH 101', 'info', '{"desc": "الكوورس جداً ممتع بالنسبه لي\nاخذته مع الدكتور بدر الحميدي\nالكورس في البدايه يتكلم عن اللمت(النهايات)\nوثم يعرف المشتقه با اللمت\nوتبدأ تاخذ طرق اخذ المشتقه وثم تطبيقات عليها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/3", "user": "user7238", "ts": 1335614399000, "tid": 120611, "pn": 3}}', 1335614399000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1030363-math101', 'stk-s2010xxxxx', 'MATH 101', 'info', '{"desc": "الكورس حلو وممتع … بالنسبه للمذاكره … انصح الطلاب بالمذاكره من الكتاب لانه مفييد جدا جدا والتمارين حقته رائعه … ذاكر كل سكشن وحل الاسئلة الفرديه كلها وراجع حلك من المانيوال سلوشن الموجود على التراكر وفالك الـ a+ ان شا الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/4", "user": "s2010xxxxx", "ts": 1335740055000, "tid": 120611, "pn": 4}}', 1335740055000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1048980-math101', 'stk-user7558', 'MATH 101', 'info', '{"desc": "الكتاب أفضل كتاب لحد الآن استخدمته في دراستي من الابتدائي للجامعة\nفيه أمثلة كثيرة ومفيدة والأسئلة اللي في الكتاب لو حليتهم تضمن الاي بلس\n\nالكورس تقريبا 60-65 % درسته في الثانوي بس الآن بتفصيل أكثر وبشرح أفضل بكثير من شرح كتاب الثانوي\nيتكلم في البداية عن اللمت ( النهايات ) وكيفية حسابها وتعريفها وبعدها ينتقل للاشتقاق وكيفيته ومعناه وغيرها\nوآخر قسم هو عن تطبيقات على الاشتقاق\n\nأصعب شي في الكورس هو درس Related Rates والباقي سهل جدا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/5", "user": "user7558", "ts": 1338557802000, "tid": 120611, "pn": 5}}', 1338557802000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1049188-math101', 'stk-google.com', 'MATH 101', 'info', '{"desc": "من اسهل الكورسات وامتعها راح تواجهك من دخولك الجامعة إلى ان تتخرج هو ماث 101 منهج تسمتع بحل مسائله ولا عندك مشكلة لو تحل اسئلة كل شابتر كاملة واضافة إلى ذلك يمديك تجيب فيه قريد بالراحة يعني لاتستغرب ان جبت فيه a … المنهج يعتمد بسكل كبير على منهج ماث002 نقطة مهمة حاول تنزل هالمنهج عند مدرس متمكن كبدر الحميدي هو الكنج في ماث101 ولا فيصل فيرق لان من خلال المدرسين هؤلاء يمكن ما تحتاج تذاكر إلا قبل الاختبار بيومين او ثلاثة على شرط ان تكون معهم فاهم وتذاكر لكوازتهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/6", "user": "google.com", "ts": 1338594791000, "tid": 120611, "pn": 6}}', 1338594791000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1050283-math101', 'stk-brav3', 'MATH 101', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته.\n\nSemester 111.\n\nجودة المقرر بشكل عام:\n\nممتازة.\n\nالمواضيع التي يغطيها المقرر :\n\n1- مشكلة الـ Velocity و الـ Tangent Line.\n\n2- مقدمة عن مفهوم الـ Limit باستخدام طرق رقمية و هندسية.\n\n3- قوانين حساب الـ Limits.\n\n4- التعريف الدقيق للـ Limit.\n\n5- الـ Continuity.\n\n6- الـ Infinite Limits.\n\n7- مقدمة عن مفهوم الـ Derivative رقمياً و هندسياً ، و طريقة حسابها من تعريفها عن طريق الـ Limits.\n\n8- الـ Derivative كـ Function.\n\n9- قوانين الـ Differentiation الأساسية (الـ Power Rule ، و الـ Derivative للـ Exponential Function).\n\n10- الـ Product و الـ Quotient Rule.\n\n11- Derivatives Of Trigonometric Functions.\n\n12- The Chain Rule.\n\n13- Implicit Differentiation.\n\n14- Derivative Of Logarithmic Functions.\n\n15- تطبيقات الـ Derivative في الفيزياء.\n\n16- Related Rates.\n\n17- الـ Critical Points و الـ Extreme Value Theorem.\n\n18- Rolle’s Theorem و الـ Mean Value Theorem.\n\n19- Intervals Of Increasing And Decreasing و الـ Concavity.\n\n20- Indeterminate Forms و قاعدة لوبيتال.\n\n21- رسم الـ Graphـات عن طريق الـ Calculus.\n\n22- Optimization.\n\n23- طريقة نيوتن.\n\n24- الـ Anti-Derivative.\n\nالكتاب المستخدم للمقرر:\n\nممتاز.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nتميل إلى اختبار الـ Techniques الرياضية بدلاً من اختبار الفهم (و هو الأهم).\n\nمدى فائدته في الناحية التطبيقية:\n\nمفيد 100%.\n\nملاحظات:\n\n1- إذا كنت عند مدرس سيء ، لا تجعله سبب للإهمال و اليأس ، الرياضيات لا تحتاج إلى مدرس ، بل تحتاج إلى مصدر جيد للدراسة ، و الكثير من التمرن.\n\n2- لا تجعل صعوبة الاختبارات سبب للإهمال و اليأس ، كثرة التمرن و الممارسة ستحول هذه الصعوبة إلى سهولة مفرطة.\n\n3- ضع جل اهتمامك في فهم الموضوع فهماً جيداً لأن فهم الموضوع هو ما يحدد قدرتك على حل المسائل الرياضية من عدمها.\n\n4- اجعل هدفك من دراسة الرياضيات الفائدة لنفسك ، فالفهم الجيد للرياضيات سيفيدك في كل نواحي حياتك.\n\nمع السلامة.\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/7", "user": "BRAV3", "ts": 1338765314000, "tid": 120611, "pn": 7}}', 1338765314000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1075994-math101', 'stk-_2214', 'MATH 101', 'info', '{"desc": "احرص على ان تكون عند مدرس كويس لانه بيريحك وذاكر او باول\n\nوركز على الميجر الاول انك تجيب فيه درجة عالية لان الميجر الثاني غالبا يجي متوسط الصعوبة الى صعب since the average for majaor 2 between 50_60", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/8", "user": "_2214", "ts": 1344168954000, "tid": 120611, "pn": 8}}', 1344168954000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1080328-math101', 'stk-chelsea_21', 'MATH 101', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nجودة المقرر بشكل عام\n\nمقرر ممتاز جدًا ، راح يفيدك بشكل مو طبيعي ، لان هذا الكورس فيه مسائل تنحل بطرق جبرية\n، يعني الي نجح بـ 001 ومااتقن المادة بشكل كويس في التعامل مع { الفاكتور\"التحليل\" ، الجذور ، الكسور ، وطرق الطرح والكسور بالاعداد } يعني اكثر كورس راح يفيدك.\nوهو حلو وممتع ويعتبر كورس سهل بشكل كبير للغاية واسهل من 002 و 001.\n\nالمواضيع التي يغطيها المقرر\nالكورس يعتمد على 3 شباتر ، تبدأ من شبتر 2 -حيث ان شبتر1- في أغلب الكتب\n- يكون مراجعة للجبر- لكن تبدأ من الشبتر الثاني وهو يتكلم بشكل عام عن “Limits”\nالحدود والنهايات ( نها ) بكل دروسها وقوانينها ورسمها ، وغيرها وايضًا مسألة “tangent line” والـ “velocity” درس وحيد بالشبتر الي يتكلم عن تطبيقات فيزيائية.\n\nالشبتر الثالث\n\n“قوانين الإشتقاق” Derivative … راح يكون في هذا الشبتر ،\nقوانين حل مسائل الإشتقاق بجميع أنواعها\n{ قواعد الإشتقاق ، اشتقاق الضرب ، اشتقاق القسمة ، اشتقاق الـ polynomials ، اشتقاق الأسس ، اشتقاق “Trigonometric Functions” ، اشتقاق بطريقة Chain Rule ، اشتقاق Log و الـ inverse Function … وفيه درسين تقريبًا عن تطبيقات فيزيائية\n\nالشبتر الرابع والأخير\n\nيتكلم بشكل عام عن القيم العظمى والصغرى من مسائل\nورسم وايضًا درس طرق نيوتن ودرس طريقة\nL’Hopital لحل الليميتس. وآخر درس في الكورس هو مقدمة عن “التكامل” وقوانينه\n\nالكتاب المستخدم للمقرر\nسيء جدًا. كتب calculus مثل Mcgraw Hill و Pearson أفضل منه بكثير.\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nأمثلة الدروس ، لابأس بها … لكن التمارين سهلة وليست صعبة مثل الاسئلة الي بالنت او من الكتب الثانية\nمدى فائدته في الناحية التطبيقية\n\nفائدة حلوة وراح تعرف حاجات ماكنت تعرفها من قبل (مثل عن طريق الرسم ) .\nالكورس هذا هو أساس الرياضيات\nلان التكامل في 102 وفي الكورسات المتقدمة ماراح تنجح فيه إذا ماعرفت الاشتقاق\nوالاشتقاق ماتعرفه إلا لمن تعرف الطرق الجبرية(الضرب والطرح وقسمة الجذور ) والتعامل مع\nالـــ base e والـ ln والـ log\n\nالمهم …\n\nالكورس سهل جدًا وماراح ياخذ وقت من مذاكرتك\nيمكن تاخذ B+, A إذا مذاكرتك وسط\nبس اعط المادة اهتمام بالحضور والهوم وورك والكويزات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/10", "user": "Chelsea_21", "ts": 1345407285000, "tid": 120611, "pn": 10}}', 1345407285000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1087610-math101', 'stk-cesar_peace', 'MATH 101', 'info', '{"desc": "-\n\nماقصروا الشباب اعطوا المقرر حقه من الوصف 🌹 , وعندي نقطة واحدة اضيفهآ\n\n( الماث كثر مآتعوّد يدك على الحل , كثر مآتسهل عليك المسآئل وتبدّع اكثر ان شاء الله )\n\n🌹 ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/11", "user": "CeSaR_PeaCe", "ts": 1346887866000, "tid": 120611, "pn": 11}}', 1346887866000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1275358-math101', 'stk-the_aviator', 'MATH 101', 'info', '{"desc": "بسم الله الرحمن الرحيم\nالسلام عليكم ورحمة الله وبركاته\nTERM 123\n1 - جودة المقرر بشكل عام :\nجيد جداً\n2 - المواضيع التي يغطيها المقرر :\nRates of change , Limits , continuity , differentiation , Mean value theorem , Optimization , Reman sum\n3 - الكتاب المستخدم للمقرر :\nجيد جداً\n4 - الأسئلة والأمثلة المستخدمة في المقرر :\nأرى أن الأمثلة ممتازة ولكن حلها في الكتاب مختصر وليس فيه خطوات واضحة للأفكار لذلك راح تقعد وقت تجمع أفكار كل مثال وترتبها ، بالنسبة للأسئلة في نهاية كل تشابتر أراها ممتازة جداااً وتساعد في ترسيخ بعض الأفكار اللي تجي في المياجر .\n5 - مدى فائدته في الناحية التطبيقية :\nأغلب المواضع مهمة لكل مهندس ، ولكن الأهم من وجهة نظري هو موضوع Optimization .\n6- اقتراحات وتعليقات :\nالكورس سهل وبسيط ولكن يحتاج منك بعض الخطوات ,\nأ - حل كل الأمثلة ( الأمثلة المحلولة وليس الأسئلة في النهاية ) واكتب جميع افكارها في دفترك.\nب - حل الأسئلة الموجودة في السيلابس كاملة وافهمها لأن الهوموورك نفسها بالظبط بس تغيير أرقام.\nج - حل old exams .\nبهذي الطرق الثلاث أضمن لك B+ وفوق .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/13", "user": "THE_AVIATOR", "ts": 1382106456000, "tid": 120611, "pn": 13}}', 1382106456000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316096-math101', 'stk-user8581', 'MATH 101', 'info', '{"desc": "كورس خفيف وسهل لكن لا تهمل وتسحب عليه … وللأسف الكثير جابوا قريدات سيئة في هالكورس بسبب انه سهل واستهانوا فيه … تبي تجيب قريد طيب : ركز مع دكتورك واول ماتاخذ الدرس حل اسئلة الكتاب لأنها مهمة جدا جدا وتبين لك انت فاهم ولا …يمكن يكون اغلبها سهلة لكن التطبيق يخليك تفهم الدرس اكثر وفي نفس لوقت في بعض الاسئلة تحتوي على افكار حلوة يمكن تجي في المياجر مع تعديل بسيط عليها …\nلا تغتر بدرجتك في الميجر الاول وتسحب عالمادة لأن الميجر الثاني يكون مستواه اعلى نوعا ما ويحتاج جهد اكثر . وكثيرا الي طارت عليهم اكثر من قريد بسبب الميجر الثاني …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/16", "user": "user8581", "ts": 1389015585000, "tid": 120611, "pn": 16}}', 1389015585000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316293-math101', 'stk-abo-da7m', 'MATH 101', 'info', '{"desc": "الفصل\n\n131\n\nجودة المقرر بشكل عام\n\nممتاز\n\nالمواضيع التي يغطيها المقرر\n\nالنهايات … الاشتقاق\n\nالكتاب المستخدم للمقرر\n\nThomas Calculus 12th | متوسط … اسئلته نهاية كل سكشن جيدة\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nيعيب اسئلة الاختبارات انه تركز على التحليل وكتابة العبارات الرياضية باكثر من شكل أكثر من تركيزه على المفاهيم الأساسية بالمادة\n\nمدى فائدته في الناحية التطبيقية\n\nمفيد ومهم وداخل بكثير من العلوم\n\nإضافات :\n\n* من أهم الأشياء اللي تعلمته بمذاكرة المقرر … حل أكبر عدد من الأولد اقزامز باوقات متفرقة طول الفصل موب قبل الاختبار باسبوع ! . عشان تطور مهارتك بالتحليل واعادة صياغة العبارات الرياضية وتكتسب مهارات وأساليب مختلفة للحل .\n\n* فيه اسئلة مفيدة جدا بالكتاب نهاية كل فصل تحت عنوان \" Theory and example \" احرص تمر عليهن يساعدنك تفهم بشكل أعمق .\n\n* تتميز المادة بخفته ( الماتيريل قليل مرة ) - بالنسبة لعدد النقاط - 3 أبواب تقريبا .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/17", "user": "abo-da7m", "ts": 1389038085000, "tid": 120611, "pn": 17}}', 1389038085000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1350642-math101', 'stk-2011_ibrahim', 'MATH 101', 'info', '{"desc": "من امتع كورسات الماث الي مرت علي كورس سهل بالنسبة للطلاب الي يحبون الماث مثلي 🤠\nفهم الكورس هذا راح يسهل فهم الكورس الي بعده Math 102 لان الاشتقاق عكس التكامل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/18", "user": "2011_IBRAHiM", "ts": 1397138229000, "tid": 120611, "pn": 18}}', 1397138229000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437378-math101', 'stk-osamah56', 'MATH 101', 'info', '{"desc": "Term 151\n\nبكل أمانة وصدق ، الكورس سهل جدا مو زي ما الناس متخيلين ، لكن كثير يجيبون درجات نازلة بسبة الاهمال زي ما قال اخوي “شدعوة” ، ف الي ياخذ الكورس لازم من البداية تركز مع الدكتور وتذاكر أول بأول لان اذا راكمتها بيصعب عليك انك تلحق .\n\n+ فيه حاجة مهمة انا واجهتها الترم ذا ، اذا انت فاهم حاجة لا تقول فاهمها خلاص وتسوي لها skip بالعكس الحاجة هذي ممكن تجيك في المياجر وتنساها ، ف البراكتس مطلوب ف كل جزء من الكورس .\n\nوالله يوفق الجميع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/26", "user": "osamah56", "ts": 1451424676000, "tid": 120611, "pn": 26}}', 1451424676000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466775-math101', 'stk-abdullah2015', 'MATH 101', 'info', '{"desc": "ترم 161\n\nباختصار، أشوف الكورس أسهل من ماث 002، إذا كان مستواك ممتاز في ماث الأوريا فغالباً راح تستمر على نفس المستوى في هذا الكورس وبنفس الجهد\n\nهو صح أسهل من 002 لكنه معتمد عليه بشكل كبير، يعني لازم تكون مستحضر الTrigonometric function والidentities حقتها والقراف حق كل دالة\n\nوأيضاً القرافات حق كل الدوال (التربيعية، التكعيبية، الأسية، اللوغارتمية … إلخ) باختصار كل الدوال اللي أخذتهم في ماث001 و002 ، بتستخدمهم في هذا الكورس وأيضًا غيرها من الأساسيات.\n\nيمكن عشان هذا السبب البعض يشوفه أصعب، لكن اللي أساسه في الماث قوي راح يشوف إنه أسهل من سابقيه.\n\nوبشكل عام، اللي متابع أول بأول ويذاكر أول بأول راح يشوف إنه سهل …\n\nوبالتوفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/30", "user": "Abdullah2015", "ts": 1485090815000, "tid": 120611, "pn": 30}}', 1485090815000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486302-math101', 'stk-bader27', 'MATH 101', 'info', '{"desc": "بسم الله الرحمن الرحيم\nجودة المقرر بشكل عام\n\nممتاز ومستخدم بشكل كبير في اغلب التخصصات (حاول تتقنه)\n\nالمواضيع التي يغطيها المقرر\nالكورس يعتمد على 3 شباتر ، تبدأ من شبتر 2 -حيث ان شبتر1- في أغلب الكتب\n- يكون مراجعة للجبر- لكن تبدأ من الشبتر الثاني وهو يتكلم بشكل عام عن “Limits”\nالحدود والنهايات ( نها ) بكل دروسها وقوانينها ورسمها ، وغيرها وايضًا مسألة “tangent line” والـ “velocity” درس وحيد بالشبتر الي يتكلم عن تطبيقات فيزيائية.\n\nالشبتر الثالث\n\n“قوانين الإشتقاق” Derivative … راح يكون في هذا الشبتر ،\nقوانين حل مسائل الإشتقاق بجميع أنواعها\n{ قواعد الإشتقاق ، اشتقاق الضرب ، اشتقاق القسمة ، اشتقاق الـ polynomials ، اشتقاق الأسس ، اشتقاق “Trigonometric Functions” ، اشتقاق بطريقة Chain Rule ، اشتقاق Log و الـ inverse Function … وفيه درسين تقريبًا عن تطبيقات فيزيائية\n\nالشبتر الرابع والأخير\n\nيتكلم بشكل عام عن القيم العظمى والصغرى من مسائل\nورسم وايضًا درس طرق نيوتن ودرس طريقة\nL’Hopital لحل الليميتس. وآخر درس في الكورس هو مقدمة عن “التكامل” وقوانينه\n\n(مكتوبه باختصار)\nالكتاب المستخدم للمقرر\nكتاب calculus.\n\nممتاز جدا من عدة نواحي\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nأمثلة الدروس تعتبر ممتازة واغلب المدرسين يستخدمونها وتجدها في النوتات\nمدى فائدته في الناحية التطبيقية\nفوائد كثيرة جدا اقرا عنها او اسئل مدرسك عنها\n\nطريقة المذاكرة\n\nتوزيع الدرجات\n\n40 بوينت كلاس ورك\n\n100 لكل ميجر\n\n140 للفاينل\n\n20 واجب\n\nفي البداية افهم من المدرس ثم انتقل لنوت المدرس وفيه كذا نوت تجدها في الرابط اسفل افضل نوت بينهم والي استخدمتهم تلقون نوتت محمد صلاح هي اول شي افتحها وافهمها زين ثم نوتة المطوع زينتها جامع امثلة الكتاب ثم بكل فكرة جايب اولد اقزام وبكذا تكون خلصت امثلة الكتاب بنوتة المطوع وحليت بعض افكار الاولد اقزامتروح على اكسامبل الكتاب وتفتح السلبوس وتحل الرسيتيشن والمقترحات واذا قدرت الاود ثم فيه ملف اولد اقزام باي سكشن ممكن كل سكشن فيه 10 اسئلة حلها وبكذا تكون قفلت السكشن 100%\n\nالميجر\n\nارجع اقرا المتريل على السريع لأنك بتكون جاهز ثم حاول تحل لا يقل عن 5-6 مياجر كاملة اذا خلصت حلهم بتعرف نقاط ضعفك عدلهم قبل الميجر\n\nالفاينل\n\nزي الميجر لان ما عندك وقت ثم حل اكبر قدر من الفاينلات لان الأسئلة تتكرر افكارها بشكل كبير\n\nملاحظات\n\nاغلب الطلاب يقول هذي المادة سهله بغض النظر عن هذي الحقيقة المادة تحتاج شغل وتمرين فاشتغل اول بأول عشان ما تحس انك ضائع قبل الفاينل او الميجر بفترة قصيرة وما يصير عندك وقت تعوض\n\nفيه درسين اغلب الطلاب يعانون منها\n\n3.9\n\nهي امثله محدودة افهمها وبتجيك نفسها في الميجر والفاينل\n\n4.7\n\nهي امثله محدودة افهمها وبتجيك نفسها في الميجر والفاينل\n\nالواجب لا تأخره أبدا حاول تحل كل يوم درس ما راح يأخذ وقت\n\nالكويز ذاكر له كانه ميجر\n\nبعض الملفات المهمة\n\n171 - Google Drive\n\nادعوا لي ومن جمع هذي الملفات وشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/33", "user": "Bader27", "ts": 1516240330000, "tid": 120611, "pn": 33}}', 1516240330000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486303-math101', 'stk-user10679', 'MATH 101', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالمواضيع التي يغطيها المقرر :\nشابتر 2 ------- الليميت وكذا موضوع متعلقة بال بالليمت وفيه مقدمة للاشتقاق\nشابتر 3--------- قوانين الليمت وتطبيقات وقوانين الاشتقاق\nشابتر 4 -------- فيه مواضيع كثيرة وبالنسبة لي اشوفه امتع شابتر لانه فيه الكيرف سكتشنق\nالكتاب المستخدم للمقرر\nالاكسرسايزيس اللي فيه ممتازة جدا وتكفي لمذاكرة الميجر\n\nنصيحة علي بالكتاب والكتاب والككتاب والكتاب\nاسالته مفيدة جداااا جداا\nوالمياجر الاول سهل ولا تفوته من يدك تراه سهل\nوالثاني برضو سهل ولكن فيه تركات\nوالفاينل ماتيريله سهل جدا\n\nالمياجر يكفي انك تذاكر بفهم من الكتاب وحاول تمسك الاسالة وحدد لك ممكن 30 سؤال على الدرس\nحلهم وبتطلع فاهم ان شاء الله وان قدرت تحلهم كلهم افضل وافضل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/34", "user": "user10679", "ts": 1516241106000, "tid": 120611, "pn": 34}}', 1516241106000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509414-math101', 'stk-mohammad-72', 'MATH 101', 'info', '{"desc": "جودة المقرر بشكل عام: ممتاز جدا ويفتح عينك على اشياء ماكنت تعرفها\nالمواضيع التي يغطيها المقرر الاشتقتاقات والنهايات وتطبيقات عليها\nالكتاب المستخدم للمقرر: مدري شسمه\nالأسئلة والأمثلة المستخدمة في المقرر ممتازة جدا بس انصح بنوت الدكتور محسن الشهراني وفيصل فيرق للفهم والاولد للتطبيق\nمدى فائدته في الناحية التطبيقية مفيد جدا\nاضافات: الكورس سهل جدا ومياجره غالبا تجي بسيطة\nاضافة 2:لاكن في ترم 182)الترم اللي خذيته فيه) جا حقد غير طبيعي من الكوردنيتر وجات المياجر صعبة جدا وفيها كونسبت صعب مقارنة ببقية المياجر وجات اسالة فيها نماذج مختلفة من ناحية الارقام ؟؟؟؟؟؟؟؟؟؟ لاكن بشكل عام الاسالة اللي تجي بسيطة الا اذا حطوكم في راسهم\nاضافة ثانية: الكورس بشكل كبير صار ستاندرد وماتتغير فيه الا ال+b c c لا+ والباقي صعب يتغير مثل الf وa فترمي افرج الميجرين 100/200 وماطيحوا القريدات الا تكه(الكوردنيتر اسمه حسين العطاس )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/38", "user": "mohammad-72", "ts": 1557169497000, "tid": 120611, "pn": 38}}', 1557169497000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1513507-math101', 'stk-user11724', 'MATH 101', 'info', '{"desc": "TERM183\nكورس سهل ورائع، لكن اذا اهملته راح تضيع ويبغاله مذاكرة أول بأول، أسئلة الكتاب ممتازة تكون سهلة وكل ما وصلت سؤال 40 و 50 تزيد الصعوبة واذا حليت الأسئلة الأخيرة ان شاء الله انك فاهم.\nطلاب كثيرين خسروا الـA+ بسبب أنهم جابوا فل مارك في الميجر الأول وأكلوها في الميجر الثاني لأنه يبدو أسهل ولكن يبغاله شوية شغل وتطبيق.\nأغلب الطلاب يذاكرون نوتات محسن، كويسة بس يبغالك تطبق أكثر، ويبغالك تنتبه أن الأولد اقزامز فيها اجدد شيء 173.\nنصيحة أخيرة لا تجيب أقل من A في الكورس هذا خصوصا، ولأنه بداية معدل، بالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/39", "user": "user11724", "ts": 1565221089000, "tid": 120611, "pn": 39}}', 1565221089000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522353-math101', 'stk-nasalmz', 'MATH 101', 'info', '{"desc": "الكورس يعتبر من اسهل كورسات لكن لابد من ان الواحد يكثر من التدريب. طبعا الشباب ما قصروا من ناحية محتوى المادة نفسها.\n\nلكن بعطي نصايح مدري ممكن تفيد ولا لا؟\n\nنوت الأستاذ محسن الشهراني كافية ووافية من ناحية فهم الكونسبت والتمارين.\nحل الاولد اقزام “باي سكشن”.\nاذا انك فاضي مر ع تمارين الكتاب.\nلا تخلي الكورس يتراكم ابدا.\nوبالتوفيق يا شباب.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/40", "user": "Nasalmz", "ts": 1590419289000, "tid": 120611, "pn": 40}}', 1590419289000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527871-math101', 'stk-hajjar', 'MATH 101', 'info', '{"desc": "اذا بتدخل الكورس على اساس انه واحد من اسهل الكورسات صدقني بتلقم C كبر راسك\nالكورس مكون من 3 شباتر\nاول شابتر هو التحميه عن الليمت وبعض النظريات\nثاني شابتر عن الاتشقاق بشكل عام وطرقة وهنا بتجي اغلب التريكات\nاخر شابتر عن تطبيقات الاشتقاق هنا الكونسبت راح يكون ثقيل شوي لكن الاسئلة بالغالب سهله\nاذا تبي A+ بالكورس شوف لك مصدر جيد للمذاكره اذا دكتورك شرحه ماش وحل اولد باي سيكشن لكل درس وقبل الاختبار افتح اولد باي تيرم\nوفالك التوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/41", "user": "hajjar", "ts": 1610618414000, "tid": 120611, "pn": 41}}', 1610618414000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530633-math101', 'stk-housam-ae', 'MATH 101', 'info', '{"desc": "بسم الله الرحمن الرحيم، والصلاه والسلام على رسول الله.\nاسأل الله تعالى التوفيق والسداد في هذا الطرح.\n\nالمادة: MATH101، مكوّن من ثلاثة تشباتر (2,3,4)\nتشابتر 2 عنوانه: Limits & Derivatives (النهايات والاشتقاق)\nتشابتر 3 عنوانه: Differentiation Rules (قوانين الاشتقاق)\nتشابتر 4 عنوانه: Application of Differentiation (تطبيقات الاشتقاق)\n\nتشابتر 2:\n\nباختصار يطرح لك فكرة النهايات، تعريفها، قوانينها، متى تكون غير موجودة، وطرق حسابها وكيف تتعامل مع الIndeterminate form/zero over zero، وكيف توجد اللمت…هنا بيحشرلك القيمة المطلقة والدالة الدرجية الكريهه داخل اللمت، والنهايات من طرف واحد، ومعنى النيهايات بيانياً. والتعريف الدقيق للنهايات. وخطوط التقارب الرأسية والافقية. ثم يتدرج بك للدوال المتصلة، وما معنى ان تكون الدالة متصلة بالنهايات وانواع عدم الاتصال. ثم يعطيك تعريف المشتقة باستخدام النهايات وقانونها بالنهايات وطريقة حلها والعلاقة بين ان الدالة المتصلة وقابليتها للاشتقاق. باختصار… ذا التشابتر حليييوة وسهل ولزييييز وخفيف وممتع لأنه تقريباً MATH001 + MATH002 حطهم في الخلاط مع بهارات ليميتاوية (Limits) يطلعلك ذا التشابتر. على فكرة، هنا يظهر الطالب الي أساسه ممتاز واستفاد من MATH001 خصوصا واتقنه، مو بس نجح فيه وياالله الحياه الحلوة! يعني لازم تستذكر بعض قوانين تشابتر P من MATH001، كذلك المتباينات والقيمة المطلقة، الدوال من تشابتر 2 لكن ولا شيء من تشابتر 3. ومن MATH002 لازم لازم لازم تكون فاكر كويس اشكال الدوال اللوغاريتمية والدوال المثلثية وبعض معكوساتها (تحديداً tan inverse)، لازم تكون فاكر شكلهم ومجالهم ومداهم وأصفارهم، واحياناً انعكاساتها لو استذكرتها قد تفيد.\n\nتشابتر 3:\n\nهو صلب الكورس كله، وهو عاموده الفقري، وقلبه النابض. التشابتر يعلمك كيف تشتق باستخدام القوانين بدلاً من طريقة النهاية المتعبة الي رح تشوفها طويلة وغير عملية بعد ما تدرس تشابتر 3، رح تتعلم الاشتقاق باستخدام كل القوانين التالي اسماؤها:\nPower Rule\nSum Rule, Difference Rule\nProduct Rule, Quotient Rule\nChain Rule (القانون الي يطيح بكثيير من الطلاب في تريكات، مهم تتقنه وتتدرب عليه)\nDerivatives of exponential functions\nImplicit Differentiation (كيف تشتق معادلة بمجهولين)\nDerivatives of Logarithmic Functions, Logarithmic Differntiation\n\nوأيضاً بتتعلم كيف تشتق الدوال المثلثية Trigonometric Functions ومعكوس الدوال المثلثية. وكيف تشتق الدوال المثلثية الي تكون مكتوبة على صيغة نهايات. وأيضاً رح تتدرب على ال Higher Derivatives. الدروس من 3.1-3.6 تحتاج تدريب كبير جداً وتعرض عالي للأسئلة، وستجد ذلك متاحاً في الكتاب، رح اتكلم عن الكتاب والمصادر بشكل اعمق بعد قليل. لمن تخلص سكشن 3.6، كذا مبروك عليك رح تكون تعرف تشتق اي دالة لاحقاً، 3.7 تطبيق فيزيائي للمشتقة، وهذا الدرس انصحك تحله باستخدام تشابتر 2 في PHYS101 لو انت تاخذه لانه اسهل بكثير، لو تنظر للسكشن بطريقة رياضية ممكن يصعب الامر قيلاً. سكشن 3.9 هو ثاني اصعب سكشن في الكورس، وهو تطبيق واقعي للمشتقة وهنا انا انبهرت، لانو اول مرة في حياتي كلها! وتعليم دام اكثر من ١٢ سنة…ارى تطبيق للرياضيات في واقع الحياه. الطلاب واجهوا صعوبات في ذا السكشن ولكن هي امثلة محدودة نسخ لصق بتجي ولكن بارقام مختلفة. سكشن 3.11 رح تاخذ فيه مشتقة الدوال الهيبربوليكية (معرف المعنى بالعربي) Hyperbolic functions، سهله ولكن لا تلخبط بينها وبين الدوام المثلثية العادية انتبه! اكثر تشابتر متعب ويتطلب جهد هو تشابتر 3 لانه كل شوي تتعلم قانون جديد وتحتاج وقت للتطبيق وحل الاسئلة الكثيرة ورح اقولك من فين تحصل اسئلة كثير لذولي السكاشن (3.1-3.6) للتدريب. احذّرك من انك تعامل تشابتر 3 مثل تشابتر 2 السخيف (نعم بيكون سخيف بعد ما تاخذ تشابتر 3) التشابتر لا يقارن ابدا بسابقه. نصيحة اخ ومن مجرب تدارك الوضع قبل ان يتفاقم الحمدلله، كثّف الجهد (ضاعفه)، وانسى الحلم الي انت كنت قاعد فيه (تشابتر 2 واصحى وشوف الواقع وشد حيلك لانه الكورس بيبدأ يمرّن عضلاته عليك). السكاشن من 3.1-3.6 فيها تركات احذر منها. وعلى فكرة نسيت اذكر انه من سكشن 3.2 الى 3.6 تقريباً فيه فكرة في كل درس اسمها Higher Derivatives…ذي باختصار يقولك مثلاً جيبلي المشتقة رقم 50 او 43 او 100، ف انت لازم تشتق اكثر من مرة وبدقة! وتجد نمط، لو وجدت النمط حليت السؤال، المشكلة في ذا السكشن تكمن فيه انه لازم تشتق كثير وتاخذ وقت، واحيانا تخطأ فيه اول او ثاني مشتقة سهواً مما يخرب عليك كل الذي يلي الخطأ فتبدأ رحلة البحث عن الخطأ لما تلاقي عشوائية بدون نمط، ينتهي الوقت غالباً دون ان تجد الخطأ! فاحذر.\n\nتشابتر 4:\n\nفي تشابتر 2، انت تعلمت اللمت عشان تفهم المشتقة ومن ثم تستطيع ان تشتق، ثم طبقت على الاشتقاق في اواخر تشابتر 3، اما في تشابتر 4، هنا انت رح تستكشف سلوك الدالة وشكلها عن طريق المشتقة والخ.\nتشابتر 4 تقريباً مزيح من تشابتر 2 و 3، هو اصعب من 2 لا شك ولكن اسهل من 3 لانه ما يحتوي على الكميات الهائلة من القوانين والمسائل التي تحتاج لتدرب مكثف، اول ثلاثة دورس 4.1,4.2,4.3 اغلبهم كونسبت، كونسبت ونظريات بشكل غريب من ناحية انه نحن كطلاب بتروليين نرتاح ونجد انفسنا في حل المسائل، ليس في الكونسبت والتعمق والتبحر فيه. فيه جزء طبعاً من الثلاثة دروس ذولي يتطلب حل ولكن مو كثير وسهل لانك تعرف كيف تشتق كل شيء من تشابتر 3. مثلاً اذا كانت المشتقة الاولى لدالة تساوى عدد موجباً عند قيمة x=2 فهذا يعني ان الدالة متزايدة عند x=2. رح تدرس اختبار الدرڤتف الاول واختبار الدرڤتف الثاني وايش يعطوك والخ.\nسكشن 4.4 اراهُ اهم/من اهم الدروس…فاكر لمن قلتلك لمن تدرس تشابتر 3 رح تشوف 2 سخيف؟ وكذلك لمن تدرس تشابتر 4 رح تشوف 3…ذي المرة مو سخيف ولكن…اقول اسهل لانه اسئلة كثييييير تنحل باستخدام سكشن 4.4 او ما يسمى بـ L’Hospital Rule. تحياتي للعالم الذي اخترع هذا القانون! هذا القانون يحللك جميع اسئلة النهايات (اللمت) باستخدام المشتقة بخطوتين بسيطتين جميلتين لطيفتين، الدرس ذا يحتاج تدرب كثيير لانه فيله انواع كثير من اللمت. لانك كبرت ووصلت لتشابتر 4 ما صار الكورس يدلعك ويجيبلك نهايات سهله فيها دوال تربيعية بس وتنحل بدون ما تستخدم مخك (أبالغ طبعاً)! يحطلك كل انواع واشكال الدوال الي شفتها في كوكب الارض وخارجه (امزح طبعاً) داخل اللمت وتحتاج تعدل على اللمت حتى تقدر تحله باستخدام اللوبيتال رول، بمعنى لازم تعدل شكل ما في داخل اللمت حتى تقدر تطبق اللوبيال…يعني مارح يجيك السؤال زي الموزة المقشرة جاهزة الاكل!\nالدروس الثلاثة 4.5,4.8,4.9 سهلين لا تفوتهم، واحد يتكلم عن خط التقارب المائل ان صح التعبير (Slant Asymptote) و الثاني عن الNewton’s Methods والاخير مقدمة عن التكامل الي رح تدرسه في MATH102 بمسى Antiderivative.\n\nمصادر مذاكرة MATH101، رح اقيّم المصادر الي انا استخدمتها فقط!\n\nالاونلاين كورس:\nممتاز جداً، مشروح من د.بدر الحميدي وايضاً د.جميل الاسماعيل كان له دور بسيط فيه. كل السكاشن مشروحة بشكل ممتاز وكافي من ناحية التمارين وتقدر تستخدم اكستنشن من كروم لتسريع الفيديو، لو ما فهمت من دكتورك وحاولت تفهم من النوتات او الكتاب ولسا ما فهمت انصحك بقوة تشوفه قبل لا تدور اي مصدر خارجي من اليوتيوب او غيره للفهم، (حلل مصادر الجامعة قبل تلجأ لغيرها).\n\nالكتاب (الي هوا Calculus by James Stewart): ممتاز جداً، كشرح وامثلة وايضا التمارين الي فيه ممتازة جدا للتدرب لانه يوفر لك كمية كبيرة من الاسئلة تتعرض لها. حل التمارين كلها الفردية والزوجية منها، طبعاً حل فقط الاسئلة الي صيغة سؤالها قد ترد في الاختبار. مثلا، مو تحللي سؤال يقولك ارسم شكل الدالة…الخ. ذا ما رح يجي فلا تحله. تمارين الكتاب مفيد جداً في السكاشن 3.1-3.6 و 4.4.\nللمعلومية: نوتات محسن مرجعها الكتاب وتقريبا هي زبدة شرح الكتاب ومخلص للدرس من الكتاب، بتشوف التعاريف والامثلة نشخ لصق من الكتاب. فانصحك بطريقتين لفهم الكونسبت، اما من الكتاب او نوتات محسن او نوتات دكتورك الخاصة ان كانت شاملة.\n\nنوتات محسن:\nممتازة جداً، وهي كما قلت سابقاً ملخص للكتاب بحيث ينقلك فقط ما يهمك وبصورة شاملة وبدون ما يسحب على شيء مهم او يعطيك المعلومة ناقصة. وايضاً حط فيها د.محسن جزاه الله خيراً اسئلة من الاولدات فيها كتمرين اضافي بعد الامثلة. النوتات مكتوبة بخط اليد ولكن هي واضحة جداً ومفهومة تماماً ولمن تتعود عليها ما ودك تروح لغيرها. اشوفها اسهل لفهم الكونسبت من الكتاب لانو خطوات الحل اوضح بكثير.\n\nاولدات محسن:\nممتازة جداً، اولدات عادية طبعا وميزتها انها باي-سكشن من الترم 171 الى 183 وبالنسبة لبعض الدروس هي اكثر من كافية نظراً لعدد الاسئلة الكبير الي توصل 35 في بعض السكاشن ولكن في البعض الاخر قليل ولا يكفي، وهنا تقدر تعوض النقص من الاولدات الي فموقع قسم الماث ولكن بتجيك على شكل مياجر/فاينلات ولكن هنا بتضطر انت تدور اسئلة على السكشن الي تبغا تتدرب عليه عكس اولدات محسن الي مجمعها باي-سكشن جاهزة لك.\n\nطريقة المذاكرة الي انصح بها (+انا سويتها):\n\nمراجعة الكونسبت السكشن من خلال اما نوتات دكتورك الخاصة او الكتاب مباشرة او نوتات محسن، اذا دكتورك عنده نوتة خاصة به افضّل انك تعتمد على المصدر الي يعطيك اياه دكتورك لانه يدرسك وايضاً قد تفيدك في الكوزات واسهل للمراجعة.\nبعدها حل الاسئلة المقترحة في السيلابوس (هوموورك وريسيتيشن) والتمارين الي فالكتاب، كل تمرين في الكتاب صيغه سؤاله هي نفس الامثلة الي اخذتها في الدرس او باختصار اي سؤال في الكتاب في ذات السكشن قد ترد صيغته في الاختبار فحله.\nثم روح لاولدات محسن باي-سكشن وحل كامل الاولد المجمع لك وكذا تكون قفلت على السكشن ١٠٠٪؜ وان شاء الله تكون فاهمه تماماً وحافره في بالك، عادةً اذا تفرغت للماث عشان تقفل سكشن كامل ياخذك يومين او احياناً ثلاث ايام لو كانت التمارين كثيرة زي في تشابتر 3.\nيفضّل بقوة ترتب نفسك على اساس قبل كل كويز تكون جاهز وحال اسئلة الكتاب والاولد، وللمياجر راجع الاولدات والمفاهيم وحل كم سؤال من كل سكشن وامورك ان شاء الله تكون تمام التمام.\n\nالختام:\n\nختاما. الكورس مهو صعب بل بالعكس سهل جدا للفهم وممتع للامانة وخفيف… حتى في مرة قلت لنفسي من باب المزح… لو كل الماث زي 101 كان من المرجع اخذ مينر في الماث… ولكن كما تعلم يا صديقي ليس كل الماث مثل 101.\nاذا رح اقارن ماث 101 ب الفيزيكس 101 او الكيميستري 101. فرح اقول انه هو اسهل من الفيزيكس 101 بكثير واسهل بفارق بسيييط عن كيميستري 101. ماث 101 كورس حق قريد فلا تفوته وتفوق وتميز يا عزيزي.\n\nان شاء الله اكون وفقت في هذا الطرح.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-101-calculus-i/120611/42", "user": "Housam-AE", "ts": 1624700502000, "tid": 120611, "pn": 42}}', 1624700502000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p957120-math101', 'stk-user7529', 'MATH 101', 'srcP', '{"html": "السلام عليكم<br>في المرفقات اخر ٤ فاينلات<br>دعواتكم ،،،<br><br>​<span data-fid=\"stk-f957120-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957120-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957120-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957120-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f957120-0": {"name": "MATH101_092_FINAL_ANSERS.PDF", "v": "data:application/pdf;base64,"}, "stk-f957120-1": {"name": "Math101_093_Final _Solution.pdf", "v": "data:application/pdf;base64,"}, "stk-f957120-2": {"name": "MATH101_101_ FINAL_AnswerKey.pdf", "v": "data:application/pdf;base64,"}, "stk-f957120-3": {"name": "Math101_102_FINAL_Master.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exam-101/117309/5", "user": "user7529", "ts": 1325440566000, "tid": 117309, "pn": 5}}', 1325440566000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p597015-math101', 'stk-f5m', 'MATH 101', 'srcP', '{"html": "دعواتك , 🌹<br><br>​<span data-fid=\"stk-f597015-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f597015-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f597015-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f597015-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f597015-0": {"name": "MATH 101Exam 2 (091) Solutions .pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e55f03ec26df2048dc703aecce6dda9627ab8c1c9348b0edf8406a47d69a9c87"}, "stk-f597015-1": {"name": "MATH 101Exam 2 (083) Solutions .pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/7725d6ee6167d0c774b20a1e409e8cf534cb5831a0066cf91dca48f03256650b"}, "stk-f597015-2": {"name": "Math 101Exam 2(082) Solutions.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/250ef5f81234d0e171230c0fa56f92c74eb2e090df4ca9255dfa9ef62a1f08ee"}, "stk-f597015-3": {"name": "MATH 101Exam 2 (081) Solutions .pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/36f41d8d01e89aebaae39214f08b55ae4c602b7766cea43efad67e3c2c0ac9e9"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-2/87404/2", "user": "F5M", "ts": 1272651985000, "tid": 87404, "pn": 2}}', 1272651985000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p577116-math101', 'stk-mr.wswas', 'MATH 101', 'srcP', '{"html": "http://www.kfupm.edu.sa/MATH/CalculusResults_pages/Math101_091_E1_Solution.pdf<br>هذا الرابط واذا مافتح معك حطيته لك بالمرفقات 👍<br><br>​<span data-fid=\"stk-f577116-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f577116-0": {"name": "Math101_091_E1_Solution.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/078c9e51eff602bc7e45c940516a7d2c47678f292a1a7797d4b8fc509ffce5c8"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exam-math-101-091/86178/3", "user": "mr.wswas", "ts": 1269878786000, "tid": 86178, "pn": 3}}', 1269878786000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1068842-math101', 'stk-_j_h', 'MATH 101', 'srcP', '{"html": "السلام عليكم ورحمه الله وبركاته …<br>هذا السليوشن نزلو لنا د.أحمد الدويك …<br>راح تحصلو فيه الأكواد كلها ما عليكم منها فقط شوفو الماستر فيرجن … :sneezing_face:<br>في المرفقات …<br><br>بشرو …<br>🌹<br><br>​<span data-fid=\"stk-f1068842-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1068842-0": {"name": "RelativeResourceManager.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/42de0ce3793f718914b17688704882f8b9758a62b93a020fef0aa18fc5744395"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-2/128946/1", "user": "_j_h", "ts": 1342601388000, "tid": 128946, "pn": 1}}', 1342601388000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar.a-math101', 'stk-omar.a', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68361", "n": "Dr. Faisal Fairag", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور فيصل فيرق … الله يذكره بالخير خلوق وحبيب جداً\n\nاخذت عنده ماث 101 سمستر 101 …\n\nشرح ممتاز جداً والصوت واضح يشرح بعض الكلمات بالعربي للي ما فهم\n\nيشرح من السلايدات ويحل اولد اقزامز كل كلاس\n\nالكويزات صعبة جداً … ناااااااااار … يجيب الاسئلة النادر ما تتكرر في الاولد اقزامز ويخليها اونلاين كويز\n\nالهوموركات ريتن …ما ادري هل تغير النظام وصارت على Webassine …\n\nالمياجر كومن …\n\nالدكتور ممتاز وشرحه رائع …لكن المشكلة عنده في الكويزات بس\n\nالقريد النهائي :: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856468-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-fairag/68361/37", "user": "Omar.a", "ts": 1308607339000, "tid": 68361, "pn": 37}}]}', 1308607339000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7684-math101', 'stk-user7684', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68361", "n": "Dr. Faisal Fairag", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 111 … ماث 101\n\nالتحضير : كل يوم بداية الكلاس وبعض الاحيان آخره … ولو تأخرت تقدر تروح له آخر الكلاس وبيحضرك.\nطريقة الشرح : سلايدات من أمثلة الكتاب بس بشكل أوضح , والتمارين أولد اقزام آخر الحصة … بالعربي توب التوب\nالكويزات : 35 اونلاين كويزز من متوسطة إلى صعبة وكويز واحد في الكلاس وواحد قروب كويز … << يحذف خمسة من الاونلاين كويزز\nالقريد النهائي: A+\nالصوت:ِ a+\nإضافات :لساني يعجز عن وصف هذا الدكتور الفاضل … ابتسامه لا تفارق شفتيه …\nمهما كثرت عليه الأسئلة يجيبك ويحرجك بأخلاقه …\nبالنسبة لآفرج سكاشنه كان بميجر 1 (( 83 )) والآفرج العام 70 … وميجر 2 (( 73 )) والآفرج العام 62 وآفرج الكلاس وورك كان حوالي (( 50 )) والآفرج العام (( 44 )) … << انسان شريح ويغرف درجات لطلابه وما يقصر معهم\nإذا لقيت فرصة وما قفلت سكاشنه نزل عنده وما راح تندم حتى لو كرفك\n\nالله يوفقك دنيا وآخره يابن فيرق …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p973020-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-fairag/68361/44", "user": "user7684", "ts": 1327400076000, "tid": 68361, "pn": 44}}]}', 1327400076000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7830-math101', 'stk-user7830', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68361", "n": "Dr. Faisal Fairag", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "--------------------------------------------------------------------------------\n\nترم 111 … ماث 101\n\nالتحضير : كل يوم بداية الكلاس وبعض الاحيان آخره . وماعنده ليت يعني لو تجي قبل الكلاس بشوي مافيه مشكلة يحضرك وبعض الحين ما يحضر يوم الاربعاء… !!\n\nطريقة الشرح : سلايدات ششرح واضحة بعدها يحل سؤال او سؤالين امثلة كتاب وبعدها اولد اقزام يمكن يحل لنا في الكلاس الواحد بمعدل 4 الى 6 اسئلة اولد اقزام طريقة حله يعرض السؤال في السلايد والاجابة تكون في السبورة يعني تكتب معها …\n\nالكويزات : 35 اونلاين كويزز من متوسطة إلى صعبة وكويز واحد في الكلاس وواحد قروب كويز … << يحذف خمسة من الاونلاين كويزز\nادري اان بعض الطلاب بيقول وش ذا 35 كويز بس والله راح تستفيدون جدا جدا … اذكر درجاتي كانت نازلة في الكويزات بس الحمد لله عطاني 54 رحت بعدها كلمته زودي 3 بوينت = 57\n\nالقريد النهائي: A+\nالصوت:ِ a+\nإضافات :شرح + ممتع الكلاس معه + حبيب جدا جدا + متساهل مع الطلاب + يدف درجات\nاصلا كورس ماث 101 كان من اسهل وامتع الكورسات بالنسبة لي مع فيصل فيرق فعلا ما كنت اذاكر الا قليل والحمد لله طلعت بقريد a لانه هو مايقصر في الكلاس يشرح ويحل لك اسئلة الاولد اقزام والاسئلة الكتاب … يعني ماكنت احتاج اذاكر بعدها 🤠\n\nبالنسبة لآفرج سكاشنه افرجنا لــميجر 1 83 وميجر 2 75 وحوله اما الكلاس اقسم بالله ان افرجنا كان 49 😲 والمشكلة الافرج الي طالبينه الديبارتمنت مفروض ما يتعدا 45 🤪\nعلى فكرة ترى افرج كلاسنا من 400 كان 312 يعني حول ال a يعني طلاب فصلنا اتوقع قريداتهم من +b وفوق …\n\nفي النهاية نصيحة مني إذا لقيت فرصة وما قفلت سكاشنه نزل عنده وما راح تندم حتى لو كرفك لان الكرف ذا راح يكون في مصلحتك …\n\nالله يوفقك يا دكتور فيصل دنيا واخره … ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p988607-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-fairag/68361/45", "user": "user7830", "ts": 1329560665000, "tid": 68361, "pn": 45}}]}', 1329560665000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-math101', 'stk-user8551', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68361", "n": "Dr. Faisal Fairag", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\n\nراح أنقل لكم تجربتي معه بماث 101 + ماث 102\n\n________________________________________\n\nماث 101 - ترم 111\n\n* التحضير : نادر ما يحضر ، ما يسجل المتأخرين ، يخصم درجة من 60 على كل غياب بدون عذر.\n\n* الشرح : عنده سلايدات (تحتوي على : صور توضيحية + أمثلة الكتاب “غير محلولة” + الكثير من أسئلة الأولد إكزام “غير محلولة” + أسئلة الكتاب + ملخص “أحيانا”) ، عادة يبدأ الشرح بمراجعة شفهية سريعة لما تم دراسته سابقا ، ثم يعطي نبذة عن الدرس الجديد (و إذا كان فيه قصه يذكرها \"مثلا قصة كف جاوس 😁\" ، ثم يبدأ يشرح من الصور اللي بالسلايدات و يحل الأمثلة على السبورة بطريقة منظمة ، بعدها يحل كم سؤال من الأولد إكزام (4 - 10 أسئلة كل كلاس ) ، و أخيرا يختار أو يخلي الطلاب يختارون من أسئلة الكتاب و يحلها.\n\n* الكويزات : تشكل النسبة الأكبر من درجة الكلاس وورك ، و هي ثلاث أنواع :\nأون لاين : 30 كويز على الويب سيتي ، يعطيك سؤال و يطلب منك الناتج النهائي فقط ، و أحيانا يكون سؤال خيارات ، لكنها صعبببببة جدا (أصعب من الأولد إكزام) ، لكني أضمن لكل واحد ينتبه بالشرح و يحل كل الكويزات إنه يطلع بـ A+ .\nفي الكلاس : كويزين طول السمستر ، مستواهم سهل إلى متوسط.\nقروب كويز : عبارة عن كويز لمجموعة من 3 أشخاص يختارون بعضهم ، مستواه صعب نوعا ما ، لكنه مفيد لدرجة ما تتخيلونها.\n\nالهومووركات : ما تشكل نسبة كبيرة من الكلاس وورك لكنه يخصم 1 من 60 على كل هوموورك ما تسلمه.\n\nطريقة حساب الكلاس الوورك : عادة يكون أفرج الكلاس الوورك عنده 35 (دليل على صعوبة الكويزات) ، و الأفرج المطلوب من قسم الماث 45 . فيكون عنده بونص حوالي 300.\nالبونص يعتمد على درجة الميجرين ، يعني مش كل الطلاب راح ياخذون بونص ، فقط اللي جابو درجات طيبة بالمياجر( أنا مثلا -و أعوذ بالله من كلمة أنا- أخذت بالكلاس وورك 38 و أعطاني بونص 40 😲 لأن درجاتي عالية بالمياجر).\n\n* الصوت : لغته الإنجليزية ممتازة ، يستخدم العربية أحيانا لتوضيح المصطلحات ، صوته واااضح.\n\n__________________________________________\n\nماث 102 - ترم 112\n\nمثل الكلام اللي بالأخضر ، لكن فيه إختلافات بسيطة.\n\n* الكلاس وورك : قسم الـ 60 على النحو التالي\n\nhttp://i45.tinypic.com/213hzb7.png\n\nيعني ما يخصم 1 على كل غياب أو على كل هوموورك ما تسلمه.\n\n* طريقة توزيع البونص : يوزعه بالتساوي على كل الطلاب ، يعني لو أفرج سكشنك 33 ، كل طالب يأخذ 12 بوينت بونص .\n\n_______________________________________\n\nإضافات :\n* لازم تكتب كل شئ مع الدكتور ، كثير من الطلاب يتوهقون وقت المياجر لأن ما عندهم مصدر يذاكرون منه … السلايدات بحد ذاتها غير مفيده لأنها عبارة عن أسئلة بدون أجوبة (أنت المفروض تكتب الأجوبة).\n* قد يكون الدكتور فيصل أفضل دكتور تقابله بالجامعة … أسطورة بأخلاقه و طريقة تعامله مع الطلاب … صعب إنك تنسى الأشخاص الطيبين مثله .\n* نسيت حاجة مهمة أذكرها … الدكتور دفييييييف بالريتين إكزامز … تأكد إنه راح يعطيك أكثر من حقك … و ما أحد يطلع من مكتبه زعلان 😉\n* من الدكاترة القلائل اللي يخليك تعشق مادته … راح تلاقي نفسك تروح قبل الكلاس بعشر دقايق.\n* لا تتردد إنك تسأله بالمياجر *__^\n\nو الله إني أفتقد “السلام عليكم يا شباب” مع بداية كل كلاس ، و “بسم الله الرحمن الرحيم” على السبورة.\nالله يحفظه و يوفقه و لا يوريه مكروه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048340-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-fairag/68361/49", "user": "user8551", "ts": 1338422879000, "tid": 68361, "pn": 49}}]}', 1338422879000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f.3.f-math101', 'stk-f.3.f', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68361", "n": "Dr. Faisal Fairag", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - Term 101\n\nوالله دخلت الموضوع مرات كثير !! من ترم 101 لين اليوم و كل مرررة اجي اكتب احس اني ما راح اوفي الدكتور فيصل حقه 😭 🥰 !!\n\nالتحضير : كان يحضر نهاية الكلاس و حفظ اسامي الطلاب من ثاني اسبوع ماشاء الله و اذا كنت تعبان او حصلك ضرف و ما قدرت تجي يقبل الاكسكيوز من الطالب شخصيا مو لازم تروح الكلينك\n\nطريقة الشرح : ممتعة ممتعة ممتعة ممتعة الف مررررة !! يشرح شوي سلايدات و يحل مسائل على البلاك بورد …\n\nالكويزات : اخذنا 29 كويز اون لاين !! 3 منها كانت نشاط تسويه و تاخذ 10 ف 3 كويزات\n\nالكلاس وورك: الافرج لازم يسير 37.5-45 و الدكتور يخليه 45 اللي هو اعلى شي !! انا سلمت بس هوموركين والله بس حليت كلللل الكويزات واخذت 52 !!!\n\nالمياجر: كومون و تصحيحه حلو\nالفاينلات : كومون\n\nالقريد النهائي: A+++++++++\nالصوت: 10/10\nإضافات : الدكتور المربي الفاضل فيصل فيرق ❤️ ❤️ ❤️ والله افضل انسان درسني في حياتي ❤️ و للاسف ما قدرت انزل معاه غير هذا الكورس 😭\n\nالله يجزاه الجنة ان شاء الله !! شكرا من القلب دكتور فيصل ❤️ 🌹 ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049026-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-fairag/68361/50", "user": "F.3.F", "ts": 1338567261000, "tid": 68361, "pn": 50}}]}', 1338567261000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr-6mo7-math101', 'stk-mr-6mo7', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68361", "n": "Dr. Faisal Fairag", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 181\nMath101\n\nالتحضير : ما حضر الا تقريبا في ربع الكلاسات او اقل .\nالشرح : افضل دكتور شرحا لماده ماث ١٠١ ممكن تشوفه ( على ضمانتي ) ، على الرغم من اني راعي فهاوه خلال الكلاسات في اغلب المواد ، الا اني ما عمري فهيت مع دكتور فيصل في كلاس واحد ( على الرغم من ان كلاسه هو الوحيد بدري الساعه ٨ وكلاساتي الباقيه كلها بعد الظهر ) ، ما شاء الله تبارك الله عليه . يبدا يعرف الدرس بشكل عام ويبدا من اول خطوه من الممكن ان يبدا بها دكتور ، ومن ثم ينتقل عبر سلايداته خطوه بخطوه عبر الدرس بشكل تدريجي وتقريبا في كل سلايد فيه سؤال او سؤالين يشرحون مفهوم السلايد ، الى ان يصل الى اخر السلايدات وهي عباره عن اولد اكزام بعضها قديم وبعضها جديد ويحلها مع الطلاب بكل حماس وبكل وضوع في الحل . وطبعا تقريبا مع كل جملة يقولوها خلال الكلاس يسئل الطلاب اذا فيه اي سؤال . كلاساته MW ويخلص درس في كل كلاس ومرات درس ونص ومرات درسين اذا كانوا سهلين .\n\nالكويزات: هذا الشيء الوحيد اللي الناس اختلفوا فيه على الدكتور ، هو بشكل عام يعتبر دكتور كريف درجة اولى ، ومتاكد الجامعه كلها ما فيها دكتور يكرف بنفس مستوى الدكتور فيصل ، قرابه ٧ كويزات كل اسبوع على البلاك بورد مع كويزات تقريبا في كل كلاس ، لونق كويز في الكلاس قبل الميجر ولونق كويز على البلاك بورد قبل الميجر بعد ، مع فتح قرابه ١٣ كويز على البلاك بورد قبل كل ميجر . كل هذا بغض النظر عن صعوبة الكويزات اللي يحطها ، فيه اسئلها اتوقع ان فيه دكاتره بيتعقدون فيها .\n\nالتعامل : اي واحد ينزل مع الدكتور يحسب حسابه انه بيتعلم ماث بافضل طريقه وبيشوف رجل ذو اخلاق من المتسحيل لاي شخص ان يرى مثل اخلاق ذاك الرجل ، ابتسامة دائمه في الوجه مع كلمات ترحيبيه عند الدخول في الكلاس مع فكاهه بسيطه خلال الكلاس ، جعل ربي يسعدك يا دكتور فيصل قد اخلاقك العاليه .\n\nالدكتور بشكل عام هو افضل دكتور ممكن للطلاب اللي مستواهم في الماث جيد جدا الى ممتاز ، وسيء جدا للطلاب اللي ناوين يراجعون اسبوع قبل الميجر او اللي اساساته في الماث سيئة . لاني بشكل عام اتكلم عن دكتور كويزاته عددها هائل جدا (تحذير للي يبدا يراجع للميجر قبل اسبوع )و دائما لا تخلو من الاسئلة اللي فيها اعتماد على ماث حق الاوريا ومرات تحتاج لفهم اكثر للسؤال ومرات تحتاج الى الاعتماد على الابتكار الرياضي في حل المسائل ( تحذير للي اساسته سيئة)\n\nالقريد النهائي :A+ من ادنى شك للطلاب المتميز رياضيا وغير مهمل ، اكبر F للطلاب المهمل والسيء رياضيا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503980-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-fairag/68361/72", "user": "Mr-6mo7", "ts": 1545615918000, "tid": 68361, "pn": 72}}]}', 1545615918000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hussain20-math101', 'stk-hussain20', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68367", "n": "Dr. A Boucherif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 / Term 131\n\nالتحضير : نهاية الكلاس و ما في مشكلة لو تأخرت اشوي\n\nطريقة الشرح : يبدا في الاثباتات ويبيك تفهمها و يركز عليها كثير …( أنا بصراحة ذي النقطة ما تعجبني كثير , لأن حنا ما راح نسوي prove … بس حلو… انها تعطيك فكرة ) … أحيانا يخلص الprove ويبغاك تحل … وحنا ما حلينا أمثلة عليه … واذا يحل … يحل بطريقة عامة (كشرح ) … فما تعرف كيف تجاوب عليه لو جابه بكويز او ميجر … لان حنا نحتاج كيف حل السوال لو قابلني … وهذا اللي ما يكرز عليه اشوي و يخليك ضايع …\nبس يحاول يفهمك … ولو ما فهمت عادي تقوله : عيد هذه النقطة … طبعا عنده نوت فيها أسئلة صعبة ممكن تستفيد منها … يقولوا و الله العالم زي ما قالوا اخواني الطلاب انها نفس النوت اللي تدرس في هارفارد … وهي جد صعبة مرررة\n\nالكويزات : اول السمستر صعبة نوعا ما … نهاية السمستر متوسطة\n\nالمياجر: كومن ( الميجر ال written يصحح و يحاول يعطيك درجة ع أي شي … ممتاز بالتصحيح)\n\nالفاينلات :كومن\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nإضافات : طبعا هو دكتور بالماث … ما شاء الله عليه … كبير بالسن ولذلك عنده خبرة كبيرة … دكتور أخلاق و محترم جدا و مبتسم و هادئ … يجاوب بالكلاس لو سألته بنفس طيبة … يحب ان الطالب يكون جاي للكلاس جاهز و عنده نوت يكتب فيها … يحب يشوف الطالب يكتب بالكلاس … و يعطي كلاس ورك كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1333357-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-boucherif/68367/14", "user": "Hussain20", "ts": 1393174171000, "tid": 68367, "pn": 14}}]}', 1393174171000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-math101', 'stk-guest', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث101\nالرجال كويس لكن شرحه عادي مافيه زود\nيقعد كلاس كامل على 3 امثلة بس\nتفهمها صح وتفيدك لكن اشوفها تضييع وقت\nيعني كلاس كامل يضيع على ثلاثة امثلة!!\n\nمشكلته يعطي اللي ما ينعطون وجه … وجه … وخذ لك الكلاس تنكيت وضحك وقلة سنع مع فكاهيين الكلاس\nانا جاي اتعلم ولا جاي اضحك في الكلاس!!\n\nما يكرف ابدا مخليك على راحتك لاهومورك ولاكويزات والغياب عنده بدرجة\nطلعت معه بقريد عالي عالي الحمدلله لكني اعتمدت على الكتاب وما انكر ان شرحه افادني للامانه\n\nهو ممتاز وشرحه كويس لكنه مهو الافضل،، احمد شوقي اصرف منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p781208-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/53", "user": "Guest", "ts": 1296775423000, "tid": 68565, "pn": 53}}, {"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 سمستر 121\n\nالتحضير: يكره التأخير، لكن لو غبت وعندك عذر مقنع يقبله مباشرة من دون أوفشل اكسكيوز\n\nالشرح: شريح ومتمكن جدا في توصيل الكونسبت، يهمه جدا أنك تفهم الكونسبت فممكن يعيد نفس المثال أكثر من مرة عشان تفهم\n\nالكويزات: متوسطة تميل للصعوبة\n\nالهومووركات:أون لاين كومن وتروح للكوردنيتر على طول فما بيده شي\n\nالكلاس وورك: يعطيك أكثر من حقك بشرط أنك ما تغيب، أما اذا كنت تغيب بكثرة وكويزاتك سيئة فما عنده مشكلة يخسف فيك ( في واحد ماخذ عنده حوالي 9 من 40)\n\nاضافات: الرجال في الأصل مهندس ففاهم التطبيق العملي للاشتقاق مضبوط وهذا شي جميل كما أنه محترم وفكره راقي إلى أبعد الحدود\n\nنقطة بسيطة: تصحيحه صارم ونهائي في الميجر، فلا تحلم يزودك لو ايش\n\nختاما: أنصح فيه وبقوة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1148686-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/49", "user": "Guest", "ts": 1356612520000, "tid": 68582, "pn": 49}}, {"id": "stk-dr-m83633", "n": "أ. أبالارا تيجاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ريسايتيشن ماث 101 ، 121\n\nأنا عندي قناعة من أيام الثانوي، المدرس اللي فاهم المادة مضبوط ومايعرف يوصل المعلومة بشكل سلس هو مدرس فاشل، وأرى أبالارا مدرس فاشل بقوة الأكسنت سيء جدا زي ماقالوا الشباب الشرح من جنبها والخطوات:\n1- هذا السؤال مرة مرة مرة سهل وسخيف\n2- مافي داعي نضيع وقتنا في ذا السؤال\n3- هذا حله كذا كذا(كلام بس من دون كتابة)\n4-يالله بأكتب الحل عشانكم مساكين\n5- يتنكب ويحله غلط\n\nنقطة صغيرة: حصل مرة عندي ظرف طارئ وغبت كلمته وقالي ما عندك مشكلة ، جزاه الله خير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165416-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/83633/19", "user": "Guest", "ts": 1358458319000, "tid": 83633, "pn": 19}}, {"id": "stk-dr-m68367", "n": "Dr. A Boucherif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101- 131\n\nمن افضل الدكاترة خلقا، كويزاته متوسطة مو سهلة ولا جدا صعبة،\nما يعترف بشي اسمه بروجكتر ولا بوربوينت. يحضر نهاية الكلاس ،ما يحب الي يزودها بالتاخير.\nشرحه يركز على التعاريف والاثباتات وما يحل امثلة صعبة.\nيبغالك تذاكر بنفسك في البيت وتحل قد ما تقدر من اسئلة الكتاب ولا تعتمد كثير على شرحه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1395565-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-boucherif/68367/17", "user": "Guest", "ts": 1409513148000, "tid": 68367, "pn": 17}}, {"id": "stk-dr-m81621", "n": "Dr. Slim Belhaiza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101-term151\n\nالتحضير : يحضر آخر الكلاس دايما وما ينسى ، أول السمستر كان يترك الباب مفتوح لو ماتحضر إلا آخر دقيتين حضرك بس بنهاية السمستر صار يشدد ويصك الباب أول ما يجي وقت بداية الكلاس بالضبط\nطريقة الشرح : يشرح من السلايدات غالبا ، وأحيانا يستخدم البورد لتوصيل الفكرة (يسميها الأولد سكول) ، يحل مثال أو مثالين أو ثلاثة على حسب الوقت ويجيب أمثلة صعبة بالعادة\nالكويزات :ما أذكر بالضبط بس أعتقد أخذنا 5 كويزات تقريبا ، مستواها على حسب المزاج والآفرج ،،\nفيه كويز وزعه وخلصناه بخمس دقايق ، وفيه كويز ةوعه وقال معكم الحصة كاملة ما راح نشرح شيء اليوم الكويز كان (الله وكيلك)\nالمياجر: كومن ، تصحيحه للمياجر متوسط يميل للكرم\nالفاينلات :كومن\nالقريد النهائي: C\nالصوت: لغة إنجليزية شمال أفريقية تونسية مادري وشلون بس واضحة ، اللهم يستخدم فوكاب صعب كثيييييييير\nإضافات : الرجل مرح ومتفهم وشخص لطيف ، لكن شرحه ليس بقدر ظرافته 90% كان سيلف ستدي ، لم أكن لأضعه خياري الأول أو الثاني\n\nأتمنى أفدتكم 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444939-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/slim-belhaiza/81621/42", "user": "Guest", "ts": 1458948610000, "tid": 81621, "pn": 42}}, {"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خالد الشمري - ترم 201 - ماث 101\n\nسيء سيء سيء سيء سيء سيء سيء سيء . حتى السوء يقول بأي ذنب اهنتني . هذا الدكتور هو التعريف المثالي للدكتور اللي خادع نفسه وشايف انه مؤدي لواجبه بكل اخلاص .\n\nالشرح : من اسوء ما رأيت , هذا لو يشوفونه علماء الماث والله يحولون بيع ورق عنب في الانستغرام مع كامل احترامي . الماث ماادة تدريب مب مادة لف ودوران في غراف الليميت اللي والله ما استفدنا منه ولا شي . اتوقع طول السيمستر حل عدد محدود جدا من الاسئلة لدرجة انه اذا حل مسألة صار قروب الشعبة المسكين يحتفل وكأنهم جايبين A في المادة . والله لو تحرث في الكونسبت رايح جاي بدون حل مسائل ما بتفلح . ايضا هذا الدكتور عنده قناعات غريبة جدا وتحس انه انسان عديم طموح ويرضى بأقل شي ويقول لطلابه ان الC درجة مشرفة . طبعا بما ان الترم اونلاين ف الشرح كان من بيته وعشان ابين لك قد ايش هذا الدكتور غير مبالي وكسول لما جا يطلب الياف بصرية عشان يعدل نته اللي من عهد الفتوحات العثمانية طردهم عشان حضرته يتعشى ونتيجة لذلك قعدنا حول الثلاث اسابيع بجودة صورة وصوت اسوء من السعودية الرياضية , متأملين انه يتعدل شرحه لما يجيب الياف . بعدها بفترة وصلت الالياف وليتها ما وصلت , من وقتها الدكتور مع احترامي صار لئيييم وتعامله جدا مبهم مع الطلاب . لو تسأله اي سؤال يجاوبك ب عشرين سؤال وياليت تفهم شي منه .اذا تدور دكتور يخليك اغبى ويصعب عليك المذاكرة فوق ما هي صعبة فهذا هو الدكتور المناسب لك . طبعا بعد كل كلاس يعطها تمغط ويقالك انه بذل مجهود وكان كلاس جدا مثمر ورائع ناهيك عن احتساء القهوة الساخنة اللي بجي لها بعدين…\n\nالتحضير : جدااااا شديييد , الدكتور احسه يحب يغيب الطلاب ومهتم في التحضير اكثر من شرح المادة . والله ما اكذب مرة حمل الحضور من مايكروسوفت تيمز اول ما بدا الكلاس ما صارله دقيقة حتى والله على ما اقول شهيد .\n\nالكويزات : من ويب اساين اسوء موقع شقته في حياتي , طبعا هذا الدكتور ما تطلع مهاراته في التقنية الا اثناء الاختبارات والكويزات , لو يستخدم نص مهاراته في محاولة قفط غش الطلاب لكان مدرس جيد لكن للاسف , عموما مرح تستفيد من كويزاته لانها كلها تجيب الحموضة وعديمة فائدة .\n\nالواجبات : يعطي واجبات في ويب اساين واتحداه ثم اتحداه انه حتى اخذ نظرة على الاسئلة . هذا يبين لك قد ايش هذا الدكتور اتكالي ويعطي واجبات لمجرد ضغط الطالب .بعض الاسئلة اجوبتها ارقام فلكية تحتاج للالة الحاسبة !!!\n\nاضافات : الدكتور خالد يحب يشرب القهوة اثناء الكلاسات , ايضا احيانا يفطر وياكل !! انا ما عندي مشكلة مع هالنقطة لكن لما حضرته يشرب وياكل يطلع اصوات جدا مقرفة مع كااااامل احترامي وتضيع التركيز , الكلاس هذا مو فسحة عشان الواحد ياكل ويشرب بل لازم تعطي الطالب كامل التركيز . انا ما اجلس 50 دقيقة يوميا عشان اسمع صوت شرب القهوة اكثر من حل المسائل حتى . طبعا لازم نذكر اصوات الدريلات والعمال في بيته اللي ايضا تسبب ازعاج للطالب . تحس انك قاعد في مخطط 51 في الدمام على هالاصوات . هل يعقل ؟؟؟؟\n\nفي النهاية المعذرة على الاطالة ونصحية زميل دراسة عانى من هالدكتور لا تسجل عنده ولا بتندم . التقييمات اللي فوق مع احترامي جميعها خاطئة وفيها نوع من التطبيل . والوعد الايفاليويشن .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526663-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/64", "user": "Guest", "ts": 1605195670000, "tid": 69876, "pn": 64}}, {"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 - 201 ( عن بعد )\n\nملاحظة : هذا الترم استثنائي وحالة خاصة و ممكن يكون الدكتور في الحضوري افضل من كذا بكثير .\n\nالتحضير : في البداية كان عن طريق سؤال تحضير بالبلاكبورد و ماله وقت محدد ، ممكن بـ بداية الكلاس او بالنص او بالنهاية ، بعدها صار يأخذ الحضور من تسجيل البلاكبورد .\n\nطريقة الشرح : عنده نوتة خاصة و يشرح على الـ one note ، شرح الدكتور اقل من عادي ، يعني لو تركز معه طول الكلاس بتفهم كونسبت بسيط واساسي بالدرس لكن ما يخليك تدخل على الاولد اقزام على طول ، بالنسبة للنوتة نفس الشيء عادية جدا وفيها كم سؤال من الكتاب لكن ما فيها اسئلة اولد اقزام ، غير كذا الدكتور يحل سؤال او سؤالين و الباقي يقول انتم حلوه بدون ما يعطينا الاجابات عشان نتأكد ، ايضا الدكتور ما ينزل حلول الاسئلة اللي يحلها بالكلاس و الريسايتيشن بل يقول ارجع للريكورد .\n\nالكويزات في الاونلاين : كل خميس على ويب اساين \" درسين الى ثلاث دروس \" ، نار و شرار ، و صعوبة الكويز تكون اما بأن الاسئلة صعبة أو الوقت ضيق او الاثنين مع بعض ، مبدأ الدكتور انه يكثر كويزات عشان بالنهاية يحذف اسوء كويز او كويزين لكن الواقع المؤلم ان كل الكويزات سيئة فـ وش تحذف و وش تخلي، الافرج بين 40% و 50% ، ايضا كانت حجة الدكتور من صعوبة الكويزات اننا نتجهز للـ assessment و midterm ، في النهاية كانت اسئلتهم اسهل بكثير وجاءت نفس افكار الاولد اقزام .\n\nاسئلة الكويز يختارهم الدكتور من الويب اساين فلا تضيع وقتك و تذاكر الاولد اقزام قبل الكويز .\n\nالمياجر: كومن\nالفاينلات : كومن\n\nالقريد النهائي: C ، و السبب كويزاته\n\nإضافات :\n\nالدكتور قمة في الاحترام و الاخلاق و يخجلك بطيبته و تواضعه ، ايضا يوم الميد كنسل كلاساته وخلاها كلها اوفيس اور \" 4 ساعات متواصله \" ، الدكتور سمعته تسبقه لكن ممكن الاونلاين خانه شوي ، ايضا الدكتور ما عنده واجبات وهذا شيء يحسب له .\n\nما انصح فيه لو كان الترم الجاي عن بعد ، لأنك حتى لو أخذت المادة سلف ستدي ، الكويزات غالبا بتلعب فيك .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526699-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/35", "user": "Guest", "ts": 1605458950000, "tid": 68408, "pn": 35}}, {"id": "stk-dr-m182895", "n": "Dr. Faisal Suwayyid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201 (math101 (online\n\nالتحضير :ياخذ سكرين شوت ببداية الكلاس في تيمز ونهايته علشان يشوف الحضور والتأخير\nطريقة الشرح : يشرح من سلاايداته الكونسبت وياخذ اسئلة اولد اقزامزس من اولد اقزامس محسن باي تشابتر و برضو حتى الكونسبت وطريقة شرحه في سلايداته تشبه سلايدات محسن بشكل كبير\nالكويزات : سهله جدا وهذا اللي يميز الدكتور+اغلبها من نفس افكار سلايدات محسن\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B+\nالصوت:واضح جدا لكن مشكلته متوتر وتحسه خايف وهو يشرح\nإضافات :الدكتور ممتازومتساعد اذا تبيه من ناحية كويزات وكلاس وورك وبونس وكذا , اما اذا تبيه من ناحية شرح فصعبة تحصل هذا الشي عند الدكتور فيصل. بالمختصر اذا انت من النوع اللي يعتمد على الدكتور من ناحية شرح وفهم كونسبت لاتنزل عنده نصيحه اما اذا ما همك الشرح وعندك مصادر ثانية تذاكر وتفهم منها زي الاونلاين فديو كورس او بعض شروحات الدكاتره الثانين في اليوتيوب فنصيحة نزل عند الدكتور فيصل لانك بتضمن درجات الكلاس وورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526701-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-suwayyid/182895/9", "user": "Guest", "ts": 1605493144000, "tid": 182895, "pn": 9}}, {"id": "stk-dr-m118569", "n": "Dr. Ahmad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 201 اونلاين، ماث 101\n\nبنود التقييم:\n\nالتحضير: من زوم، و احياناً يسأل في نص الكلاس واللي مو موجود يغيبه\nطريقة الشرح: عنده تابلت و يشرح عليه، شرحه ممتاز جداً ولو تركز معاه يمديك تدخل على الاولد على طول بدون مراجعة\nالكويزات: كثيرة و صعبة شوي و متنوعة بين ريتن و اختيارات، اخذنا 15 كويز كلها افرجها تحت 60%، في النهاية حذف علينا اسوء 5 كويزات\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: A+\nالصوت: واضح جداً\nإضافات: الدكتور في الاصل يدرس ماث 001 و 002 لكن بسبب كثرة الطلاب هذا الترم اخذوه لماث 101 و 102 و حسب كلامه بيرجع للاوريا الترم الجاي للاسف. الدكتور من افضل اللي مرو علي و درسني في الاوريا و بالحظ حطوه عند سكشني في 101 و الصراحة تاقلم بسرعة و كانه يدرس الكورس من سنوات مو كانها اول مرة له. اذا مارجعوه للاوريا لا تتردد تنزل عنده، واذا انت اوريا وجاك انبسط لانك بتفهم الكورس 100%.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527048-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-ahmad/118569/14", "user": "Guest", "ts": 1607609328000, "tid": 118569, "pn": 14}}, {"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الكورس/ (math 101 Term 201 (online\nالتحضير/ ما عنده نظام محدد. احيانا يطلب منا نكتب رقم في الشات ، و احيانا ينادي بالاسماء في وسط الكلاس ويطلب منك تحل سؤال و اذا ما عرفت تجاوب غايب، وفي محاضرات اخذ الحضور من التيمز بدون ما نكتب شي او يسأل.\nالشرح/ جيد، يشرح في البداية على السريع وبعدها يحل اسئلة ، بس عنده عيب كبير انه متقدم جدا في المنهج، يعني من قبل الاسسمنت كنا ناخذ ماتيريال الميد، وفي اخر الترم خلصنا الكورس قبل اسبوع او اسبوعين. طبعا ما عطانا اوف :no_entry_sign: صارت المحاضرات المتبقية حل اولد اكزام.\nالتعامل/ سيء جدا جدا، عادي لو ما عرفت تجاوب يمسكك تهزيء.\nالكويزات/ عن طريق ويب اساين في وقت الريسايتيشن، سهلة لو تذاكر قبلها بيوم تطلع بفل او درجة حلوة.\nالمياجر/ صارت اسسمنت وميد وطبعا كومون.\nالفاينل/ كومون.\nإضافات/ للأمانة الدكتور ما قصر معانا في مواعيد الكويزات، في بداية الترم اعطانا اوقات و ايام محددة وقال الاكثر تصويت عليها من الطلاب راح يصير هو يوم الكويزات و احيانا تصير مشاكل في الويب اساين ويعمل ميك اب للي صارت لهم المشكلة. بس للاسف الدكتور ما عنده مشكلة يضيع نص وقت المحاضرة يسأل في الطلاب شنو جواب هذا السؤال وشنو جواب هذاك وطبعا اذا ما عرفت غايب 👎.\nالتقييم النهائي/ C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527476-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/43", "user": "Guest", "ts": 1609562162000, "tid": 68413, "pn": 43}}]}', 1296775423000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-asmarica-math101', 'stk-asmarica', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68367", "n": "Dr. A Boucherif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 - 141\n\nبنود التقييم :\n\nالتحضير :\n\nيوميا في نهاية المحاضرة\n\nطريقة الشرح :\n\nغريبة جدا ما مر علي مدرس رياضيات في حياتي بهالشكل , يعقد الامور بشكل غير طبيعي وياخذ اغلب الحصة وهو يشرح الكونسبت بدون ما يعطي امثلة\n\nالكويزات :\n\nاعطانا 5 كويزات و حسب افضل 4 , مستواها من متوسط الى صعب\n\nالمياجر: common\n\nالفاينلات :common\n\nالقريد النهائي:\n\nD+\n\nالصوت:\n\nهذه مشكلة الدكتور الكبرى , الدكتور من الجزائر و لهجته الأساسية فرنسية و هذا الشي مأثر على الانجليزي بشكل كبير فتفهم عليه بصعوبة\n\nإضافات :\n\nأفضل ميزة في الدكتور أخلاقه العالية جدا و تصحيحه في اختبار الرتن للامانة ما قصر معانا\n\nنصيحة دور غيره ترى في افضل بكثير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420513-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-boucherif/68367/19", "user": "Asmarica", "ts": 1421663519000, "tid": 68367, "pn": 19}}]}', 1421663519000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bilal-math101', 'stk-bilal', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68372", "n": "Dr. Hattan Tawfiq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست معاه في ترم 111 ماث 101\n\nالشرح : والله شرحه مرة كويس كنت افهم منه اغلب الدرس و ابدا ابدا مو ممل !!!\n\nالكوزات: سهلة الى متوسط و مرررررررة مهي اسئلة مياجر !!!\n\nالتحضير : في اول الكلاس و الي يتاخر يحضره في اخر الكلاس …كان يحضر بداية كل كلاس في بداية الترم بعدين بدأ يتساهل و احيان كتيرة ما يحضر …و اذا كان مثلا يوم ربوع و بعده اجازة اسبوع مثلا فيحضر و يقول مح اخصم عالي غابو بس الي حضرو في بونس\n\nالي ما عجبني فيه حاجة وحدة : تصحيح الميجر كان ماشي عالسلوشن مانيوال بالملي ما يزود احد و ينقص على كيفه على عكس بعض المدرسين الي يدفو الطلاب\n\nو ترا والله المدرس مرة محترم و اخلاقه حلوة و بشوش الوجه\n\nالقريد النهائي : A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1021861-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hattan-tawfiq/68372/22", "user": "bilal", "ts": 1334339740000, "tid": 68372, "pn": 22}}]}', 1334339740000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4459-math101', 'stk-user4459', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68373", "n": "Dr. Abdeslam Mimouni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101\n\nالتحضير : غالبا يحضّر لكن يعرف الكلاس كامل ويعرف من الي حضر وغاب بس يزعل من الي يجي ليت\n\nطريقة الشرح : على السبوره ويحل كم سوال من الكتاب وكمان من الاولد اكزامز تبعه بس مشكلته ما يعطيك فكره جديده او مختلفه او يعطيك شي من برى الكتاب\n\nالكويزات : نوعاً ما سهله الى متوسطه واغلبها من اسئلة الهوموورك\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالصوت : واضح وبقوه\n\nالقريد النهائي: بي بلس\n\nاضافات : كلاسه حلو ويفهمك الكونسبت زين ومشكلته ما يحل اسئله كثيره , وهو دكتور طيب وكمان يزعل بسرعه اذا جاء يسأل سؤال وما احد جاوب او احد نام عنده في الكلاس , وكمان شديد في تصحيح المياجر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p695171-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdeslam-mimouni/68373/21", "user": "user4459", "ts": 1283285016000, "tid": 68373, "pn": 21}}]}', 1283285016000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saeed1-math101', 'stk-saeed1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68373", "n": "Dr. Abdeslam Mimouni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101 153\nالتحضير : ما حضر الا يوم السبت لان الجامعة طلبو منه وعادي تتاخر عنده بس بالمعقول يعني بالكثير 10 د\nطريقة الشرح : يكتب نوت عالسبورة كويسة بس احيان يقعد يكتب اشياء مالها داعي ويكتب كثير مررة لدرجة انه احيان يمسح السبورة اكثر من 3 مرات\nيحل اسئلة من السهل للصعب واخر شي يعطيك سؤال اولد اكزام ويحله\nالكويزات : صعبة اعتبرها نظامه 6 كويزات وياخذ افضل 4 منها كلاس ورك فقط بدون بونس ولا شي\nدايما تكون سؤالين سؤال سهل وسؤال صعب مرة اخر كويز في السكشنين محد جاب درجة كاملة .\nالمياجر: الريتن تصحيحه عادي يعطيك حقك بالضبط\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت:انجليزي يميل للمغربي على خفيف لكنه مفهوم\nإضافات : الاستاذ متمكن وقديم في الجامعة وفاهم الرياضيات مزبوط\nوافرج سكاشنه دايما فوق الافرج ( الميجر الاول كانو 6 و 8 فوق الافرج حتى الميجر الثاني والفاينل نفس الحال )\nلكن شوي عصبي واحيان يفصل على الطلاب وممكن يطرد الطالب اذا كان يقعد عالجوال دايم\nبعد الكويز الخامس وبسبب بعض الطلاب في احد السكاشن طردهم وقال مافي كويز سادس وبعد ما كلمناه وافق وسوا لنا كويز صعب محد جاب فوق 8\nالدكتور ينفع للدوافير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456447-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdeslam-mimouni/68373/42", "user": "saeed1", "ts": 1472816807000, "tid": 68373, "pn": 42}}]}', 1472816807000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11009-math101', 'stk-user11009', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68373", "n": "Dr. Abdeslam Mimouni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - term :173\n\nالتحضير :\nالتحضير آخر الكلاس و أيام ما يحضر ومو شديد عالتأخير.\nطريقة الشرح :\nيكتب عالسبورة الدرس والأهداف ثم الكونسبت ويبدأ يشرح عليه ويرسم ثم يحل أمثلة ويشرحها ثم يحل سؤال من ميجر قريب عليه . ستايل نوتة مرتب وجميل ووافية جداً جداً وأنصح بالكتابة معه.\nالكويزات :\nمتوسطة ويبيلها مذاكرة كويسة , وتكون مشابهة لإختباراته السابقة الموجودة بموقع الماث\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nA\nالصوت:\nواضح ومسموع\nإضافات :\nالدكتور شريح ولكن احياناً الطلاب يسألون اشياء توه شرحها او شرحها قبلها بيوم فيتنرفز شوي منها . او اسئلة على افكار بسيطة من 001+002 هو يجاوب ويشرح لكن لازم تأخذ لك تأنيب انك وصلت 101 ونسيتها. فيفضل تراجعها عالسريع وتراجع الدروس المرتبطة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498907-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdeslam-mimouni/68373/45", "user": "user11009", "ts": 1536235988000, "tid": 68373, "pn": 45}}]}', 1536235988000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-math101', 'stk-khdsa2022', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 بترم 181\nالتحضير : ينادي الاسامي اخر الكلاس , لا تتاخر لانه بيعطيك نظرة استحقارية. :no_entry_sign:\nطريقة الشرح : عنده نوتة ممتازة يشرح منها ويحل التمارين اللي فيها\nالكويزات : متوسطة الى صعبة ( ممتعة اذا تحب الرياضيات )\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: a+\nالصوت: واضح\nإضافات : الدكتور شرحه سريع , تحتاج انك تمر على النوتة قبل الكلاس (10 دقايق ) عشان تمشي مع شرحه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513292-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/30", "user": "Khdsa2022", "ts": 1564835470000, "tid": 68408, "pn": 30}}, {"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "منقول عبر واتساب\n\nبنود التقييم\n\nاسم المدرس : ازهار احمد\nالمادة : math 101\nالترم: 183\n\nالتحضير : سلسل جدا مايحضر الا قبل نهاية الحصة ب ربع ساعة تقريبا\n\nطريقة الشرح : سيئة جدا ( هو فاهم لكن مايعرف يوصل المعلومة واحيان يختصر بشكل كبير )\nولغته الإنجليزية ضعيفه وتعبانة فما بتفهم منه بعض الامور خصوصا اذا سألك ماتدري وش يبي\n\nالكويزات : متوسطة الى صعبة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C+\nالصوت: واضح\n\nإضافات : لا انصح احد ينزل عند هذا الدكتور اذا كان يأمل انه بيستفيد من حصة الماث وبالنسبة لاخلاقه فهو متعاون مع الطلاب وحبيب واحيان يحاول يطقطق في الحصة عشان يحسّن الجو ويضحك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513438-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/76", "user": "Khdsa2022", "ts": 1565118055000, "tid": 68928, "pn": 76}}, {"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nمنقول عبر واتساب\n\nاسم المدرس : منذر الفريدان\nالمادة : Math 101\nالترم: 183\n\nالتحضير : شديد (ما يعترف بالليت عنده يا حاضر او غايب)\nطريقة الشرح : اسطورية، اطلع ما احتاج اذاكر كثير\nالكويزات : نااار\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح جداً\nإضافات : الدكتور يحب ينكت كثير لكن مزاجي بقوة، لكن نهاية السمستر ما قصر ولله ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513443-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/64", "user": "Khdsa2022", "ts": 1565118575000, "tid": 68579, "pn": 64}}, {"id": "stk-dr-m78126", "n": "Dr. E Echi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "منقول عبر واتس اب\nاسم الدكتور : E ECHI (عثمان العشي)\nالمادة: MATH101\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : شديد فالتحضير و إذا تتأخر 5 دقايق ماتدخل\nطريقة الشرح : يشرح عالسبورة بالطباشير و خطته سيئة\nالكويزات : الكويزات مستواها متوسط و لكن بعد يكتبها ب خط اليد ف ممكن ذا يكون عائق فالاختبار\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: C\nالصوت: صوته واضح\nإضافات : غالبا يهتم ب الاثباتات بشكل كبير، كان بيكون مستواه أفضل لو كان يزيد من الاسئلة الصعبة بدال كثرة البروڤات (ماننكر إن بعض الاثباتات مفيدة جدا)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518744-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-echi/78126/30", "user": "Khdsa2022", "ts": 1578208481000, "tid": 78126, "pn": 30}}, {"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : بدر الحميدي\nالمادة:Math 101\nBY WHATS APP\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : والله ما كان طول الترم يحضر كان بس يحضر يوم الخميس\nطريقة الشرح :يشرح على السبوره وصراحة الي يحب يكتب مع الدكتور بيستفيد منه لانه يرتب شرحه وكذا ف سهل عليك للمراجعه\nالكويزات :كانت والله متوسطه تميل لصعوبه\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:A+\nالصوت:واضح جدًا\nإضافات : الدكتور بدر من افضل الدكاتره بالجامعة ويحاول انه يفيد الطالب ب اي شكل كان الشيء السيء الوحيد ان عنده سكشن واحد بس كل ترم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518794-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/88", "user": "Khdsa2022", "ts": 1578285800000, "tid": 68406, "pn": 88}}, {"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATS APP\nاسم الدكتور : محسن الشهراني\nالمادة: رياضيات 101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : متساهل جدًا، وبعض الايام مايحضّر والميك اب مفتوح.\nطريقة الشرح : يشرح نوتاته المتميزة بالتدريج الي يسمح لك تفهم خطوة خطوة + فيها افكار مهمة\nالكويزات : 4 اسئلة اختياري بس لازم تحل بالتفصيل، يعطيك وقت كافي للكوز. غالبا 3 اسئلة نفس مستوى النوتات وسؤال شوي صعب.\nالمياجر: لو تحل نوتاته والاسئلة الي حق كل سكشن بتشوف الميجر طقطقة\nالفاينلات :\nالقريد النهائي: بسبب ظروف خاصة جبت العيد\nالصوت: واضح جدًا\nإضافات : الدكتور شخص باذل نفسه للطالب، تحديث نوتات اول بأول ومسوي قروب للطلاب حق الاسئلة ويسوي مراجعة يوم الجمعة قبل المياجر وعند هلب سشن والخ…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518797-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/24", "user": "Khdsa2022", "ts": 1578286279000, "tid": 175316, "pn": 24}}, {"id": "stk-dr-m68577", "n": "Dr. Mohammad Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : محمد عمر\nالمادة: math101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يومي ويحاسب على الربع دقيقة\nطريقة الشرح : يفتح سلايدات ويقرأ واحيان يوضح ولكن شرحه سيء\nالكويزات : متوسطة الى سهلة\nالمياجر: مشتركة\nالفاينلات : مشتركة\nالقريد النهائي:\nالصوت: واضح\nإضافات : الدكتور جداً رسمي مع الطلاب واي غياب يسجله عليك ولو بالغلط ما راح يمتسح مرة ثانية حتى لو ما كنت غايب ، الدكتور اخلاقه جداً سيئة وشرحه جداً سيء ابداً لا يعتمد عليه ولو عندك فرصة عندك دكتور ثاني نصيييييييييييحة لا تنزل عنده ولا تفكر حتى لأن فعلياً كرهني بالسمستر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518806-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-omar/68577/25", "user": "Khdsa2022", "ts": 1578288352000, "tid": 68577, "pn": 25}}, {"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : خالد الشمري\nالمادة: Math 101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر قبل الكلاس ب ٣ دقايق واذا جيت على الوقت بالضبط اما يعطيك ليت او يغيبك و مب متعاون ابد بالتحضير حتى لو مبناك بعيد ما يسمح بالميك اب الا بعذر\nطريقة الشرح : شرحه قوي جدا تطلع من كلاسه وانت فاهم تدخل على طول اولد اكرامز ما يحتاج تراجع الكونسبت بس مشكلته انه ما يحل اساله صعبه في الكلاس بس يحل اساله بسيطه عشان توضح الفكرة و الباقي عليك\nالكويزات : اول كويزين عاديه بعدها يجيبلك كوزات من زحل\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : دكتور ممتاز جدا وتفهم معه لكن لازم تطلع من الكلاس وتبدا تحل اساله انت تطلع من كلاسه تقول وش المادة البيض\nذي لكن لازم تحل اساله عشان تطلع بقريد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518813-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/53", "user": "Khdsa2022", "ts": 1578291377000, "tid": 69876, "pn": 53}}, {"id": "stk-dr-m68373", "n": "Dr. Abdeslam Mimouni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : عبدالسلام ميموني\nالمادة:math 101\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر غالبا مره بالاسبوع (الخميس) ويكون حافظ الاسماء.\n\nطريقة الشرح : يكتب بالسبورة الكونسبت ويعطي مثال او مثالين على الافكار ثم نهاية الدرس يعطي سؤال او سؤالين اولد اقزام.\n\nالكويزات :يعطي 6 كويزات متوسطة المستوى كل كويز عليه ١٠ بوينت وسؤالين وغالبا واحد سهل والثاني في ترك ، بالإضافة انه اذا الإفرج منخفض يحذف اسوء واحد ويسوي كويز سابع.\n\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B\nالصوت:واضح ، لغته سيئة بس ينفهم\n\nإضافات : ماعنده نوتة + الدكتور متمكن من المادة وفاهم بس عنده مشكله في يوم تحسه اسطوري ويوم يطول على أفكار تافه او مايعرف يوصل فكرتها + احيانا يترك أفكار مهمة بالدرس وتجي بالاولد اقزامز +لا تتوقع انه بيعطيك درجات فوق حقك حتى لو يقدر + بشكل عام خله آخر تفكر فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518829-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdeslam-mimouni/68373/47", "user": "Khdsa2022", "ts": 1578293892000, "tid": 68373, "pn": 47}}]}', 1564835470000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6966-math101', 'stk-user6966', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خخخخخخخخخ أخذ الكورس ولا احد جاوب على سؤالي فوق لووول. الظاهر اني بجاوب على سؤالي\n\nاحم احم\nماث 101 ترم 093\n\nالتحضير : تقريباً كل يوم يخلي ورقة تمر على الطلاب , وأحياناً ينسى خصوصاً لما يكون الدرس ضغط شوي\nالشرح : جيد جداً . ويحرق دمه وهو يشرح , وماعنده شي اسمه ما فهمت , يعني تفهم تفهم . اذكر مرة ما فهمت مسألة دوخة , قلت له “مستحيل افهمها يا دكتور” , ثم قعد يشرحها لي لما فهمتها صح وللحين مو ناسيها الله يجزاه خير.\n\nطبعاً هو اشتغل مع مهندسين كثير , فتلاقون تفكيره هندسي ويوافق كلام المهندسين . وله خبرة مجنونة بالكمبيوتر !! ( كان ودي اسأله هالسؤال لكن كل يوم اقول بسأله بكرا ثم نسيت اسأله ><\" ) . يعني يعرف في البرمجة وكتابة برنامج , ودايم يتكلم في الكمبيوتر وفي الكمبيوتر . ويربط الدروس بالكمبيوتر حتى !! ماشاء الله عليه.\n\nالدكتور بحريني ودرس الثانوية بالبحرين ( راح تسمع كلمة الهاي سكوول كثيير بالكلاس !! دايم يقول \"اذكر يوم كنا بالهاي سكول كنا نسوي جذي وجذي … ) يعني تحس انه صار دكتور بعد الهاي سكول على طول, ما عمره تكلم عن جامعته ابد ,\n\nمرة سألته قلت ليش ما تتكلم عن جامعتك دكتور وكله عن الهاي سكول ؟\nقال انا درست صح ماث بالهاي سكول , اما بالجامعة الدكتورة كانت ما تعرف تشرح\n\nماخذ البكالوريوس من البحرين , والباقي من اليابان .\n\nاخلاقه عسل وذوق ,\n\nكويزاته : من متوسطة إلى سهلة .\nالميجر الاول : كان سهل مرة , اما باقي المياجر كانت اختياري\n\nوطبعا حافظ اسامي اغلب الطلاب ويناديك باسمك “فلان اوكي ؟؟”\n\nبالضبط !!\n\nالنوتات : مهمة مرة , اذكر سؤالين بالميجر كانو نفس الي كتبه بالدفتر بالضبط وحتى نفس الأرقام !! ( وانا يا حظي ما ذاكرتهم للأسف اهئ اهئ )\n\nنزل عنده وانت مغمض , بتستمتع معاه . + هو انسان يعرف شنو يعني ماث فعلا ً!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p694810-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/18", "user": "user6966", "ts": 1283228133000, "tid": 68381, "pn": 18}}]}', 1283228133000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-besooo-math101', 'stk-besooo', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 ترم 121\n\nالتحضير :\nيحضر اخر خمس دقايق وكان يمرر ورقة توقع قدام اسمك … غالبا ما يحضر و عدد المرات اللي حضر فيها ممكن تنعد ع الاصابع\nطريقة الشرح :\nيكتب نوت ع السبورة ينقلها من ورقة … شرحه ممتاز بس عيبه انه سريع فأحيانا تضحي بالفهم عشان الكتابة\n\nالكويزات :\n\nمستوى الكويزات مرررررة صعععب وانا شايفه الصراحة اعلى من مستوى شرحه بمراحل :sneezing_face:\n\nالمياجر: كومون وتصحيحه للريتن ميجر لك عليه 😐\n\nالفاينلات : كومون\n\nالقريد النهائي: اديه A\n\nالصوت: واضح جداااا\n\nإضافات :\nالمدرس حبوب ومرة متعاون … يستقبل الاسئلة بصدر رحب وما يكمل الدرس الا لما يتاكد انك فاهم … واخلاقه لا يعلى عليها … انصح فيه وبشده 🙂\n+ يديك حقك وزيادة بالكلاس وورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1158444-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/37", "user": "besooo", "ts": 1357576843000, "tid": 68381, "pn": 37}}]}', 1357576843000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupmer12-math101', 'stk-kfupmer12', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 ( Term131 )\n\nالتحضير :\nغالبًا آخر الكلاس و أحيانا ما يحضر\n\nطريقة الشرح :\nيكتب ع السبوره و شرح بططططل تفهم الكونسبيت و يوضح جميع الجوانب …\nو أحيانًا يسوي بروف للقانون و تفهم من وين اشتق …\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح جدًا\n\nإضافات :\nأنصح في هالدكتور وبشده …\nمتعاون و يجاوب على أي سؤال …\nو معظم تدريباته أولد إقزام … ناهيك عن شرحه واضح وسلس =)\nاللي يبي يحب الماث ويمشي فيها ينزل عند الدكتور جعفر\n\nو بالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1287141-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/41", "user": "KFUPMer12", "ts": 1384419306000, "tid": 68381, "pn": 41}}]}', 1384419306000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-shawq-math101', 'stk-shawq', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 ترم 132\nدكتور جعفر شرحه ممتاز يفهمك كل شي بس شديد شوي في التصحيح\nالكوزات 6 وياخذ افضل 4\nالنوت اكثره اولد اكزام\nالتقييم النهائي a+\nنزل عنده و انت مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1371599-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/45", "user": "SHAWQ", "ts": 1401057833000, "tid": 68381, "pn": 45}}]}', 1401057833000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9534-math101', 'stk-user9534', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "132 - ماث 101\nشررررررررح ممتاز جدا 🥰 … يحل اسئلة من الاولد اكزام واسئلة وامثلة الكتاب (منوع)\nكويزاته من الاولد اكزام والنوت …\nاختبرنا 6 واخذ أفضل 4 …\nمشكلته التصحيح !! خسف فينا في ميجر الريتن 😐", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373666-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/46", "user": "user9534", "ts": 1401336882000, "tid": 68381, "pn": 46}}]}', 1401336882000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rygart-math101', 'stk-rygart', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101-151\n\nالتحضير : كل محاضرة ، اول الترم كان يحضر في البداية و اخر الترم صار يحضر في النهاية\nطريقة الشرح : صراحة أشوفه مدرس مظلوم شرح رهيب و بسيط ، يشرح بالانجيلزي و اذا شاف ما احد فهم يحول عربي و مرات كل الشرح بالعربي\nشرحه ممتاز جدا انا ما توقعته كذا صراحة .\n* اول شيء يشرح القانون بعدين يحل امثلة الكتاب\n* بعدين امثلة هو يختارها\n* بعدين اولد اقزام\n* يتقبل الاسئلة ولو الاسئلة الغبية و يجابوها بكل رحابه صدر .\nالكويزات : الكويزات نفس مستوى المياجر ، لأنه كلها اولد اقزام اساسا ، اولد اقزام اترام قديمة 81-93\nاختبرنا 6 كويزات 4 كلها اولد اقزام .\nو اخر كويزين كانوا من الاسئلة بالسليبس\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت: واضح ولغته كويسه\nإضافات :\nالدكتور اخلاقه حلوة و يتقبل اي سؤال و يعاملك كأنك خويه\nالدكتور يرفع نوته لكل درس و فيها تلخيص للكتاب و اسئلة اولد اقزام .\nالدكتور تصحيحه للكويزات مو كويس ولا هو سيء مره ،\nلكن للمياجر تصحيحه كويس و افضل من الكويزات بشيء كثير و افرجنا بالريتن كان 80%\n* الدكتور ما يزودك ولا نقطة وحدة !\nبداية الترم قال ما راح ازود احد أبدا !\nوفعلا كان بقي لي نقطة لـ الاب قريد و لا زادني !\n** في النهاية انا ما كنت ناوي انزل عنده لكن قفل السكشن اللي ابيه و سجلت عنده\nلكن ما توقعت يكون بهذا المستوى و لو نزل ماث 102 بنزل عنده .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437706-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/48", "user": "Rygart", "ts": 1451703112000, "tid": 68381, "pn": 48}}]}', 1451703112000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-as2012sem-math101', 'stk-as2012sem', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH-101 Term 151\n\nالتحضير : يوميا وقليل ما ينسى يحضر\nطريقة الشرح : جدا جدا جدا جدا جدا خراااااااااااااافيييية أقسم بالله والله انه أحسن مدرس درسني ماث في الجامعة للحين\nطريقة شرحه من النوع اللي يخليك تخرج من الكلاس وانت ودك تمسك أولد إقزام من كثر ما انت فاهم الفكرة\nهو يشرح الكونسيبت في البداية بعدين يجيب كم مثال من الكتاب وبعدين يحل أسئلة أولد إقزام ويشرحها بطريقة بسيييطه جدا\n(يمكن فيه ناس ما يستانسون عليه لأنه أحيانا يشرح ويعيد في الشي أكثر من مرة)\nالكويزات : 6 كويزات مستوياتها متفارقة\nكويزين سهلة\nوثلاث كويزات واحد قبل الميجر الاول وواحد قبل الميجر الثاني وواحد قبل الفاينل (وهذي بالعادة تكون صصصعبة مرة)\nوواحد نسيت متى إختبرناه 😆\nالمياجر: أحس انه خسفني بتصحيحه للميجر الاول لكن أغلب طلاب كلاسنا كانو مبسوطين من التصحيح\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: ممتاز\nإضافات : نزل عنده لو حصلته صدقني ماراح تندم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437934-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/49", "user": "as2012sem", "ts": 1451855619000, "tid": 68381, "pn": 49}}]}', 1451855619000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majed07408-math101', 'stk-majed07408', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math-101 Term 152\nالتحضير :يوميا بالسيريال نمبر بعض الاحيان مايحضر\nطريقة الشرح : رهييييييييبه جدا جدا جدا\nوالله ماتوقعت انه فيه دكتور قادر انه يوصل المعلومه مثله ياخي غصبن عنك بتفهم.\nيبدأ بالكونسبت بعدين يعرض القوانين على البورد ويبدا بحل الامثل وشوي ويدخل في الاولد اقزام .\nقبل بدايه كل محاضره 3د او 5د يسترجع الي اخذناه في المحاضره السابقه.\n\nالكويزات : 6 كويزات مستواها مثل الاولد اقزام.\n\nالمياجر :تصحيحه بتحصل حقك او اكثر بعد مستحييل يعطيك اقل من حقك\n\nالصوت :ممتاز\n\nاضافه : نزل عند هذا الدكتور بدووووووون تفكير بتحصل عنده فهم وشرح ودرجات .\nمن افضل الدكاتره الي درست عندهم\nواذا حصل انه نزل له سكشن في 102 عنده ان شاء الله.\n\nالتقيم العام :A+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\nهذا واتوقع اني ماعطيته حقه يستاهل اكثر من كذا بكثييير[emoji18]\n\nفي النهايه لو انت منزل عن افضل دكتور في العالم\nاذا ماتتعب على نفسك ماراح تستفيد شي[emoji57]\n\nأرسلت من SM-G920I بإستخدام تاباتلك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446821-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/50", "user": "Majed07408", "ts": 1460828520000, "tid": 68381, "pn": 50}}]}', 1460828520000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10044-math101', 'stk-user10044', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 151 math 101\n\nالتحضير : يوميا نهاية الكلاس … ويهتم بالتحضير بشكل أساسي\nطريقة الشرح : نوتات مرتبة جدا بأولد قوام تفي بالغرض للمذاكرة مع اولداقزام الموقع\nالكويزات : أغلب الطلاب لا يعرفون من أين تؤكل الكتف بكوزات جعفر والأفرج دايما نازل !\nياشباب كوزاته من الكتاب خصوصا أنه يختار اسئلة الكتاب الصعبة والأسئلة الزوجية\nبكذا راح تأخذ درجة كويسة بالكلاس ورك .\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي:B\nالصوت: واضح وغير مزعج\nإضافات :\nالدكتور محترم جدا\nتصحيحه عادل اذا ما زادك ما ينقصك\nعادة يتغاضى عم الأخطاء التافهه بالحل\nطبعا بالنسبة لي ينصف كا أفضل دكتور ماث درست عنده بجامعة البترول …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448329-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/51", "user": "user10044", "ts": 1462674737000, "tid": 68381, "pn": 51}}]}', 1462674737000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulelahft-math101', 'stk-abdulelahft', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 161\n\nالتحضير: يحضر كل يوم لكن بعض الأحيان يشوف الوقت راح عالتحضير ويقول مو لازم تحضير. غالباً يحضر نهاية الكلاس.\n\nطريقة الشرح: يشرح بدون سلايدات عالسبورة، في البداية يشرح الكونسبت بعدين يبدا يحل أسئلة أولد اكزامز.\nشرحه رهييييييب يااخوان والله مايعدي نقطة إلا وأنت فاهمها وأحلى شي فيه حتى لو إن فيك نوم وتعبان مالك خلق شرحه وطريقة كلامه تشدك وتخليك مركز.\n\nالكويزات: ٥ أو ٦ كويزات في السمستر، متوسطة الصعوبة وواحد منهم لازم يكون صعب واثنين غيرهم لازم يكونوا سهلين. بمعنى في الكويزات ماعليك بتنبسط معه. ومتفاهم مع الطلاب يأجل مثل مايبون طلابه ويلغي دروس من الكويز وكل شي.\n\nالمياجر: تصحيحه كويس يعني يعطيك فوق حقك بشوي، بس لو بتروحله الأوفيس أور عشان يزيدك بوينتات مابيزيدك إلا لو صدق ظالمك. الرجال حقاني.\n\nالفاينلات: كومن.\n\nالقريد النهائي: A+++\n\nالصوت: واضح ومريح ماعليه كلام واللهجة بطلة ماشاءالله (بحريني الجنسية).\n\nإضافات: والله إنه اطلق دكتور ماث بالجامعة كلها ولو حصل لك ونزلت عنده انت محظوظ. الله يجزاه خير ❤️ ❤️ ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467291-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/52", "user": "AbdulelahFT", "ts": 1485778274000, "tid": 68381, "pn": 52}}]}', 1485778274000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mulla-math101', 'stk-mulla', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 171 - Math 101\nالتحضير :\nما يدقق ع التأخير ابداً.\nكان اهتم بالتحضير في اول اسبوعين، بس بعد ما شاف اغلب الشباب يحضرون وقف تحضير ولا رجع حضر.\nطريقة الشرح :\nأغلب شرحه بالعربي.\nعنده نوتات ينزلها لك ع البلاك بورد ويشرح منها.\nيبدأ بشرح كم مثال من الكتاب ثم مسائل اولد اكزام.\nالكويزات :\nمتوسطه.\nيجيب اسئلة من الكتاب والاولد اكزام بالنص.\nوصراحة اشوف انها معقوله للطالب المذاكر.\nالمياجر:\nكومن.\nالفاينلات :\nكومن.\nالقريد النهائي:\nيستاهل الA+ لو حصلته في كورس ماث بنزل عنده بدون تفكير\nالصوت:\nممتاز وواضح.\nإضافات :\nصراحة دكتور متمكن في الماث وشرحه اكثر من ممتاز، وماعنده مشكله انه يجاوب اي سؤال لو كان بسيط\nاذا حصل وقت قبل المياجر او الفاينل بيجلس يسوي مراجعة للماتيريال ويحل مسائل اولد اكزام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486864-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/54", "user": "Mulla", "ts": 1517131659000, "tid": 68381, "pn": 54}}]}', 1517131659000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohannadhs-math101', 'stk-mohannadhs', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101\nterm 172\n\nالتحضير :\nاول شهر ماكان يحضر بس شاف الطلاب يفلون امها بالغياب بدا يحضر اخر الكلاس ومايهتم للتأخير ويقبل ميك اب\nطريقة الشرح :\nشرحة جبار عن نفسي يعجبني ممتاز جدا وحل اسئلة من الكتاب ومن المياجر\nالكويزات :\nمتوسطة واذا انت فاهم صح بتشوفها سهله\nيعطيك 4 كوزات وياخذ الافرج لهم\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nA+ وانا مغمض\nالصوت:\nواضح واغلب شرحة بالعربي\nإضافات :\nلو اشوف اسمه باي كورس ماث بنزل عنده بدون لا اسأل اذا في احسن منه او لا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1489843-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/56", "user": "mohannadhs", "ts": 1522174208000, "tid": 68381, "pn": 56}}]}', 1522174208000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar.ab-math101', 'stk-omar.ab', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 172 - Math 101\nالتحضير : ما يدقق على التاخير واصلا نادرا يحضر بس جته فترة يحضر عشان بعض الطلاب فلوها وصارو ما يحضرون ابد\nالشرح :يبدا بالامثلة البسيطة وغالبا يسوي بروف لكل شي ندرسه ,طريقة شرحه جبارة تنفع الكل وتخليك تركز\nالكويزات: اعطانا 4 كويزات وكانت اغلب الاسالة تجي من الاولد كويزز الي من الموقع , اصلا الاسالة كانت سهلة للي مذاكر\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي : A ولو لقيت اسمه عند اي كورس بنزله\nالصوت: واضح واكسنت بحريني يلطف جو الكلاس\nاضافات : غير انه جيد بالشرح الدكتور ما شاء الله اخلاقه عسسسسل ويحب ان الطلاب يتجاوبون معه بالكلاس\nما ادري احنا افرجنا نازل وكان يبي يرفعه ولا شالسالفة بس لاحظت انه يدف دف مو طبيعي في تصحيح الكويزات وبعد الدف ذا كله اعطانا 6 بوينتس بونص\nانصح فيه خصوصا للطلاب الي مستواهم افرج", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492562-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/57", "user": "omar.ab", "ts": 1526535734000, "tid": 68381, "pn": 57}}]}', 1526535734000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-math101', 'stk-bader_alqahtani', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term172–MATH101\n\nالتحضير:بحضر اخر الكلاس و احيانا ينسى\n\nالشرح: يبدا يشرح فكرة الدرس و احيانا يعطي امثلة عليها من واقع الحياه عشان يشد انتباه الطلاب بعدها يحل امثله بسيطة و تتدرج من السهل الى الصعب و وتكون من اسئلة الكتاب و الاولد اقزامز و غير كذا منزل نوته يرفعها بالبلاك بورد ممتازة للمراجعة خصوصا الدروس ذي 3.7_3.9_4.7_4.8\n\nالكوزات: عطانا ٤ كوزات واحد قبل ميجر ١ و واحد قبل ميجر ٢ و ثنين قبل الفاينال\n\nالتصحيح: التصحيح صراحة ممتاز و يعطي الطالب حقه و ازيد بشي بسيط غير كذا انه فيه طلاب حلو بطريقة لوبيتال و الاشتقاق باليمت و اعطاهم الدرجة كامله 🥰\n\nالمياجر: كومون\n\nالفاينل:كومون\n\nالصوت: واضح جدا و اكسنت بحريني 🤣 اول كم كلاس كان يشرح انقليزي بعدها قلب عربي\n\nالتقييم: A+\n\nملاحظة: المدرس طيب و جدا متعاون مع الطلاب و خله يعرفك انك مهتم +عطانا بونس ٦ بوينتس اخر حاجه 😁2: بتسمعونه دايم يقول هذا كله خذيتوه بالهايسكول 😂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1496195-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/58", "user": "Bader_Alqahtani", "ts": 1532263019000, "tid": 68381, "pn": 58}}]}', 1532263019000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-maan_al-raddadi-math101', 'stk-maan_al-raddadi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH-102 , Term 181\nالتحضير: ما كان يحضر بداية السمستر الين ميجر 1 , بعدين سار يحضر غالب الكلاسات و احيانا لا .\n\nالشرح: يراجع الدرس حق الكلاس الماضي و يبدأ بالدرس الجديد , احيانا ما يراجع بس نادرا هالكلام , و المراجعة اشوفها شي يميزه لان دروس الماث بالعادة مترابطة فهالشي يفيد واجد. ان كان فيه شي من نستخدمه مثلا من ماث 101 او اي شي سابق يعطيك مراجعة عالسريع عليه\n\nالكوزات: عطانا ٤ كوزات واحد قبل ميجر ١ و اثنين قبل ميجر ٢ و واحد قبل الفاينال و كانت سهالات ممكن يجيك سؤال واحد هو اللي يبيله شغل شوي.\n\nالتصحيح: التصحيح برأيي اشوفه جدا ممتاز يعطيك فوق حقك بالراحة, حتى لو جوابك غلط لكن شاف المشكلة اشارة او شي بسيط و الحل يبين انك فاهم يعطيك معظم درجة السؤال.\n\nالمياجر : common\n\nالفاينل : common\n\nالصوت: ممتاز وواضح\n\nالتقييم النهائي : A+\n\nملاحظة : الدكتور حبيب و متعاون و ما يزعجه التاخير , يعني في ناس هالترم كانوا يجون بعد نص الوقت و كان يحضرهم عادي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504045-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/59", "user": "Maan_Al-Raddadi", "ts": 1545743873000, "tid": 68381, "pn": 59}}]}', 1545743873000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3794-math101', 'stk-user3794', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 092 ماث 101\n\nمدرس رائع جداً\n\nسبحان الله وجهه بشوش … وترتاح لما تشوف خشته\n\nشرحه عادي ع السبورة وأحياناً من سلايدات إذا كان الدرس يحتاج كتابة كثيرة … لا تعتمد كثير على نوته لأن أغلبها أمثلة سهله\n\nالتحضير بآخر كل كلاس … ونادر ما يمشي الورقة\n\nالتأخير عنده عادي … وبصراحه بعض الطلاب مصخوها معه … وكان ودي يكون شديد شوي بالتأخير\n\nسهل عنده تاخذ درجة حلوه بالكلاس وورك … لأنه أختبرنا 6 كويزات وكانت متوسطة الصعوبة … أخذ أفضل 4 … وفيه كويزين من أسئلة الواجب\n\nمتساهل بتسليم الواجبات\n\nصوته جيد\n\nبشكل عام المدرس طيب لأبعد درجة … وانصح تنزل عنده لكن لازم تشد حيلك\n\nالقريد النهائي : A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p639082-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/16", "user": "user3794", "ts": 1277013425000, "tid": 68383, "pn": 16}}]}', 1277013425000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_sleepy-math101', 'stk-mr_sleepy', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت مع ماث 101 ترم 091\n1) التحضير\nكل يوم\n\n2) طريقة الشرح\nجيدة جدا اعطيه 80% بس بصراحة النوت مااعجبني الامثله فيه قليلة يعني نوته مش ولابد\n\n3)الكويزات\nمتوسطة وهي اصلا كلها 3 كويزات\n\n4)المياجر +الفاينلات = كومون\n\n5)القريد النهائي\nاعطية b\n\n6)الصوت\nكويس\n\n7) إضافات\nالدكتور حبيب وخلوق وحقاني\nمن ناحية الكلاس ورك فمن السهل انك تحصل على درجة عالية 15%\nلان ثلثه على الغياب (لاتغيب) 5%\nوالثلث الثاني على الكويزات 5%\nوالثلث الثالث على الهوم ورك والله يسلم المينوال 5%\n\nتحياتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p560335-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/16", "user": "Mr_Sleepy", "ts": 1267944789000, "tid": 68385, "pn": 16}}]}', 1267944789000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mad_hfc-math101', 'stk-mad_hfc', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 term 161\nالتحضير : بداية كل كلاس وشديد شوي بالتحضير واذا جيت بعد ما حضر ياخذ اسمك نهاية الكلاس .\nالشرح : يجي محضر للدرس ب ورقه فيها ملخص للدرس شرحه جيد يشرح الكونسبت واحيانا يشرح البروف للنظريات ، بس مشكلته ما يحل اسئله كثير ، يحل مثالين او اكثر بشوي اللي هو اساسا محلول ومشروح بالكتاب يعني ممكن تفهم الكونسبت بشكل كويس لكن ما راح يثبت الكونسبت الا اذا حل اسئله كثير من الكتاب او من الاولد اقزام على الدرس < ممكن البعض يشوف هذا الشيء عليك انت ماهو على الدكتور اتفق معهم … لكن برضوه فيه دكاتره حريص جدا على انه يغطي كل الافكار والاسئله لطلابه ويخليهم جاهزين بشكل كبير للمياجر .\n\n+ علشان ما اظلمه كان قبل الميجر يفتح اخر اولد اقزام ويبدا يختار اسئله ويحلها او يقول اللي عنده سؤال في الاولد اقزام يقولي .\n\nالصوت : الصوت مناسب ماهو مرتفع مره ولا منخفض .\nالمياجر : كومون\nالفاينلات : كومون\nالقريد النهائي : اعطيه b\nاضافات : يرحب فيك بالاوفيس اور واحيانا اجيب انا سؤالين من الاولد اقزام تكون يعني صعبين شوي او فيهم فكرة وكان يحلها لكن تحسه يحلها لنفسه يعني ما يفهمك مظبوط .\nتصحيحه جيد يعطيك حقك ويمشي على الكي سيلوشن .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466836-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/25", "user": "mad_hfc", "ts": 1485168943000, "tid": 68385, "pn": 25}}]}', 1485168943000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah11011-math101', 'stk-abdullah11011', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\n\nmath101 163\n\nالتحضير : يحضر بدايه الكلاس ثم يحضر المتاخرين اخر الكلاس ما يدقق ابد على التاخير بس لا تفلها مره يعني\n\nالشرح : يشرح الكونسبت “”“” فقط\"“”\" وشرحه للكونسبت اعطيه من اربعه الى خمسه من عشره . شرح مره كونسبت مبهم مره فسألت عن كيف يجي سؤال من هالكونسبت وقالي بالحرف \" تبي اسأله رح شف الاولد اقزامز\" ومن بعد ما قالي كذا معد صرت اجلس بالصف الأول وصرت اجلس ورا. بعد اسبوعين قالنا الي يبي يستخدم جواله او ينام عادي بس يجلس اخر صف بالكلاس وكل اسبوع يزداد عدد الي يجلسون ورا الى درجه الصف الي ورا امتلى . هذي بالاضافه انه مايدقق على التاخير هي ميزاته الوحيده من وجهه نظري فقققططط وافرج الميجر الاول كان 57 والافرج العام كان 68 والثاني كان تحت الافرج بكثير بعد\n\nالكويزات : ثلاثه قبل المايجر وواحد قبل الفاينل يكرر الأفكار الي يحطها تقدر تشوف افكار كوزاته من الموقع اذا حليت الي بالموقع بتحل كوزه بالراحه لانها نفس الشي بس يغير الارقام قالنا ان كل كويز عليه 25 بس تصحيحه من 20 وقال لنا ان 5 هي بونص لكم ومستوى كوزاته متوسط الى صعب ، صراحه ما ادري كيف يدف بالكلاس ورك او لا لاني سويت دروب بس قد سألته مرتين عن ان بياخذ احسن كوزين او راح ياخذ الثلاثه كان يتهرب من الجواب ويقول كيف راح يفيك كم كويز باخذ شد حيلك وخلاص\n\nالدكتور اخلاقه جدا جدا جدا عاليه وانسان فاضل وواضح انه ذو علم بس اسلوبه وطريقه شرحه بالنسبه لي جدا ضعيفه ماعنده نوته وما يعطي هومرك او شي زي كذا قبل الميجر بيوم يفتح الموقع ويقول من عنده سؤال ويحله حركه حلوه الصراحه لكن مالها تأثير كبير يرحب بالأسئله والنقاشات بالماث بالنسبه انسان محترم وفاضل وعالم لكن كمدرس سيئ جدا\nللأمانه قابلت طلاب من سكشنا يحبونه مره ويبون ينزلون عنده الترم الجاي حاولت افهم منهم السبب وبروو انهم يحبون الي يشرح كونسبت اذا تبي تجيب عنده قريد بتتتتعععععبب كثير لان يبغا لك ترجع البيت وتحل تحل تحل تحل المنهج والكونسبت بسسسسييط وسهل لكن التركات بحر وما راح تعرفها الا بالحل وللاسف الدكتور ما راح يساعدك بهذا الشي رحت عنده بالافويس اور وهو نفس مستوى شرحه بالكلاس\n\nبالمستقبل مراح انزل عنده حتى لو تأخرت عن التخرج وزي ما قال الرجال الي فوق الي قبل ما انزل الماده عنده كنت احسبه يبالغ لكن اهرب منه هروبك من الاسد \" الاااا في حاله وااحده\" اذا كنت من طلاب ارامكو الي ماخذين المنهج وجاي تنام وتطقطق عالجوال وتسولف شوي بالكونسبت او راعي تاخير وبتاخذ الماده كلها من اولها لين اخرها سلف ستدي يحببه قلبك احذذذذذذررررر ثم احححححذذذرررر تنزل عنده بالصيف ااحححذذررر لان الصيف جدددددااا ضيق وهو يسرع بالمنهج مره فبتروح البيت وراك اطنان من الدراسه والسلف ستدي وما بتلحق صدقني \" صدقني من تجربه انقلها لك بامانه \"", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479635-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/26", "user": "abdullah11011", "ts": 1504124784000, "tid": 68385, "pn": 26}}]}', 1504124784000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-220v-math101', 'stk-220v', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 163\n\nالتحضير : يحضر من أول دقيقتين لكن يحضرك نهاية المحاضرة إذا كنت متأخر\nطريقة الشرح : يشرح الكونسبت ويحل عليه مثال وبعض الأحيان يجيب سؤال فيه فكرة ويسألنا عن طريقة حله أو يحله هو، أنا أشوف أنَ طريقة شرحه جيَدة ومقبولة لكن يعيبه أنه ما يحل مسائل كثير بس أنت في الأول والأخير أنت بترجع السكن وبتحل مسائل.\nالكويزات : متوسطة، كان الاختبار من 20 ويخليه من 25 (يعطيك 5 بونص)، اختبرنا 3 قبل الميجرين والفاينال، ونهاية الترم أخذ أفضل اثنين وزودنا في الكلاس ورك. بالنسبة للتصحيح يعطيك حقك يعني تحل نص السؤال يعطيك نص الدرجة، لكن لو جلست تخربط له طرق وقوانين من عندك والجواب النهائي غلط يعطيك صفر على السؤال.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: واضح\nإضافات : الدكتور قمة في الأخلاق ومتعاون، وقبل كل ميجر يستعرض لنا الاولد اكزامز واللي عنده سؤال منها يحله على السبورة. طبعًا كان صيف 163 ضغط أكثر من الصيفيات اللي قبل بحكم أنه حذفوا منه أسبوع، وكان الدكتور يعطينا ماتيريال كثير لدرجة أنه كان يعطينا بعض الأيام سكشن وأشوي أو قرابة السكشنين. في الأخير ما أشوف أن الدكتور سيء زي ما قالوا بعض الأخوة لكن ما أدري إيش مروا من ظروف.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480061-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/27", "user": "220V", "ts": 1505148353000, "tid": 68385, "pn": 27}}]}', 1505148353000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-math101', 'stk-mohammed_mag', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : خالد فوراتي\nالمادة: MATH 101\nالفصل الدراسي: 201 ( عن بعد , أون لاين )\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : التحضير شديد جدا\nيعني نص المحاضره بالتيمز , يقول الي فهم يرفع يده \" علشان يشوف الي يسمع كلامه مب حاط ميوت أو ساحب \" , وبعض الاحيان ينادي الاسامي بشكل عشوائي علشان يشوفك فاهم ولا لا\n\nطريقة الشرح : سيء صراحه , يعني يجيب النوم وما يفهم أو يدخل المعلومه , يبيله سلف ستدي\n\nالكويزات : سهله , تكون على الويب اساين لكن عيبها أن يمكن تغلطك على اسباب غبيه \" من الموقع يعني \"\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالصوت: ضعيف ويجيب الملل\n\nالقريد النهائي: C+\n\nإضافات : الكورس ثقيل جدا وما ينفع معه السيلف ستدي , ما انصحك جدا تنزل عنده اذا منزل ساعات كثيره .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527524-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/28", "user": "Mohammed_Mag", "ts": 1609691219000, "tid": 68385, "pn": 28}}]}', 1609691219000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-21m-math101', 'stk-21m', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : خالد فراتي\nالمادة: MATH 101\nالفصل الدراسي: 201 ( أون لاين )\nالتحضير : يسأل بشكل عشوائي عشان يشوف الي معاه والي لا واحيانا بعد مايشرح فكرة يطلب من الطلاب يرفعون اياديهم عشان يتأكد انهم معاه\nطريقة الشرح :يشرح الكونسبت و بطيء جدا بالشرح وفي كلاس الرياسيتيشن يحل اسئلة عشوائية ويحل الاسئلة بطرق طويلة\nالكويزات : 3 كويزات بس طوال الترم قبل كل ميجروقبل الفاينل وتكون سهلة من الويب ساين\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: بارد وخفيف\nالقريد النهائي: B\nإضافات : الدكتور كويس مرة اذا ناوي تاخذ المادة سيلف ستدي وتبي تركز على المواد الباقية\n* لازم تشارك معاه عشان مايسأل بشكل عشوائي *", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527563-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/29", "user": "21M", "ts": 1609777422000, "tid": 68385, "pn": 29}}]}', 1609777422000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-qranonymous-math101', 'stk-qranonymous', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 - term 203 (online)\n\nالتحضير: كان شديد ويحضر اكثر من مرة خلال المحاضرة (يسأل اسئلة ويقول ارفعوا يدكم) لكن هذا الكلام اونلاين- مدري وش وضعه بالحضوري-\nالشرح: كان يجيب امثلة ويشرحها والصراحة شرحه ما اعجبني لان امثلته الي يجيبها بسيطة وماكان يجيب لنا اولدات ولا اسئلة فيها افكار.\nالكويزات: على الويب اساين( اغلبها كانت final answer وقليل جاب لنا MCQ) - ثلاث كويزات في الترم كامل وبالنسبة لي وللاغلب كانت سهلة\nالصوت: واضح لكن يبيلك تقعد مركز لأن نبرته ثابتة\nالمياجر والفاينلات كومن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533363-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/31", "user": "QRanonymous", "ts": 1641636542000, "tid": 68385, "pn": 31}}]}', 1641636542000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a.ee-math101', 'stk-a.ee', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68389", "n": "Dr. Marwan Al-Momani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 في 143\n\nالتحضير : يومي عن طريق السيريال نمبر\nطريقة الشرح : يكتب على السبورة بطريقة جداً منظمة\nالكويزات : معظمها كان بسيط وما كان فيها تركات\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي:A\nالصوت:واضح جداً\nإضافات : 1-المدرس جداً متعاون ، ومتواجد دائماً في الأوفيس أور\n2- كان هو الكوردنيتر لهذا الفصل وكانت الإختبارات مختلفة بعض الشيء عن الإختبارات الماضية وتختبر فهمك الفعلي للمنهج", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425834-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marwan-al-momani/68389/11", "user": "A.EE", "ts": 1440589286000, "tid": 68389, "pn": 11}}]}', 1440589286000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-n9ar-math101', 'stk-n9ar', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68389", "n": "Dr. Marwan Al-Momani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 143\n\nالتحضير : يومياً\n\nطريقة الشرح : يكتب اهداف الدرس وبعدين يشرح الكونسبت وبعدين يعطيك ٩٩٩٩ مثال\n\nالكويزات : متوسطة\n\nالقريد النهائي : A+\n\nاضافات :\nالدكتور ملم ومتقن للكالكوليس\n\nيدرس الكالكوليس من عام ١٩٩٦ ميلادي\nماشاء الله\n\nSent from my iPhone using Tapatalk", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1431957-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marwan-al-momani/68389/12", "user": "N9AR", "ts": 1446551009000, "tid": 68389, "pn": 12}}]}', 1446551009000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mqr-math101', 'stk-mqr', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68389", "n": "Dr. Marwan Al-Momani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 171\n\nالتحضير : يحضر كل حصة نهاية الكلاس\n\nطريقة الشرح : يشرح كل شي على السبورة وعنده نوته هو كاتبها بنفسه وانت في الكلاس تنقلها عندك في الدفتر او تصور السبورة نهاية الكلاس طبعا المدرس يشرح كل نقطة بالمنهج وشرحه خرافي ويعطيك ٩٩٩٩ مثال على الدرس الى وصل في احد الدروس في شبتر ٤ قال تبون مثال بعد ولا خلاص .\n\nالكويزات : كانت سهل الى متوسطة وبعض المرات يجيبها نار ملتهبه وتصحيحه مره جديد وبعض المرات يمشي لك\n\nالمياجر: كومن\n\nالفاينلات :كومن\n\nالصوت: الصوت واضح\n\nإضافات : المدرس واحد من النخبة اللي درسوني الماث وشرحه مره كويس لكن فيه عنده ملاحظة وهو انه يشرح بسرعة وصراحتا ما اقدر الومه عن الشي هذا لانه المنهج طويل ويحتاج انه يسرع شوي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493194-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marwan-al-momani/68389/17", "user": "mqr", "ts": 1527562236000, "tid": 68389, "pn": 17}}]}', 1527562236000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-naaif-math101', 'stk-naaif', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68389", "n": "Dr. Marwan Al-Momani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 -172\n\nالتحضير : جيد حتى يتغاضى عن التأخير أغلب الأحيان ويحضر نهاية المحاضرة\nطريقة الشرح : طريقة تقليدية يقسم السبورة لشرائح ويعبيها أمثلة ( جيدة تفهم معاه )\nالكويزات : نسخ لصق من أسئلة الكتاب بس يختار أسئلة جامدة نقدر نقول من متوسطة مرتفعة الى صعبة، بس تصحيحه ممتاز\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح جدًا وثلاثة أرباعه عربي\nإضافات: الدكتور خلوق ومتساعد بعض الشيء ويبذل جهد اذا يناسب وقتك وهو أحد الخيارات نزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501557-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marwan-al-momani/68389/18", "user": "Naaif", "ts": 1540812399000, "tid": 68389, "pn": 18}}, {"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**MATH 101 \\- 171** التحضير : مرن ويسمح بالميك اب اليومي( هذي ميزة رهيبة فيه) لكن التأخير ما يسمح فيه لك ٥ دقايق اذا ما جيت أحضر له كلاس ثاني\n\nطريقة الشرح : على السبورة يشرح أمثلة وبعض المرات سلايدات الكتاب يعني ما عنده مصدر محدد.\n\nالكويزات : سهلة.\n\nالمياجر: كومون.\n\nالفاينلات : كومون.\n\nالقريد النهائي: A\n\nالصوت: واضح.\n\nإضافات: الدكتور خلوق ومتساعد وأيضًا يحفظ كل طلابه من أول اسبوع بالاسم يحفظهم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501561-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/7", "user": "Naaif", "ts": 1540814713000, "tid": 175799, "pn": 7}}]}', 1540812399000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammad-72-math101', 'stk-mohammad-72', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68389", "n": "Dr. Marwan Al-Momani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101 term182(ادرس عنده الحين)\nالتحضير :بنص الحصة ويمشي المتاخرين بس اذا تاخرت بزيادة يسال ليه متاخرين ليه متاخرين؟\nطريقة الشرح : يشرح من نوتة يسنخها على السبورة بعدها يحل مسائل الكتاب ويبين الفكرة( مانزلها لنا بالبلاكبورد مدري ليه 😆)\nالكويزات : من وسط الى صعب بس فيها فكرة و بسيطة\nالمياجر والفاينل بيد الكودنتيتر(حسين العطاس)\nالقريد النهائي: A+\nالصوت: من وسط الى ضعيف لازم تقعد قدام 😅بس القاعة صغيرة عشان كذا الصوت جاي واضح\nإضافات: الدكتور فاهم ويبيك تحل بطريقة وخطوات رياضية مثلا اذا بتحل الليميت لازم تكتب ليميت لمن تعوض بالارقام وكذا بس مايعيبه الصراحة لانه يعلمك الشي بالطريقة الصحيحة. والحلو فيه اذا فيه شي من ماث 001 او 002 يسويلها ريكال ويعلمنا الفكرة . بس مشكلته الوحيدة هي الساعات المكتبية يبخل علينا ويحط3 بس بالاسبوع ليه يادكتور:(ت\nفالنهاية اقولها وبكل ثقة ياحظ من ينزل عند مروان المومني 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505743-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marwan-al-momani/68389/19", "user": "mohammad-72", "ts": 1549367932000, "tid": 68389, "pn": 19}}]}', 1549367932000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-steeve_ram-math101', 'stk-steeve_ram', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68390", "n": "Dr. Ahmad Al-Dweik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت معه ماث 101 …الصراحة الحق يقال المدرس فاهم المادة بس ساعات السوفت وير يهنق كم من ثانية… عليه بعض الاغلاط في الحسابات على السبورة ولا ينتبه له الا المركز ميه ميه … يستخدم نوتته في الشرح … سريع جدا… يمسح السبورة واجد … الكويزات صعبة ويعيبها قلة الاسئلة يعني سؤالين بس عليهم 10 درجات… دقييق جدا في التصحيح… صوته مب اضح والكلام سريع جدا جدا جدا … القريد النهائي c-", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1355766-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-dweik/68390/39", "user": "steeve_ram", "ts": 1398172494000, "tid": 68390, "pn": 39}}]}', 1398172494000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-math101', 'stk-breaktheunbreakable', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68390", "n": "Dr. Ahmad Al-Dweik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term 161\n\nالتحضير :\n\nورقة تمر بين الطلاب. أذكر بعض الطلاب مرات يجوا متأخرين بحول 15 دقيقة عادي.\n\nطريقة الشرح :\n\nشرحه ما حبيته لأنه يستعمل سلايدات كثيير ويقعد يقرأ ويكتب بالسبورة قليل.\n\nالكويزات :\n\nمتوسطة مائلة للصعوبة.\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nأعطيه يمكن C+\n\nالصوت:\n\nواضح ومفهوم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492297-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-dweik/68390/47", "user": "BreakTheUnbreakable", "ts": 1526267677000, "tid": 68390, "pn": 47}}]}', 1526267677000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-euler-math101', 'stk-euler', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68391", "n": "Dr. Halic M", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أدرس عند حاليا ماث 101 ,\n\nماودي أظلمه لكن شرحه سيئ بالرغم من اجتهاااده ,\n\nالكويزات مفاجئة أحيانا , سهلة بس متشدد ف التصحيح ,\n\nلدرجة انو طلع افرج الكويز الأول 1.8 من 10 , 😐\n\nالقريد : D -\n\nماينفع معه إلا اللي مسوي للمادة سلف ستدي زي ماسوي حاليا ,\n\nوبالتوفيق ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p732905-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halic-m/68391/6", "user": "Euler", "ts": 1289038763000, "tid": 68391, "pn": 6}}]}', 1289038763000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-botos-math101', 'stk-botos', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68391", "n": "Dr. Halic M", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه ماث 101 ترم 111\nالتحضير : يومي بس مو بذيك الشدة لو جيت متأخر 10 دقايق يمشيها بس انتبه بتذكر ولا تزودها\n\nطريقة الشرح : على السبورة يشرح وفي سليدات إذا كان في رسمات بس الشرح 90% يكون على السبورة يحاول يجيب أمثلة بنفس صعوبة المياجر عشان يعودك\n\nالكويزات : ثلاث كويزات في الترم عليها 10 درجات كويز قبل الميجر الأول بيوم والثاني قبل الميجر الثاني بيوم كويز قبل الفاينل بنفس مستوى الكورس واسئلة المياجر\n\nالمياجر: كومن وتصحيحه حلو وما يدقق كثير بس يعطيك حقك\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: لكنة واضحة ويمديك تفهم معه\n\nإضافات :\nالمدرس أخلاق وانا مستغرب من الردود اللي فوق يا عالم انت مو في الأوريا تبي دكتور يمسك إيدك ويقلك تعال ادرس وحل وكويز كل أسبوع ويكرفك عشان تجيب قريد\n\nالدكتور هالك يشرح الكونسبت صح وأحلى ما فيه يجيبلك أمثلة صعبة بمستوى المياجر ويهيأك للمياجر والفاينلات\n\nالدكتور يحاول يحببك بالماث ويشجع الطلاب على اختيار الماث كتخصص لهم بالجامعة ويعاملك كطالب جامعي مو كطالب مدرسة والله إذا ماهتميت بمستقبلك ماحد مفكر فيك\nوعلى فكرة ماث 101 و 102 و201 مواد كومن يعني الشغل عليك\n\nنصيحتي إذا نزلت عنده حاول تكتب معاه عشان أمثلته حلوه وادرس أول بأول …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p957530-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halic-m/68391/11", "user": "Botos", "ts": 1325501625000, "tid": 68391, "pn": 11}}]}', 1325501625000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osaid-math101', 'stk-osaid', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68391", "n": "Dr. Halic M", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 - term111\n\nالتحضير : يوميا , يوزع ورقة تكتب فيها الآي دي … أحياناً يعدها و يعد الحضور وبعدها ينادي بالآي ديهات !\nطريقة الشرح : مدري هي طريقة شرح و لا طريقة تضييع المعلومة عن الطالب !\nالكويزات :صعبة بمستوى المياجر تقريباً\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: F\nالصوت: واطي و اللهجة أقرب للهجة ميريل رادوي لاعب الهلال السابق 😆 !\nإضافات :\nمدرس سيء جداً , يشرح لك بلا أي مثال بسيط من الكتاب أو شيء تحسه أمثلته يجيبها من مياجر!\nيبدأ على طول في الأسئلة المعقدة و في كل مرا يجيب سؤال يضيع أكثر من اللي قبله و إنت ما غير تضيع\nالمشكلة في الموضوع كامل إن لهجته تضيعك أكثر من شرحه ! و أسلوبه ممل جداً كنت أعاني من شرحه !\nكان يعطينا أول مثال بعد ما يكتب الكونسبت على السبوع و يكون أكثر من متغير بالأسماء بدون أي تعويض أي شيء !\nتصحيحه سيء جدا ! أنسى يزودك في أي شيء خصوصاُ في كويزاته !! في ميجر ون أضطريت أجيب السلوشن له علشان يعطيني حقي !\n\nنصيحة لا تنزل عنده حتى لو إنحديت لا تنزل الماث أبداً 😐 خخخ !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1134041-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halic-m/68391/12", "user": "Osaid", "ts": 1354895578000, "tid": 68391, "pn": 12}}]}', 1354895578000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah50-math101', 'stk-abdullah50', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68391", "n": "Dr. Halic M", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده ماث 101\n\nالمدرس في الشرح مو قد كذا يعني تقدر تاخذ منه فكرة عامه عن الدرس غير كذا لا\n\nالتحضير يومي بورقة تمر ع الطلاب\n\nمن اول يوم قال الي يستخدم أي جهاز في غير الدرس او نوتات راح يعتبر غايب وسوها في اكثر من طالب\n\nاهم حاجة انو اعطانا في الوب سيتي واجبات سؤال واحد كل اسبوع او اثنين ذي عليها بونص في الكلاس ورك\n\nاخر الكورس اعطى الي حاول او حل كم سؤال في واجبات الوب سيتي (يعني حل اكثر من ثلاث اسئلة ) بونص جاااامد\n\nالزبدة اذا تعرف تذاكر مع نفسك فذا دكتور ينفعك\n\nالقريد c+.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1222151-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halic-m/68391/17", "user": "Abdullah50", "ts": 1368500643000, "tid": 68391, "pn": 17}}]}', 1368500643000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-just_4_u-math101', 'stk-just_4_u', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اللحين ماخذ عنده ماث 101\n\nالتحضير : مرتين في الاسبوع ومرات مايحضر أبد\nطريقة الشرح :يستخدم الكمبيوتر لعرض نوت له موجود الآن بالجمعيه يعني يشرح وانت تحط ملاحظاتك على النوته\nالكويزات : من متوسط إلى صعب\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي:b\nالصوت:واضح\nإضافات :", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p353326-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/4", "user": "just_4_U", "ts": 1232369816000, "tid": 68395, "pn": 4}}]}', 1232369816000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-x_zero-math101', 'stk-x_zero', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "همممم انا زمااان اخذت معاه ماث 101 بترم 061\nشرحه فوق متوسط بشوي وصوته منخفض بس كان دايما يكتب على السبورة يعطي الطلاب اسئلة بالفصل كل واحد يحلها ويوريها للدكتور\nمدري عن الشباب يقولون انه يشرح من السلايدات بس يوم كنت عنده ما شرح من السلايدات الا مرة وحدة بس\nبس ما دام المادة 101 و 102 كومن احسن لك تدور دكتور شريح ينفعك بالاختبارات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p514776-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/21", "user": "X_zErO", "ts": 1262508105000, "tid": 68395, "pn": 21}}]}', 1262508105000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-math101', 'stk-hammmod', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nماث 101 ترم 141\nالتحضير : حبيب ووسيع صدر وما يخالف كثير في التأخير لان هو أصلا يتأخر يوميا 3-5 دقايق … والتحضير يكون آخر الكلاس لو حضر\nطريقة الشرح : جميلة جدا عنده نوت علي البروجيكتر فيها امثلة ويشرح لك المفهوم علي السبورة ويعلمك كل شيء من وين جاء ويحل شوية امثلة … يرحب بالاسئلة علي كل وقت\nالكويزات : قليلة ودسمة … لكن مهيب صعبة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح\nإضافات : الدكتور هو الكووردنيتور لجميع كورسات الماث … حبيييييب لآخر درجة ويقبل السوالف داخل الكلاس ومهوب متشدد عن نفسي استمتع بكل لحظة في الكلاس سواء كان يسولف أو يشرح.\nباختصار نزل عنده 101 ولن تندم\nيبدأ اول جملتين يبدأ بالانجليزي بعدين يقلب الشرح عربي تدريجيا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1416208-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/43", "user": "hAmMmOd", "ts": 1417206195000, "tid": 68395, "pn": 43}}]}', 1417206195000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the0skull-math101', 'stk-the0skull', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101\nفر منه فرارك من الاسد اذا تبي حل مسائل\n\nدكتور شرح كونسبت فقط يعني يمكن يجلس كلاس كامل يتكلم عن نقطه وحده بس\nوكلاس ممل لاخر درجه\nوكويزاته من متوسط الى صعب\nاسئلة الكويزات ماهي حول المسائل اللي يحلها بالكلاس\nيحل مسائل تافهه ما تحتاج الى دكتور يفهمك فيها\n\nلكن عشان ما نظلمه اعطيه b+ بالكونسبت فقط\nو f+ في كل شي غيرها باستثناء (التاخير والاخلاق )\nوملاحظه اخيره تصحيحه دمار\nوللي يقول دفنا بالكلاس وورك السبب لانه خسف الشعب بالتصحيح\nوتصحيح الميجر مافيه دف…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1416853-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/44", "user": "The0Skull", "ts": 1417438365000, "tid": 68395, "pn": 44}}]}', 1417438365000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-math101', 'stk-mohammedj', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term 161 math 101\n\nالتحضير : نهاية الكلاس , ما عنده مشكلة مع المتأخرين بس لا تفل امها وتتاخر دايم . وبعض الايام ما يحضر .\nطريقة الشرح :يشرح من النوت و ويكتب على السبورة . معظم الشرح شرح على الكونسبت و يحل بعض الاسئلة خصوصا اللي فيها أفكار غربية .\nالكويزات : 5 كويزات ياخذ درجة افضل 4 و الكويزات متوسطة مائلة للسهولة .\nالمياجر: كومن .\nالفاينلات :كومن .\nالقريد النهائي: A+++\nالصوت: واضح .\nإضافات : النوته حقته جبارة اشوف انها تغني عن الكتاب . مشكلتها تحوي على اسئلة صعبة جداا , اتعب واانا احاول احلها بالنهاية اكتشف انها غير متعلقة بالمنهج .\nالدكتور أخلاق و حبيب و مهتم ان الطلاب فاهمين , اذا حس اننا محنا فاهمين يروح يشرح بطريقة مختلفة و يعطي أمثلة كثير .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466527-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/47", "user": "mohammedj", "ts": 1484742995000, "tid": 68395, "pn": 47}}]}', 1484742995000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-uz0-math101', 'stk-uz0', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 191\n\nالتحضير : يحضر اخر الكلاس وبعض المرات ياخذ دقيقه او دقيتين زياده بعد الكلاس ويحضر فيها\nطريقة الشرح : الدتور فاهم الماده وشرحه مب مره لكن جيد جدا\nالكويزات : كويزاته عني اشوفها صعبه\nالقريد النهائي: B+ اعطيه\nالصوت: الصوت واضح ولكن ممكن لو تجلس بالاخير ما راح تسمع زين\nإضافات : الدكتور حبييييب ومتعاون مع الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518280-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/51", "user": "UZ0", "ts": 1577200718000, "tid": 68395, "pn": 51}}]}', 1577200718000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ibn_massoud-math101', 'stk-ibn_massoud', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 term191\n\nالتحضير : يحضر يومياً نهاية الكلاس … ومايدقق فالتأخير بس لا تفلها .\nطريقة الشرح : يشرح من سلايداته … يبدأ بالكونسبت ويشرحه وبعدها يحل أمثلة … واحيان يسحب على الأمثلة السهلة والتافهه ويحل الصعبه واشوفها ميزة فالدكتور انه مايضيع الوقت في اشياء بسيطة\nالكويزات : متوسطة مائلة للصعوبة … اذا كنت مذاكر بتجيب درجة حلوه … بس لازم تحضر للكويز كويس لأن كويزاته مو سهله\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح ومفهوم\nإضافات : الدكتور طيب ومحترم … الصراحه ماقد رحت له الاوفيس لكنه يتحمل بعض الأسئلة الغبيه في الكلاس ويجاوب عليها ومايسكت الطلاب زي بعض الدكاتره؛ لكن يعيبه أحيانا تصحيحه شديد وينقص على أشياء ماتستاهل .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518697-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/52", "user": "Ibn_massoud", "ts": 1578129682000, "tid": 68395, "pn": 52}}]}', 1578129682000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal.kfupm-math101', 'stk-faisal.kfupm', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 TERM211\nالتحضير : يوميا نهاية الكلاس ويتاخر بالتحضير يعني اذا كان عندك كلاس بمبنى بعيد عنه لا تسجل عنده\nطريقة الشرح : من سلايداته ونوعا ما اشوفها تضييع وقت ويحب اسئلة البرهان مرة\nالكويزات : صعبة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: واضح\nإضافات : الدكتور كلاسه يجيب النوم وما يحب الاسئلة الكثيرة ابدا ويعصب عليها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533280-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/56", "user": "Faisal.kfupm", "ts": 1641240347000, "tid": 68395, "pn": 56}}]}', 1641240347000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_boy1-math101', 'stk-cs_boy1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 MATH102 - 211 212\n\nالتحضير : اخر الكلاس ومرات بعد ما ينتهي الكلاس يعني بتتأخر على الكلاس الي بعده, مرتين فصل على التأخير وقال خلاص من الكلاس الجاي بحضر بأول 5د بس بعدين نسى الظاهر مدري بس سحب ولا كانه قال شي وصار عوافي تتأخر.\nطريقة الشرح : شرحة ممتاز يفهمك اذا مشيت معه\nالكويزات : في 211 كل الاسئلة سهله الا سؤال واحد هو الي عليه الكلام, لكن في 212 زادت صعوبة الاسئلة لكن لا زالت سهله (طبعا للي يذاكر وفاهم). تصحيح الدكتور كويس\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : الدكتور مره رهيب ومتساعد ويجاوب حتى على الاسئلة الغبية يمكن يطقطق عليك وعلى سؤالك شوي بس بيجاوبك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535284-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/57", "user": "cs_boy1", "ts": 1662376373000, "tid": 68395, "pn": 57}}]}', 1662376373000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-math_lover-math101', 'stk-math_lover', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68396", "n": "Dr. Suliman Al-Homaidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يدرسني ماث 101\nالتحضير: يحضر ولكن ليس بشكل يومي و شديد لو تأخرت على الكلاس دقيقة ممكن يفكر يدخلك بس لو دقيقتين لا تحضر الكلاس لانه يطردك\nطريقة الشرح: شررريح … يشرح لك التعريفات يخليك تفهم مزبوط يحل مسائل حلوة يبدأ بمسألة او اثنين سهلات و بعدها من متوسط الى صعب\nالكويزات: من سهلة الى متوسطة …بس لازم تذاكر مزبوط\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: A+\nالصوت: واضح جدا و يغير مستوى صوته من فترة لفترة\nإضافات: هذا المدرس يعجبوه الطلاب الي يفكرون صح نصيحة حضر الدرس قبل ما تحضر و راح حتفهم في الكلاس سلام سلام و الاكسنت في الانجلش جيد جدا\n\nانصحكم تنزلوا عند هذا المدرس لانه ممتاز ترا هو الان عميد كلية العلوم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p720374-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/suliman-al-homaidan/68396/14", "user": "math_lover", "ts": 1286899155000, "tid": 68396, "pn": 14}}]}', 1286899155000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hard-worker-math101', 'stk-hard-worker', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68396", "n": "Dr. Suliman Al-Homaidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 - Term 141\nالدكتور صراحة نظامه كان جدا عاجبني من ناحية شرح و تحضير … تقريبا ما كان يقروش الطلاب والوضع عنده كان سهالات\n, الشرح كان يجي يشوف ايش هو الدرس ويشرح من واقع خبرته أعتقد له أكثر من 20 سنه في مجال التدريس ( كان يبدا بالكونسبت ويعطينا كم مثال من راسه )… أحيان يجي مدرس بديل لكثرة انشغاله\n\nبالنسبة للكويزات أعطانا 7 كويزات وحذف منها أسوء ثنتين\nالمياجر كومون\nتقييمي للدكتور : B+\nصوته واضح جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1461879-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/suliman-al-homaidan/68396/19", "user": "HARD-WORKER", "ts": 1478466822000, "tid": 68396, "pn": 19}}]}', 1478466822000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_vip-math101', 'stk-_vip', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كان يدرسني بالرسيتيشن فماث 101 بس اكثر شي يدرس ستات\n\nالتحضير : يومي ينادي بالاسامي\n\nطريقة الشرح : ما شا الله عليه شريييييح وسمعت انه حتى حق ستات شرييييح برضو\n\nالكويزات : ما كان يعطينا كوزات بس حسب ما سمعت انه كوزاته على قد شرحه يعني صلخ لكن مالي تجربه شخصيه\n\nالمياجر: كومن بس اذا كانت فيده برضو على قد شرحه\n\nالفاينلات : نفس المياجر 🙂\n\nالقريد النهائي: كشرح اعطيه a\n\nالصوت: واضح جدا\n\nإضافات : حبوب ومزاجي فنفس الوقت يعني بعض الاحيان يعصب على اشياء تافهه وبعض الاحيان تشوفه ينكت ويضحك معاك\n\nنصيحتي نزل معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p350795-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/3", "user": "_vip", "ts": 1231683060000, "tid": 68398, "pn": 3}}]}', 1231683060000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-math101', 'stk-jafar_15', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101-161\n\nالتحضير : شديد في التحضير يوميا والكلاس يبدا على الوقت بالضبط ، غالبا تجي بعده بدقيقة يدخلك ، لكن تجي تصنيفات مايدخلك\n\nطريقة الشرح : ممتازة ، عنده نوته خاصة فيه كلها مسائل ويحلها\n\nالكويزات : صصصصصصصصلخخ\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالصوت: الصوت واضح\n\nإضافات : الدكتور شديد وفي مسألة التحضير مرات يمشي على التاخير بحدود دقيقة دقيتين لكن بعدها نادرا مايدخلك\nايضا الجوال ممنوع تستخدمه نهائيا وبكل بساطة يطردك اذا شافك تستخدمه ، تستخدمه في حالة انك بتصور السبورة فقط لا غير، و مايرضى انك تكتب وهو يشرح ابدا\nالدكتور راعي طقطقة فاذا كنت تزعل لا تنزل عنده او بكل بساطة كلمه اول كلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474056-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/58", "user": "Jafar_15", "ts": 1496064693000, "tid": 68579, "pn": 58}}, {"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101-162\n\nالتحضير : يومي بنهاية الكلاس ، ومايدقق على التأخير لكن يهزاك عليه\n\nطريقة الشرح : عنده نوتة خاصة ويشرح منها ، ويشوف الحل منها\n\nالكويزات : متوسطة الى صعبة\n\nالمياجر:كومن\n\nالفاينلات : كومن\n\nالصوت: ممتاز ، لكن مرات يتكلم بسرعة ماتفهم عليه\n\nإضافات : الرجال يشرح بجد لكن يبي له واحد من الطلاب يتابع وراه، بعض المرات الدكتور يغلط لان الكورس كالكس وهو تخصصه ستات فيعتمد على نوتاته والرجال يحاول يجتهد في الشرح\nايضا الدكتور يسوي هلب سيشن خاص لطلابة يحل فيها مسائل\nبشكل عام الدكتور ماهو سيء ولا هو التوب يعني وسط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474057-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/40", "user": "Jafar_15", "ts": 1496065121000, "tid": 68398, "pn": 40}}]}', 1496064693000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mha14-math101', 'stk-mha14', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68405", "n": "Dr. Assane Lo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انصح به وبقوة\n\nدرسني ماث 101 , شريح ,اخلاق لايعلى عليها ,يحضر اخر الكلاس قبل دقيقتين من النهاية\n\nكوزاته سهلة ويحذف اسوء كويز\n\nتصيحه لميجر الريتن على السلوشن كي\n\nنزل عنده وانت مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1320975-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/assane-lo/68405/45", "user": "MHA14", "ts": 1390225496000, "tid": 68405, "pn": 45}}]}', 1390225496000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4492-math101', 'stk-user4492', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 - term 111\n\nميزة الدكتور بدر الحميدي هي في النوت حقّه …\nوفي الكلاس يكتب الأمثلة اللي في النوت … وشرح بسيط عليها ، ،\nالهيلب سشن اللي يسويها كويسة …\n\nفي الكلاس وورك يعطيك أقل من حقّك !\nيعني مثلاً أنت كامل في الهوموورك يقولك : ما اقدر ازودك انت كامل …\nوطالب ثاني مايسلّم هومووركات وماخذ 5 من 10 … فـ يزوده كم درجة لأنه ناقص !\nأبي اعرف من الأوْلى للزيادة … الاول ولا الثاني !!\n\nإذا كان الميجر رررررتن …\nيساعدك قدّ مايقدر ويدفك كم درجة 😆\n\nتقييمي له : +B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047916-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/57", "user": "user4492", "ts": 1338367935000, "tid": 68406, "pn": 57}}]}', 1338367935000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-vip_master-math101', 'stk-vip_master', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ايه تقدر\nكل الفضل له بعد الله في تجاوز math 101 كان يعاملي كاحد طلابه حتى في الهيلب سيشن مع اني ما كنت منزل معه من الاساس بس احضر للفهم\n\nجربت دكاترة كثير و الى الأن مافي احد منهم افضل من بدر الحميدي و الياس شاويش في توصيل المعلومة بالنسبة لي\n\nماهو توصيل معلومة و بس الا يقولك اسلوب السؤال في الميجر كيف بيكون و ايش تتوقع يجي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1051289-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/59", "user": "VIP_Master", "ts": 1338865884000, "tid": 68406, "pn": 59}}]}', 1338865884000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-math101', 'stk-makkahboy', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث101-131\nالتحضير: ازا كان الفصل فل مايحضر او ينسى بعض الاحيان\nطريقة الشرح:.هنا الإبداع وأكثر جزء يعجبني انه ماشاء الله يعبي السبورة ويمسح ويعبي ويسمح…يحرق السبورة ماشاء الله تبارك الله عليه\nالكويزات: تقريبا 4 او 5 كويزات بالسمستر\nالمياجر: كومون\nالفاينلات: كومون أيضا\nالقريد النهائي: وبكل ثقة a+\nالصوت واضح وشوووية عربي…\nإضافات: لايفوتك المدرس ابدا الحين دكتور طبعا\nالمدرس فلة وأخلاق ويساعدك ويحاول يخليك تفهم غصب…ووالله بفضل الله ثم بفضله احب الماث وأكثر كلاس انبسط فيه…وما امل ابدا\nقبل المياجر يسوي هيلب سيشن …طلاب من سكاشن أخرى يحضرون للفايدة…والنوت حقته رائعة وجاهزة ومحلولة ماعليك الا انك تركز معه وهو يحل…طبعا في اولد اكزامز ويحل ماشاء الله. …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1291783-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/65", "user": "makkahboy", "ts": 1385064977000, "tid": 68406, "pn": 65}}]}', 1385064977000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-math101', 'stk-user8581', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101 term 131\n\nالتحضير : ورقة تمر على الطلاب , احيانا ينسى او اتوقع يشوف الكلاس زحمة فما يحضر + يسمح بالتأخير المعقول يعني بالكثير5 دقايق + الميك اب\nطريقة الشرح\nعلى السبورة ويكون رافع النوتة على البلاك بورد … يشرح لأخر دقيقة ويتفاعل مع اسئلة الطلاب حتى وان كانت تفاهة شوي لكن كلما قرب السمستر يخلص شوي يزعل من الاسئلة الي تكون عن بعض الاساسيات والصراحة ما ألومه يعني طول لسمستر وهو يشرح ويعيد في الشرح حتى بعد مايخلص الكلاس يجاوب اسئلة الطلاب ويقول اذ عندكم اسئلة ثانية تعالوا الاوفيس اور.\nنوتته تبتدي بأسئلة بسيطة وتتدرج لين توصل لأسئلة من الاولد اقزامات . ما شاء الله عليه دمه خفيف وراعي سوالف واحيانا يعطي بريك خمس دقايق ويقول فيه نكتة او قصة متعلقة بالدرس عشان الطلاب يصحصحون معاه + احيانا يعطي الطلاب سؤال ويقول الي يحله ياخذ كامل في الكويز فنصيحة حاول تجي الكلاس وانت محضر للدرس عشان تكون فاهم الدرس ويمديك تحل هالسؤال وتاخذ فل مارك في الكويز.\n\nالكويزات :\nتقريبا كانت 5 كويزات . تكون من الأولداقزامات وغالبا يأخذ اسئلة من الأولد اقزامات ويعدل عليها ويضيف لها فكرة جديدة + اسئلة الكتاب مهمة حاول تركز عليها لأن احيانا يعدل عليها ويجيبها في الكويزات .\nكويزاته نوعا ما صعبة لكن في كويزين على الاقل راح يكونوا سهلين . اذا تبي تبدع في كويزاته بعد ماتفهم الدرس وتحل اسئلة الكتاب رح لأولد اقزام مقسم ( أدهم ) وحل اسئلة على الشباتر الي خذتوها .\n\nالمياجر: كومون\nالفاينلات: كومون\n\nالقريد النهائي:\na+ قليلة في حقه\n\nالصوت:\nواضح\n\nإضافات :\nاذا حصلت سشكنه مفتوح نزل معاه حتى لو يكون في الليل … + لا تنشغل بالجوال او تفهي وهو يشرح لأن هالشي مايعجبه وراح يسألك .\n+ يدف في الكلاس ورك لكن اتوقع ع احسب درجاتك في المياجر واخر كلاس يوريك الدرجة الي تستحقها في الكلاس ورك ودرجتك بعد الزيادة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316078-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/70", "user": "user8581", "ts": 1389014243000, "tid": 68406, "pn": 70}}]}', 1389014243000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-math101', 'stk-chelsea_17', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 - ترم 131\n\nالتحضير :\nورقة تمر عالطلاب وما قد شفته مره يدقق اذا أحد حضر خويه أو لأ\n\nطريقة الشرح :\nنوت خاص به ويرفعه عالبلاكبورد , الدكتور باختصار ينسخ من النوت الى السبورة + يشرح طريقة الحل يعني لو غبت في يوم ترى الشرح ما طلع كثير عن النوت .\n\nالكويزات :\nكويزاته صعععبه أعتقد كانت 4 كويزات لكن بالنهايه بيدفكم بالكلاسورك وبتكلم عن هالنقطه بعدين\n\nالمياجر:\nكومون لكن ترى تصحيحه ممتاز وما بقول انه يساعد عشان محد يفهم ان الدكتور يدف لكل من هب ودب لكن ان شافك حال صح لكن سار في خطأ سخيف او بدائي ممكن يتغاضى , يعني مستحيل تاخذ أقل من السلوشن أو حتى نفسه غالبا أعلى.\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nB\n\nالصوت:\nشخصيا أنا من النوع اللي أول كلاس أكون باقي ما صحصحت وكلاسي عنده كان أول كلاس بالدوام , والدكتور ما شاء الله يشرح بصوت عالي وبذمة وضمير فكنت دايم أطلع من كلاسه مصدع الى نهاية الدوام … نصيحه اللي أول حصه دايم يكون تعبان فبدر الحميدي ما هو أفضل خيار لك وتراه يزعل اذا أحد رقد أو قاعد يتململ , أذكر كرة زعل يوم شاف طالب يطالع بيده يشوف كم باقي عالكلاس ( المشكلة الطالب ما بيده ساعه لكن مع قوة الزهق :d )\n\nإضافات :\n\nالدكتور متمكن من المادة لكن ما أشوف انه مثلا يستحق انك تسوي بريكات بجدولك عشانه ولا تاخذ كلاسه بوقت خايس , وأحيان يسوي هيلب سيشن قبل المياجر لكن ما أشوفه مفيد أبدا لأنه بس يحل أسئلة ما يركز على اعادة شرح الكونسبت والحيل المتوقعه بالاختبار ( التريكات ) …\n\nللأسف الدكتور خلى افرج الكلاس وورك 27.6 او شي حولها من 40 مع ان سكشنا افرجه فوق الافرج العام فالمفروض يرفعنا أكثر الله يهديه عكس مثلا الدكتور مصطفى قاسم خلا افرجنا 29.4 وفيه مثلا فيصل فيرق افرج وحدة من سكاشنه 32 أو 33 ( فوق الحد المسموح 30 🤪 )\n\nبما أنه أول حصة وأكون تعبان فكنت أنام لا إراديا ( مثل الإغماءة بمكاني ) وما كان يصحيني من النوم لأن التعب واضح ولا كان يعلق , لكن في بعضهم ينزل راسه ويتوسد ذراعه ( داخل الكلاس بنية النوم ) فكان يأشر على اللي جنبه يصحيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1372373-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/77", "user": "Chelsea_17", "ts": 1401147738000, "tid": 68406, "pn": 77}}]}', 1401147738000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-math101', 'stk-sultan_salman_1419', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 … Term 171\n\nالتحضير : في البداية كان يحضر وفي النصف الثاني من الترم ما صار يحضر … طبعا التحضير كان عبارة عن ورقة تلف على جميع الطلاب … أنصحك بعدم الغياب لكي تحصل على أكبر قدر ممكن من البونص في الكلاسورك\n\nطريقة الشرح : ممتازة … يحل العديد من الأسئلة ذات أفكار متعددة … يستخدم السبورة كوسيلة أساسية للشرح … طبعا شرحه مرتب على السبورة … أغلب شرحه من النوتة حقته ( يفضل إحضارها لكي لا تضطر لكتابة الأسئلة ) … طبعا فيه أسئلة متجددة من خارج النوتة … لكن 90% تقريبا من النوتة\n\nالكويزات : صعبة … تحتاج إلى مذاكرة جادة … أذكر أفرج الكويزات كان أقل من 50% … لذلك أضطر الدكتور إلى زيادة الكلاسورك لكل طالب بشكل كبير في نهاية الترم\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: A\n\nالصوت: ممتاز\n\nإضافات : دكتور مميز كشرح وكأخلاق وكتعاون … لكن المادة تحتاج إلى كمية عالية من الممارسة … لذلك اللي بتأخذه في الكلاس مهما اختلفت أفكار الأسئلة غير كافي … طبعا أي إشكالية تواجهها في أي سؤال الأستاذ ما راح يقصر معك في حلها .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486380-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/87", "user": "sultan_salman_1419", "ts": 1516368474000, "tid": 68406, "pn": 87}}]}', 1516368474000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-math101', 'stk-ria', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101-201 (عن بعد)\nالتحضير :ما يحضر الا نادر يقول اكتبو رقم مرات بس لكن نادر\nطريقة الشرح :يكتب السؤال في الون نوت ويحل وتكون المحاضرة مسجلة\nالكويزات :كويزاته كانت صعبة الافرج حق السكشن كان 30% في البدية كانت تفتح الكاميرا بعدين صارت لا,وارتفع الافرج ( معلومة بس اذا ما حليت في الطريقة اللي يبغاها وما طلع الجواب صح بيعطيك خطاء حتي لو حلك صح بس جوابك خطاء واذا كان جوابك صح بيشوف حلك عشان يخصم عليك)\nالمياجر: ما كان فيه ميجر بس اسسمينت واحد و ميد\nالفاينلات : كومن\nالقريد النهائي: D+\nالصوت:واضح بس مرات يتكلم عربي ومرات يتكلم انجليزي فا تلخبط شوي\nإضافات : الدكتور هذا الاغلب مدحه بس ما شفت منه شي بصراحة يبشر بالخير لا شرح كنت فاهم عليه يمكن عشانه عن بعد لانه شرح في الاونلاين كورس احسن بكثير من شرحه عن بعد وكان تعامله سيئ مع الطلاب مرات لمه احد يسأل يقول \"ما درست هذا قبل؟! هذا من 001 \" الشئ الوحيد اللي سواه زين هذا الترم انه يسوي هيلب سيشن كثيرا لكن مراح تفهم عليه لانه شرحه مب نفس المستوئ اللي كان يقول عليه ( عن بعد).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527332-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/89", "user": "RIA", "ts": 1609115309000, "tid": 68406, "pn": 89}}]}', 1609115309000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-math101', 'stk-user12137', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101-Term 213\nوالله ما يحتاج اقيمه حتى الرجل أشهر من نار على علم\nاذا شفته اترك الكل وسجل عنده خوش قطيفي\n\nالتحضير : عن طريق ورقة تتمرر على كل الكلاس, واحيانا ما يحضر, لكنه متشدد على سالفة التأخير بس طيب فيمشيها احيانا, وتقدر تكلمه واتساب اذا تعطلت وما قدرت تحضر وبيمشيها لك اذا عذرك مقبول\n\nالشرح : عنده نوتة على الون نوت يبدا بالكونسبت وبعدها يحل مسائل على السبورة وشرحه جدا جدا جدا ممتاز، وكان يعلمنا على الاسئلة الي بتجي في الميجر وبأي صيغة بتجي وحقا كان كلامه صحيح\n\nالكويزات :كويزاته كانت متوسطة الصعوبة وتصحيحه حلو يعطيك فوق حقك حتى لو الجواب النهائي غلط\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح جدا\n\nإضافات : دكتور بدر جدا ممتاز وطيب وخلوق ويتعب في الشرح ويجاوب على جميع الاسئلة المطروحة في الكلاس ولما اقول جميع فأنا اعنيها حرفيا مهما كان السؤال غبي, فالله يعينك اذا جاك ذاك الي دايما يسأل اسئلة غبية ويضيع الوقت ههههههه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535268-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/93", "user": "user12137", "ts": 1662146920000, "tid": 68406, "pn": 93}}]}', 1662146920000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7md_a-math101', 'stk-m7md_a', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\nماث 101 تيرم 121\nبنود التقييم :\n\nالتحضير : بعد عشر دقايق من بداية الكلاس\nطريقة الشرح :عادية جداً, يعطيك أمثلة الكتاب وأكثر الكلاس كلام يعني ممكن مثال واحد ويكون سهل.\nالكويزات :متوسطة\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: C+\nالصوت:8/10\nإضافات : مدرس شاد حيله أعطانا ريفيو سيشن مرة واحده , أنصح فيه لماث سهل مثل 101 يعني عشان يكون أعتمادك على نفسك أكثر! لأني صراحه معتمد على نفسي. هذا التقييم بعد شهرين من الدراسة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1125548-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/7", "user": "m7md_A", "ts": 1354057884000, "tid": 68408, "pn": 7}}]}', 1354057884000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-miizz-math101', 'stk-miizz', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nالتحضير :\nيحضر بعد 10 دقايق من الكلاس، يقول انه اذا غبت راح تخسر معلومه\nيعني مو مشكله عنده! بس يقول الي ما يكون عنده ولا غياب بساعده اخر السنه\nطبعا 10 غيابات dn\n\nطريقة الشرح :\nاشوف شرحه تعبان جداً جداً! يلحس المخ نطلع واحنا مو فاهمين شيء\nبالامانه بس مرتين الي فهمت فيها … يشرح امثله بسيطه مره و يسلخنا بالاختبار باسئله اصعب من المياجر\n\nالكويزات :\nناااااااار نااااار!\nزي ما قلت اسئلته سلخ مره بشكل ما تتصورون، للامانه اعطانا 7 اختبارات و اخذ افضل 6 او 5\nلما نسأله ليش اسئلتك صعبه يقول سهله مره! يعني هو يحسبها سهله مره\n\nلزم قبل كل كويز تذاكر اولد اقزام\n\nالقريد النهائي: C\n\nالصوت: واضح\n\nإضافات :\nنظام سيلف استدي! الحمد لله الميجر الاول الثاني درجات كويسه… طبعا بفضل الله ثم بتعبي\nلاني للامانه لو استفدت منه بالكورس بتكون بنسبة 15% - 20%\n\nتبي تنزل عنده نزل عنده ماث 101 اذا ما لقيت غيره وانحديت عليه مره يعني اخر واحد\nبس ماث 102 على الي سمعته ما ينفع نظام سيلف-استدي لانه بتتعب مره لزم مدرس فاهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165930-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/8", "user": "Miizz", "ts": 1358586172000, "tid": 68408, "pn": 8}}]}', 1358586172000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-math101', 'stk-mr.a1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور سعيد القرني\n\nأستاذ مساعد\n\nhttp://faculty.kfupm.edu.sa/MATH/garnis/\n\nTerm 151 MATH 101\n\nبنود التقييم :\n\nالتحضير : احيانا في بداية المحاضرة ، وأحيانا في منتصفها\nطريقة الشرح : يكتب نوت ع السبورة ويحل مسائل مع توضيح القوانين والنظريات ، بالنسبة لي النوت كويس وتقدر تفهم منه المادة. إيصاله للمعلومة جيد جدا.\nالكويزات : من سهلة إلى متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: تقييمه له B\nالصوت: جيد جدا وما هو مزعج\nإضافات :\nالدكتور حبيب جدا وخلوق ويتعامل مع الطلاب تعامل طيب ، بالإضافة لمرونته في تحديد مواعيد الكويزات.\nتصحيحه لميجر الريتن جدا رائع ، كان فيه سؤال Sketch والـ solution يقول one possible graph ، وعطاني الدرجة كاملة على السؤال رغم ان رسمتي تختلف اشوي.\nيكره الطلاب اللي يتأخرون ، واللي يلهون عن الشرح\nيحفز الطلاب على القدوم لمكتبه في حال واجهتهم أي مشكلة في الفهم\nدكتور رائع في تعامله ، مجتهد ويحاول يبذل كل جهده في توصيل المعلومة\n\nوعموما، مواد الماث تعتمد عليك أنت في الغالب ، الدكتور يسهل عليك الفهم ، وحتى لو ما فهمت فيه مصادر تعلم كثيرة\nابتعد عن الاهمال والتسويف وذاكر أول بأول ، وابشر بالقريد الطيب\n\nأرسلت بواسطة iPhone بإستخدام Tapatalk", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1435082-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/15", "user": "Mr.A1", "ts": 1448987214000, "tid": 68408, "pn": 15}}]}', 1448987214000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-math101', 'stk-abdullah2015', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور سعيد القرني\n\nدرست عنده ماث 101 ترم 161\n\nالتحضير: يحضر في أول خمس دقايق في المحاضرة.\n\nالكويزات: أول الكويزات كانت متوسطة تميل إلى الصعوبة، لكن الكويزات الأخيرة كانت صعبة.\n\nبما إنه الكويزات رتن، تصحيحه لها تقدر تقول يعطيك حقك، يعني ما هو اللي متساعد، وما هو اللي يخسف في درجة السؤال عشان خطأ بسيط، عدا آخر كويزين كان تصحيحه مجحف.\n\nالمياجر: ميجر الريتن كان تصحيحه جيد جداً وما كان ماشي على الـSolution Key بالحرف، يعني مثلاً اللي عليها نقطتين خصم نقطة وهكذا، يعني تصحيحه يميل إلى المساعدة، وهذي إيجابية تحسب له.\n\nالميجر الثاني كان كومون.\n\nالفاينلات: كومون\n\nالقريد النهائي: أعطيه B+\n\nالصوت: واضح\n\nإضافات:\n\n* الدكتور جيد من ناحية الشرح ومن أفضل الدكاترة من ناحية الأخلاق.\n\n* الدكتور عنده بونص 4 نقاط للي ما عنده ولا غياب، تمنيت إني كنت أدري عن هالشيء بداية السمستر، لأن فيه أيام سحبت فيها مزاج وعلى أساس ما فيه خصم من الكلاسوورك والدي إن من 12 غياب.\n\n* أفرج الكلاس وورك لسكاشن الدكتور موب شرط يكون أعلى شيء 7.5 (أو 30 نقطة)، إحنا أفرجنا كان أقل من 30 ب 3 – 4 نقاط وخلاه زي ماهو، بعض الدكاترة الثانيين أشوف إنهم يرفعون الكلاس وورك إلى آخر حد وبالتالي يكون زي البونص لكل السكشن، هالنقطة تحسب عليه كسلبية مقارنة ببعض الدكاترة الآخرين (وجهة نظر).\n\n* بشكل عام أشوف الدكتور خيار جيد لكنه ما هو الأفضل.\n\nبالتوفيق…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466701-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/21", "user": "Abdullah2015", "ts": 1485001778000, "tid": 68408, "pn": 21}}]}', 1485001778000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad.ah-math101', 'stk-ahmad.ah', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101\n\nالتحضير :\nيحضر اول الكلاس ويكره التاخير\n\nطريقة الشرح :\n\nعبارة عن امثلة الكتاب ويحلها على السبورة ، الصراحة بالنسبة لي كان الشرح مشتت يعني ماادري وش قاعد يصير بالكلاس لكن بنص الترم الدكتور رفع لنا نوتة جديدة فيها امثلة الكتاب و الشرح بعدها كم سوال اولد اقزام بكل صراحة الشرح تغير ١٨٠ درجة صار افضل بكثير وعلى كلامه انه راح يشوف نتايجها ويستخدمها في الاترام القادمة\n\nالكويزات :\nاعتبرها متوسطة و صعبة يعني حسب الماتريال يجيك الكويز لكن اغلب الكويزات كان دسمة ، اغلب الاحيان يختبرنا كويز ويكون عن ٢ بمعنى الدرجة حقت الكويز تحسب لـ ٢ عشان نقدر نوصل لاكبر عدد من الكويزات وهالشي من مصلحة الطالب اللي يبي يعدل درجته واخر الترم اخذ افضل ٦ او ٥ ماني متذكر كويس\n\nإضافات :\n- الدكتور الصراحة من ناحية التعامل لا تعليق ، يخجلك بتعامله وايضا متعاون مع الطلاب، يعاملك معاملة الاخ .\n- فيه بونص ٤ بوينت للشخص اللي مايغيب طوال السمستر .\n- تصحيح الكويز في بعض الاحيان نوعا ما كان يعجبني يعني لو عندك خطا بسيط في الحل وطلع الجواب معك صح راح يحسب لك السوال صفر ، يهتم بطريقة الحل و الجواب النهائي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1491183-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/27", "user": "Ahmad.AH", "ts": 1524138253000, "tid": 68408, "pn": 27}}]}', 1524138253000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bb_aa33-math101', 'stk-bb_aa33', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101\nTerm 181\n\nالتحضير :\nشديد في التحضير بشكل مبالغ جدااااا يعني كلاسي 11 أحضر 11:01 يقعد يطالع فيك بنظرة تحقير نوعا ما (عاد تخيل لو تأخرت 5 دقائق ) ويقلك جملته المعروفة Be on time\nإذا دخلت بعد مايخلص تحضير ليت لين 10 دقائق بعدها مايدخلك غالبا\n\nطريقة الشرح :\nيشرح من النوت حقه ( عادية جدا) , طريقة شرحه تلقين ومملة أغلب الوقت يقرأ من السلايدات ويحل أسئلة سهلة ماتجي في المياجر ويغلط بعض الأحيان ويمسح السبورة\n\nالكويزات :\nنااااار 😞 والافرج حق الكويزات نازل مرة حق السكشن حقه بس ممكن ميزتها إنها من أسئلة الكتاب والاولد اقزامس غالبا مو كل مرة\n\nإضافات :\n- ماأنصح بالدكتور كخيار أول ولا حتى أخير خصوصا ماث 102 لأنك تحتاج دكتوور ممتاز بعكس 101 اللي سهل مرة ويمديك تمشيها سلف ستدي .\n\n- الدكتور في تصحيح الكويز شديد مررررررة ومجحف يعني ممكن تكتب كل الخطوات صح تغلط في الجواب ولا إشارة يعطيك صفر, بإختصار الدكتور تحسه يصحح عشان يطلع لك غلط حتى لو جوابك صح تلاقيه يدقق في الخطوات لين يحصل خطأ ويرتاح وينقصك\n\nممكن ميزة الدكتور إنه مرن في مواعيد الكويزات ويغير بناء على رغبة الطلاب\n\n- إذا كان لا بد إنك تنزل عنده عليك بالآتي:- ذاكر من نوت دكتور محسن + patrickJMT باترك شرحه مرةة بطل هذا رابط قناته في اليوتيوب ماعليك غير تكتب اسم الدرس اللي تبغاه واكتب اسمه بعده\n\n- الدكتور أخلاق وطيب ومساعد في الاوفس اور لو تروح له\n\nالقريد النهائي للدكتور : +D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503511-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/28", "user": "bb_aa33", "ts": 1544602323000, "tid": 68408, "pn": 28}}, {"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 102 - 182 Lecture\n\nالتحضير : غالبا بعد ثلث ساعة من بداية الكلاس وأحيانا مايحضر ويمديك تحضر مع أي سكشن تبغاه\n\nطريقة الشرح : يرشح من نوته الخرافية ❤️ ويشرح في البداية الكونسبت بعدين أكثر من مثال بعدين يجيب أسئلة من الاولد اقزامس على الدرس اللي يشرحه(حركة بطططلة)\n\nالكويزات : كويزاته في ماث 101 كانت أصعب لكن في 102 كانت من سهلة لمتوسطة عبارة عن 4 أسئلة أسئلة خيارات من متعدد بس لازم تحل\n\nالمياجر: كومن .\n\nالفاينلات : كومن .\n\nالقريد النهائي: +++++++++++++++++++++++++++++++++++++++++++++++++++++A\n\nالصوت: ممتاز جدًا .\n\nإضافات : بالنسبة لي أول مرة أشوف دكتور كامل والكمال لله, إذا جيت من ناحية تحضير ولا من ناحية شرح ولا من ناحية أخلاق يعني فيه مرة غبت عن كويز كنت تعبان وماكان عندي عذر قلي تعال الاوفس اختبر ❤️ ❤️. لكن للأسف الدكتور طالع أمريكا الترم الجاي عشان يكمل دكتوراة 😞 وماراح يكون موجود\n\nالله يوفقك يادكتور محسن في الدكتوراة ❤️ ❤️ واعلم إن القلب داعيلك ياأسطورة ❤️ ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507889-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/20", "user": "bb_aa33", "ts": 1553636188000, "tid": 175316, "pn": 20}}]}', 1544602323000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mj77-math101', 'stk-mj77', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 ترم 181\n\nالتحضير : شديد بالتحصير لو تتأخر دقيقه قال لك be on time مرتين ثلاث بعدها يطردك\n\nطريقة الشرح : فاشل جداً بالشرح ومدرس الريساتيشن افضل منه بمراحل كان ، عنده نوته فاشله كمان ياخذ منها اسئله ويحلها ويشطح خطوات ولازم تجلس تسأله كل شوي عشان تفهم نقطه وحده بس\n\nالكويزات : صعبه ، كنت اذاكر واجتهد وبالنهايه يجيب سؤالين تعجيزيه وكل الكلاس مايحلها !\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: F\nالصوت: كويس ومسموع\nإضافات : الدكتور اخلاق وطيب جداً ويقبل ميك اب طوال السمستر بس الدكتور الله يهديه مايعرف يوصل اي معلومه وعانيت معاه كثييييير + اكبر سلبيه موجوده فيه ان بالنهايه مايرفع احد واتوقع مايستخدم الافرج ! لان نص الكلاس اخذوا بالكلاس وورك من بين 15 الى 20 من 40 !! , سمعت كم واحد يمدحه ونزلت عنده وندمت اشد الندم وكل اللي بقروبه نفس الكلام ندموووا انهم نزلوا عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504133-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/29", "user": "mj77", "ts": 1545881589000, "tid": 68408, "pn": 29}}]}', 1545881589000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f80-math101', 'stk-f80', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 TERM183\n\nالتحضير : بنص الكلاس , اذا تأخرت يرميلك الجمله الشهيره please … be on time\n…\nطريقة الشرح : من النوت حقته , يشرح الكونسبت و يحل مثال و بعدها يحل تمرين من النوته و يعطيك وقت تحل تمرين ثاني و بعدين يحله هو , بالنسبه لي كان شرحه ممتاز .\n…\nالكويزات : بالمستوى المطلوب , ماهي سهله لدرجه الكل ياخذ فل , ولا صعبه جداً , فيها افكار و تحدي بسيط يعني تفرح اذا جبت فل .\n…\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: مسموع و الاكسنت ممتاز\n…\nإضافات :\nبالنسبه لي هذا كان وضعي معه :-\nاركز معه بالشرح و افهم عليه و اقدر احل التمارين اللي يطلبها مننا , في وقتي الخاص ما ارجع اذاكر الكونسبت فقط القي عليه نظره مراجعه بسيطه لان شرح الدكتور سعيد كافي , و ابدا احل نوته محسن ثم اسأله الريسايتيشن و الواجب و قبل الميجر احل اولد اقزامين ( يفضل تحل اكثر بس انا اهمل و يضيق علي الوقت ان تبي الصدق 🚬 ) و بس يا خويي اتبع ذي الطريقه اول باول مع كل درس بتجيب القريد اللي يرضيك .\n\nو اذا صعب عليك شي ابحث عنه بقناه الاجودي ذا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513588-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/31", "user": "F80", "ts": 1565465037000, "tid": 68408, "pn": 31}}]}', 1565465037000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-super_mario-math101', 'stk-super_mario', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 171-172\nmath101, math102\n\nمرونة التحضير :\nالتحضير اهم شي عند الدكتور سعيد ويحاسب عالتاخير, اذا كنت منضبط بالحضور راح يكافئك الدكتور نهاية الترم بالكلاس وورك بشكل ماتتوقعه.\n\nالشرح :\nالشرح جدا ممتاز بالذات اذا كنت مجتهد وتجلس قدام راح ياخذ ويعطي معك الدكتور لين يتاكد انك فاهم, للامانة انا كنت مجتهد وكنت دايم اخذ واعطي معه وهذا اللي خلاني اتزل عنده 102 لان الدكتور من الاخر بطل ويعلم الله اني احبه في الله واحترمه لانه حببني في الماث, واذكر لي موقف بماث 102 نزل مستواي شوي بداية الترم لظروف مريت فيها تفاجأت انه جاني وكلمني وعطاني دفعة معنوية بسببها جبت A+ بالماث 102 ومعدل عالي بالترم كامل, يمكن لولا كلامه لي ونصيحته ما وعى قلبي.\n\nالكويزات:\nكويزاته بشكل شبه اسبوعي وفيها الصعب جدا جدا وفيه المتوسط والسهل, بالنهاية يمكن يحذف اسوء اربع كوزات.\n\nكلاس وورك:\nنهاية السنة بالكلاس وورك زودني ممكن 8 بونص بترم 171, ونفس الشي بترم 172, السبب لاني ماكنت اغيب واي طالب مايغيب عنده ويشارك معه راح ياخذ +7 بونص.\n\nالتعامل :\nالدكتور قمة في الرقي والاخلاق, من اكثر الدكاترة اللي احترمهم طوال مسيرتي الجامعية.\n\nبالنهاية الدكتور انصح فيه اذا كنت انسان مجتهد وملتزم بالحضور وتكتب نوتات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1523764-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/33", "user": "Super_Mario", "ts": 1594162419000, "tid": 68408, "pn": 33}}]}', 1594162419000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12007-math101', 'stk-user12007', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 201 ترم عن بعد\nالتحضير: متساهل واذا تاخرت ارسله ايميل و يضبطك\nالشرح: بالنسبة لي جيد جدا ويصير اسطوري في الريسايتيشن, مشكلته في بعض الدروس شرحها بسرعة واحس ما اعطاها حقها. كان يشرح على one note وخطه واضح. يسجل كل المحاضرات فيمديك ترجع لها متى ما تبي. نوتاته لك عليها ومافي اجوبة لازم انت تروح تسأله.\nالكوزات: في البداية كان عشوائي ومرات يكنسل الكوز بس بعدين صار كل خميس في الحصة. الكوزات مدتها قصيرة والاسالة مالها دخل باسالة ديبارتمنت الماث ( ويب اساين جدا سيئ) بشكل عام الكوزات كانت السبب الرئيسي ليش الطلاب ما جازلهم الدكتور\nالواجبات : لا يوجد\nالمياجر: -\nالفاينل: -\nالقريد النهائي A\nاضافات: الدكتور خلوق ودائما يمزح معنا ويحاول يغير جو الدراسة شوي خاصة ان التعليم عن بعد ويحاول باللي يقدر عليه يساعدك ايام الميجر والمد تيرم غرقنا اسالة اولد اكزامز وفادتني كثيير وفي الحصة اذا ما فهمت شي اساله وما بقصر معك. ماث 101 بشكل عام مادة سلف ستدي وعندك مراجع كثييير. بالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526718-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/37", "user": "user12007", "ts": 1605614300000, "tid": 68408, "pn": 37}}]}', 1605614300000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12016-math101', 'stk-user12016', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101-T201 اونلاين\n\nالتحضير : ببداية الترم كان يعطينا كويز بالبلاك بورد يوميا يحضرك منه (مايهم تغلط او لا) بس بنص الترم بدا التحضيرالكتروني من البلاك بورد\nطريقة الشرح : يفتح الون نوت ويبدا يشرح منها المفاهيم والأساسيات بعدها يبدأ يدخل بالاسئلة ويعطي للطلاب فرصة يحلون قبل لايكتب الخطوات ويبدأ هو الحل من نفسه\nالكويزات : الكويزات كانت عن طريق الويب اساين وهي اساسا بنك اسئلة مو الدكتور نفسه اللي كاتبها وكانت فيها مشكلة ضيق الوقت\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B+\nالصوت: الصوت واضح وانقليزيته كويسه\nإضافات : الدكتور خلوق وطيب جدا , متعاون مع الطلاب حتى في وقت المد تيرم قرر يكنسل اللكتشر ويعطينا هلب سشن من الساعة 9 الصبح الى 3 اذا ماخاب ظني كنا نحل فيها اسئلة اولد اقزامز , والدكتور عنده اكثر من شاشة فكان يشوف الشات في نفس الوقت ويقبل بالاسئلة ويجاوبها بنفس الوقت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526724-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/38", "user": "user12016", "ts": 1605635532000, "tid": 68408, "pn": 38}}]}', 1605635532000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-juha-math101', 'stk-juha', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 - TERM211\n\nالتحضير : شديد وما يحب التأخير\nطريقة الشرح : يشرح من نوتته اللي من وجهة نظري أشوفها عادية وشرحه بشكل عام متوسط\nالكويزات : صعبة جدًا لكن إحقاقا للحق الدكتور يدف بالتصحيح ويحاول يساعدك قد ما يقدر\nالمياجر:\nالفاينلات :\nالقريد النهائي: C+\nالصوت:.واضح وغالبا يتكلم عربي أصلا\nإضافات : الدكتور كشخص خلوق جدًا ويحب يمزح مع الطلاب ويجاوب على أي سؤال، لكن كدكتور ما أنصح فيه كخيار أول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533545-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/40", "user": "juha", "ts": 1642922934000, "tid": 68408, "pn": 40}}]}', 1642922934000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_m1-math101', 'stk-mr_m1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68408", "n": "Dr. Saeed Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101-TERM 231\nالتحضير :\nشديد، يحاسب بالدقيقة.\n\nطريقة الشرح :\nبالنسبة لي في هذا الكورس ممتاز شرحه للأمانة، لكن في الكورسات الأخرى ممكن مستواه ينزل.\n\nالكويزات :\nبالرغم أنه توجه القسم من الكتاب وهو برضوا يجيب من الكتاب، إلا أنها صعبة إلى حدٍ ما. لكن لو تشق أسئلة الكتاب خصوصًا ال بنهاية كل شابنر أظن يمديك تجيب درجات كويسة.\n\nالمياجر: كومن\nالفاينلات :كومن\nالصوت: دائمًا أقعد قدام، واضح.\n\nإضافات :\nالدكتور تعامله رهيب مع الطلاب ويمزح ويشرح بشكل ممتاز (أقلها 101)، ممكن بحصص الـ REC يصير ممل لأنه يقعد يطول الكلاس وهو ما له داعي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537195-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-garni/68408/41", "user": "Mr_M1", "ts": 1704299127000, "tid": 68408, "pn": 41}}]}', 1704299127000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-medoalkebsi-math101', 'stk-medoalkebsi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68411", "n": "Dr. Muhammad Bokhari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه ماث-101\nالتحضير :يمرر ورقه على الطلاب توقع فيها ويطابق التواقيع .\nطريقة الشرح :يشرح كونسبت كونسبت كونسبت كونسبت كونسبببببببببببببببببت\nالكويزات :وسط إلى صعبه.\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي: اعطيه a-\nالصوت:واضح.\nإضافات :المدرس يشرح الكونسبت ونوته مرتبه , اشوفه مدرس جيد جدآ .\nالمدرس عصبي , لو شافت تلعب بالجوال ياويلك ياخذه منك ويقول لك روح خذه من التشيرمن.الكلاس وورك اذا ماعندك غيابات ابشر بالدف .\nتصحيحه للمياجر جيد , بس اوقات يفوت اشياء تروح له يعدل الدرجه.\n\nانصح فيه الاشخاص الي يهتمون بالكونسبت + الي مستواهم بالماث متوسط.\n\nوبالتوفيق …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1292058-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-bokhari/68411/26", "user": "Medoalkebsi", "ts": 1385122365000, "tid": 68411, "pn": 26}}]}', 1385122365000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unbeatable-math101', 'stk-unbeatable', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68412", "n": "Dr. Ahmed Shawky", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : { يمرر ورقة كل محاضرة , ومايمانع أنك تحضر مع أي سكشن و يمديك تحضر الي تبي }\nطريقة الشرح : { ببساطة أقول لك , تفهم غصصصصصب ❤️ ❤️ ❤️ , أخذت معه Math101 , وبداية Math102 بالصيف , بس مليت وحذفت الصيف , و يوم رجعت أذكر كل الدروس الي شرحها لي قبل ما احذف ❤️, }\nالكويزات : مره يجي صعب و مره سهل 😁\nالمياجر: كوممن\nالفاينلات : كوممن\nالقريد النهائي: أقوى A+ ❤️\nالصوت: واضح\nإضافات : نزل معه وأنت مغمض , الله يطول بعمره ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p755267-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-shawky/68412/32", "user": "Unbeatable", "ts": 1293756810000, "tid": 68412, "pn": 32}}]}', 1293756810000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-math101', 'stk-abdulla_yahia', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68412", "n": "Dr. Ahmed Shawky", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. أحمد شوقي ]\n\nMATH 101 - Term 131\n- التحضير : يومياً - ورقة تمر على الطلاب ، لا يحب التأخير و يتساهل أحياناً إذا كان في حدود 5 إلى 10 دقايق ,\n\n- طريقة الشرح : في بداية السمستر كان يشرح على السبورة و بعدها صار شرحه باستخدام التابلت - شرحه ممتاز جداً ( واضح + سهل ممتنع + يوضح التركات + يشرح الكونسبت بامتياز و يكتب البروف غالباً + يحل أسئلة مشابهة جداً لأسئلة المياجر و الفاينلات ) ,\n\n- الكويزات : 5 كويزات متوسطة مائلة للسهولة - يأخذ أحسن 4 كويزات ,\n\n- المياجر : كومن ,\n\n- الفاينلات : كومن ,\n\n- القريد النهائي : A\n\n- الصوت : واضح لكن هادئ نوعاً ما - تتعود عليه مع الوقت ,\n\n- إضافات : الدكتور قمة في الأخلاق و التعامل و العلم - ما شاء الله + له خبرة واسعة في التدريس تتضح من شرحه + واسع الصدر و مبتسم دائماً ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1317265-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-shawky/68412/49", "user": "Abdulla_Yahia", "ts": 1389181922000, "tid": 68412, "pn": 49}}, {"id": "stk-dr-m83633", "n": "أ. أبالارا تيجاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. أبالارا تيجاني ]\n\nMATH 101 ( Rec ) - Term 131\n- التحضير : يومياً - ينادي بالأرقام التسلسلية على ملف إكسل ,\n\n- طريقة الشرح : شرحه جيد جداً - يذكر نقاط مهمة أحياناً قد لا يذكرها دكتور الليكتشر ، فاهم للمادة ، أحياناً تحس أنه يشرح مع نفسه ,\n\n- الكويزات : ___\n\n- المياجر : ___\n\n- الفاينلات : ___\n\n- القريد النهائي : +C\n\n- الصوت : نطقه الإنجليزي سيء بلكنة أفريقية و هو أكبر عيب فيه + صوته هادئ نوعاً ما ,\n\n- إضافات : حصل على الدكتوراة في السمستر الماضي ، جيد في التعامل في حدود كلاس الرسايتيشن + يحل بعض الأسئلة اللي جات بالميجر ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1323197-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/83633/20", "user": "Abdulla_Yahia", "ts": 1390841833000, "tid": 83633, "pn": 20}}]}', 1389181922000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-math101', 'stk-abo_yazeed6', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور جيد وفاهم وشرحه توب\n\nاخذت معه ماث 101 في ترم 113 ,هو صحيح ما يحل الا أمثلة الكتاب لكنه يشرحها بشكل ممتاز,الرجال فعلا فاهم وما تعوق معه ,عيبه هو سماجته اذا جا يمزح.\n\nتصحيحه عادل ,يستقعد على بعض المسائل “أذكر فيه سؤال في ميجر 1 نسبة كبيرة من الشباب نسوا نقطة في الحل وخصم على الكل”,ويسلك في مسائل ثانية.\n\nالشاهد كان ودي انزل معه math 202 هذا السمستر لكن سكشنه قفل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1255607-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/23", "user": "abo_yazeed6", "ts": 1377506811000, "tid": 68413, "pn": 23}}]}', 1377506811000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_albloshi-math101', 'stk-mohammed_albloshi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201\nماث 101\nاونلاين\n\nصراحة فالاونلاين م يناسبني ابدا وصعب اني افهم معاه ولكن معرف كيف فالحضوري\nالكويزات ٤ ٥ وسهلة نوعا\nالتحضير:يحضر كم مره فالمحاضرة\nعبر الصوت او شات او سؤال فالدرس ووو…\nولكن الدكتور متعاون مع الطلاب في تواريخ الكويزات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526565-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/41", "user": "Mohammed_albloshi", "ts": 1604781472000, "tid": 68413, "pn": 41}}]}', 1604781472000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wiss_alamri-math101', 'stk-wiss_alamri', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 - “ONLINE” term 201\n\nالتحضير :\nأسوء تحضير ممكن تشوفه في حياتك، ينادي بالأسماء ثم بعدين يقول ارسلوا الرقم ذا بالشات ثم بعدين ينادي بالأسماء مرة ثانيه ويسألك واذا ما جاوبت يغيبك حتى لو حضرك بالطريقتين السابقة!!! يبغى يغيبك بأي طريقة وللأسف الشديد كلاسه كان ساعة وربع.\n\nطريقة الشرح :\nشرح الدكتور حرفياً اذا قالك قراءة سلايدات، كان يستخدم سلايدات الكتاب وصراحة سيئة برأيي. كان سريييع الدكتور ويمشي بسرعة، خلصنا ماتيريال الميد (كان ميد ذاك الترم) قبله بأسبوعين.\nللأسف ساعة وربع فقط يشرح كونسبت ومثال محلول واحد فقط ويقول هذا المفروض يكون في اللكتشر، المسائل بنحلها في الريسيتيشن، طبعاً كان يجي الريسيتيشن وينادي الطلاب كل طالب يحل مسألة واذا ما عرف غيبه يعني حتى الريسيتيشن ما حل لنا أسألة.\n\nالكويزات :\nعشوائية، من ويب آساين ومو هو يكتبها. كان ياخذ أسألة عشوائية من الويب آساين بدون لا يشوفها لدرجة مرتين قد جاب لنا أسئلة لازم حاسبة ومرة جاب لنا سؤال برا المنهج أصلاً.\n\nالمياجر:\nمد واحد وكان كومون.\n\nالفاينلات :\nكومون.\n\nالقريد النهائي:\nD وبجدارة.\n\nالصوت:\nواضح.\n\nإضافات :\nطبعاً رفعته من F إلى D لأن شهادة حق الدكتور كان متعاون معنا في تواريخ الكويزات وكان أي واحد تصير له مشاكل بالكويز كان يسوي له ميك آب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534012-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/45", "user": "Wiss_Alamri", "ts": 1648362816000, "tid": 68413, "pn": 45}}]}', 1648362816000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user1939-math101', 'stk-user1939', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه ماث 101\n\nبدون مبالغة أسوأ مدرس ماث اخذت عنده في حياتي الجامعية\n\nسييييييءءءء سيييييييييء ثم سييييييييء\n\nالتحضير : يحضر ب Exel sheet واذا تأخرت خمس دقايق يحسب لك نص غياب\n\nالشرح : يشرح الماث بسلايدات !!!!!!!!!!!!!!!!!!\n\nيا ناس عمركم شفتوا ماث بسلايدات بور بوينت : | !!!!!!!!!\n\nمافيه نوت ولا هم يحزنون\n\nسلايدات !!!\n\nكوزات يجيب اسئلة مو من الكتاب وفكرتها مو في الكتاب اصلا\n\nتشوف درجات الناس اصفار وان كثرت 2 او 3 من 10\n\nفيه مره جاب لنا كوز قال هذا السؤال انا نفسي واجهت صعوبة فيه\n\nعشان كذا جبته لكم عشان تجيبون كويس في المياجر\n\nفاهم غلط الحبيب !!!!!!!!!! اوكي جب لنا شي صعب لكن مو من برا الكتاب حتى !!!\n\nطبعا الكلام على شرحه\n\nاما اخلاقه كويسه بس ما تنفعك اخلاقه ابدا اذا اخذت F كبر راسك\n\nنصيحة اخوية اذا شفتوا اسم العنبوسي وخروا عننننننننننه\n\nانننننننننحشششششششش", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p345872-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/2", "user": "user1939", "ts": 1230728107000, "tid": 68463, "pn": 2}}]}', 1230728107000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5444-math101', 'stk-user5444', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المدرس نزل لي هذا السمستر 091 … ماث 101 … 🙂\nطبعآآآ قبل لاندوام عنده اطلعنا على ردود الاخوان اعلاه ^^^^^^^ وتحطمت كليآآآ لكن الصرآآحه والله يشهد على كلامي … المدرس طلع عكس ماتوقعناه (والحمدلله جت خيره ) !!\nالأستاذ رآئد عنبوســي …\nأآأستآذ في قمه الأآأخلاق ومتعآأآون لأبعــد درجـه …\nالشرح : يشرح المفاهيم شرح وآآفي ويحل عليها أسئله توصل المعلومه ! لكن بعض الاحيان يمشي سريع بعض الشي في شرح الماتيريال !\nايضآآ اللغه الطآآغيه هي الانجليزيه واذا استصعبت بعض الامور شرحها بالعربي وبكل رحآآبه صدر … بإمكانك تسأله بالعربي أيضا … ماعنده مشكله ! … لغته رائعه جدا في الانجليزي ماشاء الله حتى بعضا الاحيان احس اني بكلاس انجلش 😆 …\nالصوت : واآضح وعاااالي …\nالكويزات : ( ابوف آآفرج ) يعني فيها لعب شويه 🙂 وبالمقابل تكون في اسئله مباشره وسهله … تقيس مدى فهمك للماتيريال وتتجنب أخطاء شنيعه ممكن تقع فيها في الميااجر\nالمياجر : كومون\nالفاينلات : كومون\nبعض السلبيات اتمنى المدرس يتجنبها :\n1- الشرح من نوت فيه كثير من الاخطاء …(مع العلم انه ينبه عليها ) … ف الافضل للمدرس انه يكتب نوته الخاص به … او يستخدم نوت آآخر يكون آفضل من الحالي وماشي على سيلابس الاصدار الجديد للكتآأآب …\n2 - تسليم الهوم وورك لازم يوم السبت ! … فـ انا اشوف لو المدرس اعتمد سياسه تأجيل الهوم وورك في بعض الاحيان مراعاه لظروف الطلاب … تكون بادره طيبه منه …🙂\nلان الويكند (يكون في الهوم تآآون 😏 او ونآآسه يعني شي من ذا القبيل ) !\n3 - زي ماذكرت أنفا انه سريع بعض الشي … ومااذكر أنه خصص حصة مراجعه او اسئله قبل ميجر 1 او 2 …\n--------------------------------------------\nشي قد يكون مستغرب بعض الشي : ان سكاشن الاستاذ رائد هي الوحيده الي ماآسكرت … واتوقع والله اعلم ان التفسير لها : هو النظره الخآطئه عن المدرس من قبل الطلاب …\n\n( أنا اتكلم عن السمستر الحالي !!!) ولا اعلم الكثير عنه سابقآآ …\n\nالجريد النهآآآآآآئي : B+ 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p521013-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/14", "user": "user5444", "ts": 1263130045000, "tid": 68463, "pn": 14}}]}', 1263130045000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_alwaleed-math101', 'stk-abo_alwaleed', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الأستاذ رائد العنبوسي\n\nالماده اللي منزلها معه - ماث 101\n\nبنود التقييم :\n\nالتحضير : بشكل يومي بعد 20 الى 30 دقيقة من بداية الكلاس يعني متعااون جدا بالتحضير ولامره شفته متضايق من الطلاب المتأخرين\n\nطريقة الشرح : الصراحه شرحه ممتااز يوصل المعلومه بشكل جميييل يستخدم الكمبيوتر لعرض النوتات على البروجيكتور ويحل امثله كثير على السبوره ويتعب لتوصيل المعلومات لجميع الطلاب , بس زي ما قالوا الشباب , خلك منتبه ومصحصح وصدقني راح تستفيد\n\nالكويزات : كويزاته متوسطه مائلة الى الصعوبه وهو نفسه يقول ان كويزاته فوق الافرج ويجيب افكار جديده\n\nالمياجر: كومن\nالفاينلات : كومن\n\nالقريد النهائي: a\n\nالصوت: واااااااااااااضح جدا جدااا , يمكن لأن الكلاس صغير ههههههههه\n\nإضافات : المدرس هذا اخلااااقه عااااليه جدا جدا جدا وتعامله رااقي جدا مع الطلاب , والله الصراحه من افضل المدرسين اللي مروا علي … دايما مبتسم ماشاء الله عليه … ماعمري شفته معصب عكس كثيير من مدرسين الماث.\n\nيعني باختصار اذا ناوي تنزل ماااث , توكل على الله ونزل عن رائد العنبووسي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p541205-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/18", "user": "Abo_Alwaleed", "ts": 1265811719000, "tid": 68463, "pn": 18}}]}', 1265811719000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.small-math101', 'stk-mr.small', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الردود الآخيرة هي اليي تثلج الصدر\n\nأنا مع الأستاذ في هذا السمستر 092 ، التحضير بعد ربع ساعة من الكلاس أو أكثر\n\nطريقة الشرح … يستعرض أهداف الدرس … و يحل مثال بسيط … و بعدها يبدأ في الأسئلة الصعبة … و أول ما يخلص من سكشن معين يحل أسئلة الريسيتيشن في نفس الكلاس … لكنه يسرع في الشرح … لكن إذا عندك أي سؤال لا تتردد إسأل\n\nكويزاته صعبة … الهوم ورك يكون يوم السبت أجله بسبب المياجر إلى الأثنين\n\nأخلاقه عالية … 👍 ، و بالنسبة لي ، أستاذ يحل أسئلة مع الطلاب أحسن من مجرد كونسبت … و كانت هذه تجربتي مع الدكتور إبراهيم الرصاصي ماث 101 … مجرد كونسبت و مثال بسيط و بعدين تروح المياجر و تنصدم 😦 🥊\n\nأستاذ ممتاز الله يوفقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p579480-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/19", "user": "MR.SMALL", "ts": 1270106489000, "tid": 68463, "pn": 19}}]}', 1270106489000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatef-math101', 'stk-abdullatef', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101\nTERM 171\n\nالتحضير : بشكل يومي بعد بداية الكلاس ب ١٥ دقيقه تقريبا يوقف الشرح ويحضر وماعنده مشكله لو جيت متاخر ، اهم شي قبل مايحضر ،، يخصم على كل غياب\nطريقة الشرح : من السلايدات يعرض النوت من البروجكتر ويبدا يشرح ويحل امثلة الكتاب\nالكويزات : صعبة صعبة صعبة مائلة للتعجيز… + التصحيح مو معقول تغلط ف اشاره ف الناتج مثلا يعطيك عالسؤال ٢ بوينت من ٥ ، احيانا سؤال او سؤالين واحد صعب ومقدور عليه والثاني ماحد يحله .\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: d+\nالصوت: واضح\nإضافات : الدكتور طريقة شرحه غير منظمة ابدا ، يلخبطك ومايرتب الافكار ، طبعا الكويزات + التصحيح كلها سيئه وشرحهه للكونسبت جدا ضعيف\n+ تخصص الدكتور stat مو math ،، لا انصح به ولو كان اخر خياراتك ،، الشكوى لله\nطبعا الترم باقي عليه شهر تقريبا بس هذا الي اشوفه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1484034-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/55", "user": "abdullatef", "ts": 1511954004000, "tid": 68463, "pn": 55}}]}', 1511954004000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-husbkt-math101', 'stk-husbkt', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83632", "n": "Dr. Khalid Al-Anezy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الأستاذ خالد العنزي 173 ماث 101\n\nمحاضر\n\nبنود التقييم :\n\nالتحضير : يمديك تتأخر اول 5 دقايق … مدري كان عنده ميك اب لان في الصيفي م كان عنده الا سكشن واحد\nطريقة الشرح : دكتور جبار بمعنى الكلمة … النوته حقته ممتازة جدا والشرح م عليه كلام\nالكويزات : 4 كوزات سهلة الى متوسطة لكن شخصيا 15 دقيقة م تكفيني هع … الكلاس وورك يعتمد ع الكوزات والمشاركة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح جدا ( يشرح بالانجلش لكن لو حس في احد م فهم يشرح عربي )\nإضافات : راح يرسل مسائل ع البلاك بورد الي يحلها يعطيه بونص ف الكلاس وورك … بالنسبة لطريقتي للمذاكرة احل مسائل النوتة واحل الـ old exams by section لياسر خالد واحل كوزات الدكتور موجودة في قسم الماث واخيرا الـ old exams", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498493-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-anezy/83632/31", "user": "Husbkt", "ts": 1535715744000, "tid": 83632, "pn": 31}}, {"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 102 - 181\n\nالتحضير : يحضر بعد 15 دقيقة الى 25 دقيقة من بداية الكلاس ( م ادري هل عنده ميك اب لأن ف 181 م كان عنده الا سكشن واحد ) نظامه كان ف 181 عادي تغيب 12 غياب بلا خصم ولا شيء\nطريقة الشرح : عنده سلايدات ( الي يميزها مكتوبة بالكمبيوتر - واضحة ) يحل الاسئلة الي فيها ف السبورة … مشكلتها ان فيها الأجوبة النهائية فقط ( عن نفسي أشوف نوتة الرصاصي هي الأفضل وبعدها محسن الشهراني )\nالكويزات : بصراحة اشوفها اصعب من المياجر … طبعا عنده 3 كلاس تست كل واحد يغطي متريال الميجروالكلاس تست الأخير يشمل الدروس الي لم تشمل ف الميجرين\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: ممتاز جدا جدا والانجليزية الي عنده ولا أروع\nإضافات : بشكل عام اشوفه يصلح للدوافير … شرحة جيد جدا … أفرج الكوزات دايما يكون طايح ف فالنهاية لما يسوي normalization يرفع الكل بشكل مجنون ( للمعلومية انا تحت الأفرج ف الثلاث كلاس تيستس و ف النهاية شفت الكلاس وورك حقي 30/40 ) … الكورس بشكل عام يحتاج براكتز والأغلب يشوفونه أفضل بكثير من ماث 101 … الا اني شخصيا اشوفه 101 أفضل … طريقة مذاكرتي كانت تعتمد مذاكرة نوتة الرصاصي بشكل اساسي ومحسن الشهراني بشكل فرعي وحل الـ old exams by section والحمدلله طلعت بـ A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504172-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/60", "user": "Husbkt", "ts": 1545970222000, "tid": 68463, "pn": 60}}]}', 1535715744000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-da7em-math101', 'stk-da7em', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : مهم جدا جدا جدا … يحضر يوميا … والغياب عنده مشكله كبيره\n\nطريقة الشرح :ممتازه جدا جدا جدا … استخدام السبوره فقط ويشرح الدرس بطريقه ولا اروع ويشرح المفاهيم بشكل ممتاز\n\nالكويزات :صعبه نوعا ما … على مستوى الشرح طبعا\n\nالمياجر:كومن 101 … 202 ماخذت معاه\n\nالفاينلات :كومن\n\nالقريد النهائي:ممتاز\n\nالصوت:ممتاز\n\nإضافات :دكتور كبير في السن لكن ماشاالله عليه فاهم الرياضيات ويوصل المعلومه بشكل ممتاز … لكن اهم شئ عنده شيئين : الحضور - تسليم الهووم وورك … انت اضمن هذي الشيئين معاه وراح تنبسط باختصار\nويسوي هيلب سيشن بالليل يفيد كثير صراحه … راعي سواليف وتنكيت بالكلاس\n\nباختصار دكتور ولا اروع … اذا انت منت راعي غياب وتحل الهووم وورك … نزل معاه ولا تتردد … طبعا هو ما يدرس الا ماث 101 و 202 … واللي سمعته منه ان ابداعه كله في 202 اكثر من 101", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p343156-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/2", "user": "Da7Em", "ts": 1230076671000, "tid": 68467, "pn": 2}}]}', 1230076671000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-prince_man-math101', 'stk-prince_man', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اول شئ الصورة تجنن هههههههههه كان صغير ابو سرحان\n\nتجربتي مع هذا اللدكتور كانت في math 101 & math 102\nالتحضير : يدقق\nالكوزيات : مافي\nالكلاس تيست : كوبي من امثلة واسئلة الكتاب\nمياجر كومن\nفاينلات كومن\nالقريد النهائي A++++++\n\nاضافات :\nمن خلال تجربتب معاه\nاذا كنت عازم على انك تشد حيلك وتعرفه بنفسك وتروح للأوفس اور لانه يركز عليها\nوايضا لازم تحضر الهيلب سيشن بالليل ورح يحطك في باله اذا حظرت …\nقليل من الدكاترة يعطون فل مارك بالطلاس وورك\nهو ماعنده اي مشكلة اذا شديت حيلك وعرفته بنفسك ولاتعيب وتروح تسال حتى لو كان الكلاس تيست حقك سئ … ابشر باللي يرضيك وزوووووود", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p647509-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/27", "user": "PRINCE_MAN", "ts": 1277783650000, "tid": 68467, "pn": 27}}]}', 1277783650000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bin_saeed-math101', 'stk-bin_saeed', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 111 … ماث 101\n\nالتحضير :\n\nشي مهم جدا جدا التحضير عند الدكتور محمود … والغياب عنده جريمه شنيعه … وكان غالبا مايحضر وفي نهايه الكلاس\n\nطريقة الشرح :\n\nقليل في حقه لو قلت طريقه شرحه ممتازه … اللي يعجبني فيه انه يكرر النقاط المهمه ويعطيك عليها امثله واضحه ويراجع معاك النقاط اللي اخذتها في الدروس اللي قبل\n\nالكويزات :\n\nماعنده كوزات لكن عنده 3 تستات وكان مستواها متوسط\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\n+a+\n\nالصوت:\n\nواااااااااااضح\n\nإضافات :\n\nالدكتور جدا حبوووووب وشرييييييييح … ويسوي هلب سشن اسبوعي ويحب الطلاب اللي يحضروا عنده … والطالب اللي يشارك معاه ومايغيب وهوموركاته كامله يعطيه كلاس ورك فوق مايتخيل\n\nاللي كان يعجبني فيه انه يهتم جدا لمصلحه الطالب ويحب يدرس الطلاب ويحب ان يشوف مستوياتهم عاليه\n\nوكان يوزع للطلاب المتميزين جلاكسي بعد المياجر خخخخخ\n\nالله يوفقه دنيا واخره استفدت منه كثييير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970984-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/49", "user": "Bin_Saeed", "ts": 1327003281000, "tid": 68467, "pn": 49}}]}', 1327003281000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-math101', 'stk-user4988', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ظالم في الكلاس وورك\nيعطي القريدات على حسب المعرفة في الكلاس يعني لازم كل يوم توريه خشتك في مكتبه ولازم تجيب قريدات حلوة بالمياجر عشان يعرفك !!لا لا وبعد بكرمك وبيعطيك جالاكسي !\nاذا ما كان يعرفك راح يخسف بك الارض وتغوووووووووووووص في اعماقها لان كل اللي يعرفهم ياخذوا 60/60\nوالضحية هم الباقون يخسف بهم عشان الافرج !\nهو يقول بنفسه \" انا ادي الكلاس وورك مجرد ما اشوف الاسم\" !! بالله هذا كلام معقوووول ؟\nما عنده الا 2-3 كلاس تستات وما فيه شي اسمه كوزات\nهو طيب لكن وش ابغى بالطيبة مدام اني بروح فيها ؟؟\nشيء ايجابي الا وهو انه مهتم بالطالب ويعامله كاحد الابناء\n\nاضافة \" أغلب الطلاب اللي عنده من المنطقة الغربية , وغالبا ما نشوف احد من الشرقية والاحساء والمحافظات اللي جمبها !! \" فهمتوا ولا لا ؟؟ مدري وش السر ؟؟؟؟؟\n\n+1\n\nخسف فيني الأرض عشاني من الشرقية ورفع ربعه فوق فوق\n\nانغشمت من مدح الطلاب الزايف فيه\n\nأسوأ مدرس ماث مر علي في حياتي كلها وبدون مبالغة\n\nخلص الكورس وما فهمت منه شي\n\nأنا ساكن في الدمام و اعطاني 55 من 60 في ماث 102\nو أعرف واحد شخصياً من مكة والله ما راح له الأوفيس أور بتاتاً لا في ماث 101 و لا 102\nحتى الدكتور عاتبه مرة إنه ما يمر عليه المكتب !!\nمع ذلك ،،، أعطاه في الكلاس وورك فل مارك (60) لأنه ما شاء الله موهوب في الماث و أدى رائع في المياجر ، يعني الطالب من النوع اللي يشتغل على الصامت !!\n\nالدكتور من النوع اللي يقدر اللي يشتغل معاه و يقدم الهووموركات و يبدع في المياجر سواء كان يشبك له و ألا لا !!\n\nو بلاشي تتهموه بالعنصرية أو الطائفية الله يرضى عليكم !!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1050901-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/57", "user": "user4988", "ts": 1338814226000, "tid": 68467, "pn": 57}}]}', 1338814226000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-slooom-math101', 'stk-slooom', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term: 121\n\nالتحضير : أحيانا يحضر و أحيانا لا ، لكنه شديد في هذا الأمر و يكرهـ المتأخرين و اللي يغيبون كثير\nطريقة الشرح : يبدأ بشرح الكونسبت لكل درس ، يحل أمثلة قليلة جدا وقت الكلاس ، لكن يعوض هالنقطة في الهيلب سيشن . 🤴\nالكويزات : ثلاثة إختبارات ، الأول و الثاني صعبة شوي و فيها أفكار مياجر و لكن الأسئلة تجي من الأمثلة إللي يكتبها وقت الكلاس و يركز عليها ، الاختبار الثالث كان سهل .\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : الدكتور كبير في السن و فاهم ما شاء الله تبارك الله ، خفيف دم و في المقابل متشدد لمصلحة الطالب ، يعطيك نصائح من ذهب ، شرحه ممتاز جدا و ممتع ، كل ثلاثاء كان يعطينا هيلب سيشن لمدة ساعة و عليها ، شديد جدا في التصحيح ، يعطي درجات حلوة في الكلاس وورك للي يبدعون في المياجر .\n\nوفقك الله يا دكتور محمود ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1207709-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/68", "user": "Slooom", "ts": 1365479230000, "tid": 68467, "pn": 68}}]}', 1365479230000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ace94-math101', 'stk-ace94', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term: 131\n\nالتحضير :\nيعشق التحضير\nالكويزات :\nنظام كلاس تست ، 3 اختبارات مستواها وسط فيها اسئلة سهلة و فيها صعبة لكن غالبا الافكار ما تكون جديدة\nالمياجر: كومن\nالفاينلات : كومن\nالتقييم النهائي: A+++++\nالصوت:\nواضح في الكلاس اما الهيلب سشن إذا تقعد قدام تمام\nإضافات :الدكتور ملك الماث و للاسف انه ماينزل 102 + يعتمد في الكلاس الورك على اجتهادك معه في الكلاس و الاوفس اورز + الهيلب سشن ممتاز في التهيئة للمياجر و الفاينل + نزل معه إذا لقيت سكشن له …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1312413-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/69", "user": "ACE94", "ts": 1388499373000, "tid": 68467, "pn": 69}}]}', 1388499373000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faaisl-math101', 'stk-faaisl', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101\nترم 141\n\nالتحضير : كشف وينادي بالاسامي وعلى قولته التحضير عندي شي مقدس وان غبت لاعاد تساله عن بونس\nطريقة الشرح : يكتب الكونسبت بعدين يحل امثلة على السبورة\nالكويزات : 3 كلاس تيستات\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: c+\nالصوت: اول الايام كان مو مسموع لكن تعودنا عليه\nإضافات : .المدرس حبيب ويحب طلابه ويقدم مصلحتهم على مصلحته وكل اسبوع يعطي هلب سيشن وقبل المياجر و الفاينل بعد\n.تصحيحه غير منطقي يعني تخطي خطا بسيط يعطيك 2 من 10 وتروح توريه يقعد يناقشك شوي بعدين يعدلها وتصير تقريبا اخدت درجتك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422418-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/72", "user": "Faaisl", "ts": 1422279569000, "tid": 68467, "pn": 72}}]}', 1422279569000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-math101', 'stk-tryagain', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور محمود سرحان\nTerm 151\nMath 101\n\nالتحضير : شي مقدس جداً … أحياناً ينسى يحضر لكن إذا حضر وكنت غايب مارح يعطيك بونص في الكلاس وورك …\n\nطريقة الشرح : الدكتور فاهم فاهم فاهم لأبعد الحدود … لكن للأسف يشتتك وقت الشرح يحل هنا وهنا وهنا فلازم تكتب معاه أحيانا … يشرح الكونسيبت بطريقة جداً ممتازة ويحاول يحل أكبر قدر ممكن من الأسئلة\n\nالكويزات : لا يوجد … طول الترم ما عندك إلا 3 كلاس تيست … وهذه أعتبرها ميزة للدكتور … بعد نهاية كل شهر في كلاس تيست … مستواهم متوسط … لا صعب ولا سهل … ودرجات الكلاس وورك رح تكون عليها … تجمع درجات الكلاس تيست من 80 وتقسمها على 6 ويطلعلك درجتك من 40 في الكلاس وورك …\n\nالصوت : واطي شوي لازم تحاول تجلس في الصفوف الأمامية …\n\nالمشكلة الوحيدة 🙂 … هي إنو يسوي هيلب سيشن \" إجباري \" يوم الأربعاء … ولازم تجي عشان يعطيك بونس في الكلاس وورك …\n\nالدكتور خرافي لأبعد الحدود … الله يعطيه الف عافية وأنصحكم فيه\n\nالقريد : A+ بدون أي كلام\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438151-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/73", "user": "TryAgain", "ts": 1452077701000, "tid": 68467, "pn": 73}}]}', 1452077701000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo3mr-math101', 'stk-abo3mr', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 151\nMath 101\n\nالتحضير :\nيعشق شي اسمه تحضير وحتى لو غبت ومعك عذر يقلك مارح يفهمك الدرس العذر وعلى مقولته التحضير شي مقدس\n\nطريقة الشرح :\n\nخرافيه بالنسبه لي يبدأ بشرح اشياء خفيفه ويربطها لك ببعض الاشياء اللي حولك ثم يبدأ يتعمق\n\nويحاول يفهمك النظريه وكيف جات\n\nبالنسبه لي طريقة شرحه جدا جدا جدا ممتازه\n\nالكويزات :\n\nعندك 3 كلاس تيست طوال الترم متوسطه الصعوبه\n\nالصوت :خفيف بحكم عمر الدكتور و لاتخاف بتتعود عليه مع الايام\n\nاضافات :\nانصح وبقوه تنزل عنده\nوعنده ميزه الدكتور ان عنده هيلب سشن\n\nتصحيحه في المياجر متوسط مع ان ورقتي لو صححها دكتور اخر بتكون اعلى\n\nوكريييم جدا بالكلاس وورك\n\nنصيحه لو انك ماتحب الغياب نزل عنده ولاتترد\n\nالتقييم A\n\nالله يسعدك يادكتور سرحان في الدنيا والاخره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438749-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/74", "user": "abo3mr", "ts": 1452640204000, "tid": 68467, "pn": 74}}]}', 1452640204000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef.m.a-math101', 'stk-yousef.m.a', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور محمود سرحان MATH 101 term 151\n\nالتحضير :\nمهم جدا بالنسبة له ، ويحضر دائما على اول الحصة\nطريقة الشرح :\n• يكتب المفاهيم الأساسية فقط على السبورة\n• يهتم بشرح النظريات أكثر من شرح الأمثلة\n• اذا جاء يحل امثلة ما يفصل كثير ويختصر العديد من خطوات ، لأنه يفترض أنك عارفها\nالكويزات :\nلا يوجد كويزات لكن عنده ( 3 كلاس تست ) يعطي تاريخهم من اول السمستر ،\nمتوسطة الصعوبة الى صعبة جدا ، وشديد في التصحيح\nالمياجر :\nمشتركة\nالفاينلات :\nمشتركة\nالقريد النهائي :\n+C\nالصوت:\nكبير في السن وصوته مقبول\nإضافات :\n\n• الدكتور طيب جدا وحريص على الطلاب ويعاملهم كأبنائه.\n• أنا لا أريد أن أظلم الدكتور، فعلى الرغم من طيبته ، أجد أني خدعت بمدح الطلاب الكثير لشرحه ، فشرحه جدا عادي وغير مرتب ولا يستحق كل هذا المدح (جربت غيره من الدكاترة وشرحهم أفضل بكثير) .\n• شرح الدكتور يشتت التركيز ، فهو لا يمشي على تسلسل شرح الكتاب للدرس .\n• أسوء شيء عند الدكتور هو أنه مافي كويزات ، فقط 3 كلاس تست صعبة عليها كل الدرجات ، وهو سبب كبير لنزولها .\n• نظام الدكتور في درجات الكلاس وورك يا أبيض أو أسود (فجوة كبيرة بين درجات الطلاب) ، الطلاب الي قدروا يجيبون في الكلاس تسات الصعبة الثلاثة فوق الافرج اعطاهم في النهاية 40 من 40 اوقريب منها (وهم الأقلية ) ، الباقين يخسف فيهم خسف ولا يعمل normalization، ( الأكثرية) أخذو درجات في العشرينيات أو أقل\n• انا حضرت أغلب الهليب سيشن وما كان عندي الا غياب واحد ومداوم في الصف الأول ، مع كذا ماعطاني بونص لاني توزيع الدرجات عنده فقط يعتمد على اختبارات الكلاس تست .\n• باختصار الدكتور شرحه عادي جدا وغير منظم وتوزيع الدرجات عنده غير منطقي ابدا ، فلا تخدع مثلي بالمدح الكبير له و تجعله خيارك الأول في التسجيل .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467136-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/75", "user": "yousef.m.a", "ts": 1485590704000, "tid": 68467, "pn": 75}}]}', 1485590704000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-owheading-math101', 'stk-owheading', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 TERM 161\nالتحضير :\nمهم , مايحضر دائمًا\nطريقة الشرح :\nناسبتني جدًا\nيبدأ من شي صغير ومفهوم بسيط وتسرح معاه لين يوصلك لفكرة الدرس\nويشرح أمثلة كافية\nالكويزات : ثلاث كوزات متوسطة الصعوبة بشكل عام\nالمياجر: مشتركة\nالفاينلات : مشتركة\nالقريد النهائي: B+\nالصوت: منخفض ولكن تتعود عليه بسرعة\nإضافات :\nمن أفضل الدكاترة الي درسوني ماشاء الله عليه ربي يحفظه ويحميه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472509-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/76", "user": "OWHEADING", "ts": 1493907278000, "tid": 68467, "pn": 76}}]}', 1493907278000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9537-math101', 'stk-user9537', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا درست عنده math101 في 122\nالتحضير : يومياً ينادي بالأرقام والتحضير تقريبا في نص المحاضرة\n\nطريقة الشرح : أول شيء يبدأ بكتابة النظرية ثم يبدأ يحل أمثله عليها والأمثلة متنوعة مابين سهلة إلى صعبة ولاكن الأغلب سهلة، طريقة الشرح مجملاً جيدة لكن انا ماعجبني لأنه مايركز كثيرا على الإثباتات اللي هي الأساس ولايركز على تفهيم الكونسبت على طول يدرعم بحل المسائل،\n\nالكويزات : تقريبا أعطانا 6 كويزات بعضها عبارة عن واجب تحله بالبيت وتسلمه بالكلاس ويعتبره كويز، وبعضها بالكلاس ويكون مستواها فوق المتوسط\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي:\n+C\n\nالصوت: واضح لكن الأستاذ انجليزيته رايح فيها جدا جدا جدا، والقرامر عنده مضروبه بقوة\n\nإضافات : الاستاذ مجملاً جيد وفي رأيي أن الرياضيات تعتمد اكثر شيء على الطالب وجهده فيالمذاكرة وحل المسائل وبالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1228932-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/9", "user": "user9537", "ts": 1369684559000, "tid": 68471, "pn": 9}}]}', 1369684559000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-math101', 'stk-magbool', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101 - 123\nبنود التقييم :\n\nالتحضير :\nكل كلاس تقريبا بعد 15 او 20 دقيقة من بداية الكلاس.\n\nطريقة الشرح :\nما عجبتني ، يبدأ بالقاعدة ويشرحها شرح شريع ماتفهمه، ثم يخش على الأمثلة اللي انتا وحظك، بعض الدروس يجيبلها أمثلة كلها سهلة وبعضها متوسطة وأحيانا يجيب أمثلة كلها صعبة ما تققدر تفهم معاها القاعدة الرئيسية\n\nالكويزات :\nحسب المزاج، بعضها صعب وبعضها سهل ، لكن التصحيح لا تستغرب إنه ينقصك على حرف ما كتبته.\n\nالمياجر:\ncommon\n\nالفاينلات :\ncommon\n\nالقريد النهائي: B\n\nالصوت:\nمو عالي لكن مسموع\n\nإضافات :\nلغة الدكتور الانقليزية تعبانة، تسأله سؤال توقع إنه يستهجنه، الكلاس ممل لأنه نادرا ماينكت، أخلاقه حسب مزاجه ، يعني يوم يجيك أخلااااق ويوم يجيك ما يطالع في وجهك…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1252399-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/16", "user": "magbool", "ts": 1376355596000, "tid": 68471, "pn": 16}}]}', 1376355596000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-emadba7-math101', 'stk-emadba7', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمة الله وبركاته\n\nحاليا (Term 131) يدرسني مادة Math 101\n\nبنود التقييم\n\nالتحضير : يحضار في نص الحصة يمسك الورقة وينادي بالارقام وعينه عالطلاب عشان لحد يرفع يده مرتين ويحضر صاحبه, بالنسبة للتأخير عادي ما يدقق لو اتأخرت كم دقيقة مو مشكلة\n\nطريقة الشرح : ما عندو انو يبدأ بالكونسبت والقواعد والاهداف من الدرس لالا على طول يبدأ يحل امثلة (من غير امثلة الكتاب وهذا شي ايجابي عشان يكون عندك امثلة محلولة اكثر ) لكن اذا في قواعد مهمة يكتبها قبل الحل\n\nالكويزات : تقريبا اسبوعية , احيانا سكشن او 2 على حسب قد ايش خلصنا وتعتبر للي فاهم الدرس مزبوط عادية متوسطة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+\n\nالصوت: عندو مشكلة انو كلامه سرريع جددا احيانا ما يكمل الكلمة كمان ههههه لكن عادي يمشي الحال\n\nإضافات : الدكتور يعتبر طيب وانا اشوف ايجابيته انو يحل امثلة كثير تذاكر منها وقت الميجر, وعلاقته معاه استاذ لطالب لا اكثر من يوم ما يخش يمسك الطبشور ويبدأ يحل ما يفتح مواضيع جانبية وهذي سلبية تحس معاه بالملل , ولو بقي 4 دقايق ما يسيبها يبدأ يحل سؤال ثاني\n\nتــــــــــــــحياتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1286909-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/18", "user": "Emadba7", "ts": 1384367668000, "tid": 68471, "pn": 18}}]}', 1384367668000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-math101', 'stk-abo-da7m', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة والفصل\nmath 101 | 131\nالتحضير :* يحضر بالأرقام بنص المحاضرة\n* يتساهل مع المتأخرين\nطريقة الشرح :* يستخدم السبورة فقط\n* يكتب القاعدة ويشرحه بعدين يعطي مثالين إلى ثلاثة\n* يترك وقت كافي جدا لأسئلة الطلاب والجواب عليهن بين كل فقرة وفقرة\n* ما عنده مشكلة يعيدلك أكثر من مرة، إذا ما فهمت أهم شي تصير مركز معه\nالكويزات :\n* بعضها سهل جدا وبعضها متوسط\n* 6 كويزات بالفصل تقريبا\n**المياجر:**مشتركة\n**الفاينلات :**مشتركة\n**القريد النهائي:**a+\n**الصوت:**واضح\nإضافات :* الاستاذ متمكن من مهنته وخبرة طويلة بالتدريس\n* مناسب جدا جدا لمتوسط الطلاب، الطالب الجيد يمكن ما يعجبه لأنه يعيد ويركز على أشياء واضحه بعض الأحيان\n* انتبه وانتبه تلعب بجوالك أو تسولف بوسط المحاضرة خطر يجيك تهزيء 🤪\n* يعيبه أنه ما يحل أمثلة صعبة فتتفاجأ بأسئلة المياجر نوعا ما اذا ما تعودت عليهن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1312535-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/19", "user": "abo-da7m", "ts": 1388517608000, "tid": 68471, "pn": 19}}]}', 1388517608000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bandar_abdullah-math101', 'stk-bandar_abdullah', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 … term 181\n\nالتحضير :\nيحضر بنص الكلاس بالسيريال نمبر\n\nطريقة الشرح :\n- بنوتات مختصره ومسائلها قليله لكن بالغالب تغطي افكار الكورس الا كم فكره.\n\nالكويزات :\nالشيء المميز فيه كويزات نسخ لصق من ال suggest problems الي بالكتاب حلها وافهمها واضمن لك الفل مارك 👏\nيعطي 7 كويزات وياخذ افضل 5 وعطانا بونص درجتين كل طالب.\n\nالتصحيح :\nفي الكويزات للاسف يدقق على اتفه الاشياء فتأكد انك تكتب كل خطوات الحل بالورقه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503930-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/39", "user": "Bandar_Abdullah", "ts": 1545513740000, "tid": 68471, "pn": 39}}]}', 1545513740000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muradadnan007-math101', 'stk-muradadnan007', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 term 181\n\nالتحضير: يحضر يوميا ومايقبل ميك اب الا بعد مايذلك وترسلو عالايميل وترسلو فالواتس وفالكلاس كمان يذلك لما تتاخر يسالك وين كنت وكذا بعدين يدخلك .\nطريقة الشرح: تسليكية ويحاول يحفظك الكورس اكثر من ان يفهمك لكن كمجمل نوتات فيها اسئلة بسيطة جدا والباقي لابد انت تعرفو بمجهودك وشرحو يكون بالكتابة فالسبورة بخط سيييييييييييييييييييييء يعني فوق الشرح السيء خط اسوأ ومايحب احد يسال كثير مع انو كل شويا يقول في احد مو فاهم ولكن اذا رفعت يدك لابد تتهزأ شويا ويعيد نفس الكلام .\nالكويزات: نسخ لصق من suggested problems مع ذلك الافرج نازل لان مافي احد فاهم بس تقدر تطلع من عندو ب درجة كاملة فالكلاس وورك اذا اتجهزت وفهمت بمجودك.\n\nالقريد النهائي: d+ البلص عشان الكويزات سهلة فقط\n\nاضافات : من ناحيتي الشخصية اسوأ دكتور مر عليا ومااعتقد انو في احد اسوأ منو لا وكمان لما نزلت القريدات وقاعدين نكلمو فالقروب انو ينزلها لنا عالبلاك بورد لان في كثير مسافرين وبرا الجامعةخرج من القروب بدون مايتكلم 🙂 زبدة الكلام اذا درست عندو الله يعينك حتمشيها سيلف ستدي الكورس كامل والحمدلله طلعت بقريد كويس وهذا كلو بفضل الله ثم الدكتور محسن الشهراني لاني كنت ادوام عند محسن لان يعقوب احضر عندو عشان التحضير فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504018-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/40", "user": "Muradadnan007", "ts": 1545679275000, "tid": 68471, "pn": 40}}]}', 1545679275000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_2015-math101', 'stk-faisal_2015', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 ترم 171\n\nالتحضير 5 دقايق بعدها ما يدخلك الا بكلمتين وبعد 10 دقايق لا تجي احسن\nالشرح بالنسبة لي ما فهمت عليه كشرح لفكرة الدرس لكن بالمسائل ممتاز لذلك اذا حضرت قبل الكلاس بتكون امورك طيبة\nكويزاته متوسطة الى صعبة\nالميجر والفاينل كومن\nالصوت واضح واللكنة ايضا\nملاحظات الدكتور الله يسامحه قال بيحذف اسوء كويزين من اصل 7 اظن فجبت فيهم صفر و واحد والباقي افرجي 7 ونص لكن للاسف حسب كل الكويزات نهاية الترم و زاد عليها لكن ما نفعتني لذلك ضبط وضعك بالكويزات والشي الثاني الدكنور شديد بموضوع الجوال فالافضل تطفيه قبل لا تدخل\nالقريد النهائي B\nويهتم بالطلاب ويسوي مراجعات حلوة قبل الميجر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504325-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/41", "user": "Faisal_2015", "ts": 1546296586000, "tid": 68471, "pn": 41}}]}', 1546296586000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-acv-math101', 'stk-acv', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 term 181\nالتحضير: مايسمح بالتأخيرابدا ينادي بالرقام الي بالكشف\nماجر كومون\nالكلاس وورك متعاون جدا\nمن ناحية الغياب مايخصم ولا يسوي شي بس اذا وصلت 12 غياب DN. اعتقد انه غير نظامه.\nاعتقد انه مناسب لل سيلف ستدي.\nالصراحه ما كنت اعتمد عليه وجبت جريد حلو\nfinal grade+B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504793-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/43", "user": "ACV", "ts": 1547147212000, "tid": 68471, "pn": 43}}]}', 1547147212000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-math101', 'stk-user10218', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68472", "n": "Dr. Stephen Binns", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 T-141\n\nالتحضير :\n\nغالبا في نهاية الكلاس ينادي الاسماء او الارقام\nأوقات ما يتذكر الا في نهاية الوقت = ما يحضر\n\nفي كم درجة على الحضور (درجتين تقريبا )\n\nطريقة الشرح :\n\nرهيب\n\nشرح مبدع و واضح وتفهم عليه\n\nيكتب نوت مشكلة من الكتاب و عنده ومن أسئلة اختبارات قديمة\n\nالكويزات :\n\nقليله عطانا بس 2\n\nقبل الميجر الاول و قبل الميجر الثاني\n\nسهلة الى متوسطة = تذاكر تحل\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\nالقريد النهائي:\n\nِA+\n\nالصوت:\n\nأكسنت واااااااضح حده < الإنجلش لغته الأم\n\nإضافات :\n\n* الرجال ما شاءالله عليه متمكن من الماث\n\n* متواجد في الأوفس أور ويفهمك عدل\n\n*الكلاس ورك يعطيك حقك (ممكن يكون فيه بونص صغير )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437927-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stephen-binns/68472/51", "user": "user10218", "ts": 1451848878000, "tid": 68472, "pn": 51}}]}', 1451848878000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cpc_2015-math101', 'stk-cpc_2015', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68474", "n": "Dr. Waleed Al-Sabah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 ترم 151\n\nالتحضير بشكل يومي ، حافظ أسماء الطلاب فيحضرهم بدون ما يقرى الأسامي\n\nالشرح : يهتم بشكل كبير بال concept و يعطي مثال ،\n\nأكبر نقطة إيجابية فيه أنه مدرس قمة في أخلاقة و تعاملاته طيب جدا جدا جدا و متواضع\n\nنقطة سلبية فيه تصحيحه شوي يخسف فيك و كوزاته فيها صعوبه\n\nالتقييم النهائي للمدرس : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434473-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/waleed-al-sabah/68474/22", "user": "CPC_2015", "ts": 1448449781000, "tid": 68474, "pn": 22}}]}', 1448449781000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-azzubair-math101', 'stk-azzubair', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68474", "n": "Dr. Waleed Al-Sabah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور طيب ويشرح لكن يضيع المحاضره وهو يشرح الكونسيبت ولا يحل تمارين ابدا\nانا نزلت عنده Math 101 واخذت F ما اقول انه هو السبب لكن انا متأكد لو اني دخلت عند دكتور ثاني كان عديت\n\nانصحكم ما تنزلوا عنده ماث ابدااااا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438471-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/waleed-al-sabah/68474/24", "user": "azzubair", "ts": 1452435450000, "tid": 68474, "pn": 24}}]}', 1452435450000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10509-math101', 'stk-user10509', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68474", "n": "Dr. Waleed Al-Sabah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 - تيرم 151\n\nالصراحة الدكتور جيد و لكن ليس ممتاز\n\nشرحه : ليس الأفضل لكن يمشي الحال .\nالتحضير : حضر تقريبًا أول شهرين و بعدها ما حضر أبدًا !\nالتصحيح : والله الشباب فجعونا منه … لكن كان تصحيحه عادي بالنسبة لي .\n\nملحوظة أخيرة : الدكتور أخلاقه جيدة و يسولف مع الطلاب و ينكت و كلاسه ممتع نوعًا ما 🙂\n\nإذا نزلت معه شد حيلك لكن لا تخاف", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438727-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/waleed-al-sabah/68474/25", "user": "user10509", "ts": 1452627084000, "tid": 68474, "pn": 25}}]}', 1452627084000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisalovic-math101', 'stk-faisalovic', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68474", "n": "Dr. Waleed Al-Sabah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**Math 101\\-181** التحضير : حضر اول اسبوعين بعدها ما حضر ابداً , طبعا الدكتور يعرف اسامي الكلاس كامل من اول اسبوع يعني اذا سحبت بيعرف انك سحبت\n\nطريقة الشرح : من سلايدات د.ابو صبيح, يمشي مع السلايدات بدون كتابة ونادرا ما يكتب على السبورة , مع نهاية الكورس بدأ يغير طريقته يعني يعطينا بس الكونسبت ويحل examples من السلايدات , بشكل عام الشرح مش ولا بد , عن نفسي كنت اعتمد على نوتات د. محسن الشهراني .\n\nالكويزات : صلخ في صلخ , اعلى من مستوى الشرح بشكل كبير جدا , افرج الكلاس في النهاية كان 18 من 50 في الكويزات , لدرجة انه في النهاية زود كل واحد 14 بوينت عشان يرفع الافرج الى (28-30 )\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: متوسط الى ضعيف لان الشرح سيئ جدا وهذا اهم شي بالنسبة لي , ولكن من ناحية الاخلاق فالدكتور في قمة الاخلاق والتعاون , في اول يوم قدم لنا طبق شوكلاتة patchi يعطيه العافيه 👍\n\nالصوت: واضح جدا , الشرح بالإنجليزي وبعض الاحيان يتكلم عربي\n\nإضافات : الدكتور مش سيئ لكن خليه خيارك الثالث , اذا نزلت عنده اعتمد على نفسك اعتماد جذري واستعد للكويز مثل استعدادك للميجر وبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504415-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/waleed-al-sabah/68474/26", "user": "FAISALOVIC", "ts": 1546429391000, "tid": 68474, "pn": 26}}]}', 1546429391000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mooha-math101', 'stk-mooha', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68561", "n": "Dr. Abdulaziz Al-Assaf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :بداية الكلاس\nطريقة الشرح :متوسطة ويعتمد بالامثلة على الكتاب كثيرا\nالكويزات :متوسطة\nالصوت:واضح\nإضافات :\nاخذت معه ماث 101 الصراحة الدكتور غير كل الي يقال عنه\nدكتور محترم +يحب المزح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p343802-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-assaf/68561/3", "user": "Mooha", "ts": 1230249351000, "tid": 68561, "pn": 3}}]}', 1230249351000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2316-math101', 'stk-user2316', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^^^^^^\nويلكم باك يابو حميد\n\nايش تبغوني اقول في اسلم شودري ؟؟طيب حبوب شريح ؟؟؟\n\nشودري من افضل الدكاترة الموجودين في الجامعة وانا احترمه احترامات كثيرات لوووول\nانا اخذت ماث 101 وكان سئ بوجهة نظري لكن بقدرة قادر جاني اسلم ل 201 وانا ما اخترته بسبب حركات قسم الماث لكن رب ضارة نافعة… الدكتور مبدع في ماث 201 لابعد الحدود ولا اتوقع انه فيه له مثيل او منافس…\n\nبالنسبة للتحضير فلا يعترف فيه لكن بعض المرات القلائل يمرر الورقة بناءْ على طلب الكواردنيتور.\nالصوت ممتاز وواضح\nالكويزات كانت تيك هوم يعني بالعربي مافي كويزات في الكلاس ابدا تروح بيتك وتنقشها وتجيبها ومن سمستر 81 ما صحح الكويزات لانه كثييير من اجوبتي خطأ وكلام فاضي ومعطيني صح\nلكن طريقة الكلاس وورك فكانت ظاااالمة جدا الله يسامحه نكبنا\n\nلكن في الاخير الحمد لله على كل حال واعطيه a لماث 201 فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p375108-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/12", "user": "user2316", "ts": 1235982079000, "tid": 68565, "pn": 12}}]}', 1235982079000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_taleb-math101', 'stk-abo_taleb', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور حبيـــب وفيه طيبة عجيبـــة…\nكلاس الماث يمشـي معه بسرعـة غير طبيعيـة…\nيعني تجلس الـ 50 دقيقة كاملـة وما تحس فيها ابد…\nوكريـم بالكلاس وورك بشكل كبير وما تعوق معه ابد انه يعطيك الـ 60…!!\nنوته جيـدة ولكن للأمانة ليست متميزة…يعني في دكاترة ثانيين نوتهم افضل في ماث 101…\nاعطيه ّa+…\nالله يذكره بالخير وليت كل الدكاترة مثلـه…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p546381-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/35", "user": "Abo_Taleb", "ts": 1266579684000, "tid": 68565, "pn": 35}}]}', 1266579684000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student_nz-math101', 'stk-student_nz', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101\n\nمدرس ما شاء الله تبارك الله\n\nفاهم من جد فاهم\n\nيوصل المعلومة باقل الاضرار بدون وجع راس حتى احيانا يشبها بتشبيها غريبة\nيعني مرة يقول\nهزا قانون بحريني >> ما ادري ايش كان يقصد ببحريني لكن القانون مذكره لحد الحين\n\nنوت ولا اروع انتبه نوته ما ينفع تذاكره لحاله ذاكره لميجر ون + اولد اقزام\nونفس الشي ميجر 2\nالفاينل امشي على نوته على السريع وامسك الكتاب\n\nالتحضير يحضر كل حصة\n\nالكوزات تاك هوم\n\nالكلاس ورك\n\nكل واحد قال انه افرج بين الميجرين غلطان\nانا اخذت الفل مارك و الميجرين كانوا دمااااااار عندي\n\nالحمد لله\n\nمدرس ميه ميه اخلاق وشرح وحصة حلوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p641325-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/43", "user": "student_NZ", "ts": 1277150681000, "tid": 68565, "pn": 43}}, {"id": "stk-dr-m83633", "n": "أ. أبالارا تيجاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 092 ريستيشن ماث 101\n\nالادمي فااااهم جدا\nلكن توصيل المعلومة عنده يمكن 5 من 10\nالاكسنت سيء جدا >> بتاخذ وقت حتى تفهم عليه\n\nالتحضير خلص السمستر و ما فوووت اي تحضير طبعا ينادي بالارقام\nوترى اعطى خويي دي ان يعني ما عنده مشكلة يعطي دي ان انتبه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p715472-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/83633/16", "user": "student_NZ", "ts": 1286353659000, "tid": 83633, "pn": 16}}, {"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 101 ماث 102\n\nالتحضير :\nكل كلاس ويكره الغائيبين و المتاخرين\nاخر السنة طلع لي 3 غيابات ما ادري من وين؟\nشيك الغيابات معاه اول باول لانه يخصم عليها\n\nطريقة الشرح :\nكويسه وسريعه\n\nالكويزات :\nصعببببببببببببه او ان المنهج كان طبيعته صعبه عاد الله اعلم\n\nالمياجر:\n\nكومن وتصحيحه للمياجر اكثر من عادي\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\n\nB\n\nالصوت:\nاذا كان الكلاس كبير\nلا تجلس في الاخير ما راح تسمع كويس\nإضافات :", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p778484-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/33", "user": "student_NZ", "ts": 1296332799000, "tid": 68582, "pn": 33}}]}', 1277150681000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4181-math101', 'stk-user4181', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^^^^^^^\n\nانا منزل عند شودري الصيف 201 واخذت عند احمد شوقي 91 ماث 101\nانصحك وبقوة بأحمد شوقي قمة القمم ما شاء الله عليه واما شودري بأجربه الصيف هذا والله يوفق الجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p647936-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/46", "user": "user4181", "ts": 1277831447000, "tid": 68565, "pn": 46}}]}', 1277831447000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-equal-math101', 'stk-equal', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الأفضل بلا منازع !! A+\n\nدكتور تهمه مصلحة الطالب بالدرجة الأولى … خفيف دم … شرّيح … ما أعتقد فيه دكتور في الجامعة مثله !\n\nالتحضير : ورقة تمر على الطلاب … ولا يشيك عليها … ما يحاسب على التأخير لكن لا تزودها معه …\nطريقة الشرح : ممتازة … يوضح المفاهيم بشكل رائع ومبسط …\nالكويزات : تيك هوم … تاخذها وتحلها وتجيبها معك … قليلة جداً … وما يطلب هوموركات كثير … الى الان سلمناه 3 هوموركات …\nالمياجر: متساهل جداً في تصحيح الرتن …\nالقريد النهائي: ما أظن فيه قريد يوفي هذا الدكتور حقه … 10/10\nالصوت: واضح وثلاثة أرباع كلامة عربي … خفيف دم والله …\nإضافات : الله يجزيه خير … ملك بمعنى الكلمة !!\n\nالدكتور متساهل جداً مع الطلاب … يعني بترتاح معه …\nلكن اعتمد على نفسك في المذاكرة وشد حيلك … لأن الدكتور ما يشد عليك أبداً … فحاول تعطي الكورس حقه …\n\nماث 101 معه متعة والله … أنصح فيه وبشدة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p750927-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/51", "user": "equal", "ts": 1293199917000, "tid": 68565, "pn": 51}}]}', 1293199917000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-brain_man-math101', 'stk-brain_man', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nأنا اخذت معاه ماث 101 - ترم 102\n\nالتحضير : ورقة تمر ع الكلاس … وما يهتم بالتأخير أبد لو تجي آخر دقيقة ما عنده مشكلة …\n\nالكويزات : يعطيك تحلها في البيت وترجعها ^^ وما يصححها أصلا … إذا جبت الكويز ضمنت الدرجة كاملة\n\nالكلاس وورك : تاخذ أكثر من حقك بكثييييييييييير … اذا سلمت الهومووركات والكويزات وما غبت ولا كلاس تاخذ 60 من 60 على طول\n\nالمياجر … هو عنده مشكلة شوي في المياجر … ميجر 1 تقدر تسمع كلامه لانه ريتن وهو اللي بيصحح ويعطيك أكثر من حقك …\nبس في الفاينال وميجر 2 لازم تشوف أولد إكزامز عشان تعرف كيف طريقة الأسئلة\nهو مرررة فاهم ويقولك ع الأسئلة اللي لازم تجي في الاختبار وفعلا تجيك\n\nإضافات : طييييب جداااا وحبوب وتعامله حلو مع الطلاب وكلاسه وناسه … والدكتور الوحييييد اللي شفته يسمح بالشاي والكوفي وهالأشياء في الكلاس … بس لا يدق جوالك في الكلاس :d\n\nالتقييم النهائي : A+++++++++ وبجداااااااااااااااارة … دكتور عظيم ^_*\n\nنصيحتي أي كورس تلقاه معاه نزل معاه ولا تشاور 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p853907-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/55", "user": "Brain_Man", "ts": 1308155850000, "tid": 68565, "pn": 55}}]}', 1308155850000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5900-math101', 'stk-user5900', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يا أخوان أنا كنت معاه في ترم 102 ماث 101\n\nالتحضير : لو تجيب قبل نهاية الكلاس بدقيقة أنت حاضر\nمتساهل كثير بالتحضير\n\nالكوزات : Take home\n\nالتصحيح بطلل ويمشي كثيررررر\n\nعدد الهوموركات 5 في الترم\nعدد الكوزات 5 في الترم\n\nإذا سلمتهم كلهم وحضرت كل الكلاسات بدون غياب تآخذ 60 / 60 في الكلاس وورك\n\nنصيحة للأخوان … ترى في الشرح عادي جداً مثله مثل أي دكتور آخر … نوته مافادني كثيرر بالمياجر\n\nلكن فيه طيبة قلب عجيبة وخفيف دم لدرجة أنه يسمح للطالب بشرب قهوة / شاي / موية داخل الكلاس\n\nلكن صرآآآحة مايعودك على المادة وراح يصييبك أهمال شديد لأنه مدرس متساهل جداً\n\nتقييمي للمدرس : A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p881141-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/62", "user": "user5900", "ts": 1312703381000, "tid": 68565, "pn": 62}}]}', 1312703381000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-suzuki-math101', 'stk-suzuki', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أسأل الله تعالى أن يشفيه\n\nطيب يا شباب\n\nالترم الجاي 112 له سكشن واحد في ماث 101\n\nتنصحونا ننزل معه ؟؟\n\nو الشيء الثاني :\n\nالشباب اللي يقولون انه الكلاس وورك عنده يعتمد على المياجر\n\nيعني ميجر 1 + ميجر 2 / 2\n\nهل هذا الكلام صحيح ؟؟ و هل ما زال يطبق نفس الطريقة\n\nلاني اشوفها نكبة صراحة …\n\nهذا الرد من عام 31-01-2009\n\nفهل ما زال يتبع نفس النظام ولا غير طريقته ؟؟\n\nو شكرا لكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p964873-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/71", "user": "SuZuKi", "ts": 1326306813000, "tid": 68565, "pn": 71}}]}', 1326306813000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_khaled-math101', 'stk-abu_khaled', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 term 102\nالتحضير :يحضر تقريبا اخر الكلاس\n\nطريقة الشرح : يعطي مقدمه بسيطه عن الي بيشرحه و يحل امثله من الكتاب ومن old exam\n\nالكويزات : يختار اسئله سهله من old exam بالارقام\n\nالصوت: واضح ويشرح بالانجليزي والعربي\n\nإضافات : مدرس ممتاز واخلاق ماشاء الله عليه. هو كان طالب بالجامعه وعارف مشاكل الطلاب ويتناقش معهم\nاخر اسبوعين تقريبا كان يخلص الشرح قبل 5 الى 10دقائق ويقعد يناقش الطلاب ومشاكلهم مع الخدمات الجامعية يقول عشان يناقشها مع لجنه مدري ايش", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p853434-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/20", "user": "abu_khaled", "ts": 1308102027000, "tid": 68568, "pn": 20}}]}', 1308102027000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_cave-math101', 'stk-black_cave', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور حسين العطاس\n\nماث 101 ترم 102\n\nالتحضير :\nبعد نصف ساعة بالضبط من بداية الكلاس و احيانا قبل\nطريقة الشرح :\nيكتب العنوان و يتكلم شوي عن الدرس\nيكتب نوت عبارة عن ملخص للكتاب مع حل الامثلة في الكتاب\nو اخر ربع او ثلث ساعة يحل بعض اسئلة الاولد اكزامز\nالكويزات :\nمو بذيك الصعوبة يعني تقريبا معظمها من النوت مع شوية لعب خفيف بس مو بذاك التعقيد\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي: +a\nالصوت:\nواضح جدا\nإضافات :\nدكتور رائع و خلوق و احسن مافيه انه يعامل الطالب على انه اخوه الصغير او ابنه\nطول السمستر ما شفته عصب ابدا\nو الكلاس وورك ما يقصر\nتصحيحه بالميجر يكون ولا اروع و يحاول يساعد الطالب بقدر الامكان\nو كان اخر السمستر يناقش الطلاب عن بعض القضايا الاكاديمية و الجامعية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p940872-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/22", "user": "BlAcK_CAVE", "ts": 1322766363000, "tid": 68568, "pn": 22}}]}', 1322766363000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ash800-math101', 'stk-ash800', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - term 181\nالتحضير : يحضر نهايه الكلاس بالسيريال نمبر\nطريقة الشرح :يفتح سلايدات احد الدكاتره و يشرح الكونسبت بسرعه وشرحه ماهو ذاك الزود\nالكويزات : عطانا تقريبا 3 او 4 كويزات واسئلتهم كثيره حول 10 اسئلة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: واضح وماعليه كلام\nإضافات : - الدكتور اخلاق ومحترم ويدف الطلاب في الكلاس وورك\n- انصح فيه للي مايعتمد على شرح الدكتور ويتعب على نفسه في المذاكره من مصادر اخرى لان نوتته ماتكفي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510093-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/33", "user": "ash800", "ts": 1558641756000, "tid": 68568, "pn": 33}}]}', 1558641756000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-arkawm-math101', 'stk-arkawm', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - term 181\nالتحضير : يحضر نهاية الكلاس بالسيريال ( الصدق انه ما يهتم كثير فأحيانا يفوت التحضير )\nطريقة الشرح : يشرح من نوتات ، الشرح نوعا ما سريع، لكن ميزة الدكتور يحل اسئلة كثير فأتوقع لو واحد حضر الدرس 10د بينبسط كثير من الشرح.\nالكويزات : 4 كوزات صعبه نوعا ما لكن التصحيح عسل وتغاضي كثير.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : - من أفضل الدكاترة اخلاق وتعامل مروا علي يعامل الطالب كإبنه بالضبط.\nبالنسبه لي اعتمدت في المذاكرة اكثر من نوتات الدكتور محسن الشهراني لأني ما كنت افهم كل شي من الدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519454-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/34", "user": "ARKAWM", "ts": 1580147850000, "tid": 68568, "pn": 34}}]}', 1580147850000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest_30o5-math101', 'stk-guest_30o5', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**Math101--**Term201(online )\nالتحضير : متساهل ماكان يحضرنا دايم\nالشرح : بطل يستعمل نوته دكتور ابو صبيح ويحل اسئلة كثير سريع حبتين بس تفهم وفي الاوفس اور موجود ودكتور اخلاقه لايعلى عليها + سوى لنا 2 هلب سشن مدت كل وحده ساعتين ونص حل اولدات وافكار متنوعه وبدع\nالكويزات: عباره عن افكار الاولد وتكون طويله 6-8 اسئله والافرج نازل لازم تشد لان قليله كويزاته يمكن3-4 طول الترم مقدور عليها\nالصوت: واضح\nاضافات: لو حصل وشفته منزل اي كورس بعيده عنده\nالقريد: ِA بجدارة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532660-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/36", "user": "guest_30O5", "ts": 1636360534000, "tid": 68568, "pn": 36}}]}', 1636360534000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_aldoseri-math101', 'stk-mohammed_aldoseri', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term 211\n\nالتحضير :\nيحضّر نهاية الكلاسات وبعض الأيام ما يحضّر, ما يحاسب عالتأخير بس ينبّه عنه, وما جربت أسوي عنده ميك أب.\n\nطريقة الشرح :\nيشرح الكونسبت من نوتة ابو صبيح ثم يبدأ يحل أولدات والشرح ممتاز وما عنده مشكلة يعيد شرح نقطة معينة لو ما فهمت. الشرح مكس عربي وانجلش.\n\nالكويزات :\nعطانا 6 كويزات وكل كويز فيه من 4 الى 6 أسئلة ومدة الكويز في الغالب تكون كامل وقت كلاس الريسايتيشن. بالنسبة لي كانت كويزاته متوسطة وأوقات أشوفها سهلة. ويكرر بعض الأفكارمن كويزاته القديمة وتصحيحه بطل ويعطي درجات على الخطوات ويمشّي بعض الأخطاء البسيطة.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+ ولو في أعلى عطيته.\n\nالصوت:\nواضح و لهجته مفهومة\n\nإضافات :\nبالنسبة للأخلاق والتعامل لا تشيل هم لأن الدكتور وسيع صدر ومتفهم لوضع الطلاب ويدري ايش يواجهونه. الدكتور حسين من أعجب ما رأيت. الهلب سشن قبل المياجر وقبل الفاينل توصل الى 4 ساعات يراجع فيها الكونسبت ويحل أولدات جامعها ومرتبها من ترم 161 الى 192. وما عنده مشكلة في وقت الهلب سشن لأنه يستمتع بالشرح ومرن في مواعيده ويراعي ظروف الطلاب كثير. والأوفس أور عنده ما يقصر في أي شي تبيه منه. وفي النهاية لو شفت أسمه لا تتردد في التسجيل عنده وخله من خياراتك الثلاثة الأولى.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533454-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/37", "user": "Mohammed_Aldoseri", "ts": 1642130722000, "tid": 68568, "pn": 37}}]}', 1642130722000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-gonal-math101', 'stk-gonal', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term 211\nالتحضير :\nنهاية الكلاسات وما يحاسب على التأخير\nطريقة الشرح :\nنوتة أبو صبيح واذا كان في وقت فتح اولدات وحلها\nالكويزات :\n6 كويزات من متوسطة الى سهلة مذاكرة نوتات محسن كانت كافية لحلها.\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nA+ دكتور أسطوري ومنزل عنده الحين 102 فـ 212\nالصوت:\nواضح جدا.\nإضافات :\nالدكتور أخلاق وتعامل أكثر من رائع, يقدم هيلب سشنز خاصه لسكاشنه قبل كل ميجر أو فاينل يشرح فيها أغلب الأولدات القديمة,\nلو قدرت تسجل عنده فـ لا تتراجع أبدا وراح تدعيلي 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533487-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/38", "user": "GONAL", "ts": 1642298783000, "tid": 68568, "pn": 38}}]}', 1642298783000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4465-math101', 'stk-user4465', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سلام عليكم\n\nانا اخذت عنده ماث 101 في 83\n\nيعتبر احد افضل 2 في المادة - رأي شخصي -\n\nالتحضير :\n\nيومي وفي منتصف الحصة عشان الطلاب يلحقوا يكتبوا اللي على السبورة\n\nوما يسجل ليت لمن حضر قبل التحضير\n\nطريقة الشرح :\n\nشرحه حلو لكن في افكار كثيره ما يشرحها يمكن لضيق الوقت\n\nالكلاس شوي ممل ذلك - والله اعلم - لطباع المدرس الهادئة جدا جدا جدا\n\nيعتمد على الناحية النظرية اكثر من العملية\n\nتلقاه يكتب كلام دش وخطوات حل في مظم الاحيان ماهي ضرورية يمكن تضيع وقت الكلاس\n\nوالامثله اللي يحلها سهله وتعتمد على الافكار الرئيسية\n\nالكويزات :\n\nعلى مستوى الشرح -متوسطه مايلة للصعوبة -\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nA\n\nالصوت:\n\nزي ما قالوا الشباب ضعيف جدا\n\nعشان كذا اغلب الطلاب يتسابقو على الصف الاول\n\nفحاول ان تكون منهم\n\nإضافات :\n\nانا ذاكرت النوت حقه واكثر من 3 اولد اقزام وجبت a والحمد لله\n\nالاولد اقزام فيه افكااااااااااااااااار كثيره ما يمدي المدرس يشرحها في الكلاس\n\nفحاول ان تحل اكبر عدد ممكن منها سواء في المياجر او الفاينل\n\nولو القاه في اي ماده ثانية راح انزال معاه على طوووول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p467065-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/22", "user": "user4465", "ts": 1254380314000, "tid": 68569, "pn": 22}}]}', 1254380314000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-che28-math101', 'stk-che28', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 … 091\nالتحضير : مايفوت كلاس … كل كلاس لازم تحضير …وعادة يكون بعد 25 دقيقة من بدايةالكلاس\nطريقة الشرح: دكتور مرتب في النوت … يمكنك الأعتماد عليه في تسجيل نوت واخذ مرجع متكامل\nللمذاكرةعن طرق نوته… يفهمك الماتيريال بحذافيره…ومافي امل تخرج من الكلاس مو فاهم\nويعطي امثله خطيرة مرة في كل سكشن … وميزة هذا الدكتور هي (( انه افضل من يشرح المسائل الكتابية))\nاعتقد لا يوجد استاذ افضل منه في المسائل الكتابية\n\nالكويزات : اول كويز واخر كويز سهلين … وام اللي بينهم صلخ … وما يحذف اقل كويز\nمن بداية السمستر بيعطيك الأيام اللي فيها كويزات… يعني تكون عارف اوقات الكويزات من اول يوم دراسي\nغالبا تكون 5 كويزات\nالقريد : اعطيه a\nالصوت : كل الناس تقول واطي … ولكن انا ارى عكس ذلك فإن صوته واضح وممتاز ولا يجيب النعاس ولا شيء\nواللي مو مصدق …يحضر كلاس عنده …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p570009-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/27", "user": "che28", "ts": 1269090929000, "tid": 68569, "pn": 27}}]}', 1269090929000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_9998-math101', 'stk-_9998', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "في الماث 101 والماث 102 … نوته بططططل … وشوية عليه كلمة بطل …\n\nلكنه في تصحيح المياجر والكويزات يخسسسسسسف فيك … أو بالأصح يعطيك حقك غير عن الدكاترة الثانين اللي يعطونك حقك … وهالشي ظهر في الماجور الأول اللي كان هو يصححه … أفرج سكشنه 63 والأفرج العام 70 … لما جت الاختيارات أفرج سكشنه 64 والأفرج العام 62 …\n\nبالنسبة للنصيحة نزل عند فيصل فيرق … شريح وأخلاق ويدفك وتصحيحه تسلييييييك … أفرجه الماجور الأول على ما سمعت أنه شي وثمانين …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p936712-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/39", "user": "_9998", "ts": 1322195293000, "tid": 68569, "pn": 39}}]}', 1322195293000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zeroal-math101', 'stk-zeroal', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term211-Math101\n\nالتحضير : يحضر اخر الكلاس وبعض الاحيان مايحضر, مابهمه اللي يجي متأخر او يطلع.\nطريقة الشرح : بالبداية كان يشرح بدون سلايدات وكان جدا ملخبط وماندري وين وصل وبعض الاحيان ينسى يغطي جزئية. اخر كم اسبوع صار يشرح من سلايدات. للأمانة ماحسيت شرحه كافي كنت اشوف مقاطع احمد مقبل.\nالكويزات : جدا سهلة, يوم شاف الافرج مرتفع صعب اخر كويزين\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: واضح جدا\nالقريد النهائي: C+\nإضافات : اشوف فيه دكاترة كثير افضل منه لكنه ماهو الاسوأ. عطانا بونص اخر الترم نسوي كود لمعادلة معينة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533476-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/35", "user": "zeroal", "ts": 1642225520000, "tid": 68571, "pn": 35}}]}', 1642225520000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salh_1-math101', 'stk-salh_1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68577", "n": "Dr. Mohammad Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101-191\nالتحضير: دائما وفي بداية الكلاس ينادي الأسماء\nطريقة الشرح: يقرأ السلايدات قراءة ويحل سؤال ولا سؤالين ))شرحه للأسف أقل من المتوسط\nالكويزات: وسط مائلة للسهولة\nالقريد النهائي: C\nالصوت: واضح\nإضافات: الدكتور طيب مره ولكن للأسف شرحه مو ذاك الزود …وغريب اصلا انهم مخلينه يدرس ماث ولكن عموما لو ما لقيت الا هو المادة بتصير سيلف ستدي لو تبي قريد كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518530-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-omar/68577/24", "user": "Salh_1", "ts": 1577821963000, "tid": 68577, "pn": 24}}]}', 1577821963000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-leon-mohammed-math101', 'stk-leon-mohammed', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181- math 101\n\nالصوت: واضح جدا\nالنوتة: غير كافية تحتاج مصادرة خارجية مثل الكتاب\nالشرح: A+++\nالأخلاق: الدكتور خلوق وطيب جدا لكنه يحب المزح والضحك مع الطلاب طبعا اذا مسك عليك شي اهنا راح تتعب اشوي معاه. مثال : في طالب من الطلاب كان منزل ماث 101 صيفي لكنه سو له دروب في الصيف ونزل عند الدكتور منذر في الترم واهنا مسك عليه هل الشي وكل مايغلط في حل السؤال هذا الطالب الدكتور يقول له زين انك حذفت الماث في الصيفي وجيت عندي.\n\nالتحضير: بدون ورقة يحفظ اسمك ووجهك من ثاني كلاس ماشاء الله عليه.\nالكويزات: ما عنده كويزات…لكن عنده 3 كلاس تست (أصعب من الميجر)\nالقريد النهائي: A+\nملاحظات : في شي واحد الطلاب يكرهونه فيه هو ان لايسمح بالتأخير ثانية واحدة : كلاسك ساعة 10 مثلا وجيت دخلت الكلاس ساعة 10 ضبط راح يطردك من الكلاس.\n\nالدكتور جدا طيب ومتساعد انصح انك تنزل عند لكن لازم تذاكر اول بأول!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503708-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/62", "user": "Leon-Mohammed", "ts": 1545053765000, "tid": 68579, "pn": 62}}]}', 1545053765000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-drohmi-math101', 'stk-drohmi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181 math 101\nالتحضير : يحضر اول السمستر ثم يعرف الاسماء وما يحضر ، لو تتأخر ١٠ ثواني يطردك\nطريقة الشرح : سلايدات يشرحها ثم بعد ما يخلص يحل مسائل\nالكويزات : ٣ كلاس تيست بالسمستر تقريبا كل واحد اصعب من الثاني ، لكن شخصيا ما اشوفه فرق بنهاية الترم كان مجموعي ٦ من ٤٠ بالكلاسوورك الملا الى ٣١ من ٤٠ وكان افرجي بالمياجر ٧٧.٥ بالمية ، طبعا رفعني ٢٥ نقطة لان الافرج حق الكلاستيست نازل\n\nالقريد النهائي : A\n\nالصوت : واضح الى مرتفع\n\nاضافات : الدكتور راعي طقطة قوية لكن بدون حقد ، فيه بعض الناس يتضايقون منها لكن اشوفه عادي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503904-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/63", "user": "Drohmi", "ts": 1545477008000, "tid": 68579, "pn": 63}}]}', 1545477008000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11724-math101', 'stk-user11724', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM183 - MATH101\nالتحضير : شديد جدا وماعنده تأخير، وطريقة التحضير انك تدخل كود يتكون من 4 أرقام تكتبه في الـ Attendance (بلاكبورد وهي طريقة جديدة) لمدة دقيقة واذا ما لحقت تصير غائب D:\nطريقة الشرح : بواسطة نوتاته ولكن مشكلتها مافيها حل، يعني ياتكتب معاه او تصور بجوالك\nالكويزات : مايعترف فيها 🙂\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح بشكل يطير النوم ويشغل العقل\nإضافات : الدكتور مزوحي جدا جدا وممكن يتجاوز حدوده باحترام، ما انصح تخليه خيارك الاول اذا المادة تعتمد على تصحيح الدكتور، لان الكلاس تستس الي اخذناها كانت حريقة الافرج كان (class test1 3/13 ) (class test2 1/12) وتاخذ درجة السؤال كاملة او تاخذ 0 مافي وسط وطبعا تحتاج تتعود على الـ0 D:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513505-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/65", "user": "user11724", "ts": 1565219447000, "tid": 68579, "pn": 65}}]}', 1565219447000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-heshamalharbi-math101', 'stk-heshamalharbi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM183-Math101\nالتحضير:شديد جدا لازم تحضر قبل وقت كلاسك بدقيقة على الأقل\nطريقة الشرح:عن طريق نوتاته لكن عيبها أنها غير محلولة\nالكويزات:لا يوجد فقط 3 كلاس تستس قبل الميجرين والفاينل\nالمياجر:كومن\nالفاينل:كومون\nالصوت:واضح جدا\nالقريد النهائي:ِA\nالدكتور يحب المزح والطقطقة وأخلاقه جدا عالية وشرحه ممتاز جدا ولو ما فهمت تروح للأوفيس أور وما تطلع إلا وأنت فاهم ولو راسلته بالإيميل يرد عليك بسرعة لكن فيه سلبية وإيجابية بنفس الوقت الي هي ان كلاس تستس حقته صعبة جدا ,بإختصار الدكتور هو خيارك الأول إذا كنت تبي تفهم .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1514167-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/66", "user": "HeshamAlharbi", "ts": 1566810892000, "tid": 68579, "pn": 66}}]}', 1566810892000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_student-math101', 'stk-_student', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا حاليا ادرس عنده ماث 101\nالتحضير: يوميا بس نادر مايحضر، بس التأخير ممنوووووووووع عنده\nالشرح: ممتاز، يتسنتج القوانين وبعدين يعطي امثلة منوعة عليها\nالكويزات: متوسطة تميل للصعوبة\nمياجر: كومون\nفاينلات: كومون\nالقريد النهائي: A\nالصوت: واضح\nإضافات: المدرس اخلاق، احيانا يستخدم برنامج يوضح فيها رسومات البيانية للمعادلات وينصح فيها وممكن ينسخها لك بالفلاش او سيدي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p516709-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/15", "user": "_student", "ts": 1262691805000, "tid": 68582, "pn": 15}}]}', 1262691805000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5232-math101', 'stk-user5232', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^^^^^\nاللي قبل شوي على قولة د.العصار\n\nماخذ معاه 101 ماث\nبإختصار بطللللللل وشريح وكويزاته سهلة ومتوسطة\nويحقد عليك اذا جيت متأخر (talk to me after the class)\nمقولته المشهورة: if don’t know how to do this go to bluding 9 and drop the course\nانصح فيه اذا ما لقيت افضل منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p516876-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/17", "user": "user5232", "ts": 1262704945000, "tid": 68582, "pn": 17}}]}', 1262704945000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_ali-math101', 'stk-saleh_ali', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يوميا\nطريقة الشرح : جيده ولاهي بذيك الخياليه على وصف الشباب فوق ( ماث101)\nالكويزات : متوسطه\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: b+\nالصوت: ضعيف نسبيا\nإضافات : الرجل جيد و اخلاق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p539408-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/22", "user": "saleh_ali", "ts": 1265548700000, "tid": 68582, "pn": 22}}, {"id": "stk-dr-m83632", "n": "Dr. Khalid Al-Anezy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه رستيشن ماث 101\nالتحضير : دائما\nطريقة الشرح : جيد\nالكويزات :من الدكتور\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:b+\nالصوت: جيد\nإضافات : مدرس جيد ولا عليه كلام ولكن اعطيه 6.5 من 10 يعني زوين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p545833-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-anezy/83632/10", "user": "saleh_ali", "ts": 1266488192000, "tid": 83632, "pn": 10}}]}', 1265548700000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5155-math101', 'stk-user5155', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نود التقييم :\n\nالتحضير :\nمتشدد جدا بعد دقيقتين انسى الموضوع\nطريقة الشرح :ممتاز جدا يشرح الكونسبيت بس مشكلته انه يعدي الخطوات ويقلك هادي ماث 101\nالكويزات :ماهي سهلة وكل أسبوع\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:b+\nالصوت:نبرة واحدة وممل بعض الشيء\nإضافات :الرجل تعامله راقي جدا تصحيحه مدمر وشديد يزود في الكلاس وورك صعب تاخذ معاه نوت لإنه سريع\nأنصح به\nأنصح به", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p768924-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/31", "user": "user5155", "ts": 1295647220000, "tid": 68582, "pn": 31}}]}', 1295647220000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhakem-math101', 'stk-alhakem', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - term 121\nالشباب ماقصّروا في مدحه\nالدكتور بطل وشريييييييييييح\n\nيجيك جاهز كل لكتشر ويحل اكزامبلز جدد كثير وليست اكزامبلز الكتاب (يحل أسئلة الهوموورك والريساتيشن اللي في السلابوس مع تغيير أرقام بعض الاحيان ) والهدف أنه يوصل الكونسبت من عدة جوانب <<\n\nالكلاس وورك يعتمد على الكوزات وهي متوسطة… يجيب اسئلة من الكتاب ولكن غالبا يجيب سؤال واحد أو سؤالين من النوع اللي يقدر يكتشف اذا فاهم الكونسبت أو لا( تقدر تقول مسألة ماتقدر تحلها إلا اذا كنت فاهم ذاك الشي وتستخدم ذاك القانون ثم تستخدم الحركة الفلانية)\nبمجرد انك تجيب الفكرة وحتى لو الحل النهائي غلط يعطيك درجة حلوة في ذاك الكوز<<نفس تصحيح الثانوي أهم شي عنده انك فاهم وش تسوي\n\nتصحيح ميجر ون (written) تصحيح عادل وعطاني درجات زيادة 👍\n\nأضمن لك انك مارح تندم لو نزلت عنده 😆\n\n((لعيونه، نزلت عنده ماث 102 للسمستر التالي مع ان سكشنه الوحيد الساعة 1 الظهر ))", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1161551-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/50", "user": "alhakem", "ts": 1357826205000, "tid": 68582, "pn": 50}}]}', 1357826205000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mech.e-math101', 'stk-mech.e', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101-T181\n\nالتحضير:\n\nبداية الكلاس والدكتور معروف شديد من هالناحية، اذا هو بنص دوامك ما عندك مشكله لكن اذا اول كلاس لك بتعاني شوي، والغياب عنده بخصم من الكلاس وورك.\n\nطريقة الشرح :\n\nاسطووووره اتعب وانا امدحه يفهمك الكونسبت صح وحريص مره مره على فهم الطالب يعني دايم يقولنا هالشيء ما جا فجاة كذا ويقعد يشرح لنا الproof ومن وين جاء، عموما من ناحية الشرح ازهل فانت عند افضل دكاترة القسم.\n\nالكويزات:\n\nمتوسطة وتميل للسهولة ، كل أسئلته من الكتاب وهو دايم يقولنا هالشيء.\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالقريد النهائي: A+\n\nالصوت: ضعيف شوي احرص انك تقعد قدام وبيكون واضح.\n\nإضافات:\n\nالدكتور اسطوره تبيها من اخلاق ولا شرح كل شيء مهما أقول ماراح اوفي حقه ، للأسف انه ما يدرس 102 الترم الجاي ولا كان نزلت عنده وانا مغمض، عموما اذا حصلته لا تفوته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504062-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/71", "user": "Mech.E", "ts": 1545759124000, "tid": 68582, "pn": 71}}]}', 1545759124000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah21-math101', 'stk-abdullah21', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 term203\nLec\nOnline\n\nالتحضير:\nكان من البلاك بورد check in and check out\n\nالشرح :\nكان ياخذ اجزاء من الكتاب theorms ويحطها في الون نوت ويشرحها وياخذ امثله عليها توضح theorm ويهتم بالكونسبت كثير ويحاول يوصل لك الكونسبت من جذره الى اخره ومتمكن من الماده وشرحه مفهوم اذا انت مركز معه\n\nالكوزات:\nمشكل\nيجيك كويز كل اسئلته سهله ويجيك كويز ثاني كل اسئلته صعبة وفي المتوسطه\nوعطانا ٧ كوزات على الويب اساين وخذ افضل ٥\n\nالتعامل :\nلايعلى عليه ، طيب ومهتم بمصلحه الطلاب\n\nالصوت: واضح و٩٠٪؜ انجليزي لكن اذكر يرضى تسأله بالعربي او الانجليزي\n\nمتواجد خارج الكلاس؟\nفي الاوفس اور موجود برا الاوفس ماعتقد يرد\n\nالقريد النهائي : A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531497-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/80", "user": "abdullah21", "ts": 1629980433000, "tid": 68582, "pn": 80}}, {"id": "stk-dr-m182904", "n": "Dr. Muhammad Imran Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 term203\nRec online\n\nالتحضير :\nيرسل لنا رابط نهايه الكلاس وتدخل تحضر نفسك\n\nالشرح: فيه ملل لكن مفهوم صراحه ويحب الي يسأل\nوكان من اول كلاس سألنا وش تبون النظام اسئلة من الكتاب ولا اولدات ولا انتوا تشرحون\n\nالتعامل : طيب لا يعلى عليه\n\nالكوزات: عند lec\n\nمتواجد برا الكلاس؟\nمتواجد اي وقت يقولك لو تبي اجتمع معك العصر عشانك تعال\nمايقصر الدكتور\n\nالقريد النهائي :\nb+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531500-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-imran-qureshi/182904/11", "user": "abdullah21", "ts": 1629981083000, "tid": 182904, "pn": 11}}]}', 1629980433000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-anon63725347-math101', 'stk-anon63725347', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 Term 221\n\n:one: طريقة التحضير :\n\nالكلاس كان عبارة عن ثلاث سكاشن ، فكان عادة يحضر عن طريق البلاكبورد ، كان يحضر في اوقات مختلفة في اول عشر دقايق ، ملاحظة مهمة الدكتور شديد في التحضير وعنده طريقة يقفط فيها الطلاب الي يحضرون انفسهم\n\n:two: طريقة الشرح :\n\nالدكتور شريييح بمعنى الكلمة ويوصل المعلومة بشكل رهيب ، يحب دائما يعطي مقدمة بعدين النظريات بعدين الامثلة ، ودائما ما كان يربط الحاجات الي ندرسها بالواقع وكيفية استخدامها في مجالات الهندسة. باختصر شرحة اسطوري ولكن تحتاج تسجل معه لانه يشرح على السبورة\n\n:three: الكويزات :\nمستواها متوسط ، و كان الافرج موزون ، يحذف اسوء كويز ، وتختلف طريقة كويزاته مره بلاكبورد ومره ويب اساين ومره ورقي ، طبعا كل أسئلته من الكتاب\n\n:four: الصوت :\nالصوت وسط الى ضعيف تحتاج تجلس قدام عشان تسمع زين ، يشرح بالانجليزي بشكل كامل والاكسنت حقه رهييب\n\nاخيرا الدكتور يعتبر خيار جدا جيد اذا لقيته انصحك تسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536463-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/84", "user": "anon63725347", "ts": 1678231582000, "tid": 68582, "pn": 84}}]}', 1678231582000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iicreative-math101', 'stk-iicreative', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "قباج ❤️\n\nهذا الدكتور حرااااام تلاقي إسمه ولا تنزل عنده … الله يوفقه فوق كل أرض وتحت كل سماء ❤️\n\nادرس عنده ماث 101\nالتحضير ما يحضر … الكويزات يعطيك 5 وياخذ افضل 4 … التصحيح تاخذ حقك بالضبط …\n\nنصيحة لا تفوتون اي ماث عنده يحببك في الماااث ويبسطها لك بشكل ما تتخيله … كان اذا شاف طالب يحل مسألة ويقسم ويضرب ويفكتر ويعبي الورقة بسلوشن يقوله هيه وقف انت منت قاعد تدرس PhD قاعد تدرس كالكس 3 خطوات وتخلص حل المسألة بالكثير 5. 🥊\n\nاعذروني مستعجل بس هذا الدكتور اذا شفت اسمه راح اسجل عنده بدون أدنى تردد 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1215235-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/15", "user": "iiCrEaTiVe", "ts": 1366736684000, "tid": 68586, "pn": 15}}]}', 1366736684000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-xsethx-math101', 'stk-xsethx', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 الترم 122\nالتحضير: في الاسبوين مرتين ثلاثة وما يدقق على التاخير\nالشرح: من نوتة هوه يكتبها والنوته مره ممتاز لفهم المادة ويرسل اسألة زيادة على الايميل للطلاب الـa+ طبعا شرحة مره بطل ويعطيك وقت عشان تنقل من السبورة وما عنده مانع انك تسأل عن شئ من فاهمه ويعيد شرحة\nالكويزات: من الاسأله الي من اليميل او الكتاب بس يغير الارقام وتكون في غاية السهولة\nالمياجر :تصحيحه ممتاز ومتساهل نوعا ما\nالقريد النهائي :a+++ واتمنا انو الدكتور ينزل اي ماث عشان انزل معاه لكن هوه ينزل كل ثلاثة سنين كورس كلكلس لانه يدرس في قسم الدراسات العليا\nالصوت :واضح جدا\nاضافات : المدرس هذا لا يفوتك اذا شفت اسمه حتى لو مسجل الساعة وحدة الليل سجل عندة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1215933-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/16", "user": "xSETHx", "ts": 1366884731000, "tid": 68586, "pn": 16}}]}', 1366884731000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-llabdulmalikll-math101', 'stk-llabdulmalikll', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 151\n\n- التحضير : الدكتور ما يحضِّر أبداً , يشوف إن الحضور هو مسؤوليَّة الطالب و إن غاب هو إلِّي بيتضرر .\n\n- طريقة الشرح : من Notes خاصة فيه , يبدأ بشرح المفاهيم العامة للدرس و بعدها يخش للأسئلة زي أي مدرس غيره , اللهم إذا جت معلومة أو سؤال مهم يحرص يحط جنبه علامة النجمة ( * ) للأهمية , و كل ما زادت عدد النجمات زادت الأهمية , ينبِّه بنهاية كل موضوع عن الـHomework Problems و الـExtra إلِّي يرسله للبريد بعد ما يخلِّص كل موضوع .\n\n- الـQuizzes : مقارنةً بالـQuizzes إلِّي أشوفها عند غيره أشوف إنَّها سهلة , عطانا 5 و حذف أسوأ واحد , كل ثلاث أسابيع Quiz يوم الثلاثاء في موضوع أو موضوعين بالكثير .\n\n- الصوت : واضح للقريب و البعيد , ينوِّع بكلامه بين العربي و الإنقليزي .\n\n- الـGrade : أخذت +D .\n\n- إضافات : الدكتور صلاح الدين من أحرص الدكاترة على الطلاب , كان دايماً ما يعطينا شبه محاضرة بعد الـMajors و يبيِّن لنا إن الوقت باقي إذا كان الواحد عنده عزيمة , برغم إنِّي أخذت درجة سيئة بهالمادة لإهمالي إلَّا إنِّي أشوف إنَّه خيار جيِّد .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438126-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/23", "user": "llABDULMALIKll", "ts": 1452046868000, "tid": 68586, "pn": 23}}]}', 1452046868000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_ali-math101', 'stk-faisal_ali', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101-173\n\nالتحضير: يومي تقريبا, ورقة يمررها وما يحاسب على التأخير\nالشرح: يعتمد على نوت عنده, ينقلها على السبورة, النوت مشابهة للكتاب لكنها ممتازة, الشرح ممتاز جدا ويعرف يوصل المعلومة للطالب\nالكويزات: متوسطة إلى سهلة, يعتمد فيها على كويزاته القديمة وبعض التمارين اللي يرسلها للطلاب على الإيميل, تصحيحه دقيق لكنه ماهو ظالم\nالمياجر والفاينلات : كومون\nالقريد النهائي : +A\n\nإضافات:\n-الدكتور قمة في الأخلاق والتعامل.\n-يسمح بالأسئلة داخل الكلاس وبالأوفيس وبالإيميل وفي السيب كمان 🙂\n-يرسل ملفات للطلاب على الإيميل بشكل دوري (تمارين للحصول على A+, كويزات قديمة, اولد اقزام محلول …الخ)\n-يخصص حصة قبل كل ميجر لمناقشة اولد اقزام مع الطلاب (يرسله لهم عشان يحلونه قبل الحصة)\n-متمكن جدا من المادة وله تقريبا حوالي 30 سنة يدرسها.\n-سريع في التصحيح\n\nبشكل عام : أراه مناسبا للطلاب الطامحين بالA+ والطلاب الغير مهتمين بالمادة أيضا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498036-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/27", "user": "Faisal_Ali", "ts": 1534967092000, "tid": 68586, "pn": 27}}]}', 1534967092000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hajjar-math101', 'stk-hajjar', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : صلاح الدين قباج\nفصل 201 اونلاين\nmath101\nفصل 201 اونلاين\nبنود التقييم :\n\nالتحضير :احسن شي في الدكتور ياخذ التحضير تلقائي من البلاك بورد وحتى لو حضرت دقيقة يحسب لك ومافي احد اخذ dn عنده\nطريقة الشرح :هنا الكلام طبعا كنت متفائل بالشرح جدا من تقييمات المنتدى وقلت بس راح اعتمد عليه بالشرح لكن جدا خاب ظني بعد اول اسبوع الدكتور يشرح كونسبت فقططط طول الساعه والنص الي ممكن يكون ممل وغير واضح من غير امثله ومع الوقت صار الي يركز معه 2-3+ الشرح بيكون على اساس عندك خلفية عن الموضوع فاذا كنت جديد راح تضيع + الدكتور يعرض ورقة نوت محلوله ومحشوه كلام ويبدأ يتكلم عنها ويستخدم الماوس للكتابه!!!!\n(واتوقع سبب الاختلاف هو وضع الاونلاين)\nالكويزات : اول كويزين كانو عباره عن هوم وورك لك محاولتين و 12 ساعة وانصلخنا بافرج 96% حاولنا نكلمه عشان لا يصير نورملايزايشن قوي للكلاس ورك وننخسف كلنا لكن ما كان مقتنع واستمر على الطريقة اللهم صار الوقت ساعة والافرج صار 85% واعلى واحد اخذ بالكلاس وورك 34\\45 + الاسئلة كانت من ويب اسسين يعني افتح صفحه ثانيه براكتس وبتطلع لك كل الاجوبه وحاولنا نكلمه على اساس نبي كويزات عادله تبين المجتهد من غير المجتهد لكن ماقتنع للاسف\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: للدكتور اعطيه C+ (واعيد واكرر انه الاختلاف يمكن عشان الاونلاين)\nالصوت: واضح جدا\nإضافات : بالرغم انه كان يركز معه 3 بالكلاس الا انه افرجنا كان عالي بالميجر والميد وهذا دليل ان الماده عباره عن سيلف ستدي بالنهايه لا تخلي دكتورك عذر الماده سهلات والاونلاين كورس كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527217-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/31", "user": "hajjar", "ts": 1608681471000, "tid": 68586, "pn": 31}}]}', 1608681471000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abosmrh-math101', 'stk-abosmrh', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : صلاح الدين قباج (S KABBAJ)\nMath 101\nTerm 201 (Online)\nبنود التقييم :\n\nالتحضير: ياخذ التحضير من البلاكبورد وهذي الطريقة ريحتنا كثيييير بحيث ان البلاكبورد يسجل الوقت اللي دخلت فيه والوقت اللي طلعت فيه ويكتبك غايب اذا ما دخلت البلاكبورد نهائياً خلال وقت المحاضرة يعني اذا دخلت لمدة دقيقة بيسجلك حاضر وما يدقق في وقت الدخول والخروج وما يسجل تأخير.\n\nطريقة الشرح: حسب المنتدى يقولون طريقة شرحة اسطورية وما الى ذلك لكن شكل الدكتور انكب مع الاونلاين، شرحة في البلاكبورد والصراحة شرحة ممتاز نوعاً ما ويهتم بجميع الطلاب وهذا ممكن يخليه يتأخر في المنهج شوي، يعرض سلايداته اللي كتبها بخط يده في البلاكبورد ويشرح عليها ويكتب عليها بالماوس وخطه الصراحة سيء لما يكتب بالماوس على الشاشة بس خطة في السلايدات واضح، أغلب وقت الكلاس يشرح فيه الكونسبت واللي كان ساعة ونص وبعض الأحيان يحل كم سؤال ويسأل الطلاب في نص الكلاس وإحنا نرد عليه في الشات وكان مقفل المايكات على كل الطلاب يعني ما يمديك تسأله سؤال شفهي لازم تكتب له. انصحك تاخذ سلايدات محسن الشهراني افضل لك + السلايدات الصراحة ممتازة من ناحية الشرح والأسئلة اللي فيها ممتازة جداً بس عيبها ان فيه انواع من الأسئلة في بعض الدروس مهي مشروحة تماماً فإذا اخذت سلايداته مع سلايدات محسن فبتكون مختم المنهج صح، وعنده مشكلة ان اذا فيه واحد سأله يجاوب عليه\n\nالكويزات: 4 كويزات طول الترم اول كويزين كانوا سهلة لدرجة ان تقريباً الكل جاب الدرجة الكاملة وبكذا صار الافرج فووق لأنها كانت 12 سؤال وكل سؤال من محاولتين يفتح 9 الصبح ويقفل 11 الليل وبدون اي نوع من المراقبة (كأنه واجب)، بعد ما شاف الوضع كذا غير الطريقة وصار الإختبار 50 دقيقة بس و 8 أسئلة وكل سؤال من محاولة واحدة بس ولكن مازال سهل وفي النهاية انخسف الجميع بالنورملايزيشن لدرجة ان اعلى واحد (جايب فل في كل الاختبارات) اخذ 12 من 15 في الكلاس وورك يعني خسف الجميع 3 درجات.\n\nالمياجر: من القسم.\nالفاينلات: من القسم.\nالصوت: واضح جدا.\nتقييم الدكتور: B+ (في الاونلاين).\n\nإضافات: الاوفس اور حق الدكتور غير مفيد (ما رحت له شخصياً ولكن هذا كلام الطلاب) ومتطلباته صعبه مثلا لازم ترسل له السؤال ولازم يكون من الاولد اقزامز وترسله في اي ترم جاء السؤال وما الى ذلك من الشروط . الدكتور كان يرسل لنا كل الأشياء من ملفات وسلايدات ودرجات والغياب عن طريق الإيميل واللي كانت طريقة سيئة جداً لما تكون تبغا تدور على ملف أو معلومة وما يستخدم البلاكبورد في حفظ الملفات. الدكتور ما يسجل محاضراته. وترا المادة سهلة سيلف ستدي وامورك طيبة بإذن الله.\n\nرابط سلايدات الدكتور صلاح الدين قباج (Math 101)\n44.36 MB folder on MEGA\nرابط سلايدات محسن الشهراني (Math 101)\nMath101 Notes by Mohsen Alshahrani - Google Drive", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530101-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/32", "user": "AboSmrh", "ts": 1621966683000, "tid": 68586, "pn": 32}}]}', 1621966683000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-loop24-math101', 'stk-loop24', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68586", "n": "Dr. S Kabbaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : صلاح الدين قباج (S KABBAJ)\nMath 101\nTerm 203 (Online)\nبنود التقييم :\n\nالتحضير: اي وقت تدخل المحاضرة على البلاكبورد انت حاضر.\n\nطريقة الشرح: الدكتور يركز على الكونسبت وبصراحة شرحه ممتاز جدا واعتقد الاونلاين ظلمه لو حضوري اعتقد كان طلعت بقريد أعلى بس الي عليك انك تحل اسئلة عشان تتدرب لأن اغلب الي يحلها الدكتور اسئلة مستواها متوسط الى سهلة ولكن احيانا يجيب افكار حلوة قد تغيب عن الواحد\n\nالكويزات: بكل صراحة حسب مافهمته ان الدكتور كانت كويزاته سهلة او متوسطة في الاونلاين ولكن بسبب الغش الي صار صعبها على الطلاب ولكن للاسف باقي الغش مستمر لانه كان غير مراقب الكويزات.\nالمياجر: من القسم.\nالفاينلات: من القسم.\nالصوت: واضح جدا.\nتقييم الدكتور: A (في الاونلاين).\n\nإضافات: للاسف اني كنت ضايع في هذا الصيف مع الاونلاين ولو يعود في الزمان حضوري اعتقد كان طلعت معه بقريد A اقل شي\nالدكتور محترم جدا وحبيب وماعنده مشكلة يجاوب على أي سؤال ودايم يعطيك من وقته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532571-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kabbaj/68586/33", "user": "loop24", "ts": 1635509550000, "tid": 68586, "pn": 33}}]}', 1635509550000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7653-math101', 'stk-user7653', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68677", "n": "Dr. M Al-Shahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم …\nبداية … انا صممت ارجع باسوورد العضوية واشارك في المنتدى بسبب هذا الدكتور …\nاللي اقدر اقول انه اول قرار خطأ اتخذه من المنتدى …\nللأٍسف الطلاب اعطوه اكبر من اللازم والوصف كان مبالغ فيه وفي شرحه …\nالرجل باختصآر مثل ماقال الاخ اللي فوقي ( الكتاب الناطق )\nمايعطيك اي جديد … كنت من الناس اللي يكره الكتاب لانه مافيه جديد …\nلكن الرجال طلع كللل اللي يقوله في سلايداته من الكتاب … الامثلة من الكتاب …\nكل شي من الكتاب مافيه اي جديد نافع في شرحه\n\nندخل للتقييم\n\nالتحضير : يحضر يوميا …\nطريقة الشرح : سلايدات نسخ لصق من الكتاآب … اسلوب فلسفي ساعات يوديني في داهية لانه يدخل لك المعلومة وفي نفس اللحظة يوريك انه متمكن بأنه يضيعك … الماتيريآل اصلا سهل … ولو كان اساسك في الاوريا حلو بتذاكر الكتاب والاولد اقزام وفالك في ميجر 2 و الفاينل فل مارك ان شاء الله\nالكويزات : سهلة ولو تذاكر سلايداته تجيب الفل\nالمياجر: نجي للمياجر … الرجال تصحيحه حريييييييييييييييييييييييييييييييييييييييييييييقه … مايرحم في التصحيح … بخسني في درجتين في الميجر لو مع اي دكتور ثاني كان اخذتهم … لكن الرجل يقول لي مايهمني طريقة الحل او انك فاهم … السؤال طلب الجواب النهائي وانت جبته غلط … واللي بيقول الرجال يصحح الاخطاء بقول له … كل الدرجات اللي اخذها مني حقه … لكن هنا الفرق … بعضهم يمشي الاخطاء ويرقعها لك ويعطيك درجات قد مايقدر … لكن الشهراني ابدا مايراعي … اسئلة عليها 10 درجات ونكتب له كلام كثير وحول الحل … اقل شي يعطينا 3 او 4 درجات … بعضنا اخذ صفر واعلى واحد شفته كان اثنين\nالفاينلات :\nالقريد النهائي: من الان وقبل نهاية سمستر 112 ماث 101 … اعطيه c لانه دكتور الـ 101 ماتحتاجه في اي شي الا في الميجر ون …\nالصوت: واضح جدا …\nإضافات : نصيحه يا اخواني … اللي عرف يذاكر لوحده مع انستركترز عاديين في الاوريا وعدى … لاينزل مع الشهراني … لانه الفل مارك تحلم بها في ميجر ون … الكلاس جدا جدا جدا جدا ممل مع هذا الرجل … مستحيل تتحمل 5 دقايق بدون ماتطالع الساعة … تذكرت … لو شافك نايم يطردك … 🙂 …\n\nوراجع لكم بعد نهاية السمستر لو تغير الكلام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1006635-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-al-shahrani/68677/19", "user": "user7653", "ts": 1331598655000, "tid": 68677, "pn": 19}}]}', 1331598655000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10843-math101', 'stk-user10843', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68677", "n": "Dr. M Al-Shahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101, Term:171\n\nالتحضير: بنص الكلاس يقرا الاسماء من الجوال … يحضر يوميا لكن قال لنا بداية الترم ان الكلاسوورك عنده ماراح ينظر لعدد الغيابات. ماكان فيه ميك اب لانه ماعنده الا سكشن واحد فقط.\n\nالشرح: الدكتور للامانة مبدع جدا جدا بالشرح وتوصيل المعلومة، يبدأ الدرس بالربط مع الدرس السابق و يشرح التسلسل لين طلعت فكرة الدرس الجديد وكيف اشتقينا المعادلات والقوانين، يبسط لك الكونسبت بشكل دقيق جدا لين تفهمه وتصير فاهم كيف جت القوانين ماهو حافظ وبس، بعد كذا يبدأ يحل مسائل ويتدرج بالصعوبة واحيانا تكون نفسها امثلة الكتاب، يعيب الدكتور فقط انه احيانا يستعجل بالشرح و بحل المسائل. الصوت واضح ولغته الانجليزية ممتازة.\n\nالكويزات: متوسطة، ذاكر مسائل الكتاب وامورك طيبة.\nالدرجات يرفعها على موقعه الشخصي.\n\nالمياجر والفاينل كومون.\n\nاضافات: الدكتور احيانا يعصب شوي لكن ورغم ذلك يظل محترم الطلاب، ماعنده مشكلة بالاسألة وقت الشرح لكن ممكن يرد بنبرة مرتفعة شوي وتحسه زعلان. لكن يظل تعامله محترم واحيانا يطقطق شوي مع الطلاب 😆\nومثل ماقالوا الشباب الدكتور منظم ودقيق جدا، انا بصراحة اول مرة اشوف دكتور مثله مهتم بموقعه الشخصي. الكويزات تجيك الورقة مطبوع عليها اسمك ورقمك، وبعد مايصحح يسوي لها سكان ويرفعها على موقعه مع الدرجة، شغل مرتب. الله يعطيه العافية دكتور محمد وان شاء الله Math102 معه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1483521-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-al-shahrani/68677/57", "user": "user10843", "ts": 1510943118000, "tid": 68677, "pn": 57}}]}', 1510943118000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_special_one1-math101', 'stk-the_special_one1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101\nTerm 151\n\nالتحضير : بالأرقام … وعلى نهاية الكلاس وما يدقق أبداً أبداً على التأخير ، لو تحضر آخر خمس دقايق يمشيها لك :o\n\nطريقة الشرح : يكتب على السبورة كونسبت مع بعض الأمثلة من الكتاب أغلبها\n\nالكويزات : متوسطة\n\nالقريد النهائي : C\n\n* الدكتور كويس من ناحية الاهتمام بالطلاب ومحاولته لإيصال المعلومة ، ولكن بصراحة أتوقع لأنه جديد على هذا الكورس 101 فما كان متمكن منه\nخصوصاً من ناحية نوعية الأمثلة اللي يركز عليها وأسئلة الكويزات مختلفة عن نوعية أسئلة المياجر … ويعيب شرحه انه ماهو مرتب فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437424-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/70", "user": "The_Special_One1", "ts": 1451468047000, "tid": 68928, "pn": 70}}]}', 1451468047000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-al-houri-math101', 'stk-al-houri', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ملاحظة نسيت أنوه عنها إني درست عنده كورسين\nMath 101 في ترم 151 وMath 201 في ترم 161\nوتقييم فوق كان عن Math 201 وطبعاً طريقته ما تغيرت في الكورسين بس الأول كان يأخذ التحضير في نهاية المحاضرة (تقريباً قبل 10 إلى 5 دقائق من انتهاء المحاضرة) ولكن في كل الأحوال فهو متساهل جداً بالتحضير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467911-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/75", "user": "Al-Houri", "ts": 1486538100000, "tid": 68928, "pn": 75}}]}', 1486538100000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-just_a_dream-math101', 'stk-just_a_dream', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69347", "n": "Dr. I Louhichi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 ترم 131\nالتحضير :\nورقة تمر ع الطلاب + اذا نسيت تحط اشارة يعتبرك غايب ويقولك اذا وصلت للـ DN اشيل الغياب …\nطريقة الشرح : لا بأس به لكن جدًا سريييع + تخاف تسأله لإنه دائمًا معصّب أو شكله معصّب\nالكويزات : الكلاس وورك كله ع الكويزات ويخلي الأفرج اقل افرج ممكن ، سكشننا كان الافرج 24 من 30 وهو الحد الأدنى ، انا بالنسبة لي الكلاس وورك اللي عطاني اياه فرق معاي ف القريد ، لا تفكر ولو للحظة انه ممكن يتعاون معاك في أي درجة ! مافي كلاس تست ولا شي بس كل اسبوع كوز وفي بداية السمستر بيسوي روحه شديد وبيقول ما راح اعدد موعد الكوز … وكان في كويزات ايام مياجر ما غير موعدها … لكن تصحيح الميجر الكتابي كان ممتاز\nالمياجر: common\nالفاينلات : common\nالقريد النهائي: C\nالصوت: فوق العالي\nإضافات : ما انصح بوضعه ضمن الخيارات ، إلا إذا كان قضاء وقدر مثل ما صار معي لإني كنت منزل عند مدرس ثاني وحطوني معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1319176-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-louhichi/69347/49", "user": "Just_A_Dream", "ts": 1389720818000, "tid": 69347, "pn": 49}}]}', 1389720818000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-math101', 'stk-m_nd_m', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 151\n\nالتحضير : شديد جدًا جدًا بالتحضير… يبدأ ينادي الأسماء قبل الحصة بـ1-3 دقائق… لو مثلا الكلاس يبدأ 8 و جيت 8:01 يعتبرك لييت… جيت بعد الـ8:10 يعتبرك أبسنت\n\nطريقة الشرح : باختصار، يركز 95% على الإكزامبلس بالكتاب و الكونسبت أو الفكرة حقت الدرس + دائمًا يحاول يسوي الكلاس زي نقاش مع الطلاب\n\nالكويزات : سهلة - متوسطة… غالبًا غالبًا من اسئلة الكتاب - يعطي بونس على علامة الكويزات النهائية بطريقة أو باخرى\nالمياجر: -\n\nالفاينلات : -\n\nالقريد النهائي: B+\n\nالصوت: لا بأس\n\nإضافات : الدكتور أخلاقه عالية جدًا لو مثلا طالب قاعد على جواله ببساطة يقول ( فلان دخل جوالك) و ممكن يقولها لنفس الشخص أكثر من مرة <----- طويل بال\n\nدائمَا قبل المياجر يوزع أوراق فيها أسئلة محلولة فيها أفكار مهمة و حلوة… 99% في سؤال بالميجر بجي من هذه الأوراق\n\nمشكلته يركز على الكونسبت بزيادة… يعني لو يخصص وقت لحل أسئلة الأولد إكزامز أو المسائل بشكل عام و يخفف تشديده على الحضور أعطيه a+\n\nتصحيحه للمياجر مرة مرة مرة ممتاز للميجر و الكويزات (أعطاني اكثر من حقي)\n\nو انتبه خلك مركز لانه ممكن يباغتك بسؤال… أسئلته غريبة يعني تحس ماتدري وش يبي… دائمًا اذا سألني أقعد أصفن فيه :d", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1435188-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/35", "user": "M_nd_m", "ts": 1449078023000, "tid": 69876, "pn": 35}}]}', 1449078023000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alnajm-math101', 'stk-alnajm', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. خالد الشمري\n\nMATH 101 - 151\n\nبنود التقييم :\n\nالتحضير : شديد نوعا ما… يبدأ يحضر قبل الكلاس بخمس دقايق وينهي التحضير بالضبط على بداية الكلاس\nالى ثلاث دقائق تقريبا ليت اكثر من كذا أبسنت\n\nطريقة الشرح : يركز على الامثلة… يعطيك مثال بسيط جدا ثم يشرح الكونسبت ثم يتسلسل في الامثلة من سهل لمتوسط\nأحيانا يعطي مثال صعب شوي ويعطي الكلاس كم دقيقة يفكر في الحل\n\nالكويزات :نسيت كم كويز :d بس اثنين منهم كانو كلاس تست متوسطة الى صعبة(الكلاس تستز كانو صعبين نوعا ما)… اعطانا في الكويز الاخير (قبل الكلاس تست الثاني) كامل الدرجة كبونص\n\nالقريد النهائي: A\n\nالصوت: ممتاز وواضح جدا\n\nإضافات :\nأخلاق عاليا\nلا تحاول تعتمد على النوتة فقط لانك بتجيب العيد بسبب عدم وجود امثلة كافية معظم اللي يعطيك الاساسيات فقط\nتصحيح المياجر كان جدا ممتاز\nلو في فرصة ثانية انزل عنده ما عندي مشكلة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438417-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/36", "user": "Alnajm", "ts": 1452393338000, "tid": 69876, "pn": 36}}]}', 1452393338000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10518-math101', 'stk-user10518', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 152\nد. خالد الشمري\n\nبروفيسور\n\nبنود التقييم :\n\nالتحضير :\nشديد في التحضير لدرجة ان يحضر قبل الكلاس ب 3 دقايق ويضل ينادي الاسماء لين يبدا الكلاس بعدها لو متأخر دقيقتين late .\n\nطريقة الشرح :\nمن امثلة الكتاب ويبدأ يناقش الاسئلة مع الطلاب ويسأل بالاسامي عشان يتأكد ان الكل منتبه معاه وما يعدي خطوة الا يسأل (( في احد مو فاهم ))\n\nالكويزات :\nزي العسل ذاكر امثلة الكتاب واسئلة الهومورك وامورك في السليم ❤️\n\nالمياجر:\nتصحيحه زي الفل وزيادة درجات بالهبل ووانا اضمن لك تاخذ فوق حقك ما فيها كلام .\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB+\n\nالصوت:\nيتكلم انجليزي واحيانا يتكلم عربي وصوته واضح ومفهوم انا اجلس في نهاية الكلاس وما كنت اعاني من الصوت ابد .\n\nإضافات :\nدكتور خلوق جدا ومحترم , في الشرح على قول اخوانا المصريين بسم الله ما شاء الله 👍\nيحفظ اسامي الطلاب كلهم انسى لو تقعد زي الصنم في الفصل عطه 3 اسابيع وهو حافظ اسمك وهذا طبعا شيء حلو 🥰\nنزل عنده ولا تتردد .\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450917-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/37", "user": "user10518", "ts": 1464783916000, "tid": 69876, "pn": 37}}]}', 1464783916000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10879-math101', 'stk-user10879', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 خلال 152 وماث 102 خلال 161 وبعطي رأيي عنه خلال 161\n\nطبعا التحضير معروف انه شديد جدا ويادوب تتأخر يمكن نص دقيقة يحطك ليت و3 دقايق غايب يعني لا تنزل عنده بعد دكتور يأخرك ويحضر بالاسم ومن قبل يبدأ المحاضرة يحضر سكيتي لانه خلال اسبوع يعرف اسماء كل اللي بالسكشن\nالصوت واضح\nالتصحيح كان شديد في 152 لكن 161 كان يمشي اخطاء فادحة بخصم خفيف هذا للميجر بس الكويز تصحيحه شديد جدا وركز وانت تحل\nالكويزات عطانا تقريبا 3 كويزات عادية صغيرة وكويز طويل عليه نفس درجة العادي وكويز بونص كل واحد حضر عطاه درجة كاملة وتيك هوم كويز كل اللي سلموا عطاهم درجة كاملة\nطبعا هو يقولي غالبا افرجه يكون نازل ويضطر يرفع وهو يرفعك حسب غياباتك\nالمياجر كومون\n\nطريقة الشرح يركز بشكل كبير عالكونسيبت أهم شي عنده تفهم الفكرة ويعطي كم مثال شاملة للدرس وشرحه جميل جدا وواضح انه يجي محضر للمحاضرة\nلكن اول يوم بعد الاجازة سلم لي عليه 🤣\n\nطبعا الدكتور حبيب مرة واخلاق ويستقبل الاسئلة وقت المحاضرة\nنقطة انبه عليها تر الدكتور احيانا يترك بعض المواضيع الصغيرة للطالب يقراها من الكتاب ويحفز الطلاب يقرون من الكتاب\nطبعا منت مضطر تقرا شي كثير يعني يمكن بالشابتر كله يعطيك فكرة وتكون فكرة جانبية صغيرة وسهلة ولو سالته عنها يجاوبك\nالقريد النهائي A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466426-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/40", "user": "user10879", "ts": 1484653397000, "tid": 69876, "pn": 40}}]}', 1484653397000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kh1-math101', 'stk-kh1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 - 171\n\nادرس عنده الان\nطريق الشرح : شرحه كله عن طريق الصبورة فقط وبعض الاحيان يوزع اوراق\n\nاجابيات : طريقة شرحه ممتازه , يتقبل جميع الاسئلة , يحب يتفاعل مع الطلاب في الاسئلة والدرس, خلوق و تعامله مع الطلاب ممتاز ,\n\nالسلبيات : جدااا شديييد بالتحضير , لا يتقبل اي عذر بانك جاي من بمنى بعيد , ممكن كويزاته من المتوسط الى الصعبه ولكن في كم سؤال من الكتاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1484206-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/45", "user": "Kh1", "ts": 1512412179000, "tid": 69876, "pn": 45}}]}', 1512412179000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_alwaleed1-math101', 'stk-abo_alwaleed1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 171\n\nالدكتور طيب جدًا وشرحه كويس ، مشكلته دقييق بالتحضير ، الساعة 9 تمام (بداية الكلاس) يقفل الكشف …\nكويزاته متوسطة مائلة للسهولة ، من الكتاب … عطانا 5 كويزات …\nبالفاينل وبالمياجر هو اللي يجي ويخليك توقع ، مع إنه ماهو المراقب ، ويسأل كيف الاختبار وكذا ، وبالفاينل وزع علينا حلاو …\nالتقييم النهائي A …\n\nوسجلت معه ماث 102 بعد …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485764-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/46", "user": "abo_alwaleed1", "ts": 1515439983000, "tid": 69876, "pn": 46}}]}', 1515439983000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11409-math101', 'stk-user11409', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. خالد الشمري\n181 math101\nالتحضير : يبدأ التحضير قبل بداية الكلاس بخمس دقايق واذا تأخرت عن بداية الكلاس فوق ٣ دقايق يحسب عليك غياب\n\nطريقة الشرح : يعطيك افكار الدرس وبعض الاسئلة تكون مقاربة لافكار المياجر ، م عنده سلايدات ، يعني شرح كلاسيكي من الاخر\n\nالكويزات :من سهلة الى متوسطة ، عادة تكون نفس افكار الكتاب\n\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: باقي م قضيت من الكورس :office_worker:\nالصوت: واضح\nإضافات : دكتور خالد اشوفه من افضل دكاترة الماث ، الي يميزه انه يسال اغلب الطلاب ودايما اسئلته فيها تريكات حتى يخلي الطالب يصحصح في الكلاس ويميز القوانين 👍\nولكن الي يعيبه فقط هو التحضير\nلا تتردد اذا شفت سكشن فاضي عنده 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501599-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/48", "user": "user11409", "ts": 1540886989000, "tid": 69876, "pn": 48}}]}', 1540886989000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11518-math101', 'stk-user11518', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 -181\nالدكتور خالد من أفضل الدكاترة أخلاقاً وأطيبهم\nيبدأ التحضير قبل الكلاس تقريبا بخمس دقايق ويعيد الأسماء إلى بداية الحصة ، بداية الحصة يسكر الباب وإذا جيت بعدها تكون ليت ، مايقبل بالميك اب\nبالنسبة للشرح يعجبني هذا الدكتور في أنه مايستعمل سلايدات ، كل شغله باليد على السبورة ، يشرحلك كيف جا القانون ومايخليك تطبق وأنت مو فاهم ليه قاعد تستعمل هذا القانون\nبالنسبة للكلاس وورك الدكتور يعطي كويزات قليلة ، فممكن يكون كويز واحد عليه 2.5 من درجة الكورس كامل! فلذلك لا تستهين بالكويزات\nوبالنسبة للبونص يعطيه على حسب الغيابات ، يقول صاحب الغيابات الأقل أحق بالبونص\n\nيعيب الدكتور شي واحد: أنه يشرح أمثلة عادية ، مايشرح أولد أقزام إلا نادراً ، فتكون فيه أفكار ماشرحها في الدرس وهنا لازم تعتمد على نفسك شوي\nأكثر مايميز الدكتور من وجهة نظري أنه يتفاعل مع الطلاب في الحصة ، ويخليهم يجاوبوا على بعض الأسئلة ويتقبل الأسئلة بصدر رحب ، وبعض المرات يكتب بعض الأشياء الخاطئة في الأمثلة أو في الحل عشان يذكر الطلاب ببعض الأساسيات في الماث", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503397-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/49", "user": "user11518", "ts": 1544420591000, "tid": 69876, "pn": 49}}]}', 1544420591000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-math101', 'stk-user11264', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 181\n\nلا أزيد على كلام الشباب فوق، الدكتور خالد من أكثر الدكاترة اللي قابلتهم خلقًا واحترامًا.\n\nالتحضير: شديد جدًا جدًا في التحضير ولا يقبل ميك أب. يبدأ ينادي بالكشف قبل 5 دقايق من وقت الكلاس، وأول ما تصير الساعة x:00 حكم يقفل الباب واللي يدخل بعدها يكون متأخر 😆\nطريقة الشرح : يقول إنه “أولد فاشند” أي إنه من الطراز القديم، ما عنده سلايدات ويشرح على السبورة ويبي الطلاب يذاكرون من الكتاب. راح يفهمك الكونسبت صح وأحيانًا يكتب أشياء غلط ويطالع بالطلاب يسألهم إذا حله صحيح ولا لا… كل هذا عشان يعزز فهمهم للكونسبت. لكن بالمقابل الدكتور يشرح أمثلة سهلة جدًا وبدائية -في نظري على الأقل- ولازم تشتغل على نفسك إذا تبي تعدي المياجر\nالكويزات : 4 إلى 5 كويزات مستواها بين السهل والمتوسط\nالمياجر: كومن\nالفاينلات : كومن\nإضافات :\n- سجلت عنده لأني سمعت إنه يعطي جالكسي بالفاينل لكن للأسف ظني خاب وما أعطانا، نقطة تنحط في عين الاعتبار 😆\n- ملحوظة على الميك أب، أحيانًا يقبل بس بشكل نااادر ويقعد يدقك بالكلام بالحصة، فالأفضل تنسى سالفة الميك أب نهائيًا ولا توجع راسك\n- أهم نقطةحاول تتجنب الغياب عنده مهما صار، لأن إذا كان الأفرج عالي (مثل حالتنا الترم هذا) راح يتجه للي يغيبون ويخصم منهم، أنا من الناس اللي كان الكلاس وورك عندي كامل بس خصم علي فوق ال5 بوينت بسبب الغياب. زعلت لأن بداية الترم قال إن الغياب عنده ما يأثر في شيء إلا على البونص، بمعنى لو غبت ما راح يعطيك بونص بس ما راح يخصم عليك. لكن بعض الشباب قالوا إنه نبههم على موضوع الغياب والخصم، فما أدري يمكن قالهم بس إني كنت غايب 😆\n\nإيجابيات: شرح ممتاز يفهمك الكونسبت - متفاعل بالحصة - أخلاق\nسلبيات: الأسئلة اللي يشرحها بسيطة وغير شاملة - التحضير (بالنسبة للبعض)\nالقريد النهائي: A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504204-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/50", "user": "user11264", "ts": 1546045086000, "tid": 69876, "pn": 50}}]}', 1546045086000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_alghamdi-math101', 'stk-abdulrahman_alghamdi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101- 181\nMATH 102- 182\n\nالتحضير: متشدد بشكل لا يتصور. يحضر قبل الكلاس ب3 دقائق واذا دخلت بعد الكلاس بدقيقة تعتبر متأخر. يقبل الميكب لكن نصيحة لا تجرب تاخذ عنده، السبب في قسم طريقة الشرح. التحضير هو المعيار الأساسي في الزيادة والخسف عند الدكتور. إذا غياباتك قليلة، أضمن لك درجة عالية في الكلاسوورك. أما إذا غياباتك كثيرة، فراحت عليك ياصاحبي\n\nطريقة الشرح: يبدأ بمثال مجهول وما يعرفه الا اللي حضر الدرس، المثال هذا يعتبر بمثابة مقدمة للدرس، ثم يدخل على الأمثلة الفعلية، سهلة وبسيطة وتوصل المعلومة بشكل كافي. لما يشرح، أكثر الطلاب يكونون على اعصابهم، خاصة الطلاب اللي مسوين ميكب، لأنه ينقض عليهم بأسئلة شاطحة وصعبة نوعًا ما عشان جو الكلاس ما يصير بيض، في كل مثال لازم يسأل أحد سؤال يخليه يحرك مخه. يحب إن الطالب يفهم ولا يحفظ. يعني إذا اعطاك قانون غالبًا يقول لك أفهمه ولا تحفظه لأن ممكن يغيرون حاجة في السؤال بعدين تنشل أطرافك. المميز في الدكتور انه ما يستعمل نوتات أبدًا. واذا استعمل نوتات تكون فقط أسئلة محلولة بالتفصيل فقط. البلاكبورد ينزل فيه حلول الكويزات.\n\nالكويزات: هنا نقطة انا ما تعجبني فيه. الكويزات غالبًا بين ال4 وال5 تكون جدًا سهلة للطالب المذاكر. الأدهى والأمر ان الدكتور عنده 3 سكاشن. وكلهم لهم نفس نموذج الكويز، هذا يعني ان اذا انت في آخر سكشن. أفرج الكلاس رح يكون جدًا عالي. الترم الماضي كان أفرج سكننا 34 من 40!.\n\nالمياجر: كومن\n\nالفاينلات: كومن\n\nالتقييم النهائي: A\n\nالصوت: واضح إذا كنت تجلس قدام. يتكلم عربي كثير فقط عشان المعلومة توصل بسهولة.\n\nإضافات: من أكثر الأشياء الي تميز الدكتور هي أخلاقه. أيضًا الدكتور يجاوب على أكثر أسئلة الطلاب في وقت الكلاس وبعد الكلاس. ودائمًا متواجد في مكتبه. كنسلة الكلاسات عنده بريال بالرغم من أنه سوا حركة غبية الترم هذا وهي انه حط لنا كلاس ساعتين بعد المغرب وكانت بمثابة تعويض عن كلاسين. الدكتور مو أفضل دكتور ممكن تدرس عنده، لكنه فعلًا يستاهل إنك تعطيه فرصه. نصيحة اذا لقيت سكشن فاضي ومستعد تكون منضبط في الكلاس أضمن لك إنك بتستمتع بالكلاس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508794-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/51", "user": "Abdulrahman_Alghamdi", "ts": 1555762984000, "tid": 69876, "pn": 51}}]}', 1555762984000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12010-math101', 'stk-user12010', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101-201\n\nد.خالد الشمري(أبو عزوز)\n\nبسم الله الرحمن الرحيم\n\nالتحضير: شديد جدا جدا، مع نظام الدراسة عن بعد باستخدام برنامج فِرَق(Teams)يسحب ملف الحضورأتوماتيكيا بعد أول دقيقتين ومَن يدخل بعدها يُحسب غائب رضيت أم لم ترضَ.\n\nالشرح: انعقد الإجماع باتفاق عقلاء كل شعبة على سوء شرحه وعلى اتصافه بكمال ضد كل صفة حسنة! الدكتور(أولد فاشند)ومعرفته في الأمور التقنية صفر-على حدِّ قوله-لذلك عنده قروب واتس للطلاب يرسل فيه-بعض الأحيان-شروح لبعض المسائل وكل أمرٍ مهم من مواعيد اختبارات وخطط للأسابيع-خصوصا لو كان فيه (Concentration period) (:-، طبعا يعتمد على الكتاب اعتماد كليّ وشرحه يقتصر على اللت والعجن في شرح المفاهيم؛ يعني: قد يأخذ نصف ساعة على شرح مفهوم واحد؛ بسبب استطراده في طرح الأمثلة الساذجة المُستغنى عنها وهو يقدر يشرحه في 10 دقائق-كحد أقصى-. بعض الأحيان-خصوصا قبل أوقات الامتحانات-يفتح ملف أولد أقزامز ويبدأ يحل كذا مسألة, ولو لم يعضنا الله بشروحات مقبل-جزاه الله عنا كل خير-لكنا على هامش هذا الفصل.\n\nالواجبات: الدكتور يعطي واجبات-لا فائدة منها حقيقةً وغثيثة بشكل لا يُتصور-على(webassign)مع أن فيه واجبات رسمية من القسم(study plan)!\n\nالاختبارات القصيرة: من عجائب وغرائب هالدكتور-وهي غريبة من عدة غرائب وعجائب للدكتور تستحق أن تُجمع وتُفرد في كتابٍ مستقل!-أنه يعطي اختبار قصير-ركّز \" قصير\"!-(quiz)في شابتر كامل بأسئلة متعددة ووقت قليل! ولكنها-ولله المنة-متوسطة الصعوبة مائلة للسهولة. طبعا نفس أسئلة الواجبات من بنك الأسئلة وبدون أي مجهود يُبذل لكتابة أسئلة أو حتى اختيار أسئلة معيّنة.\n\nالصوت: واضح ويتكلم بلغة مختلطة ناتجة من دمج العربية والانجليزية معا بشكل مقزز وهذا مما لا شأن لنا به والله المستعان!\n\nإضافات: الدكتور أخلاق للأمانة وحبيّب جدا ولكن من لي بأخلاق لا تنفع المعدّل؟ وفي المقابل عنده برود وطولة بال للأمور لا تُوصف. لا تستغرب أن المحاضرة تنقلب إلى محاضرة مهارات حياتية(Life skills) ونصائح والواحد لازم يتعب وكل بقدر جهده وفي نفس الوقت يعطيك نفائس وتصبيرات من قبيل: \" ترى ماهو لازم تأخذ A+ الB و الC+ حلوة\"!.\nطبعا أكاد أجزم أن الدكتور يختلف وضعه في الدراسة-وكلنا ضحايا لتقييمه هنا-حضوريا عن الدراسة عن بعد وأنه أفضل بكثير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526573-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/56", "user": "user12010", "ts": 1604830564000, "tid": 69876, "pn": 56}}]}', 1604830564000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-2ams-math101', 'stk-2ams', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. خالد الشمري\n\nبروفيسور\n\nبنود التقييم :\nMath 101 term 201\nالتحضير :\nيحضر بعد دقيقتين من بداية المحاضرة والتحضير كان يسحب قائمة من التميز واحيان ينادي اسماء بشكل عشوائي في المحاضرة\n\nطريقة الشرح :\nيشرح مسائل الكتاب المحلولة ويكتب ويشخبط واجد على الكتاب بالماوس\nباختصار يعقد المسائل وهي بسيطة\n\nالكويزات :\nالدكتور كان معتمد على الويب اساين بشكل كلي واسئلة الويب اساين تحتاج الحاسبة عشان تحلها\nمستوى الكوزات صعب جداً في الغالب والوقت قليل. وبالإضافة للكوزات الدكتور كان عند اسبوعياً على الاقل واجب وكل واجب يحتاج على الاقل ساعتين. وفي نهاية الترم حط مني فاينل على المنهج كامل.\nمجمل عدد الكوزات والهوموركاتات 22 .\n\nالقريد النهائي: D\n\nالصوت: الصوت في بداية الترم كان مب واضح مره يقطع بعدها تحسن.\n\nإضافات :\nالدكتور اخلاق بس يعيبه تجاهله لرسائل الطلاب او الرد بـ اموجي غير مفيد .\nالدكتور يشرح في مكان غير هادي بتسمع صوت اللي في البيت كلهم .\nالدكتور ما وضح من بداية الترم كيف راح يكون توزيع الكلاس ورك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527586-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/70", "user": "2ams", "ts": 1609815638000, "tid": 69876, "pn": 70}}]}', 1609815638000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-math101', 'stk-someone33', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 Term212\n\nالتحضير : مثل ما قالوا التحضير اهم شي عنده و يكون قبل الكلاس\n\nطريقة الشرح : يشرح الكونسبت عن طريق أمثلة يجيبها من نوتات خاصة فيه و اغلب الأمثلة من الكتاب و الشرح يكون عبارة عن حل اسئلة سهلة بشكل مو طبيعي و تضييع وقت\n\nالكويزات : 5 كويزات طول الترم و اثنين منهم كويزات طويلة لمدة الكلاس كامل ، واحد من الكويزات ما بيصححه و بيقول لكم عطاكم كلكم فل\nالكويزات ما يغيرها من 4 سنين، دور عنها في الريسورسز\n\nالقريد النهائي: B\nالصوت: واضح\n\nإضافات :\n- على الرغم من ان الدكتور مهتم بأخذ التحضير الا انه ما يحسب كم غياب لكل طالب الا نهاية الترم، بمعنى لو تجيه في نص الترم و تسأله كم غياب عندك ما بيعلمك لانه ما يعرف اصلا\n-الدكتور بيسوي قروب في الواتس لكن ما يرد على احد ولا يرد على الايميل\n- الدكتور يسأل اسئلة في نص الكلاس، لا ترفع يدك و تشارك الا لو انت متأكد من جوابك لانه بيطقطق عليك لو تجاوب غلط\n\nلو مستواك سيء في الماث ويهمك تفهم فأنا انصح بالدكتور لان شرحه بسيط جدا و واضح و يعيد في نفس المعلومة مليون مرة لين تزهق و انت تشوف نفس المعلومة من كثر التكرار\nلو مستواك جيد فأنا انصحك تشوف دكتور ثاني لأنك بتمل من كلاساته\n\nلازم تحرك يدك وتحل بعد الكلاس لأن الدكتور ما يحل اولد اقزام ابدا ابدا وما يعترف في شي اسمه اولد اقزام، الدكتور بيشرح كونسبت فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534168-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/75", "user": "SomeOne33", "ts": 1650523179000, "tid": 69876, "pn": 75}}]}', 1650523179000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulaziz_al-mumtin-math101', 'stk-abdulaziz_al-mumtin', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. خالد الشمري\n\nبروفيسور\n\nبنود التقييم :\n\nالتحضير : اشد دكتاتور في التحضير شفته بحياتي, نزل عنده لو تبي احد يغيبك من 4 دقايق\nطريقة الشرح : تمطيط, لو كنت شخص يستمتع ويفهم ببطء شديد جدا وتراه مايحل مسائل مغير يسولف عن شي مكرر شرحه سبع مرات وتقدر تفهمه ب5 دقايق\nالكويزات : اول كويز كان سهل, الباقي بين الصعب والمقبول لكن اغلب الاسئلة تجيب المغص\nالمياجر: ماكان يحط\nالفاينلات : مايحط\nالقريد النهائي: اقيمه بD صراحة, كثير دكاترة بيكونون احسن\nالصوت: نبرة صوته محتواي مره تلاقيه يهمس وفجاه يصرخ على كلمة بدون سبب\nإضافات :\nكتجربة شخصية… منزل عنده ماث 101\n1- عنده قروب واتس اب, يحط فيه اسئلة وامثلة وتواريخ اختباراته وغيره (يعتبره كمنصة رسمية)\n2- من ناحية الاشياء الغريبة, يحب يفرك القلم بيده لما يسأل كانه بيطلع منه مارد ويفصخ صندله بوسط الشرح\n3- فجأه يعطيك صباح الخير, اعرف انه بيجيك سؤال من المريخ\n4 -فكثير من الحالات مايفهم طلابه, لا اسئلتهم ولا اجوبتهم ويحب يقاطع فوسط الجواب يعني حرفيا ليه تسأل\n5- لازم تستأذن مو زي اغلب الدكاترة تطلع للحمام عالصامت ولا ينزعج\n6- نرجسي نوعا ما ومصدق نفسه مثل اغلب الدكاترة, ممكن يشخصنها معك بدون سبب\nفحالتي صارت قصة ظريفة لواحد من طلاب السكشن لما مسك جواله بحصته, انطرد للتشيرمان وكان بيلقم فصل مؤقت بس انتهى الموضوع باعتذار خطي وشفهي قدام الفصل ومعتبرينه يرادد ويلعب بالجوال بوسط الحصة (حسب كلامه الدكتور شايفه يرادد ويعاند ويلعب بالجوال واللابتوب, ماكان عنده لابتوب اصلا وسمعته يهدي الدكتور وكان خايف ماعاند) مع ان ياكثر الي فاتحين جوالاتهم, باختصار اترك جوالك وركز مع شرحه الممطط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536003-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/77", "user": "Abdulaziz_Al-mumtin", "ts": 1670676185000, "tid": 69876, "pn": 77}}]}', 1670676185000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stallion-math101', 'stk-stallion', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 - Term231\n\nالتحضير : كلاسنا كان الساعة ٧ الصباح ويحضر على وقتها بالضبط ويخلي الكود دقيقتين فقط، فجدا شديد في التحضير\nطريقة الشرح : ما يفتح سلايدات وشرحه كله عالسبورة. شرح الدكتور ممتاز جدا لكن فيه سلبيه كبيرة انه يحل بس اسئلة الكتاب ولا يحل اولدات، باختصار تعتمد على نفسك.\nالكويزات : ١٢ كويز on webassign, اول ٣ كويزات سهله جدا لكن بعدها ال٩ كويزات كانو صعبين اسئلة كثير في وقت قصير.\nالمياجر:كومون\nالفاينلات : عطانا فاينل عالكلاس وورك عليه ٥٠٪؜ من الكلاس وورك، كان صعب بشكل مزعج وما كان مقياس صراحة، افرجنا كان ٤٥٪؜ وكنا متحطمين. لكن افرج المياجر للسكشن كان ٨٠٪؜ فرفعنا رفعة قويييية لدرجة ان الكلاس وورك صار افرجه ٨٠\nالقريد النهائي:B\nالصوت:واضح\n\nاذا انت شخص ملتزم بالوقت ومتعود عالاولدات نزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537163-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/79", "user": "Stallion", "ts": 1702660865000, "tid": 69876, "pn": 79}}]}', 1702660865000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-n13-math101', 'stk-n13', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 - Term251\n\nالتحضير : الكلاس كان يبدا الساعة 8 والدكتور يفتحه قبل الكلاس بدقيقتين ويقفله بعد ثلاث او اربع دقايق من وقت الكلاس ( 8:03 )\nطريقة الشرح : شرحه كله ع السبورة يحل من اسئلة هو مجهزها وللأمانة والشيء والوحيد الي اعجبني فيه ان شرحه كافي ووافي ولكنه قليل ما يحل اولدات\nالكويزات : يسوي ثلاث كلاس تيستس وكانت يوم الخميس من قبل كل ميجر ، الكلاس تيست الثالث كان فعليًا ميني فاينل وكانت متوسطة مائلة للصعوبة والميني فاينل كانت صعب بشكل مزعج\nالفاينلات :الكلاس تيست الاول كان الافرج 64.55% وكان عليه 25% من الكلاس ورك والتيست الثاني كان الافرج 49.64% وكان عليه 25% والكلاس تيست الاخير كان عليه 50% والافرج كان 50% واعلى درجة كانت 18/20\nالقريد النهائي:D\nالصوت:واضح ولكنه منخفض واذا تجلس ورا بتعاني شوي من صعوبة بالسمع\n\nما انصح تنزل عنده الا اذا منحد ع الوقت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540815-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/80", "user": "N13", "ts": 1767733011905, "tid": 69876, "pn": 80}}]}', 1767733011905, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-frs365-math101', 'stk-frs365', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m70511", "n": "Dr. Ahmad Bonfoh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 - 171\n\n- التحضير :\nمتساهل جدا بالتحضير ويسمح بالميك اب بدون ماتقول له (طوال السمستر احضر مع شعبة ثانية) .\n\n- طريقة الشرح : قبل المحاضرة يكون رافع نوتة الدرس نوتة جديدة على البلاكبورد ، وفي المحاضرة يكتبها على السبورة ويبدأ يشرحها ، بالنسبة للنوتة جدا واضحة وممتازة واختيار الامثلة ممتاز ، بالنسبة لشرح الدكتور فهو يتعب في توصيل المعلومة ؛ لكن هذا مايعيب الدكتور لأنه بقدر المستطاع يحاول يوصلها . يخلص ماتريال الميجر في وقت ممتاز ثم يحل اسألة للطلاب.\n\n- الكويزات : كان تقريبا عنده 6 كويزات وكلها كانت سهلة وواضحة ومن الشيء المشروح ، وكان دايم يقول هذا سهل اوريكم بالكويز الجاي 😅. كان يقدم لنا هومورك من عنده تقريبا عطانا ثلاثة ، اثنين منهم كانت بونص ، الاخير عن كويز .\n\n- الصوت: اول كلاسين بتستغرب اللهجة اذا مادرست عن دكتور اكسنت افريقي ثم تتعود.\n\n- إضافات :\n\nنجي للزبدة :\n\nالدكتور مظلوم هنا في التقييم ، صحيح شرحه مش ولا بد ؛ لكن تطلع من الكلاس وانت فاهم + عنده نوتة جديدة تذاكرها ممتازة + كان يجمع اسألة على كل درس من مياجر وفاينلات 151 الى 163 (انا كنت عنده 171) وكان يحلهم بنفسه ويرفعها للطالب + متعاون في الكويزات والهوموركات = اتوقع كذا يكفي ، بالنسبة لي من افضل الدكاترة اللي مرو علي.\n\nدكتور رائع ويجتهد ويتعب للطالب ، افضل من واحد اسطوري بالشرح بس اذا تبي تذاكر ماعندك مراجع ولا مكان تتدرب فيه … وتحس انك ضايع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493530-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-bonfoh/70511/35", "user": "FRS365", "ts": 1527949447000, "tid": 70511, "pn": 35}}]}', 1527949447000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-math101', 'stk-user10207', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m70785", "n": "Dr. S Boubaker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 – Term 141\n\nhttp://s12.postimg.org/cdvgnnwcd/Boubaker_Smii.jpg\n\nطريقة الشرح: يكتب على السبورة نوت منقول من الكتاب بالضبط وهو ساكت بعدها يشرح الي كتبه. يعبّي السبورة كلام ويمسح ويكتب مرة ثانية النوت ويشرح عن الكلام الي كتبه. هذه طريقته. أشوف طريقة شرحه مملة وباردة، ومايجبر الطالب يكتب معه.\n\nيهتم بشكل كبير على الكونسبت أكثر من الأمثلة. لأنه هو ماشاء الله فاهم بالماث ويدرسّ طلبة دراسات عليا أيضاً فـ تجده يكتب النظرية ويسولف مع الطلاب عن هذه النظرية أو المعادلة وكيف جت وكيف تنحل وهكذا ويطول فيها.\n\nبعض الكويزات صحيح مش على مستوى الشرح، لكن أشوفها عادية مائلة للسهل.\n\nالكويزات يأخذها من آخر مياجر الأولد إكزام (131، 132، …) وفيه منها بأسئلة الكتاب، يجيب نفسها بالضبط وبنفس الأرقام.\n\nخلال السمستر يعطيك 4 كويزات، وهي الكلاس وورك. فعشان كذا حاول تبدع في الكويزات.\n\nتصحيح في أول مياجر (الكتابي) أشوفه كويس. عكس كلام الطلاب هنا بالموضوع يقولون سيء. يعطيك أكثر من الي تستحق (بكثير) في الميجر أو بالكويز (أتكلم عن نفسي).\n\nأكثر شيء يهتم له في الميجر (والي يزودك درجات) هو أنك تكتب بالتفصيل الممل.\n\nقبل المياجر يعطي كلاس مراجعة.\n\nبعض الأحيان يطلب من الطلاب هومورك (يكمل حل المسألة). ما يشيّك دائماً، لكن مرة شيك وحط درجات على الطلاب الي سوو الهومورك.\n\nأيضاً، بعض الأحيان يخلي الطلاب يطلعون على السبورة ويحلون المسألة والي يحل صح تضاف له درجات بالكلاس وورك.\n\nيجاوب على اسئلة الطلاب بالكلاس.\n\nالأوفيس أور يمدده وقت المياجر والفاينلات.\n\nيستعمل البلاكبورد والإيميل ويتواصل مع الطلاب بشكل جيد.\n\nيبدأ الكلاس على الوقت وينتهي على الوقت.\n\nأكثر شيء يكرهه إذا شاف أحد معه الجوال، أو يتأخر. أنتبه\n\nالتحضير ورقة تمر. لكن أنتبه تحضّر واحد غيرك لأنه يشيّك ويعصب إذا شاف واحد يحضّر خويه.\n\nأحياناً يخلي مدرس الريزينتيشن يصحح الكويزات.\n\nالصوت واضح. لغته الإنجليزية جيدة.\n\nبشكل عام، لابأس فيه، المدرس محترم… لكن أشوف فيه أفضل منه إذا لقيت. وإذا ما لقيت يبقى الدكتور سميع جيد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420425-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-boubaker/70785/37", "user": "user10207", "ts": 1421617637000, "tid": 70785, "pn": 37}}, {"id": "stk-dr-m118562", "n": "Dr. Faez Al-Qarni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term 141\n\nيدرس كلاسات الريسيتيشن.\n\nشرحه ممتاز. يفتح السلايدات على المسأئل، يتناقش مع الطلاب كيف تنحل المسألة أو كيف فكرتها، وبعدها يحلها على السبورة.\n\nيتجاوب على اسئلة الطلاب في الكلاس بكل ترحاب، على الرغم من ضيق الوقت.\n\nالسلبية الوحيدة فيه أن بعض الأحيان يطول بشرح مسألة، وبسبب هذا الشيء يخلص الكلاس وباقي كم سؤال. أيضاً، وبسبب هذا التأخير دخلنا الميجرين ولسى باقي كم درس ما أخذناهم في الريسيتيشن. نفس الشيء بالفاينل، أخذنا كلاس زايد على آخر الأيام.\n\nيحضر نهاية الكلاس.\n\nينتبه لمستوى الطلاب، ودايم يحفز الطلاب أنها يحصلون على درجات عالية في الإختبارات.\n\nعارف الأسئلة الي راح تجي بالميجر والفاينل، ويقول ركزوا عليها. وفعلاً تجي بالإختبارات.\n\nإذا ارسلته إيميل لأسئلة ما عرفت تحلها، علطول يرسل الحل لك بالإيميل.\n\nعلى أيام الفاينلات، إذا احد عنده سؤال يقدر يرسل إيميل أو يتصل عليه إذا فيه اسئلة ويتقابل معه بالجامعة في أي وقت!\n\nيخدم الطالب. يتواصل مع الطلاب على الإيميل، يحط السلايدات على البلاكبورد، إذا احد وده أولد اكزاه يجيه المكتب، أو اي سؤال، وغيرها.\n\nخطه رائع على السبورة وواضح. صوته واضح، لغته الإنجليزية جيدة. لكن تحتاج تتعود بالبداية.\n\nسريع بالكتابة على السبورة. إذا بتكتب معه، أكتب بسرعة، ولا بتتلخبط ومابتفهم وش يقول وأنت تكتب.\n\nيجي الكلاس بدري. يحب يعطي نصائح للطلاب كيف ينجحوا وكيف يحلوا وغيرها.\n\nممنوع عنده تستخدم الجوال في الكلاس. وممنوع تصور بالجوال النوت المكتوب بالسبورة.\n\nكنت أتمنى يكون مدرس اللكشتر بدل الريسيتيشن لأنه أكثر من ممتاز.\n\nشخص رائع ومتفانِ في عمله. جزاه الله خير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1421781-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faez-al-qarni/118562/6", "user": "user10207", "ts": 1422057059000, "tid": 118562, "pn": 6}}]}', 1421617637000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zahran00wolf-math101', 'stk-zahran00wolf', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m70785", "n": "Dr. S Boubaker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : تحضير ورقة\nطريقة الشرح : نوتاته كلها تعاريف ولا يكثر تمارين\nالكويزات :صعبة جداً\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: C في ماث 101 مع أني عايدة وF في ماث 102\nالصوت: واضح\nإضافات: للأمانه يخلي الطلاب يشتغلون وخفيف دم و الميجر الثاني دفني ب 3 بوينت\nبس دكتور سي لا أكسنت ولا شرح ولاتمارين\n\nابعد عنه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456155-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-boubaker/70785/42", "user": "zahran00wolf", "ts": 1472512158000, "tid": 70785, "pn": 42}}]}', 1472512158000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tmk2008-math101', 'stk-tmk2008', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m77387", "n": "Dr. Jarrar M S", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت معه ماث 101 …والصراحة بداية الترم كنت محبط تماما على كلام الطلاب عنه\nلكن بأمانه الانسان يشرح اللي في الكتاب لا زياده ولا نقصان …صح انه مو ذاك الشرح لكن انا اشوف انه يفي بالغرض ولحد يقعد يقول راحت عليك والا ابشر بالسي والدي معه …انا اخذت معه واقول شرحه مو مره وطلعت بقريد ممتاز …عيبه الوحيد اللي يذكر وهو يدري عنه… كويزاته صعبة بس عادة الافرج طايح فيرفع الطلاب في الاخير …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p718071-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jarrar-m-s/77387/27", "user": "TMK2008", "ts": 1286639987000, "tid": 77387, "pn": 27}}]}', 1286639987000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-t_a_r_i_q-math101', 'stk-t_a_r_i_q', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m77387", "n": "Dr. Jarrar M S", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مالقيت اسمه مع الانستركشرز للسمستر111\nبس باختصار دكتور يستاهل انك تضبط جدولك عليه\nنزلت عنده ماث 101 ،، وطلعت ب اي والحمدلله الفضل لله ثم له\nوالحين ضبطت جدولي واول شي سويته اخترته هو\nمتساهل بالتصحيح والشرح كويس يحل اكزامبلز كثير\nالي بينزل عنده ماراح يندم ابددددن 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p840999-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jarrar-m-s/77387/32", "user": "T_a_R_i_Q", "ts": 1304643445000, "tid": 77387, "pn": 32}}]}', 1304643445000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ur1-math101', 'stk-ur1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m78126", "n": "Dr. E Echi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 191 ، math 101\nالبروفيسور عثمان عشي\nالتحضير : يحضر بالاسم نهاية اللكتشر شديد بالتحضير واحيانا يطرد اللي يتاخر\nطريقة الشرح : يكتب ع السبورة ويمليها ويمسحها ثلاث مرات جدا طبيعي ، شرحه سيء صراحة كأنه يشرح لنفسه وخذ في بالك انك بتاخذ الكورس سيلف ستدي\nالكويزات : سهله نسبيا وغالبا نفس افكار الاسئلة في النوته حقته وتصحيحه جدا ممتاز عطانا كويز صعب واشك انه يصحح الكوزات لاننا كلنا ناخذ نفس الدرجة عطانا كويز هووم وورك وكلنا اخذنا فيه ١٠\nالقريد النهائي F\nالصوت: صوته واضح لكن آكسنت الانقلش لك عليه ، ومع الوقت بتمشي امورك\nإضافات : الدكتور طيب ومحترم وقمة في الاخلاق والقيم والعادات العربية الاصيلة . مايسمح انك تدخل الكلاس بشورت او بقهوه لأنها في نظره عدم اهتمام واستخفاف بالعلم وأهله . غير متعاون في الاوفس آور جيته اكثر من مرة بوقت الاوفيس اور ولا لقيته اضافة جداً مهمة الدكتور كريه بشكل لا يوصف عن نفسي كلاسه عباره عن حومة كبد. ، الدكتور للامانة ياسسك زين بالقوانين لانه يبرهن كل شي وهذي ميزته الوحيدة عمومًا خله اخر خياراتك وبالتوفيق يا رب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517091-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-echi/78126/28", "user": "UR1", "ts": 1574139280000, "tid": 78126, "pn": 28}}]}', 1574139280000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali224323-math101', 'stk-ali224323', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m78126", "n": "Dr. E Echi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 191 مات 101\nالتحضير : ينادي بالاسماء اخر الكلاس\nطريقة الشرح : صعبة الفهم يكتب في السبورة مااحد يفهم على كتابته لكن ذا الكورس سهل والدكتور ان شاء الله مايشكل عائق\nالكويزات : سهلة\nالمياجر:كزمن\nالفاينلات :كومن\nالقريد النهائي:C\nالصوت: ممكن مشكلة شرحخ في طريقة كلامه\nإضافات الدكتور يمكن يطرد\nك على استخدامك للجوال او لبسك للشورت . يقدر الي يشتغل معه ويضبطه في الكلاس وورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521813-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-echi/78126/33", "user": "ALI224323", "ts": 1588763541000, "tid": 78126, "pn": 33}}]}', 1588763541000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f.s.d-math101', 'stk-f.s.d', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m78226", "n": "د. بارسا باختاري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nالتحضير : مايحضر أبببببببد ويقول انا ماعلي منك انت مسؤول عن نفسك << يالبى قلبه\nطريقة الشرح :ممتااااااااااااااااااازه أحسن مدرس ماث مر علي بصراحه واذا رحت له للأوفيس أور يسوي اي شي بس عشان تفهم\nالكويزات :تقريبا أسبوعيه وصعوبتها على حسب التشابتر سهل أو متوسط أو صعب\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:a+++++++++++\nالصوت:وااااااااااااااضح وأكسنت واااااااااااااضح\nإضافات : الدكتور في قمة الأخلاق وشرحه مثل ماقلت خراااافي انا نزلت عنده ماث 101 والحين ادرس عنده ماث 102\nوأحب أصحح لأخوي اللي قال انه ايراني الجنسيه انا سالته وقال ان أمه ايرانيه وابوه امريكي وطول حياته عايش بكاليفونيا بامريكا و091 كان اول ترم يجي فيها للسعوديه\nنصيحه لوجه الله اللي يحصل له الدكتور باختاري لا بفووووووووته وينزل عنده وهو مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p609968-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/78226/13", "user": "F.S.D", "ts": 1274182610000, "tid": 78226, "pn": 13}}]}', 1274182610000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-big_world-math101', 'stk-big_world', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m81621", "n": "Dr. Slim Belhaiza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا أخذت معه ماث 101 السمستر الماضي (111)\n\nالتحضير :\n\nيحضر في نهاية الكلاس بالأسماء مثل ماقالوا الشباب\n\nطريقة الشرح :\n\nيحاول يوصل المعلومة لكن انا ماكنت افهم معه ابدا …ويحل كم مثال من الكتاب\n\nالكويزات :\n\nعطانا 3 كويزات في السمستر كام واخذ افضل اثنين (كويزات سهلة من الهوموورك)\n\nالمياجر:\n\nعنده مقولة (we are teaching calculus, not the history of calculus)\n\nالزبدة منها انه مايعطي درجات على كتابة القوانين في الميجر الـwritten (يشيل منك كم درجة)\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nC\n\nالصوت:\n6/10\n\nإضافات :\nأغلب الشباب اللي كانوا معي راحوا يحضروا مع مدرسين ثانين وافرج الكلاس كان تحت افرج الكورس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972530-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/slim-belhaiza/81621/17", "user": "big_world", "ts": 1327312159000, "tid": 81621, "pn": 17}}]}', 1327312159000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-blake-math101', 'stk-blake', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m81621", "n": "Dr. Slim Belhaiza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 2012\nالتحضير :\nنهاية الكلاس - ناادرا ينسى يحضر - يسامح ع التأخير - يسمح بالميك اب\n\nطريقة الشرح :\nيكتب ع السبورة + يحل مسائل الكتاب … للأمانة هو يتعب يحاول يوصل المعلومة بس للأسف دائما يفشل\nشرحه - بالنسبة لي - سييئ !\nنص الكلاس يضيع في الهروج ( يتفنن في صنع وايجاد المواضيع الي يضيع بيها الوقت )\nينكت ويسمج احيانا - يشرح الكونسبت اولا ويطووول فيه ثم يبدأ التمارين ( يحل تقريبا من 2 الى 3 تمارين ع كل كونسبت )\n\nالكويزات :\nمتوسطة الى صعبة - كل اسبوع كويز\n\nالمياجر: كومن\nالفاينلات :كومن\n\nالقريد النهائي:\n\nD+ or C\n\nالصوت:\nواضح - اكسنت شمال افريقيا - يتكلم عربي كثير\n\nإضافات :\n\nانا اخذت قريد سيئ عنده ، لكن والله كل الي كتبته صحيح 100٪\nللأسف هذا الترم الديبارتمنت الوضيع خلا الآفرج D+ ولأول مرة في الجامعة !\nيعني تقريبا ثلثين الدفعة اخذو تحت ال C+ الي هو مفروض يكون الآفرج !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1254572-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/slim-belhaiza/81621/32", "user": "blake", "ts": 1377153063000, "tid": 81621, "pn": 32}}]}', 1377153063000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osamah56-math101', 'stk-osamah56', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m81621", "n": "Dr. Slim Belhaiza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - term 151\n\nاتوقع انه احسن شيء تاخذ معه مادة سهلة زي 101 لان تقدر تاخذها سلف ستدي لانه في الكلاس يقرا سلايدات نفس الشرح الي بالكتاب ف اذا ما ترجع وتذاكر بنفسك ما راح تفهم\n\n+ بالنسبة لي احسن مافيه تصحيحه للميجر الريتن يدف دف مب صاحي والدليل ان افرج سكشنا اعلى من الاوفرال ب9 درجات\n\nالقريد النهائي :\nاخلاق A\nشرح c+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1431999-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/slim-belhaiza/81621/40", "user": "osamah56", "ts": 1446580746000, "tid": 81621, "pn": 40}}]}', 1446580746000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-krooom-math101', 'stk-krooom', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "152 Math102\n\nالتحضير :بداية الكلاس ولو تتاخر 3 دقايق ليت و 10 غايب ومهما سويت ما يغيرها\nطريقة الشرح : شرحه حلو ولكن لاحظت انه اللي متمكنين من الرياضيات واساساتهم تمام مع ذا الاستاذ اتوقع لهم أ+ او أ واللي اساسياتهم مش ولا بد راح يضيعون بشرحه وللاسف راح يخبصون بالمياجر والفاينل الا من رحم ربي لانه أبد ما يرجع يشرح للاشياء القديمه وهذا من ححقه\nالكويزات : نار انا اخذت أ+ بماث101 لكن افرج كوزاتي من 6 او 7 كوزات كان تقريبا 4 وهذا راح ياثر على الكلاس وورك\nالمياجر: كومون لكن ما شاء الله يعطيك نصايح حلوة قبل المياجر وتصححيه لك عليه شديد شوي\nالفاينلات :كومون\nالقريد النهائي: ب+\nالصوت:واضح\nإضافات : اذا انك كويس بالماث فانصحك فيه لكن اذا انك منت متمكن بالماث فهذا الاستاذ راح يعقدها عليك وبالنسبة للكلاس ورك انا كنت استحق 16 لكن خلاها لي 36 والسبب المياجر على حسب مياجرك يزودك لانه بالاخير غصبا عنه راح يزود الطلاب عشان يخليها بين 23 و 29 وهو خلاها 29 لكن مب كل الناس زودهم كثير من اخوياني اخذو درجتهم اللي يستاهلونها 10 او 14", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452272-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/23", "user": "Krooom", "ts": 1466270604000, "tid": 118577, "pn": 23}}, {"id": "stk-dr-m81621", "n": "Dr. Slim Belhaiza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث101 151\n\n152 ICS 253\n\nالتحضير : اخر الكلاس ومتساهل\nطريقة الشرح :على السبورة والاستاذ ما يشرح اللي بيجيلك بالمياجر يعطيك اشياء بالبزنس و اثبات كيف جت القوانين لكن ذولا ما تشوفهم بالمياجروشرحه ما يفهمه الا 5 بالكلاس لانه الامثلة اللي يحطها صعبة جدا واغلب الفصل ضايع\nالكويزات : كوزاته موية اذا انك مذاكر\nالمياجر: كومون ولكن صدقني راح تتعب عشان تجيب شي زين وتصححيحه متساهل شويتين\nالفاينلات :\nالقريد النهائي: ب+\nالصوت:واضح\nإضافات : مع ذا الاستاذ بتضمن درجة عالية بالكلاس وورك ولكن وش تستفيد اذا مياجرك رايحة فيها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452275-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/slim-belhaiza/81621/45", "user": "Krooom", "ts": 1466271603000, "tid": 81621, "pn": 45}}]}', 1466270604000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abutaleb91-math101', 'stk-abutaleb91', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83632", "n": "Dr. Khalid Al-Anezy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nأنا صراحة أخالف أغلب الشباب…الرجال متعاون لأبعد الحدود… كان يقول للي يجي متأخر يذكره آخر الكلاس عشان التحضير…بعدين الرجل هذا ما شاء الله عليه من ثاني كلاس بدون مبالغة وهو حافظ أسماء الكلاس كامل والسيريال نمبر…\nطريقة الشرح :\nيكتب ويعطي الطلاب فرصة انهم يكتبوا معاه… لكن عيبه كل أمثلته من الكتاب بالنص… ونادراً ما يعطيك أفكار جديدة…لكن للأمانة كان يشرح الفكرة شرح رائع و بسيط…يعني هو في الشرح ممتاز\nالكويزات :\nالجميل في هذا الأستاذ انه في بداية السمستر يتفق مع الطلاب على طريقة الكويزات… أخذنا معه على ما أذكر خمس كويزات أخذ أحسن أربعة… غير انه عطانا كلاس تيست بس كان بونص يعني يزيدك عليه وما ينقصك\nالمياجر:\nفي الميجر الأول صراحةً كان تصحيحه شديد… يعني ما عنده لعب… تاخذ حقك وبس\nبس إذا اكتشفت غلط في التصحيح ورحت توريه على طول يصحح ويعطيك حقك…\nالقريد النهائي:\nA\nالصوت:\nممتاز جداً… وخصوصاً إذا تحمس مع الشرح تشوفه يصارخ.\n\nإضافات :\nعلى طاري التحضير… أنا في ثاني أسبوع في سمستر101 غبت كل الأيام يعني بالعربي ما حضرت ولا كلاس ذاك الأسبوع بسبب مرض شديد… المهم اني رحت مستشفى حكومي وجبت منه الأعذار الطبية…لكن للأسف عيادة الجامعة لم تقبل الأوراق الحكومية الموثقة…وما عطوني أي عذر طبي…المهم اني رحت أكلم الأستاذ خالد فقالي في البداية روح حاول معهم كمان… وشوف و رد لي خبر… طبعاً الدكتور كان غير متعاون أبداً…و أنا صراحة كنت أحسب انه عادي إذا جبت عذر حكومي المنطقي ان الجامعة تقبله… نرجع لأستاذنا خالد… رحتله في الاوفيس ووريبته الأعذار وقالي شوف إذا استمريت معي بدون غيابات فاعتبرها ممسوحة…\nيعني الرجال مرن وقابل للتفاوض وياخذ ويعطي عكس أغلب دكاترة الجامعة…\nغير إنك بتاخذ حقك بالتمام والكمال معه…\n…\n\nللمعلومية أنا أخذت معه ماث 101 في 101", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p780846-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-anezy/83632/25", "user": "Abutaleb91", "ts": 1296690183000, "tid": 83632, "pn": 25}}]}', 1296690183000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6913-math101', 'stk-user6913', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83632", "n": "Dr. Khalid Al-Anezy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الأستاذ خالد العنزي\nماث 101\nمحاضر\n\nبنود التقييم :\n\nالتحضير : التحضير ممتاز بالسريل نمبر … وتقريبا الاسبوع الثاني و الثالث يكون حافظ اغلب الطلاب اذا مو كولهم ماشالله عليه … ومرات يحضر بالنظر يعني مو دايم ينادي بالسريل\nطريقة الشرح : احلى مايكون … يشرح لك الفكرة بأمثلة بسيطة … ويعطي اخر كل كلاس يسميه كلاس بارتسبيشن … وهي اغلبها تكون مسألة من اولد اكزام او كذا وفكرتها حلللللوة مرة … وتفييييد …\nالكويزات : يجيبها مرات من الكتاب نصيا … ومرات من اولد اكزامز … والحمدلله الاستاذ مبببببببدع\nالمياجر: التصحيح ممتاز … ويعطيك حقك … واذا هو مخطي بالتصحيح او حاجة وراجعته يعدلها ع طول\nالفاينلات : --\nالقريد النهائي: لو فيه قريد فوق a+ كان عطيته\nالصوت: واااااااضح ويتحمس مع الشرح ويوقف مثلا عشان سؤال طالب وكذا\nإضافات : قبل لايكون معلم … يكون أخو لك … وزي ماقالوا الشباب … لو عندك سؤال مستعد يجلس للوقت اللي تبي عشان تفهم الفكرة\nيعني بأسبوع المياجر … الطلاب يجلسوا يسألوه بعد الكلاس وكذا … وانا كنت اجلس وكذا ومرات نص الى ساعة والاسألة موجودة\nيهتم بالطلاب اهتمااااااام كبييييييييييييييير\nانصح فيه وبقوة … واحتمال كبير اعدل بجدول كلللللللله عشانه … تحياتي\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p849661-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-anezy/83632/27", "user": "user6913", "ts": 1307676574000, "tid": 83632, "pn": 27}}]}', 1307676574000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jarrash-math101', 'stk-jarrash', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83632", "n": "Dr. Khalid Al-Anezy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الاستاذ خالد العنزي\n\nطبعا ماعنده الا سكشن واحد واتوقع عشانه يحضر الماجستير\n\nنزلت عنده ماث 101 في ترم 102 و ماث 102 في ترم 111\n\nالتحضير : يومي وماينسى يحضر … اول مايبدأ الوقت يحضرك ويبدأ يشرح … مايتأخر عن الشرح ونادرا يغيب ولو حضرت في نص الكلاس مايقولك شيء لكن الترم هذا صار يحط ليت\n\nالشرح : من نوت عنده وفيه اسئلة مياجر وماخذها من الكتاب ويحط ارقامها … صوته عالي ماشاء الله ومستحيل تنام عنده … لو مافهمت شيء لو من 001 ماعنده مشكلة يوقف الشرح ويعيده لك الين تفهم … شرحه رائع جدا ولغته بسيطة و حلوة ولو سألته بالعربي يجاوب عليك لكن الشرح كله بالانقلش … بإختصار ملك في الشرح\n\nالكويزات : تكون 5 كويزات واحد منها بونص … بالاضافه الى انه يعطي هوم كويز في الاجازة الي بنص الترم وعادة يكون سهل ومجرد اسئلة بسيطة عشان ماتنسى المنهج … كويزاته يعطيك كلاس كامل او 35 دقيقه تقريبا ولو انت مذاكر تجيب فل مارك بالراحه\n\nالمياجر : تصحيحه على السلوشن لا يزيدك ولا ينقصك\n\nاضافات : عنده هوموركات اضافية بالاسبوع او الاسبوعين مرة يكتب سؤال عالسبورة ويطلب منك تحلها وتجيبه الكلاس الي بعده … طبعا الهومورك ذا مهم جدا في الكلاس وورك … بالنسبة للكلاس وورك كريييييييم ويعطيك اكثر من حقك بكثير … اهم شيء يركز عليه الغيابات والبونص هومورك … برضوا يطلب منك تحل اولد اكزام في نهاية الترم ويعطيك بونص عليه … يحب الي يجيه الاوفس اور ويستقبلك بكل رحابة وماتمشي من عنده الا وانت فاهم … قبل الفاينلات يحدد اوفس اور في وقت الاجازة تقدر تجيه او ترسله على الويب سيتي ويرسلك الحل على طول\n\nفيه حركة سواها لنا الترم هذا … الهومورك تقدر تسلمه متأخر بس يصححه لك من 8 … الترم ذا ماسلمت هوموركاتي الا في اخر اسبوع وعطاني درجة مرررررررررة حلوة\n\nالتقييم النهائي a+ ولو تشوف سكشنه مناسب نزل عنده وانت مغمض … الترم ذا غيرت جدولي كامل عشان انزل عنده\n\nفي الجامعة درست عند 6 مدرسين ماث والعنزي كان افضلهم بلا منازع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p961114-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-anezy/83632/29", "user": "jarrash", "ts": 1325952703000, "tid": 83632, "pn": 29}}]}', 1325952703000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4656-math101', 'stk-user4656', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83633", "n": "أ. أبالارا تيجاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا ً هذا المدرس أحد طلاب الماستر\n\nأنا كنت عنده math 101 ريسيتيشين\n\nالتحضير : يحضر آخر الكلاس , يعني ممكن تتأخر لكن أحيانا ً يخلص بدري انتبه !\nطريقة الشرح : ريسيتيشين , يعني حل مسائل ولكن هذا المدرس مبدع بحق .\nالكويزات :مافيه .\nالمياجر:كومن.\nالفاينلات :كومن.\nالقريد النهائي:A\nالصوت: وسط\nإضافات :هذا المدرس إذا جاك فنعمة يحل المسائل بأكثر من طريقة وهذا في الحقيقة جمال الرياضيات\nوبعدين فاهم لدرجة كبيرة , ويعجبني فيه سرعة البداهه , ممكن تسأله سؤال ما يقعد يفكرفيه وقت طويل\nمايمديك تخلص السؤال إلا وهو مجاوب .\nالحلو مايكتمل للأسف عنده مشكلة في اللهجة , الأخ أفريقي و يادوب تفهم اللي يقوله\nلكن مع الوقت إن شاء الله تفهم عليه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p543966-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/83633/2", "user": "user4656", "ts": 1266243446000, "tid": 83633, "pn": 2}}]}', 1266243446000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amazj-math101', 'stk-amazj', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83634", "n": "Dr. Khalid Adarbeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أ.خالد عداربه - اردني الجنسيه >> توقعاتي , انسان قمه في الأخلاق ويراعي ظروف الطلاب …\n\n- يحضر الماستر عندنا .\n- يدرس ماث 101 .\n- الشرح : اعطيه عشان ما اظلمه ولا … اعطيه 60-70 % بس يا ليت يعطينا شوي اسأله جامده (high level Qs\n- التحضير : يقول بحضر بس الظاهر يتناسا .\n- الكوزات : جيده تبين الطالب الفاهم من المو فاهم\n- النوت : جيد مرتفع بس في بعض الاخطاء او انا ناقل خطأ 🙂\n\n-", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p731264-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-adarbeh/83634/8", "user": "AMAZJ", "ts": 1288790625000, "tid": 83634, "pn": 8}}]}', 1288790625000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_ali-math101', 'stk-abo_ali', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83634", "n": "Dr. Khalid Adarbeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 111\nmath101\n\nالتحضير :\nقليل جدا يحضر -اذا شاف الكلاس فاضي\n\nطريقة الشرح :\nيشرح على السبوره ويحاول يشرح لكن من وجهة نظري انه مع نفسه\n\nالكويزات :\nسهله\n\nالمياجر:\nكومن لكن تصحيحه جدا جدا جدا جدا متعاون\nتخيلو يا عيال كتبت 3 خطوات في سوال عطاني عليها 7/10 which is so freaking good\n\nالفاينلات :\nكومن\n\nالقريد النهائي: b+\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور قريب للطالب\nجدا متفاهم لكن مع الاسف شرحه اشوف انه مع نفسه\nلكن بيكرك في الكلاس ورك والميجر الريتن\nغيرها مع نفسه\n\nيعطيك العافيه يا عداربه 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047398-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-adarbeh/83634/13", "user": "Abo_Ali", "ts": 1338285033000, "tid": 83634, "pn": 13}}]}', 1338285033000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hax_1-math101', 'stk-hax_1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m83634", "n": "Dr. Khalid Adarbeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ايه يا خالد عداربه ماث 101\n\nافضل خيار لك اذا كنت ما تعتمد على شرح المدرس\n\nكلاس وورك دف بشكل كويس\n\nميجر الريتين تصحيح ولا بالخيال\n\nلكن من ناحية الشرح مع نفسه الى اخر درجة حتى هو نفسه اذا بغى يشرح تحسه يقول ادري ما راح تاصلكم المعلومة\n\nبس افضل خيار لك اذا كنت self studier", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1155331-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-adarbeh/83634/15", "user": "hax_1", "ts": 1357371240000, "tid": 83634, "pn": 15}}]}', 1357371240000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5771-math101', 'stk-user5771', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "احم احم\n\nيالله حيهم\n\nلاول مره اشارك في تقييم وتقييمي لاول كورس آخذه في الجبل 😆\n\nالتحضير :\n\nنهاية الكلاس ومايدقق في التأخير واذا جيته بعذر حتى لو شفوي عن الغياب يمكن يمشيك\n\nطريقة الشرح :\n\nشرحه للاكسامبل الي في الكاتب واغلب الي يكتبه basic\nوطريقته انه يكتب للكلاس الاول ومايمسح السبوره ويشرحلك على الي كتبه\nواحيانا يمسح اشياء بسيطه ويرجع يكتبها\nوفي نهاية بعض الكلاسات يعطيك سوال والا سوالين من اسئلة الهوموورك الي شويه حلوه ويقول حلوها\n\nمشكلة الدكتور انه مايعطيك شي صعب يعني كل الي يشرحه سهل\nولازم انك تذاكر بنفسك وتعتمد على نفسك بحل المسائل والبحث عنها\nوتروح تسأله عادي عنده ويساعدك قد مايقدر\n\nالكويزات :\n\nانا طبعا ماخذ صيفي وهذا الظاهر اول ترم له وحتى لغته من جنبها بس تطورت مع الوقت\nوطريقته تقريبا كل اسبوع كويز\nسؤالين فقط عليها 10 درجات وتصحيحه جاف نوعا ما يعني يا صح ياغلط\nواذا كانت اغلب خطواتك صح يادوب يعطيك درجه زياده من 5\n\nالمياجر:\n\nكومن بس الميجر الاول written وتصحيحه جيد ومو جيد يعني مايدف كثير بس مايمديك تلقا عليه مخرج 😎\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nc+\n\nالصوت:\n\nواضح ولغته تطورت صارت كويسه بس تفهم عليه 100%\n\nإضافات :\n\nالدكتور جديد وجدا اخلاق ومتواضع حتى انه يسأل الطلاب ويقلهم وشرايكم فيني وفي طريقة الشرح\n\nبس صراحه اذا ما بتشتغل بنفسك في حل المسائل من الكتاب بتتعب\n\nلان الدكتور النوت حقه نفس الاكسامبل الي في الكتاب\n\nانا اشوف ان 101 ماث فيه مدرسين جدا كويسين مثل المطوع والفراتي والرصاصي …الخ\n\nفاذا بتلقا عندهم فأفضل لك كثير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p672637-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/2", "user": "user5771", "ts": 1280732324000, "tid": 92906, "pn": 2}}]}', 1280732324000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-god_given-math101', 'stk-god_given', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الكورس : (ماث 101 - صيف 123 )\nالتحضير : نهاية الكلاس ( متساهل في التأخير والغيابات )\nطريقة الشرح: نوتة مرتبة, لكنها مبسطة لأبعد الحدود.\nالكويزات: سهلة إلى متوسطة… وغالباً تكون صعبة.\nالمياجر: كومن\nالفاينلات: كومن\nالصوت: جيد جداً\n\nإضافات:\nالدكتور أخلاقه ممتازة , ويمزح مع الطلاب أحياناً, لكن مشكلته إنّه ما يجهزك للمياجر بشكل سليم; نظراً لأنّه يشرح أشياء بسيطة من الكتاب وما يجيب أسئلة أولد إكزام إلا في الـ Revision Class اللّي يكون قبل الميجر بيوم غالباً.\nخلاصة الكلام: إذا بتنزل عنده, فأنا أنصحك تعتمد على الـ Self-study أكثر من الشرح وبإذن الله تجيب قريد عالي.\n\nالقريد النهائي: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1259572-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/10", "user": "God_given", "ts": 1378282200000, "tid": 92906, "pn": 10}}]}', 1378282200000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11273-math101', 'stk-user11273', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 , ترم 172\n\nالتحضير يكون اخر الكلاس و مايهتم كثير لل التأخير\n\nالشرح جداً بسيط و يشرح من امثله الكتاب فقط , واذا خلص الشرح قبل ايام الميجر او الفاينل يحل مع الطلاب اسأله اولد ايكزام\n\nالكويزات متوسطه تميل لل الصعوبه\n\nالصوت : ممتاز\n\nالدكتور عيبه ان يمزح مع الطلاب بشكل مبالغ فيه و ممكن انها بعض الاحيان توصل الى الاستهزاء\nو الدكتور مايرحب ف الطلاب ف الاوفس اور بشكل طيب ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1495625-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/23", "user": "user11273", "ts": 1531442001000, "tid": 92906, "pn": 23}}]}', 1531442001000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-z111-math101', 'stk-z111', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أستاذ محمد كفيني رائع بمعنى الكلمة اخذت عنده math101 ترم 241\nيستخدم سلايدز الخليفي ويحل عالبورد\nشرحه رائع والبعض يشوفه بطيئ لكن بالنسبة لي هذي السرعة المناسبة\nمهما كنت تسهو وماتركز رح تقدر تفهم لانه يهمه جدًا فهم الطالب\nشخصيته مرحة وكلاسه ممتع جدًا مانحس بالوقت\nالتحضير اخر الكلاس ومايحاسب على التأخير ابد لو نجي بعد ثلث ساعه مايقول شي\nيمزح كثير ويطقطق\nاغلب الوقت يتأخر بالكلاس وياخذ حول خمس دقايق زيادة لكن زي ماقلت ماينحس فيها\nواذا طلبتوا منه ريفيو قبل المياجر بيسوي لكم متعاون جدًا ويعرف يختار الاسئلة\nمتعاون بالغيابات بالبدايه كان غيابين مجاني وبعدها زادهم\nالكويزز كانت كلها عالبلاكبورد وسهلة بمستوى المياجر ويحذف اسوأ كويز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539047-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/32", "user": "Z111", "ts": 1738219858407, "tid": 92906, "pn": 32}}]}', 1738219858407, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8219-math101', 'stk-user8219', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست معاه ماث 101 ترم 111 (شااااايب 🤠)\n\nالتحضير\nالتحضير يومي،، وعادي تحضر متاخر 👍\nكان يقولنا الي ما عندو اي غياب له اربعة درجات (من 400) بونص،، وكل غياب تروح نقطة… صدق معانا في ترم (111) بس على كلام الشعب انو ماصدق في ترم (112) عشان الافرج كان عالي 😊\n\nطريقة الشرح\nنوت يكتبها عـ السبورة،، لطيفة وجميلة نوعا ما 🥰\nبس في الترم الي بعدو سار يشرح بالايباد واغلب الشغب كرهوا الطريقة الجديدة 🤪\nعموما،، اخر ماسمعت عنو من واحد درس معاه السنة دي انو بطل يشرح بالايباد والله اعلم\n\nالكويزات\nمتوسطة،، موصعبة ولا سهلة\n\nالصوت\nواضح جدا واللهجة كويسة ❤️\n\nاضافات\nالدكتور حبووووووب وتصحيحو حليوة غالبا 👍،، اذا سالتو وما عرف يقولك ماعرف ويرجع البيت يحاول ويبحث ويرد لك 👍\n\nالقريد النهائي\nB\n\nكويس بس في افضل منو\nيعني لاتزعل اذا نزلت عندو،، بس لاتخليه خيارك الاول :man_playing_handball:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373692-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/38", "user": "user8219", "ts": 1401342022000, "tid": 94260, "pn": 38}}]}', 1401342022000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11635-math101', 'stk-user11635', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 182\n\nالتحضير : على نهاية الكلاس، يحضر بشكل يومي بس اخر السمستر فيه كم يوم ما حضر، يسمح بالتأخير.\nطريقة الشرح : يستعمل نوتات والسبورة ويجاوب على الطلاب، شرحه متوسط مهو سيء انصحه به كـ خيار ثاني.\nالكويزات : متوسطة ليست صعبة، اخذ في النهاية أفضل 5 كوزات من 6، وعطانا 2 بوينت زيادة.\nالمياجر والفاينلات : كومن لكن كانت صعبة في 182.\nالصوت: واضح\nالدكتور طيب واخلاق وعادي تسأله نهاية الكلاس او في المحاضرة او في الاوفس اور ويساعدك.\nوما يتكلم على الجوال في الكلاس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509300-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/56", "user": "user11635", "ts": 1556884697000, "tid": 94260, "pn": 56}}]}', 1556884697000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-math101', 'stk-abdullatif1994', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 … سمستر 113\nالتحضير : دايم … اخر الكلاس\nطريقة الشرح : نوت … وشرحه جيد جدا … لان القواعد الي انت حافظها يغيرها … يحط قواعد من راسه … بس انا ما تبعته\nالكويزات : …\nالمياجر: …\nالفاينلات : …\nالقريد النهائي: بفضل الله اخذت a\nالصوت: واضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1074890-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/3", "user": "Abdullatif1994", "ts": 1343892706000, "tid": 118579, "pn": 3}}, {"id": "stk-dr-m94443", "n": "Dr. Nadeem Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 … سمستر 113\nالتحضير : ورقة تمر على الطلاب ومثل كلام اخوي جنتلمان … حضر الي تبي … ومايهتم بالحضور … لو حاضر 1 … ومحضرين 30 عادي\nطريقة الشرح :سيئة جدا … لدرجة الدافور ينام عنده\nالكويزات : صعبه … يشرح شي … والكويز شي غير\nالمياجر: كان الكوردنيتر لماث 101 … سمستر 113 … المياجر صللللللخ … صللللللخ لدرجة الميجر الثاني الافرج وصل 50\nالفاينلات : صللللللخ … اول سنه يوصل الa+ الى 316\nالقريد النهائي: A بحمد من الله\nالصوت: يجيييب النووووووووم …\nإضافات :\n…\n\n^^\nقسم بالله صادق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1074891-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadeem-malik/94443/14", "user": "Abdullatif1994", "ts": 1343893111000, "tid": 94443, "pn": 14}}]}', 1343892706000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kh_sh-math101', 'stk-kh_sh', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m94443", "n": "Dr. Nadeem Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101+Math102\nTerm113+Term121\nالتحضير:\nالتحضير محد حولك خلصت معاه كورسين وكنت أروح له الأوفيس أحيان ولحد ماعرف اسمي وكل كورس سحبت مالا يقل على 7 كلاسات وكل الشباب أخذنا درجة الحضور كاملة\nالشرح: بصراحة ماينفع بحاجه\nلكن إذا الله قدر عليك ونزلت عنده خذ معاك الكتاب وركز على تعليقاته على على الأمثلة وحاول تكتب ملاحظات جنب كل مثال كيف تم حله راح يوفر عليك وقت كثير في السلف ستدي\nالكويزات:\nفي الصيف في ماث 101 عطانا كويزين في الكلاس و 3 كوزات تيك هوم\nفي ماث 102 ترم 121 عطانا 4 كويزات في الكلاس وكويز واحد تيك هوم\nالزبده الكويزات يجيها من أسئلة الكتاب الأخيره في كل سكشن\nبالعربي حل الهومورك وشف سلايدات فيرق أو أسئلة أبو سياف مقسمة حسب السكاشن حل كم سؤال منها للكويز ومنها للميجر\n\nالمياجر والفاينلات:\nكومون\nوتصحيحه عادي لا يخسف ولا يزود كثير\nإضافات: الدكتور تعامله جدا راقي ويراعي ظروفك “أحيانا” ممكن يأجلك كويز حتى بدون عذر رسمي وخصوصا إن الجامعة صارت شديده في الأعذار.\nوالهوموركات سهالات سلم متى مابغيت\nالزبدة: إذا ماحصلت إلا هو, فالكورس حيكون سلف ستدي فعليك وقتها بـ patrickjmt واليوتيوب\n\nالقريد النهائي: D- كشرح\n\nبالتوفيق شباب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1208255-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadeem-malik/94443/18", "user": "kh_sh", "ts": 1365550918000, "tid": 94443, "pn": 18}}]}', 1365550918000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman513-math101', 'stk-abdulrahman513', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "هذا ردي السابق كان في بداية الترم(121)\n\nانا نزلت عنده Math 101\nالرجل يا جماعة الخير جدا ممتاز , بعد ما تتقفل ساكشن أفضل المدرسين نزلوا عند الأستاذ الخلوق المتواضع محمد الغرابلي\n\nالشرح ممتاز من النوت يحل أسئلة كثير فاهم المادة … عطانا ثلاث كويزات متوسطة الصعوبة و أخذ أفضل اثنين … التحضير ما يحضر الا قليل خصوصا اذا شاف الفصل بدا يفضى … في الكلاس وورك عطى الأغلب 39 من 40 ان ما كانوا الجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165770-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/9", "user": "abdulrahman513", "ts": 1358547719000, "tid": 118561, "pn": 9}}]}', 1358547719000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-engineer212-math101', 'stk-engineer212', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 131\n\nالتحضير : غالبا يحضر وينادي بالسيريال نمبر وأحيانا ما يحضر\nطريقة الشرح : من نوتس يكتبها بيده “ومتعوووب عليها الصراحة” يحطها عند المكتبة مبنى 8 … يحل مسائل من الكتاب كثيير ويحل أسئلة من الورق عشان يوضحها كويس\nالكويزات : سهلة لو مذاكر …\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: a+++++++++++\nالصوت: واضح … لغته واضحة وينفهم عليه بس مكسرة شوي… مااشوفها مشكلة أبدا\nإضافات : صغير في السن أتوقع انه ماستر بس الرجاااال فاااااهم جدااا ما شاء الله عليه وورقه متعووب علييييه كل اللي عليك تحضر وتسمع وبعدين تاخد النوتس من المكتبة … النوتس حقته تغنيك عن الكتاب فعلا! اناا ما بدأت أذاكر ماث غير قبل المياجر باسبوع بالكثير والحمد لله درجاتي طيبة … للأسف ماااا نزل 102 😦\n\nأنصح الجميييع به وأشكره جدا على أخلاااااقه العالية مع الطلاب…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1295627-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/10", "user": "Engineer212", "ts": 1385571113000, "tid": 118561, "pn": 10}}]}', 1385571113000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dyaa94-math101', 'stk-dyaa94', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101-131\nاول شي بتكلم عن اهم صفه في هالمدرس…الأخلاااااااااااااااااااااااااق ياخي يحرجك بااخلاقه…محترم لأبعد الحدود\nكنت محتاج ثلاث درجات عشان القريد اللي بعده وعطاني اياها بدون ما اكلمه + هذا غير اللي زودني في الكلاس ورك…\nبالنسبه لشرحه…شرح جيد جدا انت بتحضر الكلاس كل يوم وبتطلع فاهم 100% والشرح انجليزي 100/100 مع انه فلسطيني او اردني ((مو متأكد)) و مايتكلم عربي الا ماندر…يبدأ بالكونسبت بعدين يعطيك امثله تدريجيا من الاسهل الى الاصعب ويعطيك امثله اولد اقزام بعد ومثل ماقالوا الشباب مايحتاج تكتب وتتشتت عن الدرس بس تعال واستريج وانتبه للدرس ونهاية كل سكشن راح يحط النوتس في المكتبه العامه\nبالنسبة للنوتس مرتبة وبخط واااضح.\nبالنسبه للي يقول يجيب النوم …ماعمري حسيت انه ممل بالعكس الرجل صوته عالي والكل يسمعه\nنززززززل عنده وانت مغمض\nاتمنى اني افدت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1314716-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/11", "user": "Dyaa94", "ts": 1388839131000, "tid": 118561, "pn": 11}}]}', 1388839131000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11942-math101', 'stk-user11942', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term181-math101\n\nالتحضير: ما أذكر إنه حضر إلا يمكن مرة أو مرتين.\n\nطريقة الشرح : عادية\n\nالكويزات: جداً جداً سهلة لكن احذر من شيء. كنت أجيب فيها فل مارك وأفكر إني مدرك المادة ولكن درجتي في أول ميجر كانت دون المأمول وعرفت إن كويزاته مش معيار لاستيعاب المادة من عدمها.\n\nالمياجر والفاينلات: كومن\n\nالصوت : خافت تحتاج تكون في المقدمة\n\nإضافات: الدكتور مايدقق على إلي يفتح جواله وأخلاقه عالية حتى إنه كذا مرة يشوفني ماسك جوالي وإذا سألته يجاوب بعكس كثير من الدكاترة الي مايعطون وجه للمنشغلين بجوالاتهم. مرة طرد طالب بأسلوب هادىء وابتسامة لدرجة حنا ما فهمنا ولا حتى الطالب فهم مقصد الدكتور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524199-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/32", "user": "user11942", "ts": 1595705710000, "tid": 118563, "pn": 32}}]}', 1595705710000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupmy-axis-math101', 'stk-kfupmy-axis', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118565", "n": "Dr. Abdulilah Kadri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101-TERM161\n\nالتحضير :ورقة تمر على الطلاب، غالبا ما يحضر إلا إذا شاف الحضور قليل بس أول الأيام كان متشدد في التحضير\nطريقة الشرح :هنا الكلاااااااااااام…\nالصراحة أنا ما سجلت عضوية في المنتدى إلا لهذا السبب…\nلأني لما شفت تقييم الطلاب إنخدعت وأكلتها على وجهي…\nخلينا نكون صريحين…\nالدكتور عبدالإله(طبعا هو رجل أحترمه جدا ) ماهو بذاك الزود في الشرح :no_entry_sign:\nيبدا يشرح الكونسبت من ورقة معه تسجلون منها نوتاتكم -ويعطيكم إياها بعدين بس تتأخر شوي-و ثم يبدأ بحل تمارين تتدرج في الصعوبة مع المناقشة مع الطلاب\n\nمرات تصيب ويوضح كلامه 🤴\nومرات تخيب ويخليك ضايع أكثر مما إنت عليه 🤪\n\nبعدين النوتات هذي على الرغم من انها عادية ومالها فائدة كبيرة إلا إن الرجل يذلك قدام باقي الطلاب إذا عرف إنك ما تستعملها\nو هي أغلبها قوانين و كلام كثيييير مع مجموعة تمارين بعضها محلول وبعضها غير محلول\nوفيها كمية حفظ بشكل كبير 😐\nلدرجة إنه يسألك\nWhat is the third theruim in this lesson?\nيعني الدكتور يبغاك تحفظ قوانين مرقمة مما يخليك تتشتت وتضيع مجهودك 😞\n\nأنا رغم إني ما كنت أقرأ نوتته جبت درجة أعلى من باقي الطلاب في المياجر\nأما الطلاب إلي حفظوا نوتته فجابوا أبو العيد ونزلوا الأفرج في الميجر الثاني\nلدرجة إنه جاء بعد الميجر الثاني زعلان جدا و قال أنا ما راح أعطيكم باقي النوتس واعتمدوا على نفسكم في الفينال 😐\n\nالكويزات :متوسطة وتنبهك على الأخطاء الي يمكن تقع فيها في الميجر يعني مفيدة جدا 👍\nوفي نهاية الكورس أخذ أتوقع أفضل أربع كوزات وسوا بونس كويز للي يبغى يزيد درجته 👍\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B\nالصوت:ضعيف شوي بس أكسنت رهيب\nإضافات :\n\n-الرجل واضح أنه مهتم جدا لمصلحة الطلاب ويتعب نفسه علشانهم ويقول متى تبغون الكوزات صوتوا على القروب ومشترك معنا ويجاوب على الإسئلة فيه و يسوي هلب سيشن إضافي ويسوي أوفس أور زيادة بس علشان الطلاب و متواضع جدا يعني بالعربي الرجل يخليك تنحرج من إهتمامه فيك وتعبه معك 😳\n-الرجل بطلللللللللللل في تصحيح المياجر 👍\nيعطيك نقطة على أي شي والله ياجماعة الخير إني كنت متوقع درجة وزودني عليها يمكن 10 درجات زيادة ولذلك تحصل سكشنه من أعلى السكاشن في الميجرالأول 😁\n\nعلى الرغم من الكلام الي قلته من ناحية الشرح لكن يا جماعة والله الرجل هذا له معزة خاصة عندي وأحترمه بقوة :bouquet:\nبس ماهو بذاك الزود من ناحية الشرح وأنا إنزعجت من ترفيع الطلاب له فوق اللازم :sneezing_face:\nلدرجة الآن في MATH102 162 سكشنه من أنزل السكاشن 51 والأفرج العام 58 وكل هذا علشان الي إنخدعوا فيه من ناحية الشرح في هذا المنتدى:(\n-", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1471868-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulilah-kadri/118565/16", "user": "KFUPMY-AXIS", "ts": 1492964933000, "tid": 118565, "pn": 16}}]}', 1492964933000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_legend97-math101', 'stk-the_legend97', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118565", "n": "Dr. Abdulilah Kadri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH102-171\n\nالتحضير : في البداية كان يحضر بداية الكلاس ، بعدين صار يحضر في نص الكلاس (تحضير يومي عدا تقريبا أول أسبوع ما حضر ) وكان بعض الأحيان يفصل على اللي يتأخرون كثير ـ حاول تعطيه خبر عن أسباب تأخرك (أعتقد إنه متفهم جدا ) بس لا تزودها . 😅\n\nطريقة الشرح :\nيكتب في السبورة ويحل مسائل حلوة مرة وفيها أفكار ، ويعطي طرق خنفشارية للحل 👍، مرة نايس تسهل عليك الحل . كنت والله أستمتع في كلاسه ، حتى راكمت الدروس نهاية الترم وكرهت نفسي وكرهت الحضور وكرهت الماث :no_entry_sign:.\n\nالكويزات :\nعطانا 5 كويزات (متوسطة الصعوبة ) وكلها فيها أفكار زي الأولد اقزام ، ذاكر للكويز كويس ( نهاية الترم أخذ أفضل كويز وضربه في 4 وقال هذا الكلاس وورك :popcorn:، يعني لو أخذت في واحد 10 والباقي أصفار تأخذ 40 من 40 . تأجّر فينا الله يسعده يا رب.\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nالدكتور-وعزّة ربي وجلاله- يستاهل A+++++++++++++\n\nالصوت:\nواضح، هو سوري أعتقد ، بس لغته الانجليزية مرة ممتازة ولا يتكلم إلا انجلش ، بس عادي تسأله بالعربي ويرد انجلش 😁\n\nإضافات :\nوالله العظيم الدكتور خوووورافي ، ونوته جبّاااااارة . كانت نصيحتي لأي طالب متعقد من ماث 102 يأخذ نوتة القادري . والله رغم إن درجاتي مو ذاك الزود بس والله ماث 102 مع الدكتور القادري أسهل بكثير من ماث 101 . سجّل عنده وأنت مغمض (أكره الجملة ذي) بس والله القادري مرة خلوق ومحترم وشرِّيح .\nأسعدنا الله وإياه في الدارين.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485427-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulilah-kadri/118565/21", "user": "THE_LEGEND97", "ts": 1514924155000, "tid": 118565, "pn": 21}}]}', 1514924155000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-king_of_net-math101', 'stk-king_of_net', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118567", "n": "Dr. Hamza Hroub", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nورقة يمررها على الطلاب وقليل مايحضر\nوفي أخر السنة ماحاسبنا على الغياب من الأساس\nوالتأخير ماعنده مشكلة فيه ياما دخلت متأخر أحيانا وصلت نص ساعة واكثر بعد\nأصلا الكلاسات الي دخلتها قبله في السمستر يمكن ثلاثة أو أربعة\nوكنت أتأخر بقصد لأنه دكتور لا يستحق بأن تحضر له\n\nطريقة الشرح :\nطريقة مملة جدا يجلس يشرح ساعة في مثال واحد ولا مثالين\nماعنده أساسيات الشرح أبدا أصلا مايستحق يكون مدرس\n\nالكويزات :\nكويزاته صعبه مقارنة بشرحه لأنه شرحه سيء جدا\nوعطانا كويزين الواحد من 15 وهذي الـ 15 يحطها في الـ 60 حقت الكلاس وورك\n\nالمياجر:\ncommon\n\nالفاينلات :\ncommon\n\nالصوت:\nنوعا ما واضح بس يجيب النوم\n\nالقريد النهائي:\nd+\n\nإضافات :\nدكتور من الأخير لا تنزل عنده إلا إذا اضطريت واعتبر المادة self-study\nالدكتور ضايع نوعا ما ، مايجي في مكتبه وقت الـ office hours\nدايما يضيع الأوراق حقت الطلاب مثل الواجبات والكويزات\nوالواجبات يطلب 20 واجب وسلمها أي وقت أول يوم أخر يوم ماتفرق معه\nمع العلم أنا أخذت قريد ممتاز في ماث 101 عنده وعطاني كلاس وورك حلو\nيعني لا يروح بالك إني حاط التقييم هذا عشاني ماخذ قريد سيء في المادة\nوأيضا هو محاضر ، الدكتوراه جاي يحضرها عندنا في الجامعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972473-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hamza-hroub/118567/3", "user": "KinG_OF_NeT", "ts": 1327307004000, "tid": 118567, "pn": 3}}]}', 1327307004000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-domain_of_love-math101', 'stk-domain_of_love', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118568", "n": "Dr. Ali Iftikhar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ماث 101 … الرجل موب فاهم المادة وبس ينقل من النوت مالت الحميدي ,\n\nصوته واضح وإذا عالمعلومة يمكن تصيب معاك وتفهمها , أو ممكن لأن 101 سهل ,\n\nيدف بالكلاس ورك إذا ضبطت معاه وكوزاته من متوسطة إلى صعبة …\n\nممكن مايدقق بالتصحيح للمياجر وبإمكانه يزيدك بس بخوف وحذر ,\n\nطبعا موب شريح , بس الرجل حق قريدات ,\n\nتحياتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972791-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-iftikhar/118568/7", "user": "Domain_Of_Love", "ts": 1327354971000, "tid": 118568, "pn": 7}}]}', 1327354971000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_doctor-math101', 'stk-the_doctor', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118568", "n": "Dr. Ali Iftikhar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 101 سمستر 111\nفي البداية قلت هذا المدرس من جنبها ولايعرف يشرح ودايما مرتبك بس بنص الفصل عرفت انه الماتيريال سهل\nوالمدرس برضوا كويس صراحة المدرس يدف في الكلاس ورك كويزاته مره سهله ولاكنت اذاكر فيها ومع ذلك كنت اجيب فيها درجات حلوة مع اني افرج student الهوموركات لو من قبل سنة ياخذها ماعنده مشاكل\nالتحضير لو تجي قبل ماينتهي الكلاس ب5 دقايق مايقول شي\nخلاصة الكلام نزل عنده ولاتخاف لانه حتى اذا مايعرف يشرح عند البعض الماتيريال مره سهل (ماث101)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1028125-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-iftikhar/118568/12", "user": "the_doctor", "ts": 1335304118000, "tid": 118568, "pn": 12}}]}', 1335304118000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8654-math101', 'stk-user8654', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118568", "n": "Dr. Ali Iftikhar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : بآخر الكلاس ، وما يهتم للتأخير\n\nطريقة الشرح : درسني هالترم ( 121 ) ماث 101 ، عادة يكون ماسك الكتاب ويشرح وينقل الأمثلة والتمارين منه ، ميزته انه منظم في الشرح لكنه بطيء ويبدأ بتوضيح الكونسبت ثم الأمثلة وأحيانا يعطي تمرين للطلاب\n\nالكويزات : طويلة و بعض أسئلها ثقيلة وتحتاج وقت مب هين\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nإضافات :\n\n1- أحد عيوبه إنه بطيء ، فممكن تسأله عن نقطة تلاقيه يطالع وقت طويل بالسبورة تحسه مو فاهم ، لكنه فاهم جدا بس كذا طبيعته .\n\n2- يرحب جدا بأي سؤال .\n\n3- جدي ونادرا جدا ما يخرج عن الحصة ,\n\n4- كويزاته عادة يوم قبل الميجر ، اذا حليتها تمام أضمن لك فوق 17 بالميجر .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1138183-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-iftikhar/118568/14", "user": "user8654", "ts": 1355238785000, "tid": 118568, "pn": 14}}]}', 1355238785000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-voldy-math101', 'stk-voldy', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118568", "n": "Dr. Ali Iftikhar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - Term111\n\nالتحضير : وسط الكلاس ينادي بالأسماء ويحضرك حتى لو متأخر وكثير مرات ينسى ورقة التحضير\nطريقة الشرح : بأتكلم عن نفسي شرحه كان بالنسبة لي كافي ووافي كان يشرح من نوتة الحميدي لكن معدلها بأسلوبه وتمارين أكثر دايم يحل مسائل من أولد إقزام. والله يشهد علي إنه ما فيه مرة سأله طالب أي سؤال إلا جاوب عليه\nالكويزات : سهلة وكلها من أولد إقزام وأخر اثنين كان Take home quiz\nالمياجر:كومن وتصحيح مرة حلو ويعطيك أكثر من حقك\nالفاينلات :كومن\nالقريد النهائي:A\nالصوت: الصوت واضح لكن كلامه أحيانا مكسرة\nإضافات : المدرس مرة محترم لكن شكله يخاف من الطلاب و أنا هذا رأيي فيه بعدما درست عند 3 مدرسين مختلفين وبالنسبة لي هو ثاني أحسن واحد درسني\nما أدري أنا عن الطلاب إلي أخذوا معه قبلي أو بعدي لكن أتكلم عن سكشني\nالطلاب إلي في الكلاس غير محترمين على الاطلاق تلقاهم يجون على أخر ثلث او ربع ساعة ولما يجون يقعدون يسولفون أو يسألون على شيء شرحه من بداية الكلاس وكل واحد تلقاه حريص ان هو يفهم لحاله وكثير مرات تلقى واحد قطع الكلاس على شيء قد سبق وأن شرحه ويروح نص الكلاس وهو يشرحه له وكثير شباب شايفين نفسهم عباقرة يجاوبون على سؤال غلط ويوريهم الحل الصحيح لكن مصرين انه هو غلط وهم صح مع انه أثبتهم غلط، وزيادة كثير شباب حاطين في راسهم انه هو ما يعرف يشرح وما ينتبهون للشرح وبعدين يقلون ما يعرف يشرح، هذا مو كل الناس في كلاس زي كذا فيه ناس كانت تركز لكن ما تفهم معاه لكن أنا أختلف معهم ولو كان نزل أي كورس ثاني والله كان أخذت معاه بدون تفكير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318743-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-iftikhar/118568/17", "user": "Voldy", "ts": 1389614529000, "tid": 118568, "pn": 17}}]}', 1389614529000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkt.abdullah-math101', 'stk-mkt.abdullah', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118571", "n": "Dr. Walid Sharabati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - term 112\n\nالتحضير : ورقة تمر ع الطلاب … وفي بداية التيرم كان متساهل … لكن في اخر اسبوعين صار يتأكد ويشيك ع الاسامي\n\nطريقة الشرح : يشرح امثلة على السبورة\nالكويزات : اعطانا اربع كويزات و مستواها متوسط\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B\nالصوت: واضح والاكسنت مفهوم\nإضافات :\n\nمدرس طيب واخلاقه تمام … بس مشكلته شرحه لك عليه حبتين\n\nوالطلاب يستغلون طيبته شوي … يعني الواجب والكويز كان يتأجل ثلاث او اربع مرات 😦\n\nبالنسبة للتصحيح … يعطيك حقك بالتمام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049238-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/walid-sharabati/118571/6", "user": "MKT.Abdullah", "ts": 1338608933000, "tid": 118571, "pn": 6}}]}', 1338608933000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-math101', 'stk-ad0rs', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده رسايتيشن ماث 101 سمستر 121\nالتحضير :\nاخر الكلاس واحيانا ما يحضر\nطريقة الشرح :\nمو قد كذا حاول تركز معه لكن اذا سألته يضيع وكمان تحس انه متوتر\nالقريد النهائي:\nc\nالصوت:\nواضح\nإضافات :\nفيه عيب واحد انه جدا متساهل مع الطلاب لدرجة انه بعض الطلاب يتكلموا معه كأنه خويهم واحيانا نبرة اصواتهم ما تكون محترمة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1167470-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/2", "user": "ad0rs", "ts": 1358821617000, "tid": 118572, "pn": 2}}]}', 1358821617000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu-smrah223-math101', 'stk-abu-smrah223', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nالسلام عليكم و رحمة الله و بركاته\n\nدرست عنده ريستيشن ماث 101 الترم الصيفي 123 و طبعاً كان شرحه مرررره رائع\n\nكنا ما نفهم على مدرس اللكتشر و إذا جينا عنده فهمنا يعني ما شاء الله عليه لكني دردبت هذاك السمستر\n\nو أنا الحين أخذ عنده ماث 101 لكتشر الترم 131 و لكن هذه الأيام الأخيرة صار\n\nيشرح بسرعة فأحيانا ما يمدينا نلحق عليه بالشرح\n\nالتحضير :\n\nيحضر شبه يوميا إذا ما نسي التحضير\n\nطريقة الشرح :\n\nأل ( رائعة ) بالنسبة لي و لو توفر لي ماث 102 عنده بأخذ إن شاء الله\n\nالكويزات :\n\nكويزاته كلها أولد إقزامز عشان تتدرب قبل الاختبار و ثانيا يحب يساعد الطلاب بالدرجات بس بعد يبغى الطلاب يكونون حريصين\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+++\n\nالصوت:\n\nواضح جدا و يشرح عربي أحيانا\n\nإضافات :\n\nمدرس أخلاق و محترم و يحب اللي يجيه في الأوفيس أور + تصحيحه في المياجر كويس و يساعد\n\n.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1305899-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/4", "user": "abu-smrah223", "ts": 1387201529000, "tid": 118572, "pn": 4}}]}', 1387201529000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8643-math101', 'stk-user8643', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101-131\n\nالتحضير : يمرر ورقة بآخر عشر دقايق ويمديك تحضر نفسك ولو جيت بآخر دقيقة + أنا غبت عنده تقريبا 14 مرة وما حسب إلا 7 🙂\nطريقة الشرح : يشرح على سلايدات د. فيرق\nالكويزات : مرات سهلة ومرات صعبة, المشكلة أنها قليلة يعني إذا خيست بواحد راحت عليك درجة كبيرة في الكلاس وورك\nصوته واضح جدا\nما يقول شيء للي يطلعون جوالاتهم ولّا ينامون\n\nالسمستر هذا أول سمستر له كمدرس لكتشر بسبب نقص المدرسين (كان قبل للريستايشن فقط) فتشوف أنه مرات يخبص ويخطي بالشرح\nعموما يبقى خيار جيد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1311238-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/5", "user": "user8643", "ts": 1388325723000, "tid": 118572, "pn": 5}}]}', 1388325723000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iiahmadx-math101', 'stk-iiahmadx', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور/ عادل مهدي\nT211 - Math101\n\nالتحضير\n:\nنهاية الكلاس بالسيريال نمبر ومرن من ناحية التأخر ولكن بيسألك بكل واقعية عن السبب وللأمانة انصحك ما تكذب لانه يكره الكذب لأبعد حد…\n\nطريقة الشرح\n:\nالدكتور اتعب وانا اقول انه شرييييييييح!! يخليك تخلص الكلاس وترجع بيتك تحل كل الأولد اقزامز بكل سهولة!! حرفيا صدمني من ناحية التدريس, طبعاً يشرح من الOneNote وضايفنا كلنا عشان نشوف نوتاته بعدين, وبعد ما يخلص شرح الكونسبت يقعد يحل اسئلة لين نهاية الكلاس بأفكار متنوعه.\n\nالكويزات\n:\nصعبه للأمانة ولكن صعوبتها ساعدتني مره في تخطي الكورس بقريد جميل, طبعا حسب افرج الكويزات السابقة يحدد صعوبة الكويز القادم, تصحيحه كان مو مره بالبداية بعدين صار يصحح بكل ذمة وضمير ويعطي كل شخص حقه.\n\nالفاينل والمياجر\n:\nCommon - كان يعطينا هلب سشنز بالويك اند لمن يرغب قبل المياجر والفاينلز, ما كان يقصر ابداً وأي سؤال عندك ارسله له وبيحله بالتفصيل الممل.\n\nالصوت\n: ممتاز وواضح ولكن يُفضل تجلس قدام.\nالقريد النهائي: +A\n\nإضافات :\nنزل عنده اذا لقيته على طوووووول!! بالذات اذا انت شخص تبي ترتاح لا اخذت كورسات التفاضل والتكامل الثانية, وطبعاً ما احكيلكم عن اسلوبه العسل ونكته الحلوه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535187-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/15", "user": "IIAhmaDx", "ts": 1661460808000, "tid": 118572, "pn": 15}}]}', 1661460808000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-math101', 'stk-user9305', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الاستاذ محمد ترم 131 ماث 101\n\nفي الشرح ممتاز لكن يعيبه انه يحرق ام السبورة يمسح ويكتب فصعب تلحق معه , صرت اخذ صور للسبورة واذا رجعت انقلها في دفتري , تحضيره شديد جداً مع دقات الساعة يحضر واذا خلص فيه 4-6 دقائق رينج للتأخر ثم بعدها غياب , لكن امانة اخلاق عالية جدا جدا ويهتم بشدة بمدى فهم الطلاب للأسئلة وإذا سألته وتفاعلت معه في الكلاس يعزك ويقدرك بشكل كبيير جداً ومتواجد في الساعات المكتبية ومتعاون فيها بشكل كبير… قبل ميجر 2 حط ساعة مكتبية له يوم السبت العصر لمساعدة الطلاب ❤️\n\nتقييمي له : A\n\n+ نزلت معه الترم الجاي 102 ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1295458-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/7", "user": "user9305", "ts": 1385551645000, "tid": 118577, "pn": 7}}]}', 1385551645000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khalody18-math101', 'stk-khalody18', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 101 , ترم 132\n\nالتحضير : سيء … يدخل الكلاس قبل الوقت بخمس دقائق تقريبا ويكتب ع الصبورة لما يدخل وقت الكلاس بعدين يحظر بعد دخول الوقت بكم دقيقة … لا يسمح بالتأخير ( أي تأخير يعتبر غياب حتى لو دخلت بعد التحظير بدقيقة )\n\nالشرح : جداا جدا ممتاز 👍 والنوت حقته جدا ممتازة وفيها تمارين كثيرة .\nلكن يعيبه إنه سريع بالكتابه والشرح فكثير طلاب يصورون النوت ولا يكتبون .\nويميزه أيضا انه يحب أسئلة الطلاب ويتقبلها بأفضل صورة … ومستحيل يعدي نقطة وهو حاس ان الطلاب مو فاهمينها كويس .\n\nالتصحيح : جدا دقيق ولا يدف\n\nالأوفيس : مرة طيب الدكتور ويتفهم لو رحت له وعطيته عذر مو رسمي يمشيك عادي\n+ لو حس انك تعبان الكلاس يخليك تطلع من الكلاس بدون ما يغيبك .\n\nالكويزات :\nكان يعطينا كل يوم إثنين كويز … غالبا ما تكون صعبه كثير …\n\nالدكتور مرة طيب وفاهم المادة بشكل خرافي …\n\nأعطيه B\n\n----\nنصيحتي :\n* اذا انت طالب تتأخر كثير على الكلاسات لا تنزل عنده لأنها بتنحسب غيابات .\n* اذا انت طالب آفرج ومحتاج دف بالكويزات وكذا لا تنزل عنده لان تصحيحه دقيق جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1356450-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/11", "user": "Khalody18", "ts": 1398257597000, "tid": 118577, "pn": 11}}]}', 1398257597000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silver2012-math101', 'stk-silver2012', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر 132 , المادة ماث 101\nالتحضير : بعد ثانية من بداية الكلاس يبدأ التحضير واذا خلص يشيك اللي مابعد جاؤوا للكلاس والي جاء منهم يحطه ليت . بعد كذا تجي يحطك غايب , يعني بعد ثلاث دقايق ليت اعتبر نفسك غايب\n\nطريقة الشرح : يجي قبل الكلاس ب 7 دقايق ويكتب الدرس على السبورة واول مايبدا الكلاس يحضر بسرعة ويبدأ شرح , يبدأ شرح ويسحب على الكونسبت على طول يحل مسائل اعتبرها انا useless لانك منت فاهم الكونسبت وهو الاساس بالماث , حتى في حله للمسائل يحلها بسرعة عاليه جدا لدرجة كثير من الطلاب مايفهم معاه , بعد 10 دقايق من بداية الكلاس تلاقي نفسك بعتها وفهيت لانه سبق عقلك وماعاد عندك قدرة تلحق الشرح معاه لانه يشرح بسرعة ويحل مسائل بسرعة عالية جدا ولايعطيها حقها من الشرح , صحيح انه يجاوب على الاسئلة ولكن كثير من طلابه يعانون مشاكل بالكونسبت , وهو في نظر الكثير من الطلاب كويس لانه ناسبهم يمكن قدرتهم على الفهم سريعة ماشاء الله , خطه سيء وصغير نوعا ما واحيانا اذا سألته عن شيء ماعرفت تقراه كويس بسبب سوء الخط رح يقولك تعال جيب كرسيك لاتجلس قدام , ولاتضيع لي وقت الكلاس باسئلة زي كذا , وغالبا اذا سألته سؤال يقولك this is math 001 انتم عندكم مشكلة مع الاوريا مش مع الكالكلس\nالكويزات : صعبة غالبا وتتكون من سؤالين الى ثلاثة , يبي لك تحل اولد اكزام عشان تقدر تجيب درجات عالية بالكوزات … الكوز عادة كل اسبوعين كوز , ينزل حلول الكوزات مباشرة على البلاك بورد ورح تكون نقطه حلوة للي بيعرف كيف يستفيد من هالشي , تصحيحه دقيق جدا\nالمياجر: من القسم : وتصحيحة للمياجر الرتن يعتبر دقيق جدا\nالفاينلات : من القسم\nالقريد النهائي: b\nالصوت:واضح جدا وعالي , بس الانجليزي مكسرة وضعيفة وعنده اخطاء كبيرة بالقرامر ويكررها دائما وابدا\nإضافات :\n_المدرس سمعته طيبه بين الطلاب بأن شرحه ممتاز ولكن بالنسبة لي انا لم يناسبني وقد يناسب غيري لمن يستطيع التقاط المعلومة بسرعة\n_اذا كنت من النوع الدجة فر منه فرارك من الاسد , مايدف بالقريدات ابدا .\n_بنهاية السمستر قال لحد يجيني المكتب يقول زودني الا اذا فيه اخطاء في تصحيح الكوزات يمكن اقدر ازيده …\n_يستغل وقت الكلاس من اول دقيقة لاخر دقيقة\n_نهاية السمستر نقص غيابين من ارصده الغيابات لكل طالب لانه اذا جيت الكلاس بعد دقيقتين اعتبر نفسك غايب .\n_ بعض الاحيان خلال تقدمنا بالسمستر من سرعته كنا سابقين تقسيم السيلبس للدروس باسبوعين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373435-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/13", "user": "silver2012", "ts": 1401296721000, "tid": 118577, "pn": 13}}]}', 1401296721000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-raed1997-math101', 'stk-raed1997', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 Term 161\nالتحضير: تحضير بداية الكلاس وبالدقيقة ، غالبا اذا دخلت الكلاس وخلص محضر يغيبك عن المحاضرة\nطريقة الشرح: يكتب على السبورة ، نوتاته حلوة ومفيدة إذا بتكتب وراه ، يشرح الكونسيبت ويحل أمثلة ، شرحه ممتاز بس يعيبه سرعته ، وماعنده مشكلة أنك تسأله بالعكس يفرح\nالكويزات: ست كويزات من متوسطة إلى صعبة ومتعاون مع الطلاب من ناحية اختيار الوقت\nالمياجر : كومن\nالفاينلات : كومن\nالصوت : واضح جدا ، واغلب شرحه بالعربي\nإضافات : يعيبه أخلاقه ورده ع بعض الطلاب يحرج وأحيانا يحرج الطالب وهذا الشي اللي خلاني أندم اسجل عنده ، بالإضافة انه شديد بالغياب ، غالبا يحط أول غيابين فري والباقي يخصم من الكلاس وورك ، احيانا اذا بغيت تتفاهم معه بموضوع ماتوصلون لحل ويزبد كثير ، بالنبة للكلاس وورك أنا ماعجبتني طريقة توزيعه للدرجات رغم إني طلعت بدرجة عالية ، أحس فيها ظلم للطلاب ، البعض ياخذ بونص عالي والبعض وسط وفيه ناس ماتاخذ\nالقريد النهائي: B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466655-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/30", "user": "Raed1997", "ts": 1484917111000, "tid": 118577, "pn": 30}}]}', 1484917111000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-isaleh-math101', 'stk-isaleh', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101-161\n\nالتحضير: قبل ما تبدأ المحاضرة بدقيقة و إذا دخلت بعد التحضير غايب ودقيق جدًا بالوقت\n\nطريقة الشرح: يكتب نوت عالسبورة: يبدأ بالكونسبت ويحل اسألة عليه وأشوف هذي افضل طريقة ممكن تشرح فيها\n\nالكويزات: متوسطة\n\nالمياجر: --\nالفاينلات: --\n\nالقريد النهائي: A\n\nالصوت: واضح\n\nإضافات: دفني بالكلاسوورك دف مب طبيعي. عيبه وللأسف اخلاقه، ترا الكلمه الطيبه ببلاش. عمومًا لو حصل لي بنزل عنده وأنا مغمض…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466687-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/31", "user": "iSaleh", "ts": 1484991887000, "tid": 118577, "pn": 31}}]}', 1484991887000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-r.a-math101', 'stk-r.a', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 Term 161\n\nالتحضير : شديد جدًا بالتحضير بعد دقيقة من بداية الكلاس انت غايب .\n\nطريقة الشرح : شرحه بطل لكن يعيبه السرعة في الشرح ، يكتب نوت عالسبورة ممتازة جدا .\n\nالكويزات : ٦ كويزات في الترم متوسطة مايلة للصعوبة .\n\nالتصحيح : يعطيك حقك بالملّي .\n\nالقريد النهائي: A\n\nالصوت: واضح جدا\n\nإضافات :\n- إذا انت راعي تأخير لا تنزل عنده أبد .\n- عنده حسبة غريبة للكلاس وورك ، لكن اذا عندك غيابين أو أقل راح يرفعك كثيير .\n- بعض الأحيان يحرج الطالب في أشياء مالها داعي .\n- من أفضل المدرسين \" شرحًا \" .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467153-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/32", "user": "R.A", "ts": 1485610725000, "tid": 118577, "pn": 32}}]}', 1485610725000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-meliodas-math101', 'stk-meliodas', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 163\nالتحضير يقرا القائمه مرتين بعده انت غايب\nالشرح ممتاز جدا\nالكوزات افكار اساسيه من الدروس تكون سهله الى متوسطه وافكارها جميله تجهزك الى الميجر\nالصوت واضح جدا ويشطح شوي عربي\nالقريد النهائي A++++++++\nالدكتور محمد الله يحفظه شديد في التحضير لاسباب في مصلحه الطالب ويحب الطالب المهتمين\nما يخليك تطلع من الميجر او الفاينل الا اذا حليت كل الاسئله او انت متاكد اذا خمنت اي سؤال\nيقول الك حاول تحله يبغا تبذل اقصى طاقتك في الكورس اخيرا بفضل الله ثم فضله A+في الكورس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479177-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/35", "user": "Meliodas", "ts": 1503494708000, "tid": 118577, "pn": 35}}]}', 1503494708000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-math101', 'stk-faisal_19', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 171\n\nالتحضير يحضّر في أول دقيقتين تقريباَ, بعد ما يخلص التحضير يعيد الاسماء عشان لو فيه احد جاء متأخر.\nطريقة الشرح : شخص مطنوخ في شرح الأفكار + يغرقك بحل الاسئلة ( نادر تلاقي شخص يجمع بين الثنتين هذي )\nالكويزات : متوسطة الصعوبة.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A++++++\nالصوت: واضح جداً\nإضافات :\n1- مشكلة الكويزات عنده في الوقت وليست الصعوبة.\n2- حريص جداَ على فهم الطالب فإذا شافك مسرّح او على وجهك علامة عدم الفهم ممكن يكلمك بنبرة صوت عالية فلا تفهم انه فاصل عليك,\nبالعكس من حرصه يبي الكل يطلع فاهم, يستقبل اي سؤال.\n3- إذا انت حريص معه ما بتواجه صعوبة في المياجر ان شاء الله لأنه يشرح اغلب الافكار اذا مو كلها.\n4- حاول تكتب كل شي يكتبه على السبورة, طبعاَ ممكن ما تلحق لانه سريع في الشرح فصّور واذا رجعت الغرفة انقله, النوت اللي كتبته\nمعه كان المصدر الوحيد لمذاكرتي, وبعد توفيق الله طلعت بقريد ممتاز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485666-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/36", "user": "Faisal_19", "ts": 1515336731000, "tid": 118577, "pn": 36}}]}', 1515336731000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-feras-mtn-math101', 'stk-feras-mtn', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101-171\nالتحضير :\nجدددا شدييييد وكان للأسف اول كلاس ليا في دوامي فكان مسببلي أزمة فحياتي ، واتسجلي غيابات كثير بسبب اني اتاخر دقيقة او دقيقتين بسبب الباص … بس لاحظت انه غيابات الرزيتيشن اللي اتسجلت ما اخدها ولا اهتم انه ياخدها (بس انتبه في ترم 171 كان يدرسنا واحد هندي الرزتيشن لكن في الفصل الجديد 172 صار حتى الرزتيشن يدرسها ابو شوشة مع اللكتشر برضو فلا تعتمد على اخر نقطة)\nطريقة الشرح :\nجباااارة والجبار الله وبشهادة كل اللي سجلو معاه … بس مشكلته يكتب ويمسح بسرعة واللي يكتب نوت مابيلحق الا اذا يصور وينقلها بعدين\nالكويزات :\nصعععبة مع اني اعترف اني كنت اخذ 0 وسالب واحد لكن الدوافير كانت درجاتهم ٣-٦ وغير انه تصحيحه سيييء لانه يبغا خطوة بخطوة حتى لو الناتج صح والطريقة غلط يعطيك صفر ، وعلى ترمنا ما اعتمد عالغيابات زي الاترام الماضية فالبونص وقلنا اللي عنده 11 غياب زي اللي عنده غياب واحد مافي فرق بينهم واعتمد البونص على سلوكك واهتمامك بالحضور فالاوفس اور وكويزاتك\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA\nالصوت:\nلهجة اهل الغربية ❤️\nإضافات :\nعشان اكون معاكم صريح اذا انتا مهتم فالمادة وحريص وداخل عشان تجيب قرييد عاالي فانا انصحك فيه ، لكن اذا انتا مو من النوع دا وداخل عشان تنجح ولا قريد متوسط فلا تغلط غلطتي لانه كل اللي كان يمدحلي فيه دوافير ولو بيدي ماكنت نزلت عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486403-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/37", "user": "Feras-MTN", "ts": 1516422612000, "tid": 118577, "pn": 37}}]}', 1516422612000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrhman_sh-math101', 'stk-abdulrhman_sh', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118577", "n": "Dr. Mohammad Aboshosha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T 162/ MATH 101 & T171 / MATH 102\n\nالتحضير : يدخل الكلاس قبل الوقت بخمس دقائق تقريبا ويكتب ع السبورة لما يدخل وقت الكلاس بعدين يحظر بعد دخول الوقت بكم دقيقة … لا يسمح بالتأخير ( أي تأخير يعتبر غياب حتى لو دخلت بعد التحظير بدقيقة ).\n\nوهذا العيييب الوحيد صراحة بسس\n\nالمدح ما بزيد على مدح الطلاب فوقي لا في الشرح ولا في النوته بس\n\nالتقييم لي انا \n\nلطلاب كثيييييييير درسوا عنده FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF لدرجة ان فيه واحد دردب السمستر وكان احد الاسباب الماث واعلمكم هنا ليييش :-\n\n,وهنا الفايدة من تعليقي ابغى افهمكم ليش ابو شوشة ما ينطااااق مرة للبعض\n\nاذا انت هادي مو جريء تنحرج من رد الدكاترة عليك اذا سالت لا تسجل معه\n\nابو شوشة حمااااسي مرة في الشرح وسرييع بس ففااااااهم ويفهم مرررة واللي يحله مرة يفهمك الدرس بسسسسسس\n\nاذا انت هادي وتحب الشرح الهادي ابعد :no_entry_sign:\nاذا انت تتأخر لو دقيقة عن الكلاس ابعد :no_entry_sign: بل استسلم من البداية 😁2: لانك راح تحطم الارقام القياسية كأسرع طالب ياخذ DN 👋 في الجامعة 😂 😀\n\nبعض الاحيان لما تسأل سؤال الدكتور من الحماس يرد عليك قبل ما تكمل سؤالك على اساس انه فهم سؤالك وهو ماهو حولك فبعض الطلاب ينحرج ويسكت ويسلك ويهز راسه على اساس انه فاهم بالنسبه لي كنت اوقفه وافهمه انه مو حولي واخليه يرد عليه واذا ما فهمت عااااادي جدا اقول له ما فهمت اخليه يعيد اليييين ما افهم وبعض الاحيان تسأل سؤال تقول دكتور كيف جت x مثلا ينبرش عليك ويقول لك انت قول لي كيف جت ومدري ايش طبعا هذا كله بسرعة فلاحظت انه كثييير من الطلاب يسكت ولا يعرف يجاوب ويبدأ ينحرج لانه يحس انه هو الوحيد اللي مو عارف كيف جت x فيبدأ ينحرج ويسكت ويسلك ويهز راسه على اساس انه فاهم الين ما يسكت الدكتور ولا عاد يسأل مرة ثانية لو على جثته لانه خايف ان الدكتور يحرجة طبعا المحزن المبكي في الموضوع ان الدكتور نيته طيبة بس شخصيته كذا هو يفكر انه بالاسلوب هذا راح يفهم الطالب وهذا اكثررررر شيئ يحرصصصصصصص عليه ويخاف منه وهو (فهم الطالب)\n\nوهذا للاسف اللي خلى طلاااب كثيييير يكرهون ابو شوشة لانهم ماعرفوا يتعاملون معه ببساطة او العكس طبعا. 😢\nالسر هو فهم اسلوب هذا الدكتور وتراه طيييييب وحبييييب الى ابعد ما تتصورون\n\nاتمنى اني افدتكم ولو بشيء بسيط واللي في خاطره شيئ يتكلم عادي يصحح او ينتقد كلامي واسف لطول الكلام لكنه مفيد مع ابو شوشة وغير ابو شوشة ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498726-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-aboshosha/118577/42", "user": "Abdulrhman_sh", "ts": 1535993979000, "tid": 118577, "pn": 42}}]}', 1535993979000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ibraheem_ahmed-math101', 'stk-ibraheem_ahmed', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101 -213\n\nالتحضير : ورقة تمر على الكل متساهل حتى لوجيت بعدين يمديك تجيه وتوقع\nطريقة الشرح : عنده سلايدات رهيبة فيها اهم الافكار يشرح الفكرة ثم يحل الاسئلة ما يخلص الكلاس الا وانت فاهم فكرة الدرس\n\nالكويزات : صعبة ولكن جدا رهيبة افكارها تجيك في الميجر\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:a+ اذا في اكثر بعطيه لانها قليل في حقه\nالصوت: ممتاز جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535016-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/27", "user": "ibraheem_ahmed", "ts": 1660588446000, "tid": 118579, "pn": 27}}]}', 1660588446000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhassan_alharbi-math101', 'stk-alhassan_alharbi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101-213\nلتحضير :\nورقة تمر على الطلاب و سلس في التاخير عادي\nطريقة الشرح :\nيشرح من السلايدات و يحل على الشاشة و صراحة الدكتور شريح حده و يبي يوصل لك المعلومة\nالكويزات :\nفالبداية كانو سهلين بعدين لما شاف انه الافرج عالي صعبهم\nالقريد النهائي:\nA+\nالصوت:\nواضح جدا\nإضافات :\nالدكتور اخلاق و شرح اذا يمديك تنزل عنده نزل بدون تردد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535200-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/28", "user": "alhassan_alharbi", "ts": 1661513231000, "tid": 118579, "pn": 28}}]}', 1661513231000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahadmh-math101', 'stk-fahadmh', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 Term 213\nوليد الخليفي\nالتحضير : ورقة تمر على الطلاب توقع عليها وعادي لو جيت متاخر يخليك توقع ما يقول شي\n\nطريقة الشرح : عنده سلايدات يشرح عليها بالبورد يحل شوي من الاولد واغلبها تكون اسئلة الكتاب ترتيب السلايدات صراحة رهيب وشرحه ايضًا رهيب\n\nالكويزات :الكويزات عمومًا اشوفها متوسطة في منها صعبة وفيه سهلة اذا انت مذاكر وفاهم الافكار غالبًا بتشوفها سهلة\n\nالمياجر: كومن\nالفاينلات : كومن\n\nالقريد النهائي: A+ وبجدارة\n\nالصوت: ممتاز جدًا\n\nإضافات : الدكتور حبيب وحاول يساعدك بقدر المستطاع وشريح الدكتور والكلاس صراحة ما تحس بوقته انصحك وبقوة تنزل عنده وان شاء الله اذا سنحت الفرصة بنزل عنده 102", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535270-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/29", "user": "FahadMH", "ts": 1662169515000, "tid": 118579, "pn": 29}}]}', 1662169515000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sensi-math101', 'stk-sensi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math-101 213 & Math-102 221\nالتحضير : ورقة تمر على الطلاب وماقد شفته يدقق ورى المتاخرين. ومايقبل ميك اب سكشن ثاني.\nطريقة الشرح : من سلايداته الخاصة، جدا جدا ممتازة لانها تجيب اهم افكار الدرس. شرح الدكتور واضح وممتاز واغلب الوقت ماحتجت اراجع الدرس واقدر احل اولدات من شرحه\nالكويزات : متوسطة الصعوبة. مشكلتها انها mcq ولا يشوف حلك. بس افكارها حلوه وقريبة من الاولدات\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: صوته واضح جدا والاكسنت ممتاااااز\nإضافات : الدكتور طيب مرة واخلاقه عالية مع الطلاب من تاجيل كويزات عشان ماتضغطنا مع المياجر. كان دايم يسال قبل مايحط كويز اذا احد عنده ميجر وقتها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536372-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/32", "user": "sensi", "ts": 1676590979000, "tid": 118579, "pn": 32}}]}', 1676590979000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alucard-math101', 'stk-alucard', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m118581", "n": "Dr. Saeed Salman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : كل كلاس, ورفة تمر على الكلاس, مايهتم للتأخير, لو تجي على اخر 20 دقيقه مايقول شي.\n\nطريقة الشرح : سلايدات + يكتب على البورد, يبي يفهم الطلاب بس ماش, ولو تسأله لين بكره ما يقول شي\n\nالكويزات : 4 كويزات + صعبه في الاولد اكزامز, وياخذ أحسن درجتين ( الي يذاكر الكويز من السلايدات يجيب فل )\n\nالمياجر: … math 101\nالفاينلات : …\nالقريد النهائي: C+\n\nالصوت: واضح\n\nإضافات : الفصل هذا 131 اخذ الدكتوراه, من قبل ما ياخذها وحنا نقوله يا دكتور 🤠 مافرقت\nوتراه طييب ولو تسأله بعد الكلاس يقعد معك ساعه يفهمك, وتصحيحه في المياجر عادل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316109-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-salman/118581/6", "user": "Alucard", "ts": 1389017214000, "tid": 118581, "pn": 6}}]}', 1389017214000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-math101', 'stk-m_shaer6', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m152151", "n": "Dr. J Al-Smail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "- بنود التقييم : ماث 101 …\n\n- التحضير : ممكن 70% من الكلاسات يحضر … عن طريق الأسماء او السيريال نمبر … وما يدقق ابداً ع التأخير …\n- طريقة الشرح : عنده اوراق مكتوب فيها اسئلة … يكتبها لك ع السبورة ويشرحها … فيها افكار ممتازه جددددداً … وفيه منها من اولد اكزام … شرحه خراااااااافي …\n- الكويزات : كوزاته من متوسطه تقريباً … يعني اذا مذاكر كويس ما راح تعاني فيها ابداً …\n- المياجر : كمون …\n- الفاينلات : كومن …\n- القريد النهائي : A+++++ …\n- الصوت : واضح جداً وكلامة مفهوم ومتمكن من اللغة بشكل رائع …\n- إضافات : أنصح به وبقووووووة … الدكتور طيب جددداً … وكلاسه ونااااسه … يعطي نصائح فالحياة ومتمكن جداً من المادة …\n\nDOCTOR JAMAL 👏 ❤️ …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467335-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-smail/152151/10", "user": "m_shaer6", "ts": 1485809058000, "tid": 152151, "pn": 10}}]}', 1485809058000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10775-math101', 'stk-user10775', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m152151", "n": "Dr. J Al-Smail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nMath101\n161\nالتحضير :\nتوقع على الورقة في الأسابيع الأولى تالي ينادي بالاسم في أخر الكلاس\nيتساعد مع التأخير بس يفضل إنك ما تتأخر\nطريقة الشرح :\nشرح متكامل من المفاهيم إلى الأمثلة و يتجاوب مع الأسئلة و أحيانا بشكل فكاهي و تلطيف للجو و أنصح تكتب وراه لأن كتابته مرتبة على السبورة.\nالكويزات :\nصعبة شوي يبالك تحل تمارين قبل لا تجي و ما كنت أحل مسائل كافية\nالمياجر:\ncommon\nالفاينلات :\ncommon\nالقريد النهائي:\nA+\nالصوت:\nواضح و مسموع بالأخص في الكلاسات الصغيرة زي مبنى 4 و 6.\nإضافات :\nالمدرس أخلاق و يتستقبلك بحفاوة في المكتب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480661-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-smail/152151/16", "user": "user10775", "ts": 1505913691000, "tid": 152151, "pn": 16}}]}', 1505913691000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10953-math101', 'stk-user10953', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m152151", "n": "Dr. J Al-Smail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 - 171\n\nالتحضير :\n\nالتحضير بورقه تمر عالطلاب وبدون اي مبالغة الورقه ذي ماشفتها طول السمستر الا مرتين او ثلاثه , انسان حرفيًا ماهمه التحضير كثر ماهمه تستفيد وتشارك بس باخر الاسابيع زعل شوي شاف الكلاس فاضي وسألنا وكأنه يعاتب يقول وين الطلاب ماصاروا يحضرون فحاول ماتستغل طيبته بزيادة .\n\nطريقة الشرح :\n\nيبدأ بنصايح وسواليف بداية الكلاس تغير الجو شوي وبعدها يشرح البيسك حبه حبه ويتدرج بصعوبة المسائل و ميزة الدكتور ينفع لاي شخص مهما كان مستواه دافور او غيره ويستقبل انواع الاسئلة و من سابع المستحيلات يعصب اخلاق تمشي على الأرض ماشاء الله عليه\nولو انه اذا جاء يتكلم انقليزي يتدلع شوي ويضحك على اي شي (شي كان ينرفزني نوعًا ما ) 😅 .\n\nالكويزات :كويزاته 90% ماتطلع من النوت اللي يكتبها يعدل عليها تعديلات بسيطة وفي حال كنت تشوف المياجر بدري بتلاحظ انه يجيب اسئلة نسخ لصق من اولد اقزام\nوكان يختبرنا 4 كوزات وكلاسين تست ياخذ افضل كلاس تست وافضل 3 كويزات والبونص حقه صراحة مدري كيف نظامه لان كويزاتي كانت كويسه وكلاس تستي برضو\nبس خويي قالي انه مازود واجد فلا تحط أمل كبير انه بيرفعك كثير وتنصدم بالاخير .\n\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A+\nالصوت: صوته واضح جدًا ومسموع خصوصا ان كلاساته ماتكون كبيره بمبنى 6 او 4 وكلامه مفهوم وواضح .\nإضافات :\n\nما اقول الا الله يجزاه خير الدكتور ماقصر معنا والله ولو بيدي انزل معه مرة ثانيه وانصحك تحطه خيارك الاول والاخير لانه فعلًا يستاهل وماراح تندم عليه ابدًا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492617-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-smail/152151/18", "user": "user10953", "ts": 1526576054000, "tid": 152151, "pn": 18}}]}', 1526576054000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10703-math101', 'stk-user10703', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m152152", "n": "Dr. Saddam Abbasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "صدام عباسي- ماث 101 -ترم152\nطبعا هذا الدكتور قبل ماأتكلم عنه هو مجاله في الاحصاء ماله في الرياضيات كثير طبعا انا مالقيته الاهو فاتح وانحديت اني اسجل معاه وتمنيت اني ماخذت الماث واجلته لاني ماستفدت شي شرحه سئ جدا جدا جدا مايعرف كيف يدرس الماث عنده نوته يعرضها بالبروجكتر ويتكلم فيها كأنه يدرس مادة حفظ وليست مادة فهم هي جيدة النوته لكن الشرح ماش طبعا يمكن اول ثلاث شهور كنا ندرس نص ساعه او اقل ويطلعنا بدري مررة التحضير ورقه تمر يوميا تحضر فيها انت وفيه ناس يحضرون لاصدقائهم سونا كويزات 7 وخذ اعلى 3 منها متوسطه كويزاته تصحيح الميجر ون يعطيك حقك وومنكن اذا كلمته يزيدك شوي الصوت واللغه غير واضحين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452622-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saddam-abbasi/152152/13", "user": "user10703", "ts": 1466650617000, "tid": 152152, "pn": 13}}]}', 1466650617000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zad-math101', 'stk-zad', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101 T201\nالترم كامل أونلاين\n\nالتحضير : الدكتور يعتمد على دخولك للبلاكبورد بس ونادرا جدا ينادي أحد بالاسم, يعني لو فتحت المحاضرة ونمت بيحسبك حاضر ( ما أدري كيف كان بالحضوري).\n\nالشرح : الدكتور شرحه ضعيف للأسف ونادرا يقدر يوصل الفكرة, أغلب المحاضرات كنت أشغلها وأقفل الصوت بما إنه نادرا تطلع بفائدة منه. بشكل عام لو الماث عندك ضعيف أساسا لازم تدور على مصادر شرح غيره.\n\nالصوت : اللهجة مغربية لكن واضح جدا وتقدر تفهم منه بسهولة.\n\nالكويزات : الدكتور للأسف اختبرنا 3 كلاس تست خلال الترم + واجب 20 سؤال كلها صعبة وتطول أعطانا عليه اسبوع بس. اثنين من الاختبارات + الواجب خلال أخر 3 أسابيع تقريبا. للأسف طبعا الدكتور قرر يحذف اخر كلاس تست مع انه كان الوحيد اللي جبت فيه درجة جيدة والكلاسوورك حقي كان من أقل الدرجات في السكاشن عنده.\n\nالمياجر والفاينل كومن\n\nالدكتور كتعامل محترم لكن كشرح للأسف ما يعتمد عليه إذا كنت جيد بالماث ونزلت عنده لازم تعتمد سيلف ستدي. إذا كنت من اللي يحتاج شرح الدكتور ما أنصح فيه أبدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527452-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/16", "user": "ZAD", "ts": 1609504075000, "tid": 172443, "pn": 16}}]}', 1609504075000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhussain_bin_alshei-math101', 'stk-alhussain_bin_alshei', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: Math101\nالترم: 201 (الدراسة كانت اون لاين السمستر كامل)\n\nالتحضير: الترم ذه خله التحضير الكتروني عن طريق البلاك بورد يعني البلاك بورد يسجل انت متى دخلت متى طلعت ويسجلك حضور او غايب او ليت او غيره. بس في حالة ان كان في خطا من السستم تقدر تروح له في الأوفس اور تقوله وبيعدلها لك. والدكتور متساهل من هالناحية يعني مب يشك فيك وبيعتمد على مصداقيتك . يعني حتى لو كنت غايب ورحت له قلت له انا كنت حاضر بيحطك حضور بس طبعا الكذب حرام :no_entry_sign:.\n\nالشرح: والله شوف. الدكتور شرحه جيد بس في مواد الأوريا.بس الترم ذه جاب العيد.الترم ذه جابوه من الأوريا (الي تقريبا من اول ما جا الجامعة يدرس فيها) للجبل لأن كان في نقص وعفس الدنيا لأنه ما كان متمكن في ماتيريال MATH101 فما كان شرحه واضح حيل والشعب الي نجو اغلبهم اعتمدوا على السيلف ستودي والهيلب سكشن بالأضافة الى ال WEBASSIGHNE (موقع للواجبات هذرته طويلة فما لي خلق اشرحه لأن يمكن يتغير الوضع الأترام الجاية 🚬 )\n\nالكوزات: ما عطانا كوزات وأتوقع هذا واحد من الأسباب ليش طلابه افرجهم منخفض ذه الترم.\nمياجر: مشترك\nفاينل : مشترك\nالصوت: لهجة مغربية واضحة تعلق في المخ لدرجة يمكن بتشوف روحك تقلد لهجته لجيت تذاكر 🤣.\n\nالقريد النهائي: C+\n\nاضافات: الدكتور عليمي (مبتدأ-بدائي) في التكنولوجيا ودائما يواجه مشاكل تقنية 😂. انا درست عنده قبل في الأوريا شرحه زين بس الترم ذه جاب العيد وبقوة هاذا ليش بتشوف الردود من 2020 اغلبها سلبية بس انا قلت لازم انصفه بتقييم موضوعي خالي من المشاعر والآراء الشخصية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527711-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/17", "user": "Alhussain_Bin_Alshei", "ts": 1610159630000, "tid": 172443, "pn": 17}}]}', 1610159630000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fms1-math101', 'stk-fms1', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 T201\n\nالتحضير: السمستر كان كامل اونلاين و التحضير عن طريق البلاك بورد (يسجل متى تدخل و متى تطلع و يحسب الدقايق) و الدكتور ما كان ينادي وقت الشرح فا اهم شي تدخل المحاضره. و اذ صارت لك مشكله تقدر تروح له اوفس اور (تكون بمايكروسوفت تيمز) و تكلمه و يضبطك لان الدكتور متساعد جدا.\n\nالشرح: الي اعرفه انه هو حق اوريا و ذي اول مره جابوه الجبل عشان كان فيه ضغط. فا الشرح كان ماش و لازم تعتمد على نفسك سلف ستدي. و الي ساعدني اني اعدي الماده انه فيه اونلاين فديوز حقت الماده من الديبارتمنت في البلاك بورد فا ذي ساعدت.\n\nالكويزات: عطانا 3 كلاس تيست و قال باحذف اقل واحد بداية السمستر. لكن بعد الكلاس تيست الثاني كان الافرج طايح فا قال بعطيكم واجب وعطان اسبوع نحله و نسلمه مع طريقة الحل عشان يرفع الافرج. و بعد الكلاس تيست الثالث كنسله لان كان فيه مشاكل بالتصحيح. و بالنهايه قرر ياخذ اعلى درجو من الكلاس تيستين الاول و الثاني و درجة الواجب.\n\nالصوت: اللهجة ثقيله و واضحه و هو يتكلم عربي انجليزي. وعنده كلمات دايم يقولها زي لوووووووووووووووووووك و كلمات ثانيه تعلق بمخك و تذكره.\n\nالدكتور بالنسبه لي ممتاز خصوصا اذ كنت تذاكر سلف ستدي. لان ما يضغطك بالمره فا تاخذ راحتك معه و ذا احسن شي فيه. لو بينزل بعدين بنزل معه صراحه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527830-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/18", "user": "FMS1", "ts": 1610467945000, "tid": 172443, "pn": 18}}]}', 1610467945000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-deadly_scorpion-math101', 'stk-deadly_scorpion', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172447", "n": "Dr. Ali Duman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Math 101 (163\n\nالتحضير: بالبداية كان ينادي عالاسماء بس بعدين بلش يحفظهم, متشدد شوي وما يسمح بالتأخير الا اخر فترة كان يعطينا 3 دقايق بس\nالشرح: للاسف ما كان كويس, كان يشرح لحالو يعني كلمتين عالطاير بس كان يحل امثلة كثير ويعطي الطلاب فرصة يحلو ويشرح للي مو فاهم\nالكويزات: اعطانا 6 كويزات سهلة لدرجة انو اسئلة الهوموورك كافية بس بسبب نظام الافرج انخسفنا عندو\nالمياجر: common\nالفاينلات: common\nالقريد النهائي: بسبب الشرح وسهولة الكويزات صعب يطلع عن D\nالصوت: ممكن سبب انو شرحو مو مفهوم بسبب صوتو الواطي جدا اللي دوبك تسمعهم منو\nاضافات: الدكتور محترم جدا ولكن شرحو بخلي الواحد ينترفز منو ويصير يكرهو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479124-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-duman/172447/6", "user": "Deadly_Scorpion", "ts": 1503470941000, "tid": 172447, "pn": 6}}, {"id": "stk-dr-m172444", "n": "Dr. Audu Johnson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Math 101 REC (163\n\nالتحضير: عندو التحضير اشي مقدس وكان يحضر آخر الكلاس وممكن يوخذ وقت زيادة عشان التحضير\nالشرح: شرحو مفهوم وكان يطلع الطلاب عالسبورة عشان يحلو بعض الاسئلة\nالكويزات: NA\nالمياجر: NA\nالفاينلات: NA\nالقريد النهائي: +A\nالصوت: صوتو جدا واضح ومسموع ولهجتو ممكن تفهم عليها\nاضافات: الدكتور محترم وبتجاوب مع الطلاب مشكلته انو ما بحل غير سؤالين او 3 اسئلة بالكلاس بحجة انو الطلاب لو فهمو هاظ السؤال بفهمو البقية طبعا هو اللي اعترف بهاظ الاشي وحكى انو هاي مشكلة عندو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479131-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/audu-johnson/172444/6", "user": "Deadly_Scorpion", "ts": 1503473540000, "tid": 172444, "pn": 6}}]}', 1503470941000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-suarez-math101', 'stk-suarez', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172446", "n": "Dr. Azzam Alfarraj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101-Term161\n\nالتحضير: كان يحضر اول اسبوعين ومتشدد في التحضير … بس بعد الاسبوعين ما صار يحضر .\n\nالشرح : كان يعطينا فكرة عن الدرس بعدها يحل لنا مثال او اثنين في الكتاب ويحل كم سؤال في الكتاب بعدين يدخل اولد اقزام ويحل لنا اسئلة ( بعض مرات يغير جو ويوقف 5 دقايق ويسولف علينا سالفة يلطف الجو شوي ) . الاستاذ كان عنده نوته وقبل كل كلاس كان ينزل نوتة الدرس في البلاكبورد … وفيه حركة جميلة انه كل نهاية درس يحط اسئلة اولد اقزام متعلقة في الدرس .\n\nالكويزات : سهلة … اغلب الاختبارات كان اونلاين\n\nالمياجر : كومن ( تصحيح الميجر كان خورافي ماقصر والله معنا كان كريم بشكل كبير الله يجزاه خير )\n\nالفاينلات : كومن\n\nالصوت : واضح\n\nإضافات: المدرس انصحه فيه بصراحه انسان رائع اخلاق وعلم ما شاء لله وشرح لا يعلى عليه … اذا ماحصلوا لك كبار القسم لا تتعداه .\n\nالقريد النهائي : A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467037-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzam-alfarraj/172446/4", "user": "SUAREZ", "ts": 1485427464000, "tid": 172446, "pn": 4}}]}', 1485427464000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-maxmx05-math101', 'stk-maxmx05', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "هو استاذ حق ريستيشن شكله توه بيصير محاضر\n\nدرسني ماث 101 ترم 151\n\nبنود التقييم :\n\nالتحضير : يحضر مع بداية الكلاس بالاسامي\nطريقة الشرح : كان ريستيشن فكان يحل الاسئلة الركوميندد في السيلبس حق الريتشن , وكان شرحة على ما اذكر واضح وممتاز\nالكويزات : ما كانت منه\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\n\n* الدكتور حبيب ينكت ومن ه الكلام\n* يتكلم عربي كثير\n* لا يسمح بستخدام الجوال في الكلاس\n* الدكتور يتقبل الاسئلة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475080-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/3", "user": "Maxmx05", "ts": 1497365763000, "tid": 172448, "pn": 3}}]}', 1497365763000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_fa-math101', 'stk-omar_fa', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m172449", "n": "Dr. Yassir Khalid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - 153\nالتحضير : بالأرقام أحياناً بدايه الكلاس وأحياناً نهايته ولا يدقق على الليل عندنا ناس يجي قبل نهايه الكلاس ب10 دقايق يحضره لكن لا تزودها معه .\n\nطريقة الشرح : على السبوره و سلايدات. ولا يقلق الطلاب اللي يبي ينتبه ينتبه واللي مايبي بكيفه مايقول له شي مخلي الطلاب على راحتهم. لكن عيبه أنه يجيب النوم ولو فهيت شوي عنه أنسى تفهم الباقي.\nالكويزات : سهله للي مذاكر صح يعني تفهم الأساسيات مع كم مثال ماتنزل عن 15 من 20\nالمياجر: كومن , تصحيحه كويس ويوزع درجات .\nالفاينلات :كومن\nالقريد النهائي: B+\nالصوت: واضح ولغته مفهومه\nإضافات : للأمانه أنه أخلاق ومحترم ومتساهل مع الطالب ويعطي بونص بس يختلف على حسب غياباتك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457906-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yassir-khalid/172449/4", "user": "Omar_FA", "ts": 1474206775000, "tid": 172449, "pn": 4}}]}', 1474206775000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11369-math101', 'stk-user11369', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 - Term 173 - REC\n\nالتحضير : ورقة يمررها وبعد فترة صار يحضر بالأسماء ، بس بشكل عام هو مايهتم بالتحضير كثير.\nطريقة الشرح :يعطينا عدة أسئلة نحلها مع بعض من ثم يحل لنا السؤال بشرح وافي وبالتفصيل ، ويعلمنا الأخطاء الشائعة للطلاب والأشياء اللي يركزون عليها في الاختبارات .\nالكويزات : لاتوجد .(REC)\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A+.\nالصوت: واضح .الكلاس أغلبه بالعربي مع بهارات انجليزية.\nإضافات : الدكتور لطيف ومتساعد بجنووووون 😆 أي سؤال تعطيه اياه بأي طريقة كانت يعطيك الجواب سواء ايميل واتس مكتبه اللي تبي. هالشيء يفك عنك ازمة خصوصا في مادة زي الماث.انصح فيه بقووووووة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498035-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/14", "user": "user11369", "ts": 1534966082000, "tid": 175316, "pn": 14}}]}', 1534966082000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11325-math101', 'stk-user11325', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 101 181\nالتحضير : مرن جدا بالميك اب بس مايهتم بالتحضير مرة\nطريقة الشرح : ممتاز الله يسعده افضل مدرس درسني ماث من ١٤ سنة بس انتبهوا لو تدخلون الكلاس متاخرين دقيقة بيفوتكم اشياء مهمة\nطبعا شرحه كالاتي ، يبدا يفتح النوت بداية كل سكشن يشرح الكونسبت ثم يحل مسائل كثير\nالكويزات : متوسط مائل للصعوبة بس تصحيحه ممتاز ، هو قال اهم شي اخلي الافرج ٣٠ /٤٠\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: a+\nالصوت: واضح يشرح عربي وانجليزي\nإضافات :\nالدكتور ممتاز وخلوق ويهتم لرأي الطلاب بس بعض الاراء ليتهم يحتفظون فيها لنفسهم .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501779-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/15", "user": "user11325", "ts": 1541162307000, "tid": 175316, "pn": 15}}]}', 1541162307000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed3-math101', 'stk-mohammed3', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181 ماث 101\nالتحضير :ينادي الطلاب من الكشف في نص الحصة وبعض الاحيان مايحضر اصلا ومتساهل مره في التاخير ومن ناحية الميك اب.\n\nطريقة الشرح : يفتح النوت ويشرح الكونسبت بعدها يحل مسائل لين ماتطفش ويغطي اغلب الافكار الي تجي في المياجر عموما شرحه جدا ممتاز والنوت حقته جدا ممتازة.\n\nالكويزات :متوسطة وتصحيحة ممتاز\n\nالمياجر:كومون\n\nالفاينلات :كومون\n\nالقريد النهائي:A+\n\nالصوت: واضح والاكسنت حقه واضح ويشرح هو بالعربي والانجليزي.\n\nإضافات : الدكتور حبيب واخلاق ومتساعد مره مع الطلاب واسلوبه ممتاز في الشرح وخفيفودايم موجود وقت الاوفس اور ويسوي قروب واتساب للطلاب عشان اذا عندهم اسئلة او يتناقش معاهم عن اليوم الي يبغون فيه كويز من الاخر افضل دكتور ماث درسني للحين طبعا يسمح للطلاب من سكاشن ثانية عند دكاترة ثانين يحضرون عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503621-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/16", "user": "Mohammed3", "ts": 1544890077000, "tid": 175316, "pn": 16}}]}', 1544890077000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedgs-math101', 'stk-mohammedgs', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH101 LEC- 181\n\nالتحضير: يحضر في وسط الكلاس أو في نهايته وأحيانًا ما يحضر خير شر، لاحظت إنه ما يحب التأخير فحاول تجي بدري. من ناحية الميكب فهو مرن لأبعد درجة تقدر تنقل اسمك لأي سكشن وتقدر تحضر في أي سكشن متى ما بغيت *إلا وقت الكويزات تحضر مع سكشنك الأصلي أو اللي نقلت اسمك له* ينادي بأسماء طلاب سكشنه الحالي بعدين يمر على السكاشن الثانية على السريع يشوف إذا في أحد مسوي ميكب.\n\nطريقة الشرح: يشرح من نوتته، في البداية يشرح كونسبت بشكل ممتاز جدًا بعدها أسئلة أسئلة أسئلة ويغطي أغلب الأفكار اللي في السكشن وتجي في المياجر، يسوي بروفس أحيانًا عشان تعرف كيف جاء القانون أو النظرية.\n\nالكويزات: متوسطة مائلة للسهولة أحيانًا والصعوبة أحيانًا أهم شي عنده الآفرج يكون 30 من 40، الكويزات تجي من الأفكار اللي في نوتته والأولد إقزام باي سكشن فحاول تخلص كل أسئلتهم قبل كل كويز. بشكل عام الكويزات حلوة والفل مارك مقدور عليها.\n\nالمياجر: كومون.\n\nالفاينلات: كومون.\n\nالقريد النهائي: A+\n\nالصوت: واضح والشرح عربي وإنقليزي.\n\nإضافات:\n1- الدكتور يدخل طلابه قروب واتس وما يقصر معنا صراحة في المساعدة وحل بعض الأسئلة.\n2- بدا الدكتور هالسمستر في إنه يكتب أسئلة على السبورة في نص الكلاس ويخلي الطلاب يحاولون يحلونها، حسيت هالشي حلو مرة وأحيانًا وأنا أذاكر أتذكر كيف حليته في الكلاس.\n3- نوتة الدكتور ممتازة جدًا وشاملة أغلب إذا مب كل الأفكار ومليانة أسئلة من الكتاب والأولد إقزامز وأمثلة من عنده لا تدور مصدر غيرها في المذاكرة.\n4- الدكتور حبيب وخفيف دم وأخلاقه حلوة.\n5- لو جتك الفرصة تنزل عنده نزل بدون أدنى تردد وخله خيارك الأول!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504020-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/17", "user": "MohammedGS", "ts": 1545689730000, "tid": 175316, "pn": 17}}]}', 1545689730000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hasan_o-math101', 'stk-hasan_o', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math101-181\n\nالتحضير:-\nكان يمرر الكشف اول أسبوعين وبعدين صار يحضر بالأسماء طبعا التحضير غالبا كان مرتين او مرة في الأسبوع وآخر الترم ما صار يحضر كثير.\nبالنسبة للتأخير ما يعطي ليت لكن يتضايق من اللي يتأخروا ويدخلوا في نص الوقت بس تاخير دقيقة او دقيقتين ما يقول شيء\nبالنسبة للميك اب عنده نوعين النوع الأول اللي ميك اب ويكون طول السمستر وتغير كلاسك الى كلاس ثاني ويشمل الكويزات النوع الثاني ميك اب اذا فاتك كلاسك او اذا ما كنت تبغى تحضر مع كلاسك بس وقت الكويز لازم تختبر مع سكشنك بس اخر كوزين كان يمشي بس ينبه الطلاب.\n\nطريقة الشرح:-\nيشرح من النوتة حقه وغالبا يبدا يشرح الكونسبت وإذا كان فيه قانون او شيء يشرح البروف (لانه يقول في طلاب مميزين ويحبوا هذي الأشياء ولازم أوضحها لهم مو احفظها لهم) ويبدا يحل مسائل من النوت ويكون من ضمنها أولد اقزام ويحط ريمارك وتنبيهات كثيرة ويكررها في الكلاس.\n\nالكويزات:-\nمتوسطة مايلة للسهولة وأحيانا متوسطة مايلة للصعوبة عشان يخلي افرج الكويزات زي ماهو محدد من الديبارتمنت وطبعا وقد تكرر اكثر من كويز الأسئلة من النوت بس مغير الأرقام وكان يقول هذي بسبب أنكم ما تذاكروا النوت\n\nالمياجر:- كومون\n\nالفاينلات:- كومون\n\nالقريد: (+infinity^(A\n\nالصوت واللغة:-\nغالبا عربي وأحيانا إنجليزي وطبعا ممكن يوضح اي نقطة بالعربي اذا ما فهمت وتقدر تسأله بالعربي\n\nاضافات:-\nالدكتور كان طالب في الجامعة ففاهم وضع الطلاب.\nالدكتور عنده نوتة مميزة جدا لو ما قدرت تنزل عنده لا تستغني عن نوتته.\nالدكتور دايم متواجد في الاوفيس في وقت الاوفيس أور.\nيعمل مجموعة واتس ويدخل كل الطلاب اللي يدرسهم ويساعد الطلاب ويشرح في القروب ومتواجد ماشاء الله لا قوة الا بالله ٢٤ ساعة في القروب.\nاذا قدرت تنزل عنده لا تتردد في انك تنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504077-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/18", "user": "Hasan_O", "ts": 1545774113000, "tid": 175316, "pn": 18}}]}', 1545774113000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-math101', 'stk-rapls', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 181 Lecture\n\nالتحضير : بداية الترم ما كان يحضر كثير , لأنه عارف ان الطلاب ما كانوا يغيبون الا قليل منهم , احيانًا يحضر بالكويزات واخر الترم صار يحضر بالكشف , الميك اب عنده مسموح بس تعطيه خبر .\n\nطريقة الشرح : يشرح من نوتاته , احيانًا يستعرضها على البروجكتر , ما يستغني عن السبورة يكتب احيانًا 4 و 5 مرات , شرحه ممتاز جدًا ويعرف وين يضيعون الطلاب ووش النقاط اللي تكون معقدة بالنسبة لهم .\n\nالكويزات : كويزاته متوسطة الى صعبة بس كويز واحد كان سهل , يعرف نقاط ضعف الطلاب ويعرف يختبر الكونسبت بشكل جميل , كويزين ريتن والباقي خيارات مع وجوب الحل .\n\nالمياجر: كومن .\n\nالفاينلات : كومن .\n\nالقريد النهائي: A++\n\nالصوت: ممتاز جدًا .\n\nإضافات : الدكتورعنده أسلوب قوي جدًا وكاريزما عالية وكلاسه ممتع وجميل وكثير يحضرون مستمعين , معروف بسمعته الحسنة وشرحه الممتاز , تسجيل الهلب سشن عنده يقفل في دقائق ويحضرون زيادة على المسجلين , اعطانا سبع كويزات واخذ افضل 5 مع زيادة بوينتس للناس اللي يصححون اغلاط النوتة والناس اللي غيابهم قليل , قد لا يمر في حياتك دكتور مثله , تعامله في المكتب راقي جدًا , يسوي قروب واتساب لطلابه ويدخلونه برضو باقي الطلاب ويجاوب عليهم في أي وقت ويقضي من وقته كثير من أجل الطالب .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504745-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/19", "user": "Rapls", "ts": 1547042381000, "tid": 175316, "pn": 19}}]}', 1547042381000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-math101', 'stk-user11372', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175316", "n": "Dr. Mohsen Alshahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math-101 term 191\n\nالتحضير:\nالدكتور اسطوووووووووووورة بهذا الموضوع , يسمح بالتنقل بين جميع السكاشن خلال الدوام , ماعدى ايام اللي يصير فيها كويزات لازم تحضر بسكشنك , ويسمح بالتأخير عادي ويراعي\nالطالب لو كنت جاي من مبنى بعيد , من أفضل الدكاترة اللي يمكن يمرون عليك بموضوع التحضير\n\nطريقة الشرح:\nاسطورية , يشرح من النوتات حقته , ويحل مسائل الى ان تخرج من راسك , وأحيانا ياخذ كلاسات الريساتيشن حق الدكتور الثاني وهذا غالبا صار معظم السمستر ويشرح فيها عادي طبيعي\nكانها محاضرة عادية , لان احيانا نتأخر بسبب كثرة حل المسائل ماشاء الله والاولد اقزام , اذا تبي تفهم 100% اضمن لك عند هذا الدكتور ولاتدور غيره مره\nوبالنسبة للتأخير في نهاية الكلاس احيانا نتأخر دقيقتين بس كحد اقصى لان هو مازال يشرح , لكن ما أذكر تأخرنا اكثر من كذا مره\n\nالمياجر:\nكومن\n\nالفاينلات:\nكومن\n\nالقريد النهائي:\nA+++++++++++++++++++++++++++++++++++++++++ وعلامة البلس من هنا الى نهاية العالم مع جميع مراتب الشرف وجميع المكافاة الدولية\n\nالصوت: واضح جدا يشرح عربي .\n\nإضافات :\nالدكتور متعاون مره بالاوفيس اور , يرحب بجميع الطلاب لو عندك سؤال او شي ي\nبالنسبة للكويزات اختبرنا 5 هذا الفصل عبارة عن 4 اختيارات كل كويز واجباري انك تحل\nفي بعض الطلاب كانوا مايحبون هذا الشي انك لو اخترت الجواب غلط حتى لو كان حلك صحيح 90% راح تاخذ صفر على السؤال كامل\nلكن بالنسبة لي اشوفها عادي كانه مثل وضع المياجر\nالدكتور هو الدكتور الوحيد بماث 101 بترم 191 اللي عمل هلب سشن ويجيك يومين قبل الميجر يوم خاص لطلابه يحل اولد اقزام لهم لترم سابق\nشي شي والله يفرح الصدر الله يسعده دنيا واخره\nوتخيل برضوا فوق كل هذا الدلع بيفتح قروب واتس آب لطلابه وبيدخل طلابه كلهم حول 160 طالب من سكاشنه\nويجاوب على جميع الاسئلة , حرفيا جميع ! … مو مثل بعض الدكاترة يفتحون قروبات لطلابهم ومايردون ابدا كأنهم اصنام\n\nاخر كلمة حبيت اقولها لك دكتور لو تشوف التقييم : الله يجزاك الجنة ويرحم والديك وعساك على القوة يارب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518499-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohsen-alshahrani/175316/23", "user": "user11372", "ts": 1577772011000, "tid": 175316, "pn": 23}}]}', 1577772011000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-math101', 'stk-to_be_engineer', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 - 171\n\nالتحضير : بعد خمس دقايق ما يسمح لاحد يدخل في اغلب الحالات لكن احيانا يسمح.\nطريقة الشرح : يستعمل السلايدات اللي تجي مع الكتاب( للاسف) … ما اقول شرحه سيئ بس كان ممكن يكون من مصدر افضل.\nالكويزات : سهلة عطانا 6 كويزات وحذف الاسوء … تحل اسئلة الريساتيشن والاسئلة المقترحة في السيلبس تضمن كلاس ورك حلو لانه يجيب افكار قريبه منها.\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: B+\nالصوت: يبلع شوية حروف بس بشكل عام واضح.\nإضافات :\nالدكتور اخلاق، مرح، شباب لكن له ايجابيات وسلبيات …\nالايجابيات : شرح واضح وما يجيب النوم ودايم نهاية الكلاس يحط اسئلة يجبها من عنده فيها افكار حلوه يعطينا وقت نحلها و يصير نقاش فيها + عطانا 3 هيلب سشن قبل الميجرين وقبل الفاينل (رغم انه ما كان في داوم اسبوع الفاينل ) + اذا منت فاهم سؤال في الكويز يشرحه لك (مره شرح نص السؤال ما بقى الا التعويض 👍) .\n\nالسلبيات :ما عنده نوتة او سلايدات خاصة فيه فلازم تشوف لك مصدر مناسب ترتاح له مثل الكتاب او نوتة دكتور ثاني ( الكتاب ممتاز لكن المياجر في 171 كانت فوق مستوى الكتاب عكس 172 اللي كانت مقاربة لمستوى اسئلة الكتاب).\n\nاذا الدكتور عدل السلبية اللي عنده بيكون من افضل دكاترة القسم …الى هذاك الوقت لا تخليه خيارك الاول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493421-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/6", "user": "To_Be_Engineer", "ts": 1527803580000, "tid": 175799, "pn": 6}}]}', 1527803580000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11839-math101', 'stk-user11839', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m176963", "n": "Dr. Abdulmuhsin Alfaraj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 / 191\n\nالتحضير :\nغالبا يحضر بورقة تمر ولكن الصدق انه ماقد حضر اكثر من ٥ مرات طول هالترم ومتساااعد جدا انك تحضر في اي سكشن له والوضع حبي من هالناحية.\n\nطريقة الشرح :\nيشرح من سلايدات الدكتور محسن الشهراني، نظامه يشرح الكونسبت وبعدها يجلس يحل اغلب الاسئلة اللي في السلايدات ويجيب اسئلة من عنده فيها افكار، ولما يشرح الاسئلة يحب يعطيك شورت كت كثييير تخليك تحل الاسئلة في ثواني ويركز على نقاط كثير يحس انها ممكن تجي في الميجر.\n\nالكويزات :\nهالترم اختبرنا كوزين بس\nواحد قبل الميجر الاول والثاني قبل الفاينل\nبشكل عام متوسطة يعطيك ٤ اسئلة تغطي اغلب ماتيريال الميجر الاول / الفاينل.\nوطبعا لازم اخر سؤال يخليه صعب زي اول كويز جاب سؤال ماحد حله حرفيييا\n\nواعطانا كوزين قال حلوها في البيت وجيبوها، وماكان يهمه حلك صح او لا اهم شيء يكون في جواب وبتاخد الدرجة كاملة.\nبشكل عام لو تحل اسئلة محسن والاولد اقزام بتجيب فل.\n\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي:\nA+++++++++++++++++++++++++\nواحسني ظلمته A+ ماتكفيه و فوقها ،اسطورة وبس.\nالصوت:\nواااضح جدا.\nإضافات :\n\n1- الدكتور جددداااااا محترم ويعاملك كأنك واحد من اخوانه ويحب يساعد حتى بعد وقت الكلاس ويحب يعطيك نصايح في الحل وفي الحياة وكل شيء، وفاتح مكتبه لطلابه.\n\n2 - الدكتور متساعد لابعد درجة، قبل المياجر والفاينل اعطانا هيلب سيشن كل واحد مدته ٣ ساعات يحل اولد اقزام ويشرح وكل شيء.\n\n3 - في الكلاس وورك بعض السكاشن دفاهم ٣ درجات يعني كل واحد اخذ فوق حقه.\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518365-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulmuhsin-alfaraj/176963/4", "user": "user11839", "ts": 1577421153000, "tid": 176963, "pn": 4}}]}', 1577421153000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-terox-math101', 'stk-terox', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m176963", "n": "Dr. Abdulmuhsin Alfaraj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 / 191\nMath 102 / 192\n\nالتحضير: يمرر ورقة وتحط صح على اسمك مرات ينسى والتأخير مسموح\n\nطريقة الشرح: يشرح امثلة من الكتاب ومرات يشرح من نوتات محسن\n\nالكويزات: في ترم 191 كان فيه كويزين متوسطين الصعوبة الى سهل وعطانا واجب بمحل الكويز اما بالنسبة لترم 192 كان الوضع صعب فعطانا كويز واحد سهل\n\nالمياجر: كومن\n\nالفاينلات: كومن\n\nالقريد النهائي: +A\n\nالصوت: واضح جدا ومرات يتكلم عربي ويجاوبك في العربي ومافيه اي مشكلة\n\nإضافات: الاستاذ كمية اخلاق ويساعدك قدر الامكان والله من خيرة الاساتذة والله يوفقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521888-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulmuhsin-alfaraj/176963/6", "user": "Terox", "ts": 1589054557000, "tid": 176963, "pn": 6}}]}', 1589054557000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rashid_a-math101', 'stk-rashid_a', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m176965", "n": "Dr. Jae-Chean Joo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 162 - Math 101\n\nلتحضير : ينادي بالاسماء بداية الكلاس واذا جيت متأخر عشرين دقيقة وكذا يمشيك\nطريقة الشرح : يشرح من الكتاب\nالكويزات : سهلة وبعض الاحيان يجيب من الكتاب ونادرا ما يجيب من الاولد اقزام\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: C\nالصوت: لك عليه\nإضافات : طبعا الدكتور كان اول ترم له بالجامعة ومو عارف بنظام الجامعة زين , والاكسنت حقه لازم تتعود عليه احيانا ما تفهم عليه\nانا للامانة سجلت عنده عشان التحضير لا اكثر , اذا بتسجل عنده اعتمد ع نفسك وخذها سلف ستدي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1476389-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jae-chean-joo/176965/2", "user": "Rashid_A", "ts": 1499891154000, "tid": 176965, "pn": 2}}]}', 1499891154000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-joudah-math101', 'stk-joudah', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101 + MATH 102\n\nالتحضير :\nفي اول ترم ليه في الجامعة كان متشدد خصوصا بداية الترم بس تساهل في الترم الثاني\nطريقة الشرح :\nالشرح ممتاز وبيحاول يحضر الطلاب لللأسئلة الصعبة بقدر الإمكان\nيعمل حوالي حصتين اضافيتين في الترم (حوالي ساعتين أو أقل الحصة) يحل فيها اولد اكزامز قبل المياجر أو الفاينل\nالهوموركات حقته طويلة ومتعبة (يعني بالعامية يبغاك تكرف) لكنه يختار فيها الاسئلة اللي حتفيدك ويعطيك مهلة طويلة تحلها واحيانا يمددها لو طلب منه الطلاب\nالنوتات حقته ممتازة لكن حسيت انو مستواها نزل في ماث 102 وخصوصا في نهاية ماث 102 واظن السبب هو انه في الترم الثاني كان عنده مواد اكثر ومواد تخصص بينما الترم الأول كان يدرس فقط ماث 101 هذا غير الضغط اللي حصل بسبب تقديم الاختبارات بس غالبا اذا درس هذي المواد مرة ثانية حتتحسن ان شاء الله\nالنوتات عنده نوعين نوتة شرح للدرس ونوتة فيها اسئلة محلولة على الدرس (بمستوى الاولد اكزامر)\nطبعا كل النوتات والهومووركات ينزلها على البلاكبورد حتى الكويزات يحط نسخة منها على البلاكبورد مع الحل (بعد الاختبار طبعا)\nالكويزات :\nاما متوسطة أو صعبة … الترم الاول عمل 6 والثاني اظن 8 … احيانا لما يكون الكويز مرة صعب والدرجات متدنية جدا يعطي درجات اضافية على الكويز للي يحله ويجيبه الحصة اللي بعدها وبالرغم من ذلك تلاقي افرج الكلاسوورك نهاية الترم نازل فيرفع الدرجات (انا شخصيا شايف الاسلوب هذا ممتاز ولمصلحة الطالب)\nالشي اللي ممكن يزعج في كوزاته هو طريقة التصحيح: لو الجواب غلط 0 حتى لو كانت غلطة حسابية بسيطة يعني زي الخيارات بس الفرق انو مافي خيارات (طبعا في بعض الاستثناءات زي لو الاجابة فيها جزئين انت جايب واحد منهم صح يعطيك جزء من الدرجة ولو ما اعطاك تقدر تروحله ويعطيك)\nالمياجر:\nكومون لكن في ماث 101 كان رتن وقتها ( يعني اسئلة مقالية مو خيارات)\nتصحيحه للميجر يميل للتشدد … مو مرة متشدد في الخطوات لكن اللي خلاني اقول انه يميل للتشدد هو انك لو أخطأت في بداية السؤال واعتمدت على معطيات من هذا الخطأ في حل باقي السؤال حيحسب السؤال كله خطأ حتى لو كانت طريقتك في حل باقي الخطوات صحيحة وطبعا ما يعطي درجات زيادة\nوكذلك اللي خلاني اقول انه يميل للتشدد هو ان افرج السكشن في الميجر 1 (الرتن) اقل من الافرج العام بينما الميجر الثاني (MCQ) كانت كل سكاشنه اعلى من الافرج العام بالرغم من انه كان اول ترم ليه\nالفاينلات :\nكومون\nالصوت:\nجيد وطريقة الكلام والشرح تمنع النوم\nإضافات :\nالدكتور تخصصه علوم اكتوارية ويحب يتكلم عن تخصصه وللعلم أنا تخصصت علوم اكتوارية فلو تحب تتعرف على التخصص تقدر تساله وتستفسر منه\nبحكم انه جاي من الاردن، احيانا (في حالات نادرة) ما يشرح شي لانه يعتقد إن الطلاب دارسينه زي مثلا في اول حصة في ماث 102 شرح درس المجموع بدون ما يشرح علامة السيجما وايش معناها بس هذا الشي ما حصل الا مرتين طوال الترمين على حسب ما اتذكر وما اظنه حيحصل مرة ثالثة خصوصا لو درس 101 او 102\nنصيحتي:\nلو انت طالب تبغى ترتاح وما همك القريد العالي لا تنزل عنده\nلكن لو القدريد يهمك ومستعد تشتغل عشانه بس بدك اللي يساعدك ويشجعك فهو المناسب ليك خصوصا لو المادة ما فيها اختبارات رتن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475323-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/3", "user": "joudah", "ts": 1497636467000, "tid": 176969, "pn": 3}}]}', 1497636467000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal70-math101', 'stk-faisal70', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math101\\-161التحضير : يحضر بالبداية واذا جيت متاخر يحضرك بعد الكلاس بس لا تزودها\nطريقة الشرح : يشرح من النوتة حقته كاتبها و مرتبة وكل نقطة عليها سؤال يوصل المعلومة بشكل ممتاز و يتجاوب مع الاسئلة.\nالكويزات : متوسطة مائلة الصعوبة و صعبة كان يجيبها من الاولد اكزامز و الاكوزات من موقع الماث\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح يتكلم انجليزي اغلب الوقت .\nإضافات :\nيعطي بونص زيادة على الكويز اذا حليته مرة ثانية والواجبات عطانا 4 او 5 بس كانت طويلة وتحتاج وقت الشي المؤكد يعطيك واجب قبل الميجر و الفاينل.\nمتساعد و يهتم بفهم الطالب كان يسوي هلب سيشن للطلاب قبل الميجر و الفاينل يحل فيه اولد اكزامز وكان يطلب من الطلاب يسألون اسئلة عشان يحلها .\nماقصر معي في الكلاس ورك زادني.\nالتصحيح للميجر و الكويزات ممتاز يحاسب على الخطوات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475472-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/5", "user": "Faisal70", "ts": 1497915285000, "tid": 176969, "pn": 5}}]}', 1497915285000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mhero7m-math101', 'stk-mhero7m', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ب161 و نص 162(سويت دروب للسمستر)\nماث 101 و ماث 102 وحاليا منزل عنده ماث 201 وان شاء الله راجع لكم بعد هالسمستر(181) و بكتب لكم عن تدريسه للمادة\n\nالتحضير : في 161 كان شديد وما يحب انك تتأخر اكثر من 5 دقايق لك كان يدخلك ويسامح كثير\nطريقة الشرح : اسطورة بالشرح ما شاء الله و حبيّب ويسولف في بعض الاحيان + ما يجيب لك النوم\nالكويزات : أذكر انها كانت صعبة لكن لو ذاكرت شويج اولد اكزام فسهلة لكن المشكلة ان تصحيحه كان اذا ما جبت الاجابة النهائية للسؤال فراح يعطيك 0 عليه بغض النظر عن الخطوات\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح جدا\nإضافات : المدرس ذا غالبا أفضل مدرس درسني ماث في الجامعة …الرجال خلوق جدا واذكر ان غياباتي معه كانت كثيرة ورحت له مرة عشان أبي أتأكد كم باقي لي عالحرمان وجاوبني بأن دامك طالب مجتهد وتحاول تسوي اللي تقدر عليه فلا تشيل هم الغيابات…الكلاس وورك بيدلعكم فيه ان شاء الله…عنده واجبات كثيرة لكن ما يطلب منك انك تحلها صح، اهم شي انك تسلمها وانت واضح انك حاولت تحلها حتى لو الاجابة النهائية خاطئة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498272-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/9", "user": "MHeRo7M", "ts": 1535452948000, "tid": 176969, "pn": 9}}]}', 1535452948000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-adel_pete-math101', 'stk-adel_pete', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m182895", "n": "Dr. Faisal Suwayyid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 101 Rec - 191\n\nالتحضير : يحضر أخر المحاضرة وغالباً يسمح بالتأخير.\nطريقة الشرح : يكتب أسئلة متوسطة إلى صعبة جداً على الصبورة من الدروس حقت الأسبوع ويعطيكم وقت تحلونها وبعد كذا يبدأ يحلها ويشرح الأفكار, صراحه هو واضح أنه مرة فاهم بالرياضيات ويعطي أحياناً تركات لكن ماكان يوصل المعلومة بشكل جيد ويحل بسرعة ومايمديك تكتب وراه.\nالكويزات : مافيه كويزات بالريساتيشن\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: c+\nالصوت: ضعيف جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525215-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-suwayyid/182895/5", "user": "Adel_PETE", "ts": 1598717356000, "tid": 182895, "pn": 5}}, {"id": "stk-dr-m182904", "n": "Dr. Muhammad Imran Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 191 - math101\n\nالتحضير : ورقة تمرر غالباً في نصف المحاضرة ومايدقق بشكل كبير على التأخير.\nطريقة الشرح : يشرح فكرة الدرس على الصبورة وصراحه هذا شيء جيد لأنه يبني الفكرة بشكل مفهوم, ثم بعدها يحل أسئلة الكتاب وأحياناً يحل اختبارات قديمة.\nالكويزات : متوسطة الصعوبة. لكن تصحيحه شديد شوي.\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B\nالصوت: واضح\nإضافات : الدكتور لا تخليه خيارك الأول لكن عنده نقاط جيده مثل الشرح بالنسبه لي كان جيد, ومن المهم تحضر من البداية لأن لو تأخرت 5 دقائق بتضيع أهم جزء من المحاضرة. وبالنسبه للكويزات بالنهاية فيه أفرج وحتى لو تصحيحه شديد بيزيدكم كثير وفيه البعض بسبب الزيادة عطاهم درجة كاملة في الأعمال الفصلية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525395-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-imran-qureshi/182904/5", "user": "Adel_PETE", "ts": 1599464986000, "tid": 182904, "pn": 5}}]}', 1598717356000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hamadkd-math101', 'stk-hamadkd', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m182895", "n": "Dr. Faisal Suwayyid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 201 MATH 101 Online\nالتحضير : يحضر بداية كل كلاس ونهايته عن طريق تصوير الموجودين في تيمز (يعني ماينادي اسماء فقط تواجدك يعني حضورك)\nطريقة الشرح : للامانه هو فاهم الكونسبت لكن يجد صعوبة في توصيل المعلومه وشرحه للأمانه سيء لكن بإذن الله يتحسن مع الوقت بحكم انه جديد على التدريس\nالكويزات : بعضها سهل وبعضها متوسط مائل للصعوبة\nالمياجر: -\nالفاينلات :-\nالقريد النهائي: F\nالصوت: خافت لكن متردد جدا واحسه مرتبك وهو يشرح\nإضافات : الدكتور طيب جدا واخلاقه عاليه ومتعاون مع الطلاب لكن اللي ينقصه الشرح وتوصيل المعلومه ، ممكن مع الوقت يتمكن من الشرح بشكل ممتاز لكن حاليا لاتفكر انك تنزل عنده ابدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526531-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-suwayyid/182895/8", "user": "HamadKD", "ts": 1604593141000, "tid": 182895, "pn": 8}}]}', 1604593141000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-brhuggi-math101', 'stk-brhuggi', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m182895", "n": "Dr. Faisal Suwayyid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(MATH 101- 201 (ONLINE\n\nالتحضير : يسحب التحضير من التيمز نهاية الكلاس\n\nطريقة الشرح : يشرح من سلايدات، واعتقد انه اول ترم له كمحاضر عشان كذا بتحس انه متوتر في الكلام وليس طليق اللسان وممكن يكون مزعج جداً وماتقدر تركز معه بسبب ذا الشيء، عن نفسيحاولت اركز معه اكثر من مرة بس ماش.\n\nالكويزات : يقسم الكلاس وورك بين 6 كويزات على كل واحد 1% و 4 تيستات على كل واحد 2.25% والحل عن طريق ويب اساين وقت كلاسك ومايحتاج كاميرا ووقت اي كويز او تيست مافيه محاضرة. مرات يكون ملتبل ومرات فاينل انسر على حسب الجو\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: C\n\nالصوت: سيء جداً وتعتة كثيرة في كلامه تخلي الكلاس ممل\n\nإضافات : الدكتور خلوق إلى أبعد حد ويحاول يبذ جهده الصراحة، لكن عند مشاكل كبيرة في الصوت ومحاولة ايصال المعلومة ويمشي على سلبس غريب بعض المرات، اذا ناوي تنزل عنده لازم يكون عندم مصدر مذاكرة أساسي غيره عشان ماتضيع.\n\nفي كل اسبوع يحدث اكسل شيت ويرفعها وفيها كل معلوماتك من غياب وحضور ودرجات وتقسيم وغيره بشكل واضح وماراح يتعبك من هذه الناحية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527435-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-suwayyid/182895/10", "user": "BRHUGGI", "ts": 1609422892000, "tid": 182895, "pn": 10}}]}', 1609422892000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-math101', 'stk-moh_ammed', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m182895", "n": "Dr. Faisal Suwayyid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 101-201 (تعليم عن بعد - كورونا)\n\nالتحضير: يأخذ التحضير نهاية المحاضرة بشكل تلقائي من التيمز، سمعت إنه يأخذ التحضير بداية ونهاية المحاضرة بس مالاحظت هالشيء حصل.أتوقع إنه يقبل ميكب أب بس ماجربت.\n\nالشرح: سيء جدا بالذات إن التعليم عن بعد.أنا وكثير من الطلاب أخذوا المادة سلف ستدي 100%. يمكن لو التعليم كان حضوري يكون أحسن من كذا مع إني ما أظن يتحسن كثير.\n\nالصوت: يقطع كثير بالكلام والله.\n\nالتعامل: أخلاقه حلوة ماشاء الله عليه.\n\nالكويزات: كويزاته سهلة،بالذات اللي كانت ببداية الترم كانت سهلة مرة. هذا شيء حلو صح بس بنفس الوقت يمكن يخليك تكسل عن المذاكرة أحيانا.\n\nالقريد النهائي: D or F\n\nإضافات: - الدكتور الله يهديه يغلط كثير بوضع أسئلة الكويزات والتستات،أكثر من مرة يتأجل الكويز أو التست بسبب إن الأسئلة فيها مشكلة.\n- لاتنزل عنده إلا إذا انجبرت عليه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527479-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-suwayyid/182895/11", "user": "Moh_ammed", "ts": 1609569363000, "tid": 182895, "pn": 11}}]}', 1609569363000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12111-math101', 'stk-user12111', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m182904", "n": "Dr. Muhammad Imran Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term 202\nmath 101 online term\nالتحضير : نهاية الكلاس ينادي الاسامي\nطريقة الشرح : يشرح من سلايدات (اتوقع اسمها سلايدات الشهراني الزبدة هي السلايدات اللي كانها مكتوبة بقلم ايباد او قلم كمبيوتر ) وما يجيب شي برا . شرحه كويس بس نصيحتي حضر للدرس جعل لو قبل الكلاس بدقيقتين اقراه شوي لان بالبداية ماكنت افهم لين صرت اقرا قبل الكلاس وصرت افهم كل شي\nالكويزات : الكويزات كانت بالبلاك بورد عكس باقي الدكاترة بذاك الوقت كانو يستخدمون webassign وكانت كوبي بيست اولد اكسامز كل كويز سؤالين وتوتال 8 كويزات يمكن .\nلاحظنا شي بالكويزات ان دايما الاجابة هي A بكل كويزاته واسالته وتوقعنا لانه ما يعرف كيف يفعل خيار بالبلاكبورد يخلي الاجابات تتخربط . والافرج ماكان عالي وانا كنت اعرف شخص واحد بس من الشعبة انتبه ان الاجابات دايم A\nالمياجر: كومن للكل\nالفاينلات : كومن للكل\nالقريد النهائي: +A\nالصوت: ك مستوى صوت كويس لكن لهجته شوي يبيلك تتحمله للمعلومية لهجته باكستاني\nسكير = تربيع\nحرف W او O = حرف V\n\nإضافات : حبوب ومحترم كثير لو تجيه باي وقت يرحب فيك - بصراحة اشوف ممكن تستغني عنه شوي اذا تحب السلف ستدي يعني محاضرته مافيها ذيك المعلومات اللي بتروح عليك لو ماحضرت .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530756-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-imran-qureshi/182904/10", "user": "user12111", "ts": 1625440023000, "tid": 182904, "pn": 10}}]}', 1625440023000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fairytale-math101', 'stk-fairytale', 'MATH 101', 'doc', '{"docs": [{"id": "stk-dr-m185072", "n": "Dr. Manal Alotibi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : تحضر بداية الكلاس ومره متشدده فيه اذ جيتي بعد التحضير لو ب دقيقة تعتبرك late من بعد ثالث غياب تنقصك\nطريقة الشرح : على الباور بوينت وتستخدم البورد اذ تحل مسائل الشرح على حسب الدرس فيه دروس ما تعرف تشرحها او توصل المعلومه وفيه دروس لا شرحها كويس فيهم مره\nهي تدرس كانت سكشنين الساعه ١٢ وسكشنين الساعه ١ والي الساعه ١ يكون شرحها مره احسن من الي ب ١٢ لانه كانت تتعلم من اغلاطها وتطور من سكشن ١٢\nالكويزات : متوسطه الصعوبه واحلى شي فيها اذ كان فيه سؤال غلط او جابته برا المنهج والبنات كلموها تحذفه وتعطي الكل درجة السؤال ( اغلبها من اسألة الكتاب )\nالمياجر : سكشنين كانو يجيبون على الافرج وواحد انزل من الافرج وواحد اعلى\nالفاينل : -\nالصوت : الصدق صوتها عالي كانها تصارخ لدرجة الكلاس الي جمبنا مره جو وقالو لها قصري صوتك بعدين صار صوتها كويس بس لا تخلونها تعصب بتندمون\nاضافات: تسوي هيلب سشن والبنات يمدحونه ولكن عن نفسي ما قد حضرته\n\nMath 101- Term 241", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538296-math101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/manal-alotibi/185072/2", "user": "fairytale", "ts": 1732371452466, "tid": 185072, "pn": 2}}]}', 1732371452466, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
